INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93677, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "羊", "is_correct": true, "explanation": "羊（yáng）指身上有毛、会咩咩叫的动物，是正确答案。"}, {"text": "样", "is_correct": false, "explanation": "样（yàng）声调不同（第四声），意思是样子。"}, {"text": "养", "is_correct": false, "explanation": "养（yǎng）声调不同（第三声），意思是饲养。"}, {"text": "氧", "is_correct": false, "explanation": "氧（yǎng）声调不同（第三声），意思是氧气。"}], "explanations": {"羊": "羊（yáng）指身上有毛、会咩咩叫的动物，是正确答案。", "样": "样（yàng）声调不同（第四声），意思是样子。", "养": "养（yǎng）声调不同（第三声），意思是饲养。", "氧": "氧（yǎng）声调不同（第三声），意思是氧气。"}, "sentence_index": null, "correct_answer": "羊"}, "level_3": {"options": [{"text": "羊", "is_correct": true, "explanation": "羊是草地上常见的动物，与句意相符，是正确答案。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会大量出现在草地上，与句中的场景不合。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不是草地上常见的东西，与「很多」的描述不合。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯不会出现在草地上，与句中的场景不合。"}], "explanations": {"羊": "羊是草地上常见的动物，与句意相符，是正确答案。", "冰箱": "语义：冰箱不会大量出现在草地上，与句中的场景不合。", "钢琴": "语义：钢琴不是草地上常见的东西，与「很多」的描述不合。", "电梯": "语义：电梯不会出现在草地上，与句中的场景不合。"}, "sentence_index": 0, "correct_answer": "羊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家养了一张羊。", "explanation": "这里应该用〈只〉。「张」用于平面的东西，不用于羊。"}, {"text": "草地上跑着一条羊。", "explanation": "这里应该用〈只〉。「条」用于细长的东西，不用于羊。"}, {"text": "他家有一头羊群。", "explanation": "这里应该说〈一群羊〉。「头」用于计数单个牲畜，不能用来数成群的羊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93677, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "羊", "is_correct": true, "explanation": "羊（yáng）指身上有毛、会咩咩叫的动物，是正确答案。"}, {"text": "痒", "is_correct": false, "explanation": "痒（yǎng）声调不同（第三声），意思是身体皮肤发痒的感觉。"}, {"text": "盐", "is_correct": false, "explanation": "盐（yán）韵母 an 与 ang 不同，意思是食盐。"}, {"text": "严", "is_correct": false, "explanation": "严（yán）韵母 an 与 ang 不同，意思是严格。"}, {"text": "样", "is_correct": false, "explanation": "样（yàng）声调不同（第四声），意思是样子。"}], "explanations": {"羊": "羊（yáng）指身上有毛、会咩咩叫的动物，是正确答案。", "痒": "痒（yǎng）声调不同（第三声），意思是身体皮肤发痒的感觉。", "盐": "盐（yán）韵母 an 与 ang 不同，意思是食盐。", "严": "严（yán）韵母 an 与 ang 不同，意思是严格。", "样": "样（yàng）声调不同（第四声），意思是样子。"}, "sentence_index": null, "correct_answer": "羊"}, "level_3": {"options": [{"text": "羊", "is_correct": true, "explanation": "羊是能动的动物，会看见人并跑开，与句意相符，是正确答案。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：「跑开」要求能动的主语，桌子不能跑开。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会看见人，也不会跑开，与句意不合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会看见人，也不会跑开，句意不通。"}], "explanations": {"羊": "羊是能动的动物，会看见人并跑开，与句意相符，是正确答案。", "桌子": "配价：「跑开」要求能动的主语，桌子不能跑开。", "石头": "语义：石头不会看见人，也不会跑开，与句意不合。", "窗户": "语义：窗户不会看见人，也不会跑开，句意不通。"}, "sentence_index": 6, "correct_answer": "羊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一匹羊跑进了院子。", "explanation": "这里应该用〈只〉。「匹」用于马、骡等，不用于羊。"}, {"text": "一座羊跑进了院子。", "explanation": "这里应该用〈只〉。「座」用于山、楼房等大型固定的东西，不能修饰羊。"}, {"text": "一棵羊跑进了院子。", "explanation": "这里应该用〈只〉。「棵」用于植物，羊不能用这个量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93677, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民每天都要照顾那棵羊。", "corrected_sentence": "农民每天都要照顾那只羊。", "error_description": "错误：「那棵羊」；正确：「那只羊」。「棵」用于植物，羊是动物，量词应用「只」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93677, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些羊们都很健康。", "corrected_sentence": "这些羊都很健康。", "error_description": "错误：「羊们」；正确：「羊」。「这些」已表示复数，名词「羊」后不能再加「们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
