INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93678, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "反刍类哺乳动物，有绵羊、山羊等，毛、肉可利用。", "primary_collocate": null, "pronunciation": "yáng", "ipa": "jɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "牧民在草原上放羊。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "羊的毛可以做衣服。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "羊和牛都吃草。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家靠养羊生活。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种羊的毛特别长。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，牧民把羊赶回家。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "羊是一种吃草的动物。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草原上有一群羊。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想买几头羊。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些羊来自北方的牧场。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "头", "label": "量词"}, {"form": "群", "label": "量词"}, {"form": "山羊", "label": "复合词"}, {"form": "绵羊", "label": "复合词"}], "register": "中性", "sense_fingerprint": "反刍类哺乳动物的总称，毛和肉可利用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e36a8cdb-5406-47d1-930e-7fc5be5a3f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
