INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93679, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "男朋友是女生喜欢、常常一起玩的男生。", "primary_collocate": null, "pronunciation": "nán péng yǒu", "ipa": "nan˧˥ pʰɤŋ˧˥ joʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "小红喜欢她的男朋友，两个人常常一起玩。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末她的男朋友来找她一起去公园玩。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的男朋友打球很好，她常去看他打球。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小丽的男朋友是同班同学，他们放学后一起玩。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有个男朋友，常常陪她去逛街。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不认识她的男朋友，只见过他一次。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，她的男朋友借给她一把伞。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的男朋友总是和她一起玩游戏。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈问女儿：“你的男朋友是谁？”", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个男孩是小静的男朋友，他们常一起骑车。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "男朋友们", "label": "复数"}], "register": "口语", "sense_fingerprint": "女生喜欢、常常一起玩的男生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1ebf27a-bc60-422b-bfea-fa9b711a051c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93679, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男朋友", "is_correct": true, "explanation": "“男朋友”指女生喜欢、常常一起玩的男生，与句中“小红喜欢她的”和“两个人常常一起玩”相符。"}, {"text": "猫", "is_correct": false, "explanation": "语义：“两个人”指人，猫不能与小红算作“两个人”一起玩。"}, {"text": "房子", "is_correct": false, "explanation": "配价：“一起玩”要求能参与的人作主体，“房子”不能与人一起玩。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是物品，不能成为“两个人常常一起玩”中的一方。"}], "explanations": {"男朋友": "“男朋友”指女生喜欢、常常一起玩的男生，与句中“小红喜欢她的”和“两个人常常一起玩”相符。", "猫": "语义：“两个人”指人，猫不能与小红算作“两个人”一起玩。", "房子": "配价：“一起玩”要求能参与的人作主体，“房子”不能与人一起玩。", "电脑": "语义：电脑是物品，不能成为“两个人常常一起玩”中的一方。"}, "sentence_index": 0, "correct_answer": "男朋友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里有三个男朋友在打篮球。", "explanation": "这里应该用〈男生〉。男朋友指恋爱关系中的男方，不能泛指班里的男孩；“男生”才指一般的男性学生。"}, {"text": "我的男朋友是我爸爸的弟弟，今年四十岁。", "explanation": "这里应该用〈叔叔〉。男朋友指恋爱关系中的男方，不能指亲戚；爸爸的弟弟要说“叔叔”。"}, {"text": "她已经和男朋友结婚三年了。", "explanation": "这里应该用〈丈夫〉。男朋友指恋爱关系中的男方，还没有结婚；已经结婚的男方要说“丈夫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93679, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "男朋友", "is_correct": true, "explanation": "“男朋友”指女生喜欢、常常一起玩的男生，下雨时能借伞给她，符合句意。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不能借伞给人，“她的书包借给她一把伞”不通。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不能借伞给人，不能作“借给她一把伞”的主体。"}, {"text": "男子", "is_correct": false, "explanation": "搭配：“她的”后一般不接“男子”，说“她的男子”不自然，这里应说“她的男朋友”一类的关系词。"}], "explanations": {"男朋友": "“男朋友”指女生喜欢、常常一起玩的男生，下雨时能借伞给她，符合句意。", "书包": "语义：书包是物品，不能借伞给人，“她的书包借给她一把伞”不通。", "小狗": "语义：小狗不能借伞给人，不能作“借给她一把伞”的主体。", "男子": "搭配：“她的”后一般不接“男子”，说“她的男子”不自然，这里应说“她的男朋友”一类的关系词。"}, "sentence_index": 6, "correct_answer": "男朋友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个男朋友只有五岁，还在上幼儿园。", "explanation": "这里应该用〈男孩〉。男朋友指恋爱中的男方，不能指五岁的小孩；指男性儿童要说“男孩”。"}, {"text": "她的男朋友今年三岁，是她生的孩子。", "explanation": "这里应该用〈儿子〉。男朋友指恋爱关系中的男方，不能指自己生的孩子；这里应该说“儿子”。"}, {"text": "婚礼上，男朋友先向客人敬酒。", "explanation": "这里应该用〈新郎〉。男朋友指恋爱关系中的男方，婚礼上结婚的男方要说“新郎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93679, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐有一只男朋友，他是医生。", "corrected_sentence": "我姐姐有一个男朋友，他是医生。", "error_description": "量词错误：“男朋友”指人，应该用量词“个”；“只”多用于动物，说“一只男朋友”是量词用错了。正确说法是“一个男朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93679, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她前年就有男朋友着。", "corrected_sentence": "她前年就有男朋友了。", "error_description": "动态助词错误：“有男朋友”表示已经有了这种状态，要用“了”，不能用“着”。说“有男朋友着”是错用了“着”，正确说法是“她前年就有男朋友了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
