INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93680, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "恋爱关系中的男方。", "primary_collocate": null, "pronunciation": "nán péng yǒu", "ipa": "nan˧˥ pʰɤŋ˧˥ joʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "她和男朋友已经谈了三年恋爱。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的男朋友在北京工作，我们很少见面。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天带男朋友回家见父母。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有男朋友吗？", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和男朋友吵架了，心情很不好。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日那天，男朋友送给我一束花。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的男朋友打算明年和她结婚。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我男朋友，不是普通朋友。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我男朋友做饭做得比我好。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟男朋友分手以后，一个人去旅行。", "target_word": "男朋友", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "男朋友们", "label": "复数"}], "register": "口语", "sense_fingerprint": "恋爱关系中的男方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1ebf27a-bc60-422b-bfea-fa9b711a051c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93680, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男朋友", "is_correct": true, "explanation": "“男朋友”指恋爱关系中的男方，与“谈了三年恋爱”相符。"}, {"text": "爸爸", "is_correct": false, "explanation": "语义：爸爸是亲属，不能与“她”谈恋爱。"}, {"text": "狗", "is_correct": false, "explanation": "语义：“谈恋爱”的对象须是人，狗不能作为恋爱关系中的一方。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能成为恋爱关系中的一方，“谈恋爱”的对象须是人。"}], "explanations": {"男朋友": "“男朋友”指恋爱关系中的男方，与“谈了三年恋爱”相符。", "爸爸": "语义：爸爸是亲属，不能与“她”谈恋爱。", "狗": "语义：“谈恋爱”的对象须是人，狗不能作为恋爱关系中的一方。", "汽车": "语义：汽车不能成为恋爱关系中的一方，“谈恋爱”的对象须是人。"}, "sentence_index": 0, "correct_answer": "男朋友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她和男朋友已经结婚十年了。", "explanation": "这里应该用〈丈夫〉。男朋友指恋爱关系中的男方，还没有结婚；已经结婚十年的男方要说“丈夫”。"}, {"text": "那个男朋友才五岁，还在上幼儿园。", "explanation": "这里应该用〈男孩〉。男朋友指恋爱关系中的男方，不能指五岁的孩子；指男性儿童要说“男孩”。"}, {"text": "她是我的男朋友，我们每个周末都一起去打球。", "explanation": "这里应该用〈女朋友〉。男朋友指恋爱关系中的男方，女方要说“女朋友”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "男朋友", "is_correct": true, "explanation": "“男朋友”指恋爱关系中的男方，能与她结婚，符合句意。"}, {"text": "猫", "is_correct": false, "explanation": "配价：“结婚”要求双方都是人，猫不能与“她”结婚。"}, {"text": "大楼", "is_correct": false, "explanation": "配价：“结婚”的主体须是人，“大楼”不能作结婚的一方。"}, {"text": "小学生", "is_correct": false, "explanation": "搭配：“结婚”要求成年人，“小学生”与“打算明年和她结婚”搭配不当。"}], "explanations": {"男朋友": "“男朋友”指恋爱关系中的男方，能与她结婚，符合句意。", "猫": "配价：“结婚”要求双方都是人，猫不能与“她”结婚。", "大楼": "配价：“结婚”的主体须是人，“大楼”不能作结婚的一方。", "小学生": "搭配：“结婚”要求成年人，“小学生”与“打算明年和她结婚”搭配不当。"}, "sentence_index": 6, "correct_answer": "男朋友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班里的男朋友都爱打篮球。", "explanation": "这里应该用〈男同学〉。男朋友指恋爱关系中的男方，不能泛指班里的男生；这里应该说“男同学”。"}, {"text": "他是我的男朋友，今年八岁。", "explanation": "这里应该用〈儿子〉。男朋友指恋爱关系中的男方，八岁的孩子不可能是男朋友；这里应该说“儿子”。"}, {"text": "婚礼上，男朋友先向客人敬酒。", "explanation": "这里应该用〈新郎〉。男朋友指恋爱关系中的男方，婚礼上结婚的男方要说“新郎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她曾经有过一只男朋友。", "corrected_sentence": "她曾经有过一个男朋友。", "error_description": "量词错误：“男朋友”指人，量词应用“个”，不能用“只”（“只”多用于动物或成对的东西）。正确说法：“她曾经有过一个男朋友。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她终于找了到男朋友。", "corrected_sentence": "她终于找到了男朋友。", "error_description": "补语错误：结果补语“到”要紧跟动词“找”，“了”放在补语之后，应说“找到了男朋友”，不能说“找了到男朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93681, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "守信", "is_correct": true, "explanation": "反义：守信指遵守信用，与不讲信用、转而替对手做事正相反。"}, {"text": "购买", "is_correct": false, "explanation": "无关：购买指付钱取得物品，与背叛没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "无关：参加指加入某项活动，与背叛不构成反义。"}, {"text": "陪伴", "is_correct": false, "explanation": "无关：陪伴指伴随在旁，与背叛不构成反义。"}], "correct_answer": "守信", "explanations": {"守信": "反义：守信指遵守信用，与不讲信用、转而替对手做事正相反。", "购买": "无关：购买指付钱取得物品，与背叛没有反义关系。", "参加": "无关：参加指加入某项活动，与背叛不构成反义。", "陪伴": "无关：陪伴指伴随在旁，与背叛不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93681, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "守信", "is_correct": true, "explanation": "反义：守信指遵守信用，与背叛对方、不讲信用正相反。"}, {"text": "推荐", "is_correct": false, "explanation": "无关：推荐指介绍人或物，与背叛没有反义关系。"}, {"text": "邀请", "is_correct": false, "explanation": "无关：邀请指请人来做客，不是背叛的反义。"}, {"text": "参观", "is_correct": false, "explanation": "无关：参观指到某处察看，与背叛无关。"}], "correct_answer": "守信", "explanations": {"守信": "反义：守信指遵守信用，与背叛对方、不讲信用正相反。", "推荐": "无关：推荐指介绍人或物，与背叛没有反义关系。", "邀请": "无关：邀请指请人来做客，不是背叛的反义。", "参观": "无关：参观指到某处察看，与背叛无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93681, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "背叛是不守信用，转过头帮对手做事。", "primary_collocate": null, "pronunciation": "bèi pàn", "ipa": "pei˥˩ pʰan˥˩", "syllable_count": 2, "sentences": [{"text": "他背叛了朋友，去帮我们的对手做事。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司老板发现员工背叛了他，把秘密卖给了对手。", "target_word": "背叛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们说好一起做生意，他却背叛了我。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王背叛了球队，加入了对手的队伍。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你答应过我，怎么能背叛我呢？", "target_word": "背叛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最好的朋友背叛了她，她很难过。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他背叛了合作伙伴，和对手签了合同。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没想到他会背叛我们，帮对手做事。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的师傅背叛了老板，去了对面的店。", "target_word": "背叛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间要讲信用，不能背叛对方。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "背叛了", "label": "完成体"}, {"form": "背叛过", "label": "经历体"}, {"form": "背叛者", "label": "复合"}], "register": "中性", "sense_fingerprint": "不讲信用，反过来替对手做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43035244-64f2-4d65-bc07-110cd48c7371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93681, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保护", "is_correct": false, "explanation": "语义：保护指照护、护卫，与“去帮我们的对手做事”矛盾。"}, {"text": "背叛", "is_correct": true, "explanation": "正确：背叛指不守信用、转而替对手做事，与后半句一致。"}, {"text": "照料", "is_correct": false, "explanation": "语义：照料指照顾，与“去帮我们的对手做事”矛盾。"}, {"text": "背诵", "is_correct": false, "explanation": "搭配：背诵的对象是课文、诗词，不说“背诵朋友”。"}], "explanations": {"保护": "语义：保护指照护、护卫，与“去帮我们的对手做事”矛盾。", "背叛": "正确：背叛指不守信用、转而替对手做事，与后半句一致。", "照料": "语义：照料指照顾，与“去帮我们的对手做事”矛盾。", "背诵": "搭配：背诵的对象是课文、诗词，不说“背诵朋友”。"}, "sentence_index": 0, "correct_answer": "背叛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他背叛了比赛，中途回家了。", "explanation": "这里应该用〈放弃〉。放弃用于比赛、计划，背叛的对象是人或誓言。"}, {"text": "他背叛了这本书的内容，删掉了一半。", "explanation": "这里应该用〈删改〉。删改用于文字、内容，背叛的对象是人、誓言或信念。"}, {"text": "这位选手背叛了比赛规则，被取消了资格。", "explanation": "这里应该用〈违反〉。违反用于规则、纪律，背叛不说背叛规则。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93681, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支持", "is_correct": false, "explanation": "语义：支持指站在一方、帮助一方，与“和对手签了合同”的转向相矛盾。"}, {"text": "背叛", "is_correct": true, "explanation": "正确：背叛指不守信用、转向对手，与“和对手签了合同”一致。"}, {"text": "签署", "is_correct": false, "explanation": "搭配：签署的对象是合同、协议，不说“签署合作伙伴”。"}, {"text": "维护", "is_correct": false, "explanation": "语义：维护指保护、护卫，与“和对手签了合同”的背弃矛盾。"}], "explanations": {"支持": "语义：支持指站在一方、帮助一方，与“和对手签了合同”的转向相矛盾。", "背叛": "正确：背叛指不守信用、转向对手，与“和对手签了合同”一致。", "签署": "搭配：签署的对象是合同、协议，不说“签署合作伙伴”。", "维护": "语义：维护指保护、护卫，与“和对手签了合同”的背弃矛盾。"}, "sentence_index": 6, "correct_answer": "背叛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了钱，背叛了公司的电脑。", "explanation": "这里应该用〈卖掉〉。背叛的对象是人、誓言或信念，电脑要说卖掉。"}, {"text": "他酒后闹事，背叛了球队的名声。", "explanation": "这里应该用〈损害〉。背叛的对象是人、誓言或信念，名声要说损害、毁坏，不说背叛。"}, {"text": "他背叛了这个谣言。", "explanation": "这里应该用〈驳斥〉。驳斥用于谣言、说法，背叛的对象是人或誓言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他背叛给了公司，跑去给对手工作了。", "corrected_sentence": "他背叛了公司，跑去给对手工作了。", "error_description": "“给”用错了：背叛是及物动词，直接带宾语，不说“背叛给”，应说“背叛了公司”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很背叛了我们，把客户都带走了。", "corrected_sentence": "他背叛了我们，把客户都带走了。", "error_description": "“很”不能修饰动词：应说“他背叛了我们”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
