INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93682, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "效忠", "is_correct": true, "explanation": "反义：效忠指忠心服从，与背叛军队、帮助敌人正相反。"}, {"text": "帮助", "is_correct": false, "explanation": "无关：帮助指给予支持，与背叛没有反义关系。"}, {"text": "参观", "is_correct": false, "explanation": "无关：参观指到某处察看，与背叛无关。"}, {"text": "邀请", "is_correct": false, "explanation": "无关：邀请指请人来做客或参加，不是背叛的反义。"}], "correct_answer": "效忠", "explanations": {"效忠": "反义：效忠指忠心服从，与背叛军队、帮助敌人正相反。", "帮助": "无关：帮助指给予支持，与背叛没有反义关系。", "参观": "无关：参观指到某处察看，与背叛无关。", "邀请": "无关：邀请指请人来做客或参加，不是背叛的反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93682, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "违背誓约或原则，投向敌方。", "primary_collocate": null, "pronunciation": "bèi pàn", "ipa": "pei˥˩ pʰan˥˩", "syllable_count": 2, "sentences": [{"text": "那个将军背叛了国王，投向了敌人。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他违背誓言，背叛了自己的国家。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争中，有人背叛了自己的原则。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们当年发过誓，没想到他会背叛。", "target_word": "背叛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个士兵背叛了队伍，跑到了敌人那边。", "target_word": "背叛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从不背叛自己的信仰。", "target_word": "背叛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为了钱，他背叛了革命，成了敌人的朋友。", "target_word": "背叛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王发现大臣背叛了他，投向了敌国，非常生气。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说过永远不会背叛自己的誓言。", "target_word": "背叛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那名军官背叛了军队，帮敌人打自己人。", "target_word": "背叛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "背叛了", "label": "完成体"}, {"form": "背叛过", "label": "经历体"}, {"form": "背叛者", "label": "复合"}], "register": "中性", "sense_fingerprint": "违背誓言或原则，倒向敌人一方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43035244-64f2-4d65-bc07-110cd48c7371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拥戴", "is_correct": false, "explanation": "语义：拥戴指拥护、推崇，与后半句“投向了敌人”的背离相矛盾。"}, {"text": "背叛", "is_correct": true, "explanation": "正确：背叛指违背誓约或原则、投向敌方，与“投向了敌人”的走向一致。"}, {"text": "陪伴", "is_correct": false, "explanation": "语义：陪伴指伴随相处，不表示背弃，与“投向了敌人”矛盾。"}, {"text": "守卫", "is_correct": false, "explanation": "语义：守卫指保卫、看守，与“投向了敌人”的背离相矛盾。"}], "explanations": {"拥戴": "语义：拥戴指拥护、推崇，与后半句“投向了敌人”的背离相矛盾。", "背叛": "正确：背叛指违背誓约或原则、投向敌方，与“投向了敌人”的走向一致。", "陪伴": "语义：陪伴指伴随相处，不表示背弃，与“投向了敌人”矛盾。", "守卫": "语义：守卫指保卫、看守，与“投向了敌人”的背离相矛盾。"}, "sentence_index": 0, "correct_answer": "背叛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他背叛了自然规律，结果实验失败了。", "explanation": "这里应该用〈违背〉。违背多用于规律、常识，背叛的对象是人、誓言或信念。"}, {"text": "他为了钱，背叛了那本旧字典。", "explanation": "这里应该用〈卖掉〉。背叛的对象是人、誓言或信念，旧字典要说卖掉或丢掉。"}, {"text": "这个国家的人民背叛了外国的入侵。", "explanation": "这里应该用〈抵抗〉。入侵是外来的侵略，应说抵抗，不说背叛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "维护", "is_correct": false, "explanation": "语义：维护指保护、支持，与“成了敌人的朋友”矛盾。"}, {"text": "背叛", "is_correct": true, "explanation": "正确：背叛指违背誓约或原则、投向敌方，与“成了敌人的朋友”一致。"}, {"text": "承担", "is_correct": false, "explanation": "搭配：承担的对象是责任、任务，不说“承担革命”。"}, {"text": "追随", "is_correct": false, "explanation": "语义：追随指跟从，与“成了敌人的朋友”的背离结果矛盾。"}], "explanations": {"维护": "语义：维护指保护、支持，与“成了敌人的朋友”矛盾。", "背叛": "正确：背叛指违背誓约或原则、投向敌方，与“成了敌人的朋友”一致。", "承担": "搭配：承担的对象是责任、任务，不说“承担革命”。", "追随": "语义：追随指跟从，与“成了敌人的朋友”的背离结果矛盾。"}, "sentence_index": 6, "correct_answer": "背叛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个司机背叛了红灯，被罚了款。", "explanation": "这里应该用〈闯〉。背叛的对象是人、誓言或信念，红灯要说闯。"}, {"text": "他背叛了这份试卷，考试没及格。", "explanation": "这里应该用〈做〉。做题用于试卷，背叛的对象是人、誓言或信念。"}, {"text": "他做错事，背叛了自己的名誉。", "explanation": "这里应该用〈毁坏〉。名誉会被毁坏、损害，不说被背叛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那名士兵背叛的誓言，投向了敌人。", "corrected_sentence": "那名士兵背叛了誓言，投向了敌人。", "error_description": "“的”用错了：加“的”后“背叛的誓言”只是定语，句子缺少谓语，应说“那名士兵背叛了誓言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很背叛了信仰，投向了敌人。", "corrected_sentence": "他背叛了信仰，投向了敌人。", "error_description": "“很”不能修饰动词：背叛是动词，应直接说“他背叛了信仰”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
