INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93683, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "发言人是代表大家出来说话的人。", "primary_collocate": null, "pronunciation": "fā yán rén", "ipa": "fa˥ jɛn˧˥ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "我们班的发言人是小王。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家选了小李做发言人。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组讨论后，发言人站起来说话了。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小组的发言人讲得很清楚。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来当我们的发言人？", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请每组的发言人说一说想法。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，他是我们的发言人。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发言人说完以后，大家都鼓掌了。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次讨论，我们让小红当发言人。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们请老张当发言人，去和公司谈。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "中性", "sense_fingerprint": "小组或集体中代表大家说话的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65734415-928a-473e-bc99-3005a844ecdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93683, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "班费", "is_correct": false, "explanation": "语义：班费指班级的钱款，不是人，不能和“是小王”搭配。"}, {"text": "发言人", "is_correct": true, "explanation": "正确：“发言人”是代表大家说话的人，与“我们班的”和“是小王”相合。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是地方，不是人，“我们班的教室是小王”不成立。"}, {"text": "作业", "is_correct": false, "explanation": "配价：“是小王”要求主语指人，作业不是人，不能充当主语。"}], "explanations": {"班费": "语义：班费指班级的钱款，不是人，不能和“是小王”搭配。", "发言人": "正确：“发言人”是代表大家说话的人，与“我们班的”和“是小王”相合。", "教室": "语义：教室是地方，不是人，“我们班的教室是小王”不成立。", "作业": "配价：“是小王”要求主语指人，作业不是人，不能充当主语。"}, "sentence_index": 0, "correct_answer": "发言人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会上由小王担任发言人，负责把大家的意见记下来。", "explanation": "这里应该用〈记录员〉。发言人是代表大家发言的人，记录意见的职责属于记录员。"}, {"text": "我们组的发言人每个月负责给大家发工资。", "explanation": "这里应该用〈会计〉。发言人只代表大家发言，发工资是会计的工作。"}, {"text": "他只是发言人，从不开口说话。", "explanation": "这里应该用〈旁听者〉。发言人要代表大家说话，“从不开口”与它的意思相矛盾，这种人应称旁听者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93683, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发言人", "is_correct": true, "explanation": "正确：“发言人”指代表大家说话的人，与“他是我们的”相合，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能指人，不能与“他”同指。"}, {"text": "会场", "is_correct": false, "explanation": "语义：会场是开会的地点，“他是我们的会场”不成立。"}, {"text": "婴儿", "is_correct": false, "explanation": "搭配：“开会时”参会的是成年人，“婴儿”与开会的语境不搭配。"}], "explanations": {"发言人": "正确：“发言人”指代表大家说话的人，与“他是我们的”相合，符合句意。", "桌子": "语义：桌子是家具，不能指人，不能与“他”同指。", "会场": "语义：会场是开会的地点，“他是我们的会场”不成立。", "婴儿": "搭配：“开会时”参会的是成年人，“婴儿”与开会的语境不搭配。"}, "sentence_index": 6, "correct_answer": "发言人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班选了一条发言人。", "explanation": "这里应该用〈位〉。“条”多用于细长的东西，指人应用“位”。"}, {"text": "老师请一把发言人站起来。", "explanation": "这里应该用〈位〉。“把”用于有柄或可以握的物件，指人应用“位”。"}, {"text": "我们班的一本发言人是小王。", "explanation": "这里应该用〈位〉。“本”用于书籍等，指人不能用“本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93683, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们推选了一只发言人。", "corrected_sentence": "他们推选了一位发言人。", "error_description": "错误：量词“只”。“发言人”指人，量词应用“位”，“只”多用于动物，用在这里是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93683, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家推选了一台发言人，去和学校谈。", "corrected_sentence": "大家推选了一位发言人，去和学校谈。", "error_description": "错误：量词“台”。“台”用于机器等物件，指人应用“位”，用在这里是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
