INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93684, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "受机构或团体委托，代表其对外发表意见或消息的人。", "primary_collocate": null, "pronunciation": "fā yán rén", "ipa": "fa˥ jɛn˧˥ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "外交部发言人今天回答了记者的问题。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司发言人说，新产品下个月上市。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方发言人告诉记者，事情已经解决了。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的发言人没有回答问题。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队发言人说，那位球员没有受伤。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校发言人对记者说，明天不上课。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府发言人在电视上说了这件事。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院发言人说，病人现在很好。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问发言人，这件事是真的吗？", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是公司的新闻发言人，常和记者见面。", "target_word": "发言人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "新闻发言人", "label": "复合"}], "register": "中性", "sense_fingerprint": "机构或团体对外发布消息的官方代表", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65734415-928a-473e-bc99-3005a844ecdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93684, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食堂", "is_correct": false, "explanation": "语义：食堂是用餐的地方，不能回答记者的问题。"}, {"text": "胖子", "is_correct": false, "explanation": "语义：“胖子”描述外形，不是机构的职务，不能代表外交部回答问题。"}, {"text": "发言人", "is_correct": true, "explanation": "正确：“发言人”是机构对外发布消息的代表，能回答记者的问题，符合句意。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：司机不负责对外回答记者的问题，与“回答了记者的问题”不搭配。"}], "explanations": {"食堂": "语义：食堂是用餐的地方，不能回答记者的问题。", "胖子": "语义：“胖子”描述外形，不是机构的职务，不能代表外交部回答问题。", "发言人": "正确：“发言人”是机构对外发布消息的代表，能回答记者的问题，符合句意。", "司机": "搭配：司机不负责对外回答记者的问题，与“回答了记者的问题”不搭配。"}, "sentence_index": 0, "correct_answer": "发言人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的发言人决定了加薪的事。", "explanation": "这里应该用〈总裁〉。发言人只对外发布消息，不能决定公司内部的事。"}, {"text": "这家餐厅的发言人亲自下厨做了饭。", "explanation": "这里应该用〈厨师〉。发言人负责对外发布消息，下厨做饭是厨师的工作。"}, {"text": "这位发言人每天负责开车送大家上班。", "explanation": "这里应该用〈司机〉。发言人是对外发布消息的代表，开车接送是司机的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，不能在电视上代表政府发表意见。"}, {"text": "发言人", "is_correct": true, "explanation": "正确：“发言人”是政府对外发表意见的代表，在电视上说话符合句意。"}, {"text": "市民", "is_correct": false, "explanation": "搭配：“政府”后面应接公职人员，市民不是政府的对外代表。"}, {"text": "高个子", "is_correct": false, "explanation": "语义：“高个子”描述外形，不是政府的职务，不能代表政府发表意见。"}], "explanations": {"教室": "语义：教室是上课的地方，不能在电视上代表政府发表意见。", "发言人": "正确：“发言人”是政府对外发表意见的代表，在电视上说话符合句意。", "市民": "搭配：“政府”后面应接公职人员，市民不是政府的对外代表。", "高个子": "语义：“高个子”描述外形，不是政府的职务，不能代表政府发表意见。"}, "sentence_index": 6, "correct_answer": "发言人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "外交部的一只发言人今天回答了记者的问题。", "explanation": "这里应该用〈位〉。“只”多用于动物等，指人应用“位”。"}, {"text": "医院的一条发言人说，病人现在很好。", "explanation": "这里应该用〈位〉。“条”用于细长的东西，指人不能用“条”。"}, {"text": "球队的一把发言人说，那位球员没有受伤。", "explanation": "这里应该用〈位〉。“把”用于有柄的物件，指人不能用“把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医院的一只发言人今天接受了采访。", "corrected_sentence": "医院的一位发言人今天接受了采访。", "error_description": "错误：量词“只”。“发言人”指人，量词应用“位”，“只”不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府的一座发言人今天讲了话。", "corrected_sentence": "政府的一位发言人今天讲了话。", "error_description": "错误：量词“座”。“座”用于山、房屋等大型固定物，指人应用“位”，用在这里是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
