INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93685, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脚步是走路时，脚迈出的一步。", "primary_collocate": null, "pronunciation": "jiǎo bù", "ipa": "tɕjɑʊ˨˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "楼上的脚步很重，好像有人在跑。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脚步很轻，没有吵醒孩子。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到老师的脚步，大家马上坐好。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她放慢脚步，等着后面的朋友。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他停下脚步，回头看了看。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的脚步越来越慢。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我加快脚步，想赶上最后一班车。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听那脚步，我就知道是爸爸回来了。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她踏着轻快的脚步走进教室。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里很静，我只听得见自己的脚步。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "脚步声", "label": "复合"}], "register": "中性", "sense_fingerprint": "走路时脚迈出的一步，常指走路的动作和声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14564538-3a40-44fa-a32f-b1e6c7a259d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93685, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "脚步", "is_correct": true, "explanation": "正确。脚步（jiǎo bù）指走路时脚迈出的一步或脚步声。"}, {"text": "角度", "is_correct": false, "explanation": "角度（jiǎo dù）与脚步（jiǎo bù）只有第二个音节不同：dù 与 bù 声母不同（d/b），意思是角度。"}, {"text": "胶布", "is_correct": false, "explanation": "胶布（jiāo bù）与脚步（jiǎo bù）第一个音节声调不同（第一声与第三声），意思是胶布。"}, {"text": "剿捕", "is_correct": false, "explanation": "剿捕（jiǎo bǔ）与脚步（jiǎo bù）声母、韵母都相同，只有第二个音节声调不同（第三声与第四声），意思是围剿捉拿。"}], "explanations": {"脚步": "正确。脚步（jiǎo bù）指走路时脚迈出的一步或脚步声。", "角度": "角度（jiǎo dù）与脚步（jiǎo bù）只有第二个音节不同：dù 与 bù 声母不同（d/b），意思是角度。", "胶布": "胶布（jiāo bù）与脚步（jiǎo bù）第一个音节声调不同（第一声与第三声），意思是胶布。", "剿捕": "剿捕（jiǎo bǔ）与脚步（jiǎo bù）声母、韵母都相同，只有第二个音节声调不同（第三声与第四声），意思是围剿捉拿。"}, "sentence_index": null, "correct_answer": "脚步"}, "level_3": {"options": [{"text": "脚步", "is_correct": true, "explanation": "正确。“脚步很重”形容走路时脚发出的声响和动作，符合“好像有人在跑”的语境。"}, {"text": "行李", "is_correct": false, "explanation": "语义：“行李”是物品，不会在楼上跑动，与后半句“好像有人在跑”冲突。"}, {"text": "身影", "is_correct": false, "explanation": "体貌：“身影”描写人或物的外形轮廓，不能说“很重”，这种说法不通。"}, {"text": "台阶", "is_correct": false, "explanation": "搭配：“台阶”是建筑的组成部分，不说“很重”，与这一语境不搭配。"}], "explanations": {"脚步": "正确。“脚步很重”形容走路时脚发出的声响和动作，符合“好像有人在跑”的语境。", "行李": "语义：“行李”是物品，不会在楼上跑动，与后半句“好像有人在跑”冲突。", "身影": "体貌：“身影”描写人或物的外形轮廓，不能说“很重”，这种说法不通。", "台阶": "搭配：“台阶”是建筑的组成部分，不说“很重”，与这一语境不搭配。"}, "sentence_index": 0, "correct_answer": "脚步"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雪地上留下了一串脚步，一直通到门口。", "explanation": "这里应该用〈脚印〉。“脚步”指走路时迈出的一步，留在地上的痕迹要用“脚印”。"}, {"text": "这首歌的脚步很快，让人忍不住跳起舞来。", "explanation": "这里应该用〈节奏〉。“脚步”指走路时迈出的一步，说音乐的快慢要用“节奏”。"}, {"text": "这条河的脚步很急，不能下去游泳。", "explanation": "这里应该用〈水流〉。“脚步”指人走路迈出的一步，河水的流动要用“水流”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93685, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脚步", "is_correct": true, "explanation": "正确。“我加快脚步”指加快走路的动作，符合“想赶上最后一班车”的语境。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：“脚印”是留在地上的痕迹，不是动作，不能被“加快”。"}, {"text": "脚趾", "is_correct": false, "explanation": "搭配：“加快”不能用于“脚趾”这样的身体部位。"}, {"text": "小路", "is_correct": false, "explanation": "配价：“加快”需要动作或过程作宾语，“小路”是场所，不能被加快。"}], "explanations": {"脚步": "正确。“我加快脚步”指加快走路的动作，符合“想赶上最后一班车”的语境。", "脚印": "语义：“脚印”是留在地上的痕迹，不是动作，不能被“加快”。", "脚趾": "搭配：“加快”不能用于“脚趾”这样的身体部位。", "小路": "配价：“加快”需要动作或过程作宾语，“小路”是场所，不能被加快。"}, "sentence_index": 6, "correct_answer": "脚步"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的脚步很快，一下子就超过了前面的卡车。", "explanation": "这里应该用〈车速〉。“脚步”指走路时迈出的一步，车的快慢要用“车速”，不能用来形容车。"}, {"text": "这幅画的脚步很暖，看着让人觉得安心。", "explanation": "这里应该用〈色调〉。“脚步”指走路时迈出的一步，画面的色彩基调要用“色调”。"}, {"text": "这本书的脚步很厚，足有五百页。", "explanation": "这里应该用〈厚度〉。“脚步”指走路时迈出的一步，书的厚薄要用“厚度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "走廊里传来一只脚步。", "corrected_sentence": "走廊里传来一阵脚步。", "error_description": "量词错误：“脚步”作声音时用“阵”或“串”计量，不能用“只”。应说“一阵脚步”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93685, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他放慢了两只脚步，不想打扰孩子。", "corrected_sentence": "他放慢了脚步，不想打扰孩子。", "error_description": "量词错误：“脚步”不能用“只”计量。这里表示动作，不需要数量词，应说“放慢了脚步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
