INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93686, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "走路时两脚之间的距离；步子。", "primary_collocate": null, "pronunciation": "jiǎo bù", "ipa": "tɕjɑʊ˨˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷年纪大了，脚步迈得很小。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个子高，脚步比我大得多。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步时脚步要均匀，才不容易累。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们的脚步整齐，一点儿也不乱。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脚步很大，我得小跑才跟得上。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走路时脚步太大，容易摔倒。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小路很窄，脚步要迈小一点。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的脚步不大，但走得很稳。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家排成一队，脚步保持一致。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路不好走，脚步不能迈得太大。", "target_word": "脚步", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "脚步声", "label": "复合"}], "register": "中性", "sense_fingerprint": "走路时两脚之间的距离，步子的大小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14564538-3a40-44fa-a32f-b1e6c7a259d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93686, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "脚步", "is_correct": true, "explanation": "正确。脚步（jiǎo bù）指走路时两脚之间的距离，即步子。"}, {"text": "角度", "is_correct": false, "explanation": "角度（jiǎo dù）与脚步（jiǎo bù）只有第二个音节不同：dù 与 bù 声母不同（d/b），意思是角度。"}, {"text": "胶布", "is_correct": false, "explanation": "胶布（jiāo bù）与脚步（jiǎo bù）第一个音节声调不同（第一声与第三声），意思是胶布。"}, {"text": "剿捕", "is_correct": false, "explanation": "剿捕（jiǎo bǔ）与脚步（jiǎo bù）声母、韵母都相同，只有第二个音节声调不同（第三声与第四声），意思是围剿捉拿。"}], "explanations": {"脚步": "正确。脚步（jiǎo bù）指走路时两脚之间的距离，即步子。", "角度": "角度（jiǎo dù）与脚步（jiǎo bù）只有第二个音节不同：dù 与 bù 声母不同（d/b），意思是角度。", "胶布": "胶布（jiāo bù）与脚步（jiǎo bù）第一个音节声调不同（第一声与第三声），意思是胶布。", "剿捕": "剿捕（jiǎo bǔ）与脚步（jiǎo bù）声母、韵母都相同，只有第二个音节声调不同（第三声与第四声），意思是围剿捉拿。"}, "sentence_index": null, "correct_answer": "脚步"}, "level_3": {"options": [{"text": "脚步", "is_correct": true, "explanation": "正确。“脚步迈得很小”说明步子小，符合“年纪大了”的语境。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指身体的形状，不能用“迈”来描写，“身材迈得很小”说法不通。"}, {"text": "眼神", "is_correct": false, "explanation": "语义：“眼神”不会迈步，与“迈得很小”的动作相冲突。"}, {"text": "手臂", "is_correct": false, "explanation": "配价：“迈”的动作主体应是脚或腿，“手臂”不能作“迈”的主语。"}], "explanations": {"脚步": "正确。“脚步迈得很小”说明步子小，符合“年纪大了”的语境。", "身材": "体貌：“身材”指身体的形状，不能用“迈”来描写，“身材迈得很小”说法不通。", "眼神": "语义：“眼神”不会迈步，与“迈得很小”的动作相冲突。", "手臂": "配价：“迈”的动作主体应是脚或腿，“手臂”不能作“迈”的主语。"}, "sentence_index": 0, "correct_answer": "脚步"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个插座的脚步很高，碰一下会很危险。", "explanation": "这里应该用〈电压〉。“脚步”指两脚之间的距离，电的强弱要用“电压”。"}, {"text": "雪地上的脚步很深，一直通到山下。", "explanation": "这里应该用〈脚印〉。“脚步”指步子的大小，雪地上留下的痕迹要用“脚印”。"}, {"text": "他的脚步一直延伸到山脚下。", "explanation": "这里应该用〈踪迹〉。“脚步”指步子，不能“延伸”到远处；表示留下的路线要用“踪迹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脚步", "is_correct": true, "explanation": "正确。“脚步要迈小一点”指步子要小，与“小路很窄”的语境相符。"}, {"text": "路面", "is_correct": false, "explanation": "语义：“路面”是路的表面，不会迈步，与“迈小一点”相冲突。"}, {"text": "车轮", "is_correct": false, "explanation": "配价：“迈”的主体是人或脚，“车轮”不能作“迈”的主语。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”描述身体的高矮，不能与“迈小一点”搭配。"}], "explanations": {"脚步": "正确。“脚步要迈小一点”指步子要小，与“小路很窄”的语境相符。", "路面": "语义：“路面”是路的表面，不会迈步，与“迈小一点”相冲突。", "车轮": "配价：“迈”的主体是人或脚，“车轮”不能作“迈”的主语。", "身高": "搭配：“身高”描述身体的高矮，不能与“迈小一点”搭配。"}, "sentence_index": 6, "correct_answer": "脚步"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的脚步很高，我根本买不起。", "explanation": "这里应该用〈价格〉。“脚步”指走路时两脚之间的距离，衣服的价钱要用“价格”。"}, {"text": "这盏灯的脚步很低，房间里暗暗的。", "explanation": "这里应该用〈亮度〉。“脚步”指两脚之间的距离，灯光的明暗要用“亮度”。"}, {"text": "这杯水的脚步很高，还是等它凉一凉再喝。", "explanation": "这里应该用〈温度〉。“脚步”指两脚之间的距离，水的冷热要用“温度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的一只脚步迈得很大，一步就跨过了小水沟。", "corrected_sentence": "他的脚步迈得很大，一步就跨过了小水沟。", "error_description": "量词错误：“脚步”前不能用“一只”计量，应去掉“一只”，说“他的脚步”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下坡的时候，脚步要跑小一点。", "corrected_sentence": "下坡的时候，脚步要迈小一点。", "error_description": "搭配错误：“脚步”常与动词“迈”搭配，说“脚步迈小一点”，不能说“脚步跑小一点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
