INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93688, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "abstract", "definition": "数目，十个十。", "primary_collocate": null, "pronunciation": "bǎi", "ipa": "paɪ˨˩˦", "syllable_count": 1, "sentences": [{"text": "十个十是一百，我们先学会这个数。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从一数到一百，用了两分钟。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上放着一张一百块的钱。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明考试得了一百分，妈妈很高兴。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九十九再加一，就是一百。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路长一百米，我走了两分钟。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百减去五十，还剩五十。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年有三百六十五天，不是一百天。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离学校三百米，走路很近。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了三本书，一共花了一百块。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一百", "label": "复合"}], "register": "中性", "sense_fingerprint": "百：确切的数目一百，十个十", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd05d25bf-15fb-4699-a34e-f76e1fe1de8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93688, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "百", "is_correct": true, "explanation": "正确答案。百（bǎi）表示一百。"}, {"text": "白", "is_correct": false, "explanation": "bái（第二声）与 bǎi（第三声）声调不同，意思是白色。"}, {"text": "拜", "is_correct": false, "explanation": "bài（第四声）与 bǎi（第三声）声调不同，意思是拜访。"}, {"text": "板", "is_correct": false, "explanation": "bǎn 与 bǎi 韵母不同（-n 与 -i），意思是木板。"}], "explanations": {"百": "正确答案。百（bǎi）表示一百。", "白": "bái（第二声）与 bǎi（第三声）声调不同，意思是白色。", "拜": "bài（第四声）与 bǎi（第三声）声调不同，意思是拜访。", "板": "bǎn 与 bǎi 韵母不同（-n 与 -i），意思是木板。"}, "sentence_index": null, "correct_answer": "百"}, "level_3": {"options": [{"text": "百", "is_correct": true, "explanation": "正确答案。十个十就是一百。"}, {"text": "十", "is_correct": false, "explanation": "语义：十个十是一百，不是一十。"}, {"text": "千", "is_correct": false, "explanation": "语义：十个十是一百，不是一千。"}, {"text": "拾", "is_correct": false, "explanation": "语域：“拾”是票据上用的大写数字，口语中不用于此；而且十个十也不等于一拾。"}], "explanations": {"百": "正确答案。十个十就是一百。", "十": "语义：十个十是一百，不是一十。", "千": "语义：十个十是一百，不是一千。", "拾": "语域：“拾”是票据上用的大写数字，口语中不用于此；而且十个十也不等于一拾。"}, "sentence_index": 0, "correct_answer": "百"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家百货商店的东西很多，大家都爱来。", "explanation": "这里的“百”是“百货”的语素，指各种商品，不表示数目一百。"}, {"text": "这次会议来了上百个代表，很热闹。", "explanation": "这里的“上百”是概数，表示很多，与本词确切的数目“一百”不同。"}, {"text": "这次会议来了数百个代表，很热闹。", "explanation": "这里的“数百”是概数，表示几百，与本词确切的数目“一百”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93688, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "百", "is_correct": true, "explanation": "正确答案。百（bǎi）表示一百。"}, {"text": "宝", "is_correct": false, "explanation": "bǎo 与 bǎi 韵母不同（-o 与 -i），意思是宝贝。"}, {"text": "买", "is_correct": false, "explanation": "mǎi 与 bǎi 声母不同（m 与 b），意思是购买。"}, {"text": "败", "is_correct": false, "explanation": "bài（第四声）与 bǎi（第三声）声调不同，意思是失败。"}], "explanations": {"百": "正确答案。百（bǎi）表示一百。", "宝": "bǎo 与 bǎi 韵母不同（-o 与 -i），意思是宝贝。", "买": "mǎi 与 bǎi 声母不同（m 与 b），意思是购买。", "败": "bài（第四声）与 bǎi（第三声）声调不同，意思是失败。"}, "sentence_index": null, "correct_answer": "百"}, "level_3": {"options": [{"text": "百", "is_correct": true, "explanation": "正确答案。一百减五十等于五十。"}, {"text": "万", "is_correct": false, "explanation": "语义：一万减去五十不等于五十，数目不对。"}, {"text": "亿", "is_correct": false, "explanation": "语义：一亿减去五十仍然很大，不能还剩五十。"}, {"text": "仟", "is_correct": false, "explanation": "语域：“仟”是票据用的大写数字，口语不用；而且“一仟”指一千，减五十不剩五十。"}], "explanations": {"百": "正确答案。一百减五十等于五十。", "万": "语义：一万减去五十不等于五十，数目不对。", "亿": "语义：一亿减去五十仍然很大，不能还剩五十。", "仟": "语域：“仟”是票据用的大写数字，口语不用；而且“一仟”指一千，减五十不剩五十。"}, "sentence_index": 6, "correct_answer": "百"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了三本书，一共花了几百块。", "explanation": "这里的“几百”是概数，表示几个百，与本词确切的“一百”不同。"}, {"text": "他买了三本书，一共花了好几百块。", "explanation": "这里的“好几百”是概数，表示较多，与本词确切的“一百”不同。"}, {"text": "他买了三本书，一共只花了原价的百分之六十。", "explanation": "这里的“百分之”表示比例，“百”不表示数目一百。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个班有一百一个学生，都很认真。", "corrected_sentence": "这个班有一百零一个学生，都很认真。", "error_description": "数词错误：“一百零一”中的“零”不能省，说“一百一个”会被理解为错误的数目，应说“一百零一个学生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二班有一个百人参加了比赛。", "corrected_sentence": "二班有一百个人参加了比赛。", "error_description": "数词语序错误：“一百个”不能说成“一个百”，应说“一百个人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93689, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收缩", "is_correct": true, "explanation": "正确。“收缩”与“膨胀”互为反义词，指体积变小。"}, {"text": "扩大", "is_correct": false, "explanation": "“扩大”与“膨胀”同义，表示范围或体积变大，不是反义词。"}, {"text": "发酵", "is_correct": false, "explanation": "“发酵”是面团产生气体而变大的过程，与“膨胀”相关但不是反义词。"}, {"text": "增长", "is_correct": false, "explanation": "“增长”与“膨胀”同义，都指数量或体积变多，不是反义词。"}], "correct_answer": "收缩", "explanations": {"收缩": "正确。“收缩”与“膨胀”互为反义词，指体积变小。", "扩大": "“扩大”与“膨胀”同义，表示范围或体积变大，不是反义词。", "发酵": "“发酵”是面团产生气体而变大的过程，与“膨胀”相关但不是反义词。", "增长": "“增长”与“膨胀”同义，都指数量或体积变多，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93689, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收缩", "is_correct": true, "explanation": "正确。“收缩”与“膨胀”互为反义词，指体积变小。"}, {"text": "变软", "is_correct": false, "explanation": "“变软”指质地变得柔软，不是“膨胀”的反义词。"}, {"text": "上升", "is_correct": false, "explanation": "“上升”表示数量增加，与“膨胀”方向一致，不是反义词。"}, {"text": "维持", "is_correct": false, "explanation": "“维持”表示保持不变，不是“膨胀”的反义词。"}], "correct_answer": "收缩", "explanations": {"收缩": "正确。“收缩”与“膨胀”互为反义词，指体积变小。", "变软": "“变软”指质地变得柔软，不是“膨胀”的反义词。", "上升": "“上升”表示数量增加，与“膨胀”方向一致，不是反义词。", "维持": "“维持”表示保持不变，不是“膨胀”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93689, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "膨胀是东西变大、变鼓起来。", "primary_collocate": null, "pronunciation": "péng zhàng", "ipa": "pʰɤŋ˨˦ ʈʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "把气球放在太阳下面，它会慢慢膨胀。", "target_word": "膨胀", "sentence_source": "generated"}, {"text": "海绵泡在水里，很快就膨胀了。", "target_word": "膨胀", "sentence_source": "generated"}, {"text": "干香菇放进热水里会膨胀变大。", "target_word": "膨胀", "sentence_source": "generated"}, {"text": "面包放进烤箱以后，慢慢膨胀起来。", "target_word": "膨胀", "sentence_source": "generated"}, {"text": "米饭煮好后，米粒膨胀得又软又大。", "target_word": "膨胀", "sentence_source": "generated"}, {"text": "他吃得太饱，肚子膨胀得像个鼓。", "target_word": "膨胀", "sentence_source": "generated"}, {"text": "夏天太热，轮胎里的气会膨胀，要小心。", "target_word": "膨胀", "sentence_source": "generated"}, {"text": "河豚一生气，身体就会膨胀成球。", "target_word": "膨胀", "sentence_source": "generated"}, {"text": "冰变成水会缩小，水结成冰却会膨胀。", "target_word": "膨胀", "sentence_source": "generated"}, {"text": "豆子泡了一夜，已经膨胀了一倍。", "target_word": "膨胀", "sentence_source": "generated"}], "morphological_forms": [{"form": "膨胀了", "label": "体标（了）"}, {"form": "膨胀过", "label": "体标（过）"}, {"form": "膨脹", "label": "繁体"}], "register": "中性", "sense_fingerprint": "具体物体吸水、受热后变大鼓起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14564538-3a40-44fa-a32f-b1e6c7a259d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93689, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷却", "is_correct": false, "explanation": "语义：“冷却”表示降温，与“放在太阳下面”的受热条件冲突。"}, {"text": "膨胀", "is_correct": true, "explanation": "正确。“慢慢膨胀”指受热后体积变大，符合“放在太阳下面”的语境。"}, {"text": "碎裂", "is_correct": false, "explanation": "语义：“碎裂”指突然断成碎片，与“慢慢”的渐变过程不符。"}, {"text": "凝固", "is_correct": false, "explanation": "搭配：“凝固”指液体变成固体，气球里的空气不会“凝固”。"}], "explanations": {"冷却": "语义：“冷却”表示降温，与“放在太阳下面”的受热条件冲突。", "膨胀": "正确。“慢慢膨胀”指受热后体积变大，符合“放在太阳下面”的语境。", "碎裂": "语义：“碎裂”指突然断成碎片，与“慢慢”的渐变过程不符。", "凝固": "搭配：“凝固”指液体变成固体，气球里的空气不会“凝固”。"}, "sentence_index": 0, "correct_answer": "膨胀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冰块在阳光下慢慢膨胀，最后变成了一摊水。", "explanation": "这里应该用〈融化〉。冰块受热变成水是固体变液体，不是体积变大，“膨胀”不能表示这个变化。"}, {"text": "这张照片可以膨胀到一米宽。", "explanation": "这里应该用〈放大〉。“膨胀”指物体因受热、吸水等体积自然变大，照片的尺寸扩大要用“放大”。"}, {"text": "这棵小树一年膨胀了两米。", "explanation": "这里应该用〈长高〉。“膨胀”说的是体积增大，树的高度增加要用“长高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93689, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降温", "is_correct": false, "explanation": "语义：“降温”与“夏天太热”的语境相反，不符合常理。"}, {"text": "膨胀", "is_correct": true, "explanation": "正确。“会膨胀”指受热后气体体积变大，与“夏天太热”的语境相符。"}, {"text": "液化", "is_correct": false, "explanation": "语义：气体在高温下不会液化，“液化”与“夏天太热”的语境冲突。"}, {"text": "结冰", "is_correct": false, "explanation": "搭配：“结冰”指水变成冰，轮胎里的气不会“结冰”。"}], "explanations": {"降温": "语义：“降温”与“夏天太热”的语境相反，不符合常理。", "膨胀": "正确。“会膨胀”指受热后气体体积变大，与“夏天太热”的语境相符。", "液化": "语义：气体在高温下不会液化，“液化”与“夏天太热”的语境冲突。", "结冰": "搭配：“结冰”指水变成冰，轮胎里的气不会“结冰”。"}, "sentence_index": 6, "correct_answer": "膨胀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "轮胎扎了个洞，慢慢膨胀了下去。", "explanation": "这里应该用〈瘪〉。“膨胀”指物体体积变大、鼓起来，轮胎漏气后慢慢变瘪，不能说膨胀。"}, {"text": "气球放掉了气，变得又膨胀又软。", "explanation": "这里应该用〈扁〉。“膨胀”指物体变大、鼓起来，气球放气后变扁，要用“扁”。"}, {"text": "这根蜡烛烧了一夜，变得越来越膨胀。", "explanation": "这里应该用〈短〉。“膨胀”指体积变大，蜡烛烧短要用“变短”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93689, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气一热，气球就被膨胀起来。", "corrected_sentence": "天气一热，气球就膨胀起来。", "error_description": "“膨胀”是不及物动词，不能用“被”字句，应说“气球膨胀起来”，不能说“气球被膨胀起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93689, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏天太热，轮胎里的气会膨胀很厉害。", "corrected_sentence": "夏天太热，轮胎里的气会膨胀得很厉害。", "error_description": "“膨胀”后面带程度补语时要用“得”连接，应说“膨胀得很厉害”，省略“得”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
