INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93691, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93691, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "皮是包在人、动物或水果外面的一层。", "primary_collocate": null, "pronunciation": "pí", "ipa": "pʰi˧˥", "syllable_count": 1, "sentences": [{"text": "这个苹果的皮很薄，不用削。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃橘子以前，先把皮剥开。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香蕉的皮是黄色的，里面是白色的。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西瓜的皮很厚，里面的肉很甜。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条蛇的皮上有漂亮的花纹。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用刀把土豆的皮削掉了。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洋葱的皮一层一层的，剥着剥着我就哭了。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种葡萄的皮有点酸，我不吃皮。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摔了一跤，膝盖上的皮破了。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳太大，她背上的皮都晒红了。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "层", "label": "量词"}, {"form": "张", "label": "量词"}, {"form": "橘子皮", "label": "复合词"}], "register": "中性", "sense_fingerprint": "皮：包在水果、动物或人外面的一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb8dd41a-3ee5-4ea6-a6a8-3eb267922083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93691, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "皮", "is_correct": true, "explanation": "正确：皮（pí）指包在人、动物或水果外面的一层。"}, {"text": "批", "is_correct": false, "explanation": "pī（第一声）与 pí（第二声）声调不同，意思是批（批评、批准）。"}, {"text": "披", "is_correct": false, "explanation": "pī（第一声）与 pí（第二声）声调不同，意思是披（披在身上）。"}, {"text": "迷", "is_correct": false, "explanation": "mí 与 pí 声母不同（m 与 p），意思是迷（迷路、迷恋）。"}, {"text": "贫", "is_correct": false, "explanation": "pín 比 pí 多一个鼻音 n，韵母不同，意思是贫（贫穷）。"}, {"text": "匹", "is_correct": false, "explanation": "pǐ（第三声）与 pí（第二声）声调不同，意思是匹（量词，如一匹马）。"}], "explanations": {"皮": "正确：皮（pí）指包在人、动物或水果外面的一层。", "批": "pī（第一声）与 pí（第二声）声调不同，意思是批（批评、批准）。", "披": "pī（第一声）与 pí（第二声）声调不同，意思是披（披在身上）。", "迷": "mí 与 pí 声母不同（m 与 p），意思是迷（迷路、迷恋）。", "贫": "pín 比 pí 多一个鼻音 n，韵母不同，意思是贫（贫穷）。", "匹": "pǐ（第三声）与 pí（第二声）声调不同，意思是匹（量词，如一匹马）。"}, "sentence_index": null, "correct_answer": "皮"}, "level_3": {"options": [{"text": "皮", "is_correct": true, "explanation": "正确：皮指苹果外面的一层，可以削掉，与“很薄，不用削”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能说薄厚，“薄”不能修饰颜色。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”可以说淡、浓，不能说薄。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字与苹果的薄厚无关，且名字不用削，句子说不通。"}], "explanations": {"皮": "正确：皮指苹果外面的一层，可以削掉，与“很薄，不用削”相符。", "颜色": "搭配：“颜色”不能说薄厚，“薄”不能修饰颜色。", "味道": "搭配：“味道”可以说淡、浓，不能说薄。", "名字": "语义：名字与苹果的薄厚无关，且名字不用削，句子说不通。"}, "sentence_index": 0, "correct_answer": "皮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "乌龟的皮很硬，谁也打不破。", "explanation": "这里应该用〈壳〉。皮指包在外面的一层组织，乌龟坚硬的背甲应说壳。"}, {"text": "我买了一只狗皮，准备做手套。", "explanation": "这里量词应该用〈张〉。成片的兽皮要用张，“只”用于活的或单个的动物。"}, {"text": "这台冰箱的皮很亮，我每天都擦。", "explanation": "这里应该用〈外壳〉。皮指包在人、动物或水果外面的一层，冰箱的外壳不叫皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93691, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "皮", "is_correct": true, "explanation": "正确：皮（pí）指包在人、动物或水果外面的一层。"}, {"text": "鼻", "is_correct": false, "explanation": "bí 与 pí 声母不同（b 与 p），意思是鼻（鼻子）。"}, {"text": "泥", "is_correct": false, "explanation": "ní 与 pí 声母不同（n 与 p），意思是泥（泥土）。"}, {"text": "劈", "is_correct": false, "explanation": "pī（第一声）与 pí（第二声）声调不同，意思是劈（用刀斧分开）。"}], "explanations": {"皮": "正确：皮（pí）指包在人、动物或水果外面的一层。", "鼻": "bí 与 pí 声母不同（b 与 p），意思是鼻（鼻子）。", "泥": "ní 与 pí 声母不同（n 与 p），意思是泥（泥土）。", "劈": "pī（第一声）与 pí（第二声）声调不同，意思是劈（用刀斧分开）。"}, "sentence_index": null, "correct_answer": "皮"}, "level_3": {"options": [{"text": "皮", "is_correct": true, "explanation": "正确：皮指洋葱外面一层一层的部分，与“一层一层的”“剥着哭”相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格没有一层一层的，与剥洋葱哭无关。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”不能用“一层一层的”来形容。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：亮度不能一层一层地剥，与剥洋葱哭无关。"}], "explanations": {"皮": "正确：皮指洋葱外面一层一层的部分，与“一层一层的”“剥着哭”相符。", "价格": "语义：价格没有一层一层的，与剥洋葱哭无关。", "重量": "搭配：“重量”不能用“一层一层的”来形容。", "亮度": "语义：亮度不能一层一层地剥，与剥洋葱哭无关。"}, "sentence_index": 6, "correct_answer": "皮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆汽车的皮很薄，一碰就坏。", "explanation": "这里应该用〈车身〉。皮指包在人、动物或水果外面的一层，汽车的外面要说车身。"}, {"text": "这只羊的皮很长，冬天很暖和。", "explanation": "这里应该用〈毛〉。羊身上长而密的毛要说毛，皮不说长。"}, {"text": "这块玻璃的皮很光滑，摸起来很舒服。", "explanation": "这里应该用〈表面〉。皮指包在人、动物或水果外面的一层，玻璃的表面要说表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93691, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我削掉了一只苹果皮。", "corrected_sentence": "我削掉了一层苹果皮。", "error_description": "表示一层果皮，量词应用“层”，错误形式用了“只”。“只”多用于单个的物品或活的动物，不用于薄薄的果皮，应说“一层苹果皮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93691, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他脚上皮磨破了。", "corrected_sentence": "他脚上的皮磨破了。", "error_description": "“脚上”修饰“皮”时，中间要加“的”。错误形式省掉了“的”，应说“脚上的皮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93692, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93692, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93692, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "包在人体、动植物体表面的一层组织；也指物体的表面。", "primary_collocate": null, "pronunciation": "pí", "ipa": "pʰi˧˥", "syllable_count": 1, "sentences": [{"text": "冬天风大，我脸上的皮很干。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩的皮很嫩，要多保护。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树的皮很粗，摸起来不平。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晒伤以后，我肩膀上的皮掉了一层。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西红柿的皮很薄，用热水一烫就掉了。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球的皮破了，里面没有气了。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "橙子的皮很厚，剥起来有点难。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象的皮很厚，摸起来很硬。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气干燥，他手上的皮都裂了。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个苹果的皮很光滑，摸起来很舒服。", "target_word": "皮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "层", "label": "量词"}, {"form": "张", "label": "量词"}, {"form": "树皮", "label": "复合词"}], "register": "中性", "sense_fingerprint": "皮：人体、动植物体表的一层组织，也指物体的表面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb8dd41a-3ee5-4ea6-a6a8-3eb267922083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93692, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "皮", "is_correct": true, "explanation": "正确：皮（pí）指人体、动植物体表的一层组织，也指物体表面。"}, {"text": "批", "is_correct": false, "explanation": "pī（第一声）与 pí（第二声）声调不同，意思是批（批评、批准）。"}, {"text": "披", "is_correct": false, "explanation": "pī（第一声）与 pí（第二声）声调不同，意思是披（披在身上）。"}, {"text": "迷", "is_correct": false, "explanation": "mí 与 pí 声母不同（m 与 p），意思是迷（迷路、迷恋）。"}, {"text": "贫", "is_correct": false, "explanation": "pín 比 pí 多一个鼻音 n，韵母不同，意思是贫（贫穷）。"}, {"text": "匹", "is_correct": false, "explanation": "pǐ（第三声）与 pí（第二声）声调不同，意思是匹（量词，如一匹马）。"}], "explanations": {"皮": "正确：皮（pí）指人体、动植物体表的一层组织，也指物体表面。", "批": "pī（第一声）与 pí（第二声）声调不同，意思是批（批评、批准）。", "披": "pī（第一声）与 pí（第二声）声调不同，意思是披（披在身上）。", "迷": "mí 与 pí 声母不同（m 与 p），意思是迷（迷路、迷恋）。", "贫": "pín 比 pí 多一个鼻音 n，韵母不同，意思是贫（贫穷）。", "匹": "pǐ（第三声）与 pí（第二声）声调不同，意思是匹（量词，如一匹马）。"}, "sentence_index": null, "correct_answer": "皮"}, "level_3": {"options": [{"text": "皮", "is_correct": true, "explanation": "正确：皮指脸上的表层组织，冬天风大会让它变干，与句意相符。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字与脸的干燥无关，句子说的是脸上的皮。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能说干，与脸的状态无关。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”不能说干，只能说轻、重。"}], "explanations": {"皮": "正确：皮指脸上的表层组织，冬天风大会让它变干，与句意相符。", "名字": "语义：名字与脸的干燥无关，句子说的是脸上的皮。", "价格": "语义：价格不能说干，与脸的状态无关。", "重量": "搭配：“重量”不能说干，只能说轻、重。"}, "sentence_index": 0, "correct_answer": "皮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晒伤以后，我肩膀上掉了一只皮。", "explanation": "这里量词应该用〈层〉。皮屑、皮层用层，“只”用于活的或单个的动物。"}, {"text": "这只猫的皮很长，摸起来很软。", "explanation": "这里应该用〈毛〉。猫身上的长毛要用毛，皮不能说长。"}, {"text": "这条河的皮很干净，我们常在里面游泳。", "explanation": "这里应该用〈河面〉。皮指包在体表或物体表面的一层，河水的表面要说河面，不说皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93692, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "皮", "is_correct": true, "explanation": "正确：皮（pí）指人体、动植物体表的一层组织，也指物体表面。"}, {"text": "鼻", "is_correct": false, "explanation": "bí 与 pí 声母不同（b 与 p），意思是鼻（鼻子）。"}, {"text": "泥", "is_correct": false, "explanation": "ní 与 pí 声母不同（n 与 p），意思是泥（泥土）。"}, {"text": "劈", "is_correct": false, "explanation": "pī（第一声）与 pí（第二声）声调不同，意思是劈（用刀斧分开）。"}], "explanations": {"皮": "正确：皮（pí）指人体、动植物体表的一层组织，也指物体表面。", "鼻": "bí 与 pí 声母不同（b 与 p），意思是鼻（鼻子）。", "泥": "ní 与 pí 声母不同（n 与 p），意思是泥（泥土）。", "劈": "pī（第一声）与 pí（第二声）声调不同，意思是劈（用刀斧分开）。"}, "sentence_index": null, "correct_answer": "皮"}, "level_3": {"options": [{"text": "皮", "is_correct": true, "explanation": "正确：皮指橙子表面的一层，可以剥，很厚，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色可以说深浅，不能说厚，也不能剥。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能说厚，也不能剥。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：年纪与橙子的厚薄、剥无关，句子说不通。"}], "explanations": {"皮": "正确：皮指橙子表面的一层，可以剥，很厚，与句意相符。", "颜色": "搭配：颜色可以说深浅，不能说厚，也不能剥。", "价格": "语义：价格不能说厚，也不能剥。", "年纪": "语义：年纪与橙子的厚薄、剥无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "皮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只螃蟹的皮很硬，夹人很疼。", "explanation": "这里应该用〈壳〉。螃蟹身上坚硬的外壳要用壳，皮指包在体表的组织，不指硬壳。"}, {"text": "他摔倒以后，皮断了，要去医院接一下。", "explanation": "这里应该用〈骨头〉。皮是体表的一层组织，摔倒后断的是骨头，不说皮断了。"}, {"text": "蝴蝶的皮很薄，很漂亮。", "explanation": "这里应该用〈翅膀〉。蝴蝶薄薄的、能飞的部分是翅膀，不是皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我肩膀上掉了一个皮。", "corrected_sentence": "我肩膀上掉了一层皮。", "error_description": "表示脱落的一层皮屑，量词应用“层”，错误形式用了“个”。“个”是通用量词，不能用来计量这种成层的皮，应说“一层皮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他手上皮裂开了。", "corrected_sentence": "他手上的皮裂开了。", "error_description": "“手上”修饰“皮”时，中间要加“的”。错误形式省掉了“的”，应说“手上的皮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
