INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93693, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自媒体是自己在网上发文字、照片、视频给大家看。", "primary_collocate": null, "pronunciation": "zì méi tǐ", "ipa": "tsɨ⁵¹ meɪ³⁵ tʰi²¹⁴", "syllable_count": 3, "sentences": [{"text": "她做自媒体，每天发视频。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想做自媒体，给大家看我的生活。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多年轻人都喜欢做自媒体。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做自媒体不容易，要天天写文章。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他靠自媒体认识了很多朋友。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李毕业后决定专心做自媒体。", "target_word": "自媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥白天上班，晚上做自媒体。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做自媒体的人要会拍照，也要会写字。", "target_word": "自媒体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边上学，一边做自媒体。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人因为做自媒体，学会了拍照和剪辑。", "target_word": "自媒体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "自媒體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "个人在网上自己发内容的做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06f273b2-8ada-4e9a-bf00-a5ca09e322b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93693, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自媒体", "is_correct": true, "explanation": "自媒体：个人在网上自己发内容的做法，“她做自媒体，每天发视频”句意通顺。"}, {"text": "梦", "is_correct": false, "explanation": "语义：梦不能每天拿来发视频，“她做梦，每天发视频”讲不通。"}, {"text": "噩梦", "is_correct": false, "explanation": "语义：噩梦是睡觉时做的内容，不能每天发视频。"}, {"text": "客", "is_correct": false, "explanation": "搭配：“做客”指当客人，与“每天发视频”搭配不通。"}], "explanations": {"自媒体": "自媒体：个人在网上自己发内容的做法，“她做自媒体，每天发视频”句意通顺。", "梦": "语义：梦不能每天拿来发视频，“她做梦，每天发视频”讲不通。", "噩梦": "语义：噩梦是睡觉时做的内容，不能每天发视频。", "客": "搭配：“做客”指当客人，与“每天发视频”搭配不通。"}, "sentence_index": 0, "correct_answer": "自媒体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都用自媒体打扫房间。", "explanation": "这里应该用〈扫帚〉。自媒体是做事的方式，不能用来打扫房间，应说用扫帚。"}, {"text": "自媒体在车间里装配汽车。", "explanation": "这里应该用〈工人〉。自媒体是个人在网上发布内容的方式或账号，不会在车间里装配汽车；做这种事的应该是工人。"}, {"text": "他用自媒体把门锁上了。", "explanation": "这里应该用〈钥匙〉。自媒体是在网上发内容的做法，不能用来锁门，锁门要用钥匙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93693, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自媒体", "is_correct": true, "explanation": "自媒体：个人在网上自己发内容的做法，“晚上做自媒体”句意通顺。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以去“做”的对象，“晚上做天空”讲不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是可以去“做”的对象，“晚上做月亮”讲不通。"}, {"text": "母亲", "is_correct": false, "explanation": "搭配：“做母亲”是身份，不是晚上可以去做的活动，与“晚上做”搭配不通。"}], "explanations": {"自媒体": "自媒体：个人在网上自己发内容的做法，“晚上做自媒体”句意通顺。", "天空": "语义：天空不是可以去“做”的对象，“晚上做天空”讲不通。", "月亮": "语义：月亮不是可以去“做”的对象，“晚上做月亮”讲不通。", "母亲": "搭配：“做母亲”是身份，不是晚上可以去做的活动，与“晚上做”搭配不通。"}, "sentence_index": 6, "correct_answer": "自媒体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我哥哥把自媒体放进书包里带去学校了。", "explanation": "这里应该用〈作业〉。自媒体是做事的方式，不能装进书包，应说把作业放进书包。"}, {"text": "我哥哥把自媒体穿在身上去上学了。", "explanation": "这里应该用〈衣服〉。自媒体是做事的方式，不能穿在身上，应说穿衣服。"}, {"text": "我哥哥白天睡觉，晚上把自媒体吃掉了。", "explanation": "这里应该用〈饭〉。自媒体是做事的方式，不能吃，应说把饭吃掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93693, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前做了过自媒体。", "corrected_sentence": "我以前做过自媒体。", "error_description": "体标重复：“过”表示曾经做过，不能与“了”同用，应说“做过自媒体”，不说“做了过自媒体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93693, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥做自媒体做很好。", "corrected_sentence": "哥哥做自媒体做得很好。", "error_description": "补语标记缺失：“做”后面的补语要用“得”引出，应说“做得很好”，漏掉“得”就不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
