INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93694, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "个人通过网络平台自主发布信息的传播方式或账号。", "primary_collocate": null, "pronunciation": "zì méi tǐ", "ipa": "tsɨ⁵¹ meɪ³⁵ tʰi²¹⁴", "syllable_count": 3, "sentences": [{"text": "这个自媒体有一百万个粉丝。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我关注了一个做美食的自媒体。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的自媒体每周更新两次。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个自媒体的文章写得很有意思。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她开了一个自媒体，专门讲历史。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个旅行自媒体今天发了新视频。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每天都看这个自媒体的消息。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个自媒体是几个大学生一起办的。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己的自媒体名字改了。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "许多人觉得这个自媒体讲得很清楚。", "target_word": "自媒体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "自媒體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "个人在网络平台上运营的账号或频道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06f273b2-8ada-4e9a-bf00-a5ca09e322b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自媒体", "is_correct": true, "explanation": "自媒体：个人在网络平台上运营的账号，“这个自媒体有一百万个粉丝”句意通顺。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不能拥有粉丝，句子讲不通。"}, {"text": "餐桌", "is_correct": false, "explanation": "语义：餐桌不能拥有粉丝，句子讲不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“有……粉丝”的主语应是账号或人，“冰箱”与之搭配不通。"}], "explanations": {"自媒体": "自媒体：个人在网络平台上运营的账号，“这个自媒体有一百万个粉丝”句意通顺。", "雨伞": "语义：雨伞不能拥有粉丝，句子讲不通。", "餐桌": "语义：餐桌不能拥有粉丝，句子讲不通。", "冰箱": "搭配：“有……粉丝”的主语应是账号或人，“冰箱”与之搭配不通。"}, "sentence_index": 0, "correct_answer": "自媒体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个自媒体有四个轮子，跑得很快。", "explanation": "这里应该用〈汽车〉。自媒体是网上的账号或传播方式，没有轮子，有四个轮子的是汽车。"}, {"text": "这个自媒体昨天判了他三年徒刑。", "explanation": "这里应该用〈法院〉。判刑只能由法院做出，自媒体是账号或传播方式，不能判人刑罚。"}, {"text": "这个自媒体有十张床。", "explanation": "这里应该用〈病房〉。自媒体是账号或传播方式，不会有床，说床要用病房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自媒体", "is_correct": true, "explanation": "自媒体：个人在网络平台上运营的账号，“我每天都看这个自媒体的消息”句意通顺。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会发布消息，“看……的消息”讲不通。"}, {"text": "枕头", "is_correct": false, "explanation": "语义：枕头不会发布消息，句子讲不通。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“……的消息”要有信息来源，厨房不能作为消息的来源。"}], "explanations": {"自媒体": "自媒体：个人在网络平台上运营的账号，“我每天都看这个自媒体的消息”句意通顺。", "椅子": "语义：椅子不会发布消息，“看……的消息”讲不通。", "枕头": "语义：枕头不会发布消息，句子讲不通。", "厨房": "搭配：“……的消息”要有信息来源，厨房不能作为消息的来源。"}, "sentence_index": 6, "correct_answer": "自媒体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把自媒体讲得很清楚。", "explanation": "这里应该用〈个〉。“把”用于有柄的东西，自媒体不能用“把”来数。"}, {"text": "这支自媒体讲得很清楚。", "explanation": "这里应该用〈个〉。“支”用于笔、棍子等细长的东西，自媒体不能用“支”来数。"}, {"text": "这头自媒体讲得很清楚。", "explanation": "这里应该用〈个〉。“头”用于牛、猪等牲畜，自媒体不能用“头”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个自媒体做很好。", "corrected_sentence": "这个自媒体做得很好。", "error_description": "补语标记缺失：“做”后面要用“得”引出补语，应说“做得很好”，漏掉“得”就不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我这个自媒体学到了很多东西。", "corrected_sentence": "我从这个自媒体学到了很多东西。", "error_description": "介词缺失：表示来源要用“从”引出，应说“从这个自媒体学到”，漏掉“从”就不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93698, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "跟团游", "is_correct": true, "explanation": "反义：“跟团游”由旅行社统一安排行程，与“自由行”自己安排行程相反。"}, {"text": "导游", "is_correct": false, "explanation": "导游是带团讲解的人，不是旅游方式，与“自由行”不构成反义。"}, {"text": "游客", "is_correct": false, "explanation": "游客指旅行的人，与“自由行”这种旅行方式不构成反义。"}, {"text": "机票", "is_correct": false, "explanation": "机票是乘机凭证，与“自由行”不构成反义。"}], "correct_answer": "跟团游", "explanations": {"跟团游": "反义：“跟团游”由旅行社统一安排行程，与“自由行”自己安排行程相反。", "导游": "导游是带团讲解的人，不是旅游方式，与“自由行”不构成反义。", "游客": "游客指旅行的人，与“自由行”这种旅行方式不构成反义。", "机票": "机票是乘机凭证，与“自由行”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93698, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "跟团游", "is_correct": true, "explanation": "反义：“跟团游”由旅行社统一安排行程，与“自由行”自己安排行程相反。"}, {"text": "旅行社", "is_correct": false, "explanation": "旅行社是提供旅游服务的机构，不是旅游方式，与“自由行”不构成反义。"}, {"text": "地图", "is_correct": false, "explanation": "地图是出行时使用的工具，与“自由行”不构成反义。"}, {"text": "酒店", "is_correct": false, "explanation": "酒店是住宿场所，与“自由行”不构成反义。"}], "correct_answer": "跟团游", "explanations": {"跟团游": "反义：“跟团游”由旅行社统一安排行程，与“自由行”自己安排行程相反。", "旅行社": "旅行社是提供旅游服务的机构，不是旅游方式，与“自由行”不构成反义。", "地图": "地图是出行时使用的工具，与“自由行”不构成反义。", "酒店": "酒店是住宿场所，与“自由行”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93698, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不随团、由游客自行安排行程的旅游方式。", "primary_collocate": null, "pronunciation": "zì yóu xíng", "ipa": "tsɨ˥˩ joʊ˧˥ ɕiŋ˧˥", "syllable_count": 3, "sentences": [{"text": "今年我不想跟团，想去日本自由行。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由行的好处是可以自己决定每天去哪里。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这次去泰国是自由行，不是跟团。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由行没有导游，所以要自己看地图。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢自由行，因为不用跟着团队赶路。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加自由行的游客要自己订酒店和机票。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起跟团，爸爸更喜欢自由行。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由行的行程由游客自己安排，时间很灵活。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一家人去台湾自由行，玩了七天。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次自由行时，我在车站迷了路。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "自由行游客", "label": "复合"}], "register": "中性", "sense_fingerprint": "旅游方式：不跟团，游客自己安排行程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a9ccfdf-6e54-4f66-b305-2e8ae631542e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自由行", "is_correct": true, "explanation": "正确：“自由行”指自己安排行程的旅行，与前句“不想跟团”形成对照。"}, {"text": "跟团游", "is_correct": false, "explanation": "语义：“跟团游”就是跟着旅行团走，与前句“不想跟团”直接矛盾。"}, {"text": "团购", "is_correct": false, "explanation": "语义：“团购”指多人一起买东西，去日本不能说团购。"}, {"text": "游客", "is_correct": false, "explanation": "搭配：“去”后接地点或活动，“游客”指人，不能作“去日本”的宾语。"}], "explanations": {"自由行": "正确：“自由行”指自己安排行程的旅行，与前句“不想跟团”形成对照。", "跟团游": "语义：“跟团游”就是跟着旅行团走，与前句“不想跟团”直接矛盾。", "团购": "语义：“团购”指多人一起买东西，去日本不能说团购。", "游客": "搭配：“去”后接地点或活动，“游客”指人，不能作“去日本”的宾语。"}, "sentence_index": 0, "correct_answer": "自由行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们这次去泰国是一只自由行，玩了三个城市。", "explanation": "这里量词用错了。“只”用于动物，不能修饰“自由行”；说“自由行”应该用量词“次”，如“一次自由行”。"}, {"text": "妈妈想报名参加一座自由行，去看看那边的山。", "explanation": "这里量词用错了。“座”用于山、房屋等大型固定物，不能修饰“自由行”，应说“一次自由行”。"}, {"text": "机器人能在房间里自由行，不用人遥控。", "explanation": "这里“自由行”是“自由地行走、移动”的意思，指机器人在房间内移动，不是旅游方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自由行", "is_correct": true, "explanation": "正确：“自由行”与“比起跟团”形成对比，表示爸爸更喜欢自己安排的旅行。"}, {"text": "旅行团", "is_correct": false, "explanation": "语义：“旅行团”就是跟团，与前句“比起跟团”矛盾。"}, {"text": "跟团游", "is_correct": false, "explanation": "语义：“跟团游”就是跟团，与“比起跟团”的比较对象重复，句意矛盾。"}, {"text": "地图", "is_correct": false, "explanation": "语义：“地图”是工具，与“跟团”的比较无关，不能说比起跟团更喜欢地图。"}], "explanations": {"自由行": "正确：“自由行”与“比起跟团”形成对比，表示爸爸更喜欢自己安排的旅行。", "旅行团": "语义：“旅行团”就是跟团，与前句“比起跟团”矛盾。", "跟团游": "语义：“跟团游”就是跟团，与“比起跟团”的比较对象重复，句意矛盾。", "地图": "语义：“地图”是工具，与“跟团”的比较无关，不能说比起跟团更喜欢地图。"}, "sentence_index": 6, "correct_answer": "自由行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们这次去台湾是一把自由行，玩了七天。", "explanation": "这里量词用错了。“把”用于有柄的器具，不能修饰“自由行”；应说“一次自由行”。"}, {"text": "我们这次去云南是一本自由行，买了很多东西。", "explanation": "这里量词用错了。“本”用于书籍，不能修饰“自由行”；应说“一次自由行”。"}, {"text": "小宝宝刚学会走路，在屋子里自由行了几步。", "explanation": "这里“自由行”是“自由行走”的意思，指小孩在屋里走动，不是旅游方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去年去了一只自由行。", "corrected_sentence": "我们去年去了一次自由行。", "error_description": "量词错误：“自由行”应使用量词“次”（一次自由行）；“只”用于动物，不能用于旅行方式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去年去了过自由行，很开心。", "corrected_sentence": "我们去年去过自由行，很开心。", "error_description": "体标错误：“了”和“过”不能同时用在动词后，“去了过”应改为“去过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
