INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93699, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "笔是用来写字和画画的东西。", "primary_collocate": null, "pronunciation": "bǐ", "ipa": "pi˨˩˦", "syllable_count": 1, "sentences": [{"text": "他从书包里拿出一支笔，开始写字。", "target_word": "笔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟用笔在白纸上画了一个大太阳。", "target_word": "笔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔很好用，我想再买一支。", "target_word": "笔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的时候，每个人都要带两支笔。", "target_word": "笔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的笔掉在地上了，你看见了吗？", "target_word": "笔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她左手拿着笔，右手拿着本子。", "target_word": "笔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔是爸爸送我的生日礼物。", "target_word": "笔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子正拿着笔认真地写作业。", "target_word": "笔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的笔放在讲台上，没有人动。", "target_word": "笔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的笔借我用一下，好不好？", "target_word": "笔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "枝", "label": "量词"}, {"form": "毛笔", "label": "复合词"}, {"form": "铅笔", "label": "复合词"}], "register": "中性", "sense_fingerprint": "笔：用来写字和画画的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb8dd41a-3ee5-4ea6-a6a8-3eb267922083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93699, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "笔", "is_correct": true, "explanation": "笔 bǐ（第三声），用来写字和画画的东西。"}, {"text": "闭", "is_correct": false, "explanation": "闭 bì（第四声）与 bǐ（第三声）声调不同，意思是关闭。"}, {"text": "鼻", "is_correct": false, "explanation": "鼻 bí（第二声）与 bǐ（第三声）声调不同，意思是鼻子。"}, {"text": "匹", "is_correct": false, "explanation": "匹 pǐ 与 bǐ 声母不同（p 与 b），意思是量词“匹”。"}, {"text": "饼", "is_correct": false, "explanation": "饼 bǐng 与 bǐ 韵母不同（多了后鼻音 ng），意思是饼子。"}], "explanations": {"笔": "笔 bǐ（第三声），用来写字和画画的东西。", "闭": "闭 bì（第四声）与 bǐ（第三声）声调不同，意思是关闭。", "鼻": "鼻 bí（第二声）与 bǐ（第三声）声调不同，意思是鼻子。", "匹": "匹 pǐ 与 bǐ 声母不同（p 与 b），意思是量词“匹”。", "饼": "饼 bǐng 与 bǐ 韵母不同（多了后鼻音 ng），意思是饼子。"}, "sentence_index": null, "correct_answer": "笔"}, "level_3": {"options": [{"text": "笔", "is_correct": true, "explanation": "笔：“一支”的量词用于笔，且可以拿出来写字，句意成立。"}, {"text": "本子", "is_correct": false, "explanation": "搭配：本子的量词是“本”，不说“一支本子”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不能用来写字，“开始写字”与它不搭。"}, {"text": "橡皮", "is_correct": false, "explanation": "语义：橡皮只能用来擦字，不能用来“开始写字”。"}], "explanations": {"笔": "笔：“一支”的量词用于笔，且可以拿出来写字，句意成立。", "本子": "搭配：本子的量词是“本”，不说“一支本子”。", "书包": "语义：书包不能用来写字，“开始写字”与它不搭。", "橡皮": "语义：橡皮只能用来擦字，不能用来“开始写字”。"}, "sentence_index": 0, "correct_answer": "笔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试的时候，每个人都要带两本笔。", "explanation": "这里应该用〈支〉。笔的量词是“支”，“本”用于书、本子，不用于笔。"}, {"text": "她用笔给花浇水。", "explanation": "这里应该用〈水壶〉。浇花要用水壶，笔是写字画画的工具，不能用来浇水。"}, {"text": "她每天用笔梳头。", "explanation": "这里应该用〈梳子〉。梳头要用梳子，笔是写字画画的工具，不能用来梳头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93699, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "笔", "is_correct": true, "explanation": "笔 bǐ（第三声），用来写字和画画的东西。"}, {"text": "米", "is_correct": false, "explanation": "米 mǐ 与 bǐ 声母不同（m 与 b），声调相同，意思是大米。"}, {"text": "把", "is_correct": false, "explanation": "把 bǎ 与 bǐ 韵母不同（a 与 i），意思是握住、拿。"}, {"text": "逼", "is_correct": false, "explanation": "逼 bī（第一声）与 bǐ（第三声）声调不同，意思是逼迫。"}, {"text": "必", "is_correct": false, "explanation": "必 bì（第四声）与 bǐ（第三声）声调不同，意思是必定。"}], "explanations": {"笔": "笔 bǐ（第三声），用来写字和画画的东西。", "米": "米 mǐ 与 bǐ 声母不同（m 与 b），声调相同，意思是大米。", "把": "把 bǎ 与 bǐ 韵母不同（a 与 i），意思是握住、拿。", "逼": "逼 bī（第一声）与 bǐ（第三声）声调不同，意思是逼迫。", "必": "必 bì（第四声）与 bǐ（第三声）声调不同，意思是必定。"}, "sentence_index": null, "correct_answer": "笔"}, "level_3": {"options": [{"text": "笔", "is_correct": true, "explanation": "笔：“这支”的量词用于笔，也能作为礼物送人，句意成立。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“这支”用于笔，书包的量词是“个”，不说“这支书包”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：蛋糕的量词是“块”，不说“这支蛋糕”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见摸不着，不能当作生日礼物送人。"}], "explanations": {"笔": "笔：“这支”的量词用于笔，也能作为礼物送人，句意成立。", "书包": "搭配：“这支”用于笔，书包的量词是“个”，不说“这支书包”。", "蛋糕": "搭配：蛋糕的量词是“块”，不说“这支蛋糕”。", "空气": "语义：空气看不见摸不着，不能当作生日礼物送人。"}, "sentence_index": 6, "correct_answer": "笔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一张笔，借给你用。", "explanation": "这里应该用〈支〉。笔的量词是“支”，“张”用于纸张、平面的东西，笔不用“张”。"}, {"text": "他用笔钉钉子。", "explanation": "这里应该用〈锤子〉。钉钉子要用锤子，笔不能用来钉钉子。"}, {"text": "他用笔撬开了箱子。", "explanation": "这里应该用〈撬棍〉。撬箱子要用撬棍，笔是写字画画的工具，不能用来撬东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
