INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93699, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我笔找不到了。", "corrected_sentence": "我的笔找不到了。", "error_description": "省略错误：“我的笔”中的“的”不能省，要说“我的笔”，不说“我笔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
