INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93701, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "里手是对一件事特别熟悉的人。", "primary_collocate": null, "pronunciation": "lǐ shǒu", "ipa": "li˨˩˦ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "说到种茶，他是我们村的里手。", "target_word": "里手", "sentence_source": "generated"}, {"text": "这位师傅是修自行车的里手。", "target_word": "里手", "sentence_source": "generated"}, {"text": "我想找个里手帮我看看电脑。", "target_word": "里手", "sentence_source": "generated"}, {"text": "王奶奶包饺子是里手，大家都爱吃。", "target_word": "里手", "sentence_source": "generated"}, {"text": "他在海边长大，是游泳的里手。", "target_word": "里手", "sentence_source": "generated"}, {"text": "要买旧手机，最好带个里手去。", "target_word": "里手", "sentence_source": "generated"}, {"text": "这件事你问他，他可是里手。", "target_word": "里手", "sentence_source": "generated"}, {"text": "他开了二十年车，是公认的里手。", "target_word": "里手", "sentence_source": "generated"}, {"text": "她是画画的里手，一看就懂。", "target_word": "里手", "sentence_source": "generated"}, {"text": "村里谁家盖房子，都请老张这个里手来看。", "target_word": "里手", "sentence_source": "generated"}], "morphological_forms": [{"form": "老里手", "label": "复合词"}], "register": "口语", "sense_fingerprint": "对某件事特别熟悉的人，常说“某方面的里手”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14564538-3a40-44fa-a32f-b1e6c7a259d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93701, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”与“说到种茶”的话题无关，句意不通。"}, {"text": "画家", "is_correct": false, "explanation": "语义：“画家”与“种茶”的话题无关，句意不通。"}, {"text": "里手", "is_correct": true, "explanation": "正确：“里手”指对某事很熟悉的人，与“说到种茶”相符。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：“司机”的身份与“种茶”的话题不搭配。"}], "explanations": {"厨师": "语义：“厨师”与“说到种茶”的话题无关，句意不通。", "画家": "语义：“画家”与“种茶”的话题无关，句意不通。", "里手": "正确：“里手”指对某事很熟悉的人，与“说到种茶”相符。", "司机": "搭配：“司机”的身份与“种茶”的话题不搭配。"}, "sentence_index": 0, "correct_answer": "里手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的电饭煲是里手，煮饭很快。", "explanation": "「里手」指人，不能用来称呼物品。这里语义不对。"}, {"text": "他刚学会骑车，还是个里手，经常摔跤。", "explanation": "「里手」指对某事很熟练的人，不指新手。这里应该用〈新手〉。"}, {"text": "他的里手不错，村里人都爱找他。", "explanation": "「里手」指人，不指技艺。这里应该用〈手艺〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93701, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小偷", "is_correct": false, "explanation": "语义：“小偷”与“这件事你问他”的语境不符，句意不通。"}, {"text": "演员", "is_correct": false, "explanation": "搭配：“他可是演员”与“这件事你问他”的专业语境不搭配。"}, {"text": "里手", "is_correct": true, "explanation": "正确：“里手”指对某事很熟悉的人，与“他可是”的语境相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：“游客”与“这件事你问他”的语境不符，句意不通。"}], "explanations": {"小偷": "语义：“小偷”与“这件事你问他”的语境不符，句意不通。", "演员": "搭配：“他可是演员”与“这件事你问他”的专业语境不搭配。", "里手": "正确：“里手”指对某事很熟悉的人，与“他可是”的语境相符。", "游客": "语义：“游客”与“这件事你问他”的语境不符，句意不通。"}, "sentence_index": 6, "correct_answer": "里手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一本里手，专门讲修车。", "explanation": "「里手」指人，不指书籍。这里应该用〈指南〉。"}, {"text": "我们班都是里手，连最简单的题都不会做。", "explanation": "「里手」指对某事很熟练的人，与“连最简单的题都不会做”矛盾。这里应该用〈新手〉。"}, {"text": "我家门口新开了一家里手，专门卖水果。", "explanation": "「里手」指对某事很熟悉的人，不指店铺。这里应该用〈商店〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93701, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村有一条里手，会种茶。", "corrected_sentence": "我们村有一个里手，会种茶。", "error_description": "量词错误：“里手”指人，量词应用“个”，“条”用于细长的东西，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93701, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他修过几十年的车，是只里手。", "corrected_sentence": "他修过几十年的车，是个里手。", "error_description": "量词错误：“里手”指人，量词应用“个”，“只”多用于小动物，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
