INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93703, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "节日是一年里大家一起庆祝的特别的日子。", "primary_collocate": null, "pronunciation": "jié rì", "ipa": "tɕjɛ˧˥ ʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "春节是中国最大的节日。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日的时候，大家一起吃饭。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最喜欢哪个节日？", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日里，街上很热闹。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个国家都有自己的节日。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日快到了，商店里人很多。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在节日里能收到礼物。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日我们要去看奶奶。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日那天，我们都穿新衣服。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "元旦是新年的第一个节日。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "节日气氛", "label": "复合词"}], "register": "中性", "sense_fingerprint": "一年里大家一起庆祝的特别日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb8dd41a-3ee5-4ea6-a6a8-3eb267922083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93703, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "节日", "is_correct": true, "explanation": "正确：节日 jié rì 指一年里大家一起庆祝的特别日子。"}, {"text": "节食", "is_correct": false, "explanation": "jiéshí 与 jiérì 第二个音节的声母和声调都不同（sh 与 r，第二声与第四声），意思是节制饮食。"}, {"text": "竭力", "is_correct": false, "explanation": "jiélì 与 jiérì 第二个音节的声母不同（l 与 r），声调相同，意思是尽最大力量。"}, {"text": "烈日", "is_correct": false, "explanation": "lièrì 与 jiérì 第一个音节的声母不同（l 与 j），声调也不同，意思是炽热的太阳。"}, {"text": "吉日", "is_correct": false, "explanation": "jírì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调相同，意思是吉利的日子。"}], "explanations": {"节日": "正确：节日 jié rì 指一年里大家一起庆祝的特别日子。", "节食": "jiéshí 与 jiérì 第二个音节的声母和声调都不同（sh 与 r，第二声与第四声），意思是节制饮食。", "竭力": "jiélì 与 jiérì 第二个音节的声母不同（l 与 r），声调相同，意思是尽最大力量。", "烈日": "lièrì 与 jiérì 第一个音节的声母不同（l 与 j），声调也不同，意思是炽热的太阳。", "吉日": "jírì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调相同，意思是吉利的日子。"}, "sentence_index": null, "correct_answer": "节日"}, "level_3": {"options": [{"text": "节日", "is_correct": true, "explanation": "正确：“中国最大的节日”指春节所属的类别，句意完整。"}, {"text": "国家", "is_correct": false, "explanation": "语义：春节本身是节日，不能说它是“最大的国家”。"}, {"text": "城市", "is_correct": false, "explanation": "语义：“城市”指地方，春节是节日，不能说它是“最大的城市”。"}, {"text": "文化", "is_correct": false, "explanation": "搭配：“文化”是抽象的整体概念，不能用“中国最大的”来限定春节这个具体的节日。"}], "explanations": {"节日": "正确：“中国最大的节日”指春节所属的类别，句意完整。", "国家": "语义：春节本身是节日，不能说它是“最大的国家”。", "城市": "语义：“城市”指地方，春节是节日，不能说它是“最大的城市”。", "文化": "搭配：“文化”是抽象的整体概念，不能用“中国最大的”来限定春节这个具体的节日。"}, "sentence_index": 0, "correct_answer": "节日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一天是个平常的节日。", "explanation": "这里应该用〈日子〉。节日指大家一起庆祝的特别日子，不能用来形容“平常的”一天。"}, {"text": "那只节日真热闹。", "explanation": "这里应该用〈个〉。节日的量词是“个”，“只”一般用于动物等，不能说“那只节日”。"}, {"text": "我的节日是三月五号。", "explanation": "这里应该用〈生日〉。节日是大家一起庆祝的日子，个人的生日要用“生日”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93703, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "节日", "is_correct": true, "explanation": "正确：节日 jié rì 指一年里大家一起庆祝的特别日子。"}, {"text": "几日", "is_correct": false, "explanation": "jǐrì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调也不同（第三声与第二声），意思是几天。"}, {"text": "即日", "is_correct": false, "explanation": "jírì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调相同，意思是当天。"}, {"text": "忌日", "is_correct": false, "explanation": "jìrì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调也不同（第四声），意思是去世的纪念日。"}], "explanations": {"节日": "正确：节日 jié rì 指一年里大家一起庆祝的特别日子。", "几日": "jǐrì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调也不同（第三声与第二声），意思是几天。", "即日": "jírì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调相同，意思是当天。", "忌日": "jìrì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调也不同（第四声），意思是去世的纪念日。"}, "sentence_index": null, "correct_answer": "节日"}, "level_3": {"options": [{"text": "节日", "is_correct": true, "explanation": "正确：“在节日里”指礼物送出的特定时候，句意完整。"}, {"text": "军营", "is_correct": false, "explanation": "语义：孩子们不会在军营里收到礼物，“军营”与“孩子们”的场景不符。"}, {"text": "战场", "is_correct": false, "explanation": "语义：“战场”是危险的地方，与孩子们收礼物的场景不符。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“工厂”是生产场所，与“孩子们”和“收到礼物”的场景不搭配。"}], "explanations": {"节日": "正确：“在节日里”指礼物送出的特定时候，句意完整。", "军营": "语义：孩子们不会在军营里收到礼物，“军营”与“孩子们”的场景不符。", "战场": "语义：“战场”是危险的地方，与孩子们收礼物的场景不符。", "工厂": "搭配：“工厂”是生产场所，与“孩子们”和“收到礼物”的场景不搭配。"}, "sentence_index": 6, "correct_answer": "节日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司每周有两天节日。", "explanation": "这里应该用〈假日〉。节日指大家一起庆祝的特别日子，每周固定的休息日要用“假日”。"}, {"text": "新年的节日很浓。", "explanation": "这里应该用〈气氛〉。“浓”用来形容气氛，节日是日子，不能说“节日很浓”。"}, {"text": "晚会的节日很精彩。", "explanation": "这里应该用〈节目〉。晚会上表演的项目叫“节目”，“节日”指特定的日子，不能说“晚会的节日”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只节日大家都很开心。", "corrected_sentence": "这个节日大家都很开心。", "error_description": "量词错误：“节日”的量词应为“个”，不是“只”。“只”一般用于动物等，应改为“这个节日”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93703, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在节日时候，我们都要去公园。", "corrected_sentence": "在节日的时候，我们都要去公园。", "error_description": "结构助词错误：修饰名词的时间词“时候”前要加“的”，应说“节日的时候”，不能说“节日时候”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
