INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93704, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年中有纪念意义或喜庆意义的日子，如春节、中秋节。", "primary_collocate": null, "pronunciation": "jié rì", "ipa": "tɕjɛ˧˥ ʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "中秋节是中国的传统节日。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国庆节是为了纪念国家成立的节日。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年里有很多节日，比如春节和中秋节。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "劳动节是为工人设的节日。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日有一千多年的历史。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "端午节是纪念屈原的节日。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每逢节日，家家都挂红灯笼。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们国家的节日，学校都放假。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日历上用红色标出的日子就是节日。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个节日，人们会做月饼。", "target_word": "节日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "节日气氛", "label": "复合词"}], "register": "中性", "sense_fingerprint": "有纪念或喜庆意义的日子，如春节、中秋节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb8dd41a-3ee5-4ea6-a6a8-3eb267922083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93704, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "节日", "is_correct": true, "explanation": "正确：节日 jié rì 指有纪念或喜庆意义的日子。"}, {"text": "节食", "is_correct": false, "explanation": "jiéshí 与 jiérì 第二个音节的声母和声调都不同（sh 与 r，第二声与第四声），意思是节制饮食。"}, {"text": "竭力", "is_correct": false, "explanation": "jiélì 与 jiérì 第二个音节的声母不同（l 与 r），声调相同，意思是尽最大力量。"}, {"text": "烈日", "is_correct": false, "explanation": "lièrì 与 jiérì 第一个音节的声母不同（l 与 j），声调也不同，意思是炽热的太阳。"}, {"text": "吉日", "is_correct": false, "explanation": "jírì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调相同，意思是吉利的日子。"}], "explanations": {"节日": "正确：节日 jié rì 指有纪念或喜庆意义的日子。", "节食": "jiéshí 与 jiérì 第二个音节的声母和声调都不同（sh 与 r，第二声与第四声），意思是节制饮食。", "竭力": "jiélì 与 jiérì 第二个音节的声母不同（l 与 r），声调相同，意思是尽最大力量。", "烈日": "lièrì 与 jiérì 第一个音节的声母不同（l 与 j），声调也不同，意思是炽热的太阳。", "吉日": "jírì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调相同，意思是吉利的日子。"}, "sentence_index": null, "correct_answer": "节日"}, "level_3": {"options": [{"text": "节日", "is_correct": true, "explanation": "正确：“中秋节是中国的传统节日”说的是中秋节的类别，句意完整。"}, {"text": "国家", "is_correct": false, "explanation": "语义：中秋节是节日，不能说它是“中国的传统国家”。"}, {"text": "城市", "is_correct": false, "explanation": "语义：中秋节是节日，不能说它是“中国的传统城市”。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“传统乐器”说的是器物，与“中秋节是”所说的节日不搭配。"}], "explanations": {"节日": "正确：“中秋节是中国的传统节日”说的是中秋节的类别，句意完整。", "国家": "语义：中秋节是节日，不能说它是“中国的传统国家”。", "城市": "语义：中秋节是节日，不能说它是“中国的传统城市”。", "乐器": "搭配：“传统乐器”说的是器物，与“中秋节是”所说的节日不搭配。"}, "sentence_index": 0, "correct_answer": "节日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下雨的那天是我的节日。", "explanation": "这里应该用〈日子〉。节日指有纪念或喜庆意义的特别日子，下雨的那天不具备这种意义。"}, {"text": "这是一个平凡的节日。", "explanation": "这里应该用〈日子〉。节日指有纪念或喜庆意义的特别日子，不能用来形容平凡的日子。"}, {"text": "我今天考了一百分，真是个好节日。", "explanation": "这里应该用〈日子〉。节日指有纪念或喜庆意义、大家共同过的特定日子，个人考得好的一天不是节日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93704, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "节日", "is_correct": true, "explanation": "正确：节日 jié rì 指有纪念或喜庆意义的日子。"}, {"text": "几日", "is_correct": false, "explanation": "jǐrì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调也不同（第三声与第二声），意思是几天。"}, {"text": "即日", "is_correct": false, "explanation": "jírì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调相同，意思是当天。"}, {"text": "忌日", "is_correct": false, "explanation": "jìrì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调也不同（第四声），意思是去世的纪念日。"}], "explanations": {"节日": "正确：节日 jié rì 指有纪念或喜庆意义的日子。", "几日": "jǐrì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调也不同（第三声与第二声），意思是几天。", "即日": "jírì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调相同，意思是当天。", "忌日": "jìrì 与 jiérì 第一个音节的韵母不同（i 与 ie），声调也不同（第四声），意思是去世的纪念日。"}, "sentence_index": null, "correct_answer": "节日"}, "level_3": {"options": [{"text": "节日", "is_correct": true, "explanation": "正确：“每逢节日”指每次遇到节日，句意完整。"}, {"text": "考试", "is_correct": false, "explanation": "语义：红灯笼是节日的装饰，家家在考试时挂灯笼说不通。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“每逢”后接时间或场合，“学校”是地点，不能说“每逢学校”。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：红灯笼是喜庆的装饰，与葬礼的场合相冲突。"}], "explanations": {"节日": "正确：“每逢节日”指每次遇到节日，句意完整。", "考试": "语义：红灯笼是节日的装饰，家家在考试时挂灯笼说不通。", "学校": "搭配：“每逢”后接时间或场合，“学校”是地点，不能说“每逢学校”。", "葬礼": "语义：红灯笼是喜庆的装饰，与葬礼的场合相冲突。"}, "sentence_index": 6, "correct_answer": "节日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚会的节日很精彩。", "explanation": "这里应该用〈节目〉。晚会上表演的项目叫“节目”，“节日”指特定的日子，不能说“晚会的节日”。"}, {"text": "我们公司每周有两天节日。", "explanation": "这里应该用〈假日〉。节日指有纪念或喜庆意义的特别日子，每周固定的休息日要用“假日”。"}, {"text": "街上的节日很浓。", "explanation": "这里应该用〈气氛〉。“浓”用来形容气氛，节日是日子，不能说“节日很浓”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每只节日，我们都会回老家。", "corrected_sentence": "每个节日，我们都会回老家。", "error_description": "量词错误：“节日”的量词应为“个”，“只”不能用于节日，应改为“每个节日”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在这个节日时候，人们会一起做月饼。", "corrected_sentence": "在这个节日的时候，人们会一起做月饼。", "error_description": "结构助词错误：修饰名词的时间词“时候”前要加“的”，应说“这个节日的时候”，不能说“这个节日时候”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
