INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93706, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "机构邀请记者发布消息并回答提问的会议。", "primary_collocate": null, "pronunciation": "jì zhě huì", "ipa": "tɕi˥˩ ʈʂɤ˨˩˦ xuei˥˩", "syllable_count": 3, "sentences": [{"text": "明天上午公司要开记者会。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长在记者会上回答了问题。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场记者会来了很多记者。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者会八点开始，请大家准时到。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队今天下午召开记者会。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电视上看过那场记者会。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者会上，经理介绍了新产品。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在记者会上说了对不起。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司为什么突然开记者会？", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者会结束后，大家都回家了。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "记者招待会", "label": "复合"}, {"form": "記者會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：机构邀请记者发布消息并回答提问的会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '996bd829-ae6b-4c7b-887c-9cabc20a2540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "记者会", "is_correct": true, "explanation": "“记者会”指机构邀请记者发布消息并回答提问的会议，与“公司要开”搭配，句子通顺。"}, {"text": "玩笑", "is_correct": false, "explanation": "语义：“开玩笑”指说笑逗乐，公司明天上午安排的是正式活动，不是开玩笑。"}, {"text": "陷阱", "is_correct": false, "explanation": "语义：“陷阱”是设来害人的圈套，与公司安排的会议完全不符。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：“苹果”是水果，不能“开”，与公司安排的会议不符。"}], "explanations": {"记者会": "“记者会”指机构邀请记者发布消息并回答提问的会议，与“公司要开”搭配，句子通顺。", "玩笑": "语义：“开玩笑”指说笑逗乐，公司明天上午安排的是正式活动，不是开玩笑。", "陷阱": "语义：“陷阱”是设来害人的圈套，与公司安排的会议完全不符。", "苹果": "语义：“苹果”是水果，不能“开”，与公司安排的会议不符。"}, "sentence_index": 0, "correct_answer": "记者会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们下午在记者会上吃了火锅。", "explanation": "这里应该用〈聚餐〉。记者会是机构邀请记者发布消息、回答提问的场合，吃火锅要说聚餐。"}, {"text": "老师在记者会上给我们讲了课。", "explanation": "这里应该用〈讲座〉。记者会没有授课的功能，讲课要说讲座。"}, {"text": "我们班的记者会，每个家长都要签到。", "explanation": "这里应该用〈家长会〉。记者会是面向记者的，家长到校聚会要说家长会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "记者会", "is_correct": true, "explanation": "“记者会”与“上”组成场所，指发布消息的会，与“经理介绍新产品”的语境相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”不是进行产品介绍的场所，句子不通。"}, {"text": "病房", "is_correct": false, "explanation": "语义：“病房”不适合进行产品介绍，与语境冲突。"}, {"text": "洗手间", "is_correct": false, "explanation": "语义：“洗手间”是上厕所的地方，不是介绍新产品的场合。"}], "explanations": {"记者会": "“记者会”与“上”组成场所，指发布消息的会，与“经理介绍新产品”的语境相符。", "厨房": "语义：“厨房”不是进行产品介绍的场所，句子不通。", "病房": "语义：“病房”不适合进行产品介绍，与语境冲突。", "洗手间": "语义：“洗手间”是上厕所的地方，不是介绍新产品的场合。"}, "sentence_index": 6, "correct_answer": "记者会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "记者会上，新人交换了戒指。", "explanation": "这里应该用〈婚礼〉。记者会是机构邀请记者发布消息、回答提问的场合，新人交换戒指要说婚礼。"}, {"text": "记者会上，同学们跑了一百米。", "explanation": "这里应该用〈运动会〉。记者会是发布消息、回答提问的场合，比赛跑步要说运动会。"}, {"text": "记者会上，孩子们吹灭了蜡烛。", "explanation": "这里应该用〈生日派对〉。记者会不是庆祝生日的场合，吹灭蜡烛要说生日派对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府明天开一本记者会。", "corrected_sentence": "市政府明天开一场记者会。", "error_description": "错误：量词“本”；正确：“场”。“记者会”作为活动，量词要用“场”，“本”只用于书册。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天晚上我在网上看了一条记者会。", "corrected_sentence": "昨天晚上我在网上看了一场记者会。", "error_description": "错误：量词“条”；正确：“场”。“记者会”是一次活动，量词要用“场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
