INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93707, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "签是把自己的名字写在纸上。", "primary_collocate": null, "pronunciation": "qiān", "ipa": "tɕʰjɛn˥", "syllable_count": 1, "sentences": [{"text": "请在这张纸上签你的名字。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿起笔，在本子上签了自己的名字。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们在表格下面签上名字。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在这里签一下名字吧。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在卡片上签了他的名字。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在生日卡上签着自己的名字。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把名字签在画的右下角。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来，在照片后面签上你的名字。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写字很慢，只签了自己的姓。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先签名字，再交给老师。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "签了", "label": "体标"}, {"form": "签过", "label": "体标"}, {"form": "签着", "label": "体标"}, {"form": "簽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把自己的名字写在纸上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb8dd41a-3ee5-4ea6-a6a8-3eb267922083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93707, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "签", "is_correct": true, "explanation": "正确：签 qiān 指把自己的名字写在纸上。"}, {"text": "钱", "is_correct": false, "explanation": "qián（第二声）与 qiān（第一声）声调不同，意思是钱。"}, {"text": "枪", "is_correct": false, "explanation": "qiāng 与 qiān 韵母不同（ang 与 an），声调相同，意思是枪。"}, {"text": "先", "is_correct": false, "explanation": "xiān 与 qiān 声母不同（x 与 q），声调相同，意思是先、首先。"}, {"text": "掐", "is_correct": false, "explanation": "qiā 与 qiān 韵母不同（ia 与 ian），声调相同，意思是用指甲按、捏。"}], "explanations": {"签": "正确：签 qiān 指把自己的名字写在纸上。", "钱": "qián（第二声）与 qiān（第一声）声调不同，意思是钱。", "枪": "qiāng 与 qiān 韵母不同（ang 与 an），声调相同，意思是枪。", "先": "xiān 与 qiān 声母不同（x 与 q），声调相同，意思是先、首先。", "掐": "qiā 与 qiān 韵母不同（ia 与 ian），声调相同，意思是用指甲按、捏。"}, "sentence_index": null, "correct_answer": "签"}, "level_3": {"options": [{"text": "签", "is_correct": true, "explanation": "正确：“请在这张纸上签你的名字”，签指在纸上写下自己的名字，句意完整。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是抹掉，与在纸上写名字的要求相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“名字”搭配。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物，与在纸上写名字不符。"}], "explanations": {"签": "正确：“请在这张纸上签你的名字”，签指在纸上写下自己的名字，句意完整。", "擦": "语义：“擦”是抹掉，与在纸上写名字的要求相反。", "吃": "搭配：“吃”不能与“名字”搭配。", "煮": "语义：“煮”是加热食物，与在纸上写名字不符。"}, "sentence_index": 0, "correct_answer": "签"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在本子上签了一首诗。", "explanation": "这里应该用〈写〉。签只指写上自己的名字，不能用来表示写诗。"}, {"text": "妈妈在纸上签了一只小鸟。", "explanation": "这里应该用〈画〉。签只表示写名字，不能用来表示画画。"}, {"text": "他在合同下面签了手印。", "explanation": "这里应该用〈按〉。签指用笔写上自己的名字，按手印要用“按”，不能说“签手印”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93707, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "签", "is_correct": true, "explanation": "正确：签 qiān 指把自己的名字写在纸上。"}, {"text": "前", "is_correct": false, "explanation": "qián（第二声）与 qiān（第一声）声调不同，意思是前面。"}, {"text": "浅", "is_correct": false, "explanation": "qiǎn（第三声）与 qiān（第一声）声调不同，意思是浅。"}, {"text": "尖", "is_correct": false, "explanation": "jiān 与 qiān 声母不同（j 与 q），声调相同，意思是尖。"}, {"text": "歉", "is_correct": false, "explanation": "qiàn（第四声）与 qiān（第一声）声调不同，意思是道歉的歉。"}], "explanations": {"签": "正确：签 qiān 指把自己的名字写在纸上。", "前": "qián（第二声）与 qiān（第一声）声调不同，意思是前面。", "浅": "qiǎn（第三声）与 qiān（第一声）声调不同，意思是浅。", "尖": "jiān 与 qiān 声母不同（j 与 q），声调相同，意思是尖。", "歉": "qiàn（第四声）与 qiān（第一声）声调不同，意思是道歉的歉。"}, "sentence_index": null, "correct_answer": "签"}, "level_3": {"options": [{"text": "签", "is_correct": true, "explanation": "正确：“我把名字签在画的右下角”，签指在画上写下名字，句意完整。"}, {"text": "挂", "is_correct": false, "explanation": "语义：“挂”指悬挂物件，与在画角写下名字的动作不符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与在画角写名字的动作相反。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”不能与“名字”搭配，无法在画上切出名字。"}], "explanations": {"签": "正确：“我把名字签在画的右下角”，签指在画上写下名字，句意完整。", "挂": "语义：“挂”指悬挂物件，与在画角写下名字的动作不符。", "扔": "语义：“扔”是丢弃，与在画角写名字的动作相反。", "切": "搭配：“切”不能与“名字”搭配，无法在画上切出名字。"}, "sentence_index": 6, "correct_answer": "签"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把照片签在墙上。", "explanation": "这里应该用〈贴〉。签指用笔写上自己的名字，不能用来表示把照片粘在墙上。"}, {"text": "他给朋友签了个电话。", "explanation": "这里应该用〈打〉。签指用笔写上自己的名字，不能用来表示打电话。"}, {"text": "我把衣服签干净了。", "explanation": "这里应该用〈洗〉。签指写上自己的名字，不能用来表示把衣服洗干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你这张纸上签名字，再把文件交给我。", "corrected_sentence": "请你在这张纸上签名字，再把文件交给我。", "error_description": "介词错误：表示地点的“在”不能省略，应说“在这张纸上签名字”，不能说“这张纸上签名字”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93707, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前签了过自己的名字。", "corrected_sentence": "我以前签过自己的名字。", "error_description": "体标错误：表示经历的“过”不能与“了”连用，应说“签过”，不能说“签了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
