INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93708, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在文件上写上自己的名字，表示负责或同意。", "primary_collocate": null, "pronunciation": "qiān", "ipa": "tɕʰjɛn˥", "syllable_count": 1, "sentences": [{"text": "这份合同你签了吗？", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你同意的话，就在下面签上名字。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板已经签了这份文件。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生请家人在文件上签名字，表示同意。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房前，我们要先签合同。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他签了名字，就要负责这件事。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国前，爸爸在同意书上签了名字。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把文件签好后，交给了秘书。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在这张收据上签名字，表示收到了。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司和他签了三年的合同。", "target_word": "签", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "签了", "label": "体标"}, {"form": "签过", "label": "体标"}, {"form": "签着", "label": "体标"}, {"form": "簽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在文件上写名字，表示负责或同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb8dd41a-3ee5-4ea6-a6a8-3eb267922083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93708, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "签", "is_correct": true, "explanation": "正确：签 qiān 指在文件上写名字，表示负责或同意。"}, {"text": "钱", "is_correct": false, "explanation": "qián（第二声）与 qiān（第一声）声调不同，意思是钱。"}, {"text": "枪", "is_correct": false, "explanation": "qiāng 与 qiān 韵母不同（ang 与 an），声调相同，意思是枪。"}, {"text": "欠", "is_correct": false, "explanation": "qiàn（第四声）与 qiān（第一声）声调不同，意思是欠（债）。"}, {"text": "先", "is_correct": false, "explanation": "xiān 与 qiān 声母不同（x 与 q），声调相同，意思是先、首先。"}], "explanations": {"签": "正确：签 qiān 指在文件上写名字，表示负责或同意。", "钱": "qián（第二声）与 qiān（第一声）声调不同，意思是钱。", "枪": "qiāng 与 qiān 韵母不同（ang 与 an），声调相同，意思是枪。", "欠": "qiàn（第四声）与 qiān（第一声）声调不同，意思是欠（债）。", "先": "xiān 与 qiān 声母不同（x 与 q），声调相同，意思是先、首先。"}, "sentence_index": null, "correct_answer": "签"}, "level_3": {"options": [{"text": "签", "is_correct": true, "explanation": "正确：“这份合同你签了吗”，签指在合同上写名字，句意完整。"}, {"text": "吃", "is_correct": false, "explanation": "语义：合同是文件，不能吃。"}, {"text": "喝", "is_correct": false, "explanation": "语义：合同是文件，不能喝。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“合同”搭配。"}], "explanations": {"签": "正确：“这份合同你签了吗”，签指在合同上写名字，句意完整。", "吃": "语义：合同是文件，不能吃。", "喝": "语义：合同是文件，不能喝。", "洗": "搭配：“洗”不能与“合同”搭配。"}, "sentence_index": 0, "correct_answer": "签"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在日记本上签下了今天的心情。", "explanation": "这里应该用〈写〉。签指在文件上写自己的名字表示同意或负责，不能用来写心情。"}, {"text": "他在选票上签了一票。", "explanation": "这里应该用〈投〉。签指写自己的名字，不能用来表示投票。"}, {"text": "他把地图签在墙上。", "explanation": "这里应该用〈挂〉。签指在文件上写名字，不能用来表示把东西挂在墙上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93708, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "签", "is_correct": true, "explanation": "正确：签 qiān 指在文件上写名字，表示负责或同意。"}, {"text": "前", "is_correct": false, "explanation": "qián（第二声）与 qiān（第一声）声调不同，意思是前面。"}, {"text": "浅", "is_correct": false, "explanation": "qiǎn（第三声）与 qiān（第一声）声调不同，意思是浅。"}, {"text": "尖", "is_correct": false, "explanation": "jiān 与 qiān 声母不同（j 与 q），声调相同，意思是尖。"}, {"text": "掐", "is_correct": false, "explanation": "qiā 与 qiān 韵母不同（ia 与 ian），声调相同，意思是用指甲按、捏。"}], "explanations": {"签": "正确：签 qiān 指在文件上写名字，表示负责或同意。", "前": "qián（第二声）与 qiān（第一声）声调不同，意思是前面。", "浅": "qiǎn（第三声）与 qiān（第一声）声调不同，意思是浅。", "尖": "jiān 与 qiān 声母不同（j 与 q），声调相同，意思是尖。", "掐": "qiā 与 qiān 韵母不同（ia 与 ian），声调相同，意思是用指甲按、捏。"}, "sentence_index": null, "correct_answer": "签"}, "level_3": {"options": [{"text": "签", "is_correct": true, "explanation": "正确：“爸爸在同意书上签了名字”，签指在同意书上写名字，句意完整。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与在同意书上写名字不符。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是焚毁，与在同意书上写名字的动作相反。"}, {"text": "嚼", "is_correct": false, "explanation": "搭配：“嚼”不能与“名字”搭配。"}], "explanations": {"签": "正确：“爸爸在同意书上签了名字”，签指在同意书上写名字，句意完整。", "扔": "语义：“扔”是丢弃，与在同意书上写名字不符。", "烧": "语义：“烧”是焚毁，与在同意书上写名字的动作相反。", "嚼": "搭配：“嚼”不能与“名字”搭配。"}, "sentence_index": 6, "correct_answer": "签"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司签了很多宣传单。", "explanation": "这里应该用〈印〉。签指写上自己的名字，不能用来表示印刷宣传单。"}, {"text": "他签了一遍笔记。", "explanation": "这里应该用〈抄〉。签指写上自己的名字，不能用来表示把笔记抄一遍。"}, {"text": "他用布签了一下桌子。", "explanation": "这里应该用〈擦〉。签指写上自己的名字，不能用来表示擦桌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前签了过这份合同。", "corrected_sentence": "我以前签过这份合同。", "error_description": "体标错误：表示经历的“过”不能与“了”连用，应说“签过”，不能说“签了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司已经签着三份合同。", "corrected_sentence": "公司已经签了三份合同。", "error_description": "体标错误：表示已完成的动作要用“了”，“着”表示持续的状态，应说“签了三份合同”，不能说“签着三份合同”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93710, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "淘汰", "is_correct": true, "explanation": "反义：“评选”是选出优秀者，“淘汰”是剔除落后者，二者方向相反。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论与评选同属评议过程，不构成反义。"}, {"text": "公布", "is_correct": false, "explanation": "公布是宣布结果，与评选相关但不构成反义。"}, {"text": "参赛", "is_correct": false, "explanation": "参赛指参加比赛，与评选不构成反义。"}], "correct_answer": "淘汰", "explanations": {"淘汰": "反义：“评选”是选出优秀者，“淘汰”是剔除落后者，二者方向相反。", "讨论": "讨论与评选同属评议过程，不构成反义。", "公布": "公布是宣布结果，与评选相关但不构成反义。", "参赛": "参赛指参加比赛，与评选不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93710, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "淘汰", "is_correct": true, "explanation": "反义：“评选”是选出优秀者，“淘汰”是剔除落后者，二者方向相反。"}, {"text": "报名", "is_correct": false, "explanation": "报名指登记参加，与评选不构成反义。"}, {"text": "投票", "is_correct": false, "explanation": "投票是表达选择的方式之一，与评选不构成反义。"}, {"text": "宣传", "is_correct": false, "explanation": "宣传是推广活动或事物，与评选不构成反义。"}], "correct_answer": "淘汰", "explanations": {"淘汰": "反义：“评选”是选出优秀者，“淘汰”是剔除落后者，二者方向相反。", "报名": "报名指登记参加，与评选不构成反义。", "投票": "投票是表达选择的方式之一，与评选不构成反义。", "宣传": "宣传是推广活动或事物，与评选不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93710, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经过评议比较，选出优秀者。", "primary_collocate": null, "pronunciation": "píng xuǎn", "ipa": "pʰiŋ˧˥ ɕɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "学校每年都评选最佳教师。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛由专家评选，大家都很服气。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在评选今年的优秀员工。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "评选结果明天公布。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师们评选出了三篇好作文。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家评选他当学习代表。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "评选要公平，不能只看名气。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报社评选了今年的十大新闻。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们一起评选最好看的照片。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "评选活动从上个月开始，有很多人参加。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "评选了", "label": "体标"}, {"form": "评选过", "label": "体标"}, {"form": "评选活动", "label": "复合"}, {"form": "評選", "label": "繁体"}], "register": "中性", "sense_fingerprint": "经过评议比较后选出优秀的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a9ccfdf-6e54-4f66-b305-2e8ae631542e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "评选", "is_correct": true, "explanation": "正确：“评选”指经过评议比较选出优秀者，与“最佳教师”搭配自然。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽培植物，学校不能种植教师。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言或文字，不能说翻译教师。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能说煮教师。"}], "explanations": {"评选": "正确：“评选”指经过评议比较选出优秀者，与“最佳教师”搭配自然。", "种植": "语义：“种植”指栽培植物，学校不能种植教师。", "翻译": "搭配：“翻译”的对象是语言或文字，不能说翻译教师。", "煮": "搭配：“煮”的对象是食物，不能说煮教师。"}, "sentence_index": 0, "correct_answer": "评选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从一堆水果里评选出最甜的一个。", "explanation": "这里应该用〈挑选〉。“评选”指经过评议比较选出优秀的人或事物，个人挑水果要用〈挑选〉。"}, {"text": "妈妈去市场评选了一条鱼。", "explanation": "这里应该用〈选购〉。“评选”用于经过评议选出优秀者，买东西要用〈选购〉。"}, {"text": "他评选了学医，以后想当医生。", "explanation": "这里应该用〈选择〉。“评选”需要经过评议比较，个人决定做什么要用〈选择〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "评选", "is_correct": true, "explanation": "正确：“评选”指经过评议比较选出，与“要公平、不能只看名气”的评价语境相符。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做菜，与“看名气”的评价标准无关，不存在公平与否的评议。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”是清洁动作，不能说“打扫要公平”。"}, {"text": "放牧", "is_correct": false, "explanation": "语义：“放牧”指照看牲畜，与“看名气”的判断无关。"}], "explanations": {"评选": "正确：“评选”指经过评议比较选出，与“要公平、不能只看名气”的评价语境相符。", "烹饪": "语义：“烹饪”指做菜，与“看名气”的评价标准无关，不存在公平与否的评议。", "打扫": "搭配：“打扫”是清洁动作，不能说“打扫要公平”。", "放牧": "语义：“放牧”指照看牲畜，与“看名气”的判断无关。"}, "sentence_index": 6, "correct_answer": "评选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在抽屉里评选出了一把能开门的钥匙。", "explanation": "这里应该用〈找到〉。“评选”指经过评议比较选出优秀者，在抽屉里找钥匙要用〈找到〉。"}, {"text": "工厂用机器评选出了有问题的零件。", "explanation": "这里应该用〈筛选〉。“评选”指选出优秀者，把有问题的零件挑出来要用〈筛选〉。"}, {"text": "我在沙滩上评选贝壳，挑了好几个。", "explanation": "这里应该用〈挑拣〉。“评选”指经过评议比较选出优秀者，在沙滩上挑贝壳要用〈挑拣〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校评选了出三个优秀学生。", "corrected_sentence": "学校评选出了三个优秀学生。", "error_description": "补语位置错误：结果补语“出”应紧跟动词，应说“评选出”，不能说“评选了出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前评选了过最佳员工。", "corrected_sentence": "我们以前评选过最佳员工。", "error_description": "体标错误：“评选过”表示曾经评选过，“了”和“过”不能同时出现在动词后，应说“评选过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
