INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93713, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "语文是学说话、读书、写字的课。", "primary_collocate": null, "pronunciation": "yǔ wén", "ipa": "y˨˩˦ wən˧˥", "syllable_count": 2, "sentences": [{"text": "我们上语文，先读课文，再写字。", "target_word": "语文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一年级的孩子在语文里学写字。", "target_word": "语文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不爱算题，就爱读书写字，最喜欢语文。", "target_word": "语文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天有语文，别忘了带课文。", "target_word": "语文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在语文里学说话读书和写字。", "target_word": "语文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，今天语文我们学写自己的名字。", "target_word": "语文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我女儿每天晚上复习语文，读课文，写字。", "target_word": "语文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下课以后，同学们还在讨论语文里的故事。", "target_word": "语文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比起体育，他更怕语文，因为要写很多字。", "target_word": "语文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课表上，星期一的第二节是语文。", "target_word": "语文", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "语文课", "label": "复合"}, {"form": "语文老师", "label": "复合"}], "register": "中性", "sense_fingerprint": "学校里学说话、读书、写字的课", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3dc0c7-80d5-48fc-b8be-6568a6743104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93713, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "语文", "is_correct": true, "explanation": "这是目标词，是学说话、读书、写字的课，与“读课文、写字”的内容相符。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学课的内容与“读课文、写字”不符。"}, {"text": "体育", "is_correct": false, "explanation": "语义：体育课不以读课文为内容，与前半句的活动不相符。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐课的内容与“读课文、写字”不符。"}], "explanations": {"语文": "这是目标词，是学说话、读书、写字的课，与“读课文、写字”的内容相符。", "数学": "语义：数学课的内容与“读课文、写字”不符。", "体育": "语义：体育课不以读课文为内容，与前半句的活动不相符。", "音乐": "语义：音乐课的内容与“读课文、写字”不符。"}, "sentence_index": 0, "correct_answer": "语文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都去语文跑步。", "explanation": "这里应该用〈操场〉。“去”后接场所，“语文”是学科，不是场所。"}, {"text": "我们今天玩了一个很好玩的语文。", "explanation": "这里应该用〈游戏〉。“玩”的对象是游戏，“语文”指学科或语言文字，不能拿来玩。"}, {"text": "老师表扬了这篇语文。", "explanation": "这里应该用〈作文〉。被表扬的是作文这类作品，“语文”是学科，不能用“这篇”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93713, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语文", "is_correct": true, "explanation": "这是目标词，是复习的内容，与“读课文、写字”相符。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐与“读课文、写字”的活动不符。"}, {"text": "游戏", "is_correct": false, "explanation": "搭配：“复习”接的是学过的内容，不接“游戏”。"}, {"text": "美术", "is_correct": false, "explanation": "语义：美术主要是画画，与“读课文、写字”不符。"}], "explanations": {"语文": "这是目标词，是复习的内容，与“读课文、写字”相符。", "音乐": "语义：音乐与“读课文、写字”的活动不符。", "游戏": "搭配：“复习”接的是学过的内容，不接“游戏”。", "美术": "语义：美术主要是画画，与“读课文、写字”不符。"}, "sentence_index": 6, "correct_answer": "语文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给朋友写完了语文，就拿去寄了。", "explanation": "这里应该用〈信〉。写完后拿去寄的是信件，“语文”指学科或语言文字，不能寄出去。"}, {"text": "这首语文很美，大家都喜欢读。", "explanation": "这里应该用〈诗〉。“这首”和“很美”描述的是诗，“语文”是学科或语言文字。"}, {"text": "他每天唱语文，唱到很晚。", "explanation": "这里应该用〈歌〉。唱的是歌曲，“语文”指学科或语言文字，不能用“唱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每周有五只语文课。", "corrected_sentence": "我们每周有五节语文课。", "error_description": "“语文课”的量词应用“节”，不用“只”。“只”用于动物等，不用于课程。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我女儿昨天复习了三只小时语文。", "corrected_sentence": "我女儿昨天复习了三个小时语文。", "error_description": "量词错误：“小时”的量词应用“个”，不用“只”。“只”用于动物等，不用于时间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1adc6bf-316e-4205-a11b-ebfbcdec0c97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
