INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93715, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "考察是去一个地方，仔细看一看，弄明白那里的情况。", "primary_collocate": null, "pronunciation": "kǎo chá", "ipa": "kʰau˨˩˦ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "我们先去山里考察一下路况。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理明天要去工厂考察。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去那座城市考察一下生活环境。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带着学生去公园考察植物的生长情况。", "target_word": "考察", "complexity_tier": "T3", "furigana": "kǎo chá", "sentence_source": "generated"}, {"text": "我们在买房以前先去那个小区考察了一次。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司派他去国外考察市场。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们到村子里考察了三天。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开店以前，我想先去实地考察一下。", "target_word": "考察", "complexity_tier": "T3", "furigana": "kǎo chá", "sentence_source": "generated"}, {"text": "你去那儿考察过吗？", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸去海边考察新的旅游路线。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "考察了", "label": "完成体"}, {"form": "考察过", "label": "经历体"}, {"form": "考察着", "label": "持续体"}, {"form": "考察团", "label": "复合词"}], "register": "中性", "sense_fingerprint": "亲自去某地仔细看，了解当地情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdffcdca-4576-4326-9e48-c5ba571a4003') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93715, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考察", "is_correct": true, "explanation": "考察：亲自去现场仔细看、了解情况，与“去山里”和“路况”搭配，正确。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：演奏是表演乐器，与观察路况无关。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做饭做菜，与了解路况的意思不符。"}, {"text": "栽培", "is_correct": false, "explanation": "搭配：“栽培”用于植物或人才，不能与“路况”搭配。"}], "explanations": {"考察": "考察：亲自去现场仔细看、了解情况，与“去山里”和“路况”搭配，正确。", "演奏": "语义：演奏是表演乐器，与观察路况无关。", "烹饪": "语义：烹饪是做饭做菜，与了解路况的意思不符。", "栽培": "搭配：“栽培”用于植物或人才，不能与“路况”搭配。"}, "sentence_index": 0, "correct_answer": "考察"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我考察了一杯咖啡。", "explanation": "这里应该用〈喝〉。考察指实地观察、调查，不能用于喝东西，“喝一杯咖啡”才是正确说法。"}, {"text": "妈妈每天考察房间。", "explanation": "这里应该用〈打扫〉。考察指实地调查，不能用于清理房间。"}, {"text": "我们考察了那场足球比赛。", "explanation": "这里应该用〈观看〉。考察指实地调查，不能用于观看比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93715, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考察", "is_correct": true, "explanation": "考察：到某地实地调查、了解情况，与“到村子里”和“了三天”搭配，正确。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车船等交通工具，不能用于“到村子里”的调查活动。"}, {"text": "弹奏", "is_correct": false, "explanation": "语义：弹奏是演奏乐器，与到村子里做调查的意思不符。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙是做面包点心，与调查了解的意思无关。"}], "explanations": {"考察": "考察：到某地实地调查、了解情况，与“到村子里”和“了三天”搭配，正确。", "驾驶": "搭配：“驾驶”的对象是车船等交通工具，不能用于“到村子里”的调查活动。", "弹奏": "语义：弹奏是演奏乐器，与到村子里做调查的意思不符。", "烘焙": "语义：烘焙是做面包点心，与调查了解的意思无关。"}, "sentence_index": 6, "correct_answer": "考察"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我考察朋友去逛街。", "explanation": "这里应该用〈陪〉。考察指亲自去现场调查，不能用于陪伴朋友。"}, {"text": "我给朋友考察电话。", "explanation": "这里应该用〈打〉。考察不能用于打电话，“打电话”才是正确说法。"}, {"text": "我考察你回家。", "explanation": "这里应该用〈送〉。考察不能用于送人回家，“送你回家”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93715, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明天要考察了那个小镇。", "corrected_sentence": "他明天要考察那个小镇。", "error_description": "错误：“考察了”中的“了”。正确：去掉“了”，说“明天要考察那个小镇”。“明天要”表示动作还没发生，不能再用表示完成的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93715, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们曾经考察着过那个地区。", "corrected_sentence": "我们曾经考察过那个地区。", "error_description": "错误：“考察着过”。正确：“考察过”。“着”表示持续，“过”表示经历，二者不能同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
