INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93716, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "实地观察、调查并研究。", "primary_collocate": null, "pronunciation": "kǎo chá", "ipa": "kʰau˨˩˦ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "专家正在考察这里的土壤。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家去北极考察气候变化。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们考察了这片森林里的动物。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员考察过很多古代的房子。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组专门考察河水的污染情况。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老教授一生都在考察长城。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究队在沙漠里考察了两个月。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想考察一下当地的民族文化。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者们考察后写出了一份报告。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家一直在考察农村的变化。", "target_word": "考察", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "考察了", "label": "完成体"}, {"form": "考察过", "label": "经历体"}, {"form": "考察着", "label": "持续体"}, {"form": "考察团", "label": "复合词"}], "register": "书面", "sense_fingerprint": "到现场观察、调查并做研究", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdffcdca-4576-4326-9e48-c5ba571a4003') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93716, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考察", "is_correct": true, "explanation": "考察：到现场观察、调查并研究，与“专家”和“土壤”搭配，正确。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：演奏是表演乐器，与研究土壤无关。"}, {"text": "栽培", "is_correct": false, "explanation": "搭配：“栽培”用于植物或人才，不能说“栽培土壤”。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做菜，与观察研究土壤的意思不符。"}], "explanations": {"考察": "考察：到现场观察、调查并研究，与“专家”和“土壤”搭配，正确。", "演奏": "语义：演奏是表演乐器，与研究土壤无关。", "栽培": "搭配：“栽培”用于植物或人才，不能说“栽培土壤”。", "烹饪": "语义：烹饪是做菜，与观察研究土壤的意思不符。"}, "sentence_index": 0, "correct_answer": "考察"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他考察了这道数学题。", "explanation": "这里应该用〈解〉。考察指实地观察、调查，不能用于解题。"}, {"text": "孩子们考察了那本童话书。", "explanation": "这里应该用〈阅读〉。考察指实地调查，读书应该说“阅读”。"}, {"text": "妈妈考察了一顿晚饭。", "explanation": "这里应该用〈准备〉。考察不能用于准备饭菜，“准备晚饭”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考察", "is_correct": true, "explanation": "考察：到沙漠实地调查、了解情况，与“在沙漠里”和“两个月”搭配，正确。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：沙漠里不能游泳，游泳也不表示调查研究。"}, {"text": "滑冰", "is_correct": false, "explanation": "语义：沙漠里不能滑冰，滑冰与调查研究的意思无关。"}, {"text": "钓鱼", "is_correct": false, "explanation": "语义：钓鱼需要水域，沙漠里不能钓鱼，也与调查研究无关。"}], "explanations": {"考察": "考察：到沙漠实地调查、了解情况，与“在沙漠里”和“两个月”搭配，正确。", "游泳": "语义：沙漠里不能游泳，游泳也不表示调查研究。", "滑冰": "语义：沙漠里不能滑冰，滑冰与调查研究的意思无关。", "钓鱼": "语义：钓鱼需要水域，沙漠里不能钓鱼，也与调查研究无关。"}, "sentence_index": 6, "correct_answer": "考察"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他考察了一张照片。", "explanation": "这里应该用〈拍〉。考察指实地调查，不能用于拍照片，“拍一张照片”才是正确说法。"}, {"text": "我考察了一碗面。", "explanation": "这里应该用〈吃〉。考察不能用于吃东西，“吃一碗面”才是正确说法。"}, {"text": "她考察了一首歌。", "explanation": "这里应该用〈唱〉。考察不能用于唱歌，“唱一首歌”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "专家去那片湿地考察着过。", "corrected_sentence": "专家去那片湿地考察过。", "error_description": "错误：“考察着过”。正确：“考察过”。“着”表示持续，“过”表示经历，二者不能同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在考察了农村的变化。", "corrected_sentence": "他正在考察农村的变化。", "error_description": "错误：“正在……考察了”。正确：“正在考察”。“正在”表示动作进行，不能与表示完成的“了”同时用于同一动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93717, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反驳", "is_correct": true, "explanation": "反义：反驳指用理由驳倒对方的论断，与论证自己的观点相对。"}, {"text": "购买", "is_correct": false, "explanation": "无关：购买指付钱取得物品，与论证没有反义关系。"}, {"text": "保护", "is_correct": false, "explanation": "无关：保护指照护、护卫，与论证不构成反义。"}, {"text": "参加", "is_correct": false, "explanation": "无关：参加指加入某项活动，与论证无关。"}], "correct_answer": "反驳", "explanations": {"反驳": "反义：反驳指用理由驳倒对方的论断，与论证自己的观点相对。", "购买": "无关：购买指付钱取得物品，与论证没有反义关系。", "保护": "无关：保护指照护、护卫，与论证不构成反义。", "参加": "无关：参加指加入某项活动，与论证无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93717, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反驳", "is_correct": true, "explanation": "反义：反驳指用理由驳倒对方的论断，与论证相对。"}, {"text": "陪伴", "is_correct": false, "explanation": "无关：陪伴指伴随在旁，与论证无关。"}, {"text": "参观", "is_correct": false, "explanation": "无关：参观指到某处察看，与论证无关。"}, {"text": "邀请", "is_correct": false, "explanation": "无关：邀请指请人来做客，与论证无关。"}], "correct_answer": "反驳", "explanations": {"反驳": "反义：反驳指用理由驳倒对方的论断，与论证相对。", "陪伴": "无关：陪伴指伴随在旁，与论证无关。", "参观": "无关：参观指到某处察看，与论证无关。", "邀请": "无关：邀请指请人来做客，与论证无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93717, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "论证是用道理和证据，说明一件事是对的。", "primary_collocate": null, "pronunciation": "lùn zhèng", "ipa": "lwən˥˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他用很多数据论证自己的想法是对的。", "target_word": "论证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们论证这个办法可行。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位科学家用实验论证了新理论。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要用事实来论证你的看法。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一步一步论证，大家都听懂了。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她论证了这个计划为什么能成功。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "律师用证据论证他的朋友没有说谎。", "target_word": "论证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请论证一下这样做的正当性。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他试图论证这项政策的合理性。", "target_word": "论证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先说道理，再用例子论证。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "论证了", "label": "完成体"}, {"form": "论证过", "label": "经历体"}, {"form": "论证一下", "label": "短时"}], "register": "书面", "sense_fingerprint": "用道理和证据说明某事正确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43035244-64f2-4d65-bc07-110cd48c7371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93717, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "质疑", "is_correct": false, "explanation": "语义：质疑指提出疑问，与“想法是对的”的肯定结论矛盾。"}, {"text": "否定", "is_correct": false, "explanation": "语义：否定指认为不对，与“想法是对的”矛盾。"}, {"text": "论证", "is_correct": true, "explanation": "正确：论证指用道理和证据说明某事正确，与“想法是对的”一致。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“用很多数据”限定的动作是论证或说明，不说“用数据赞美”。"}], "explanations": {"质疑": "语义：质疑指提出疑问，与“想法是对的”的肯定结论矛盾。", "否定": "语义：否定指认为不对，与“想法是对的”矛盾。", "论证": "正确：论证指用道理和证据说明某事正确，与“想法是对的”一致。", "赞美": "搭配：“用很多数据”限定的动作是论证或说明，不说“用数据赞美”。"}, "sentence_index": 0, "correct_answer": "论证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他论证了那辆汽车。", "explanation": "这里应该用〈检查〉。论证的对象是论点、观点，具体的汽车要用检查，不说论证。"}, {"text": "他论证了一杯咖啡，觉得很好喝。", "explanation": "这里应该用〈品尝〉。论证的对象是观点、论点，咖啡要说品尝，不说论证。"}, {"text": "他用歌声论证了自己的感情。", "explanation": "这里应该用〈表达〉。论证用于观点、论点，感情要用表达，不说论证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93717, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "揭露", "is_correct": false, "explanation": "语义：揭露指暴露隐藏的事实，与“他的朋友没有说谎”的结论矛盾。"}, {"text": "怀疑", "is_correct": false, "explanation": "语义：怀疑指不相信，与“他的朋友没有说谎”的结论矛盾。"}, {"text": "论证", "is_correct": true, "explanation": "正确：论证指用证据说明某事正确，与“没有说谎”一致。"}, {"text": "夸奖", "is_correct": false, "explanation": "搭配：夸奖的对象是人或行为，“没有说谎”是事实判断，不说“夸奖没有说谎”。"}], "explanations": {"揭露": "语义：揭露指暴露隐藏的事实，与“他的朋友没有说谎”的结论矛盾。", "怀疑": "语义：怀疑指不相信，与“他的朋友没有说谎”的结论矛盾。", "论证": "正确：论证指用证据说明某事正确，与“没有说谎”一致。", "夸奖": "搭配：夸奖的对象是人或行为，“没有说谎”是事实判断，不说“夸奖没有说谎”。"}, "sentence_index": 6, "correct_answer": "论证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用道理论证了大家。", "explanation": "这里应该用〈说服〉。论证的对象是论点，不能直接用于人。"}, {"text": "这位学生论证了自己的经历。", "explanation": "这里应该用〈讲述〉。论证是说明道理的论述，讲述经历要用讲述。"}, {"text": "警察论证了那扇门的颜色。", "explanation": "这里应该用〈辨认〉。论证是用道理证明观点，颜色要用辨认。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她被认真论证了自己的观点。", "corrected_sentence": "她认真论证了自己的观点。", "error_description": "“被”用错了：这里“她”是论证的人，不能用“被”，应说“她认真论证了自己的观点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要很论证这个方法是否可行。", "corrected_sentence": "我们要论证这个方法是否可行。", "error_description": "“很”不能修饰动词：论证是动词，应说“我们要论证这个方法是否可行”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
