INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93719, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "考核是用考试或别的办法，看一个人做得好不好。", "primary_collocate": null, "pronunciation": "kǎo hé", "ipa": "kʰaʊ˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "公司每年都考核新员工。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用考试考核学生的汉语水平。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月公司要考核每位员工一次。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院怎么考核新来的医生？", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用做菜的办法来考核厨师。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理正在考核每个人的工作。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校用口试考核学生的口语。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想考核一下他的能力。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，教练要考核一下队员。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作三个月后，公司会考核你。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "考核了", "label": "体标"}, {"form": "考核过", "label": "体标"}, {"form": "考核着", "label": "体标"}], "register": "中性", "sense_fingerprint": "用考试或别的办法看一个人做得好不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb8dd41a-3ee5-4ea6-a6a8-3eb267922083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93719, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考核", "is_correct": true, "explanation": "正确：考核指按标准评定员工的表现，与“每年”“新员工”的语境相符。"}, {"text": "检修", "is_correct": false, "explanation": "语义：检修指检查、修理机器设备，不能用于员工。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：打扫的对象是场所或卫生，不能说打扫员工。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪指做饭菜，与评定员工无关。"}], "explanations": {"考核": "正确：考核指按标准评定员工的表现，与“每年”“新员工”的语境相符。", "检修": "语义：检修指检查、修理机器设备，不能用于员工。", "打扫": "搭配：打扫的对象是场所或卫生，不能说打扫员工。", "烹饪": "语义：烹饪指做饭菜，与评定员工无关。"}, "sentence_index": 0, "correct_answer": "考核"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们去南方考核了当地的风土人情。", "explanation": "这里应该用〈考察〉。考核评定人的成绩或表现，了解当地风土人情要用考察。"}, {"text": "科学家每天考核蚂蚁的行为。", "explanation": "这里应该用〈观察〉。考核针对人的成绩或表现，不能用来说观察动物的行为。"}, {"text": "医生考核了病人的心脏。", "explanation": "这里应该用〈检查〉。考核评定的是人的成绩和表现，对身体器官的检查不用考核。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93719, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考核", "is_correct": true, "explanation": "正确：考核指用口试等办法评定学生的口语水平，与“口试”相符。"}, {"text": "播种", "is_correct": false, "explanation": "语义：播种指把种子种进土里，不能用来说口试和口语。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：装修的对象是房屋，不能说装修学生的口语。"}, {"text": "烧制", "is_correct": false, "explanation": "语义：烧制指用火烧陶瓷等物品，与口试和口语无关。"}], "explanations": {"考核": "正确：考核指用口试等办法评定学生的口语水平，与“口试”相符。", "播种": "语义：播种指把种子种进土里，不能用来说口试和口语。", "装修": "搭配：装修的对象是房屋，不能说装修学生的口语。", "烧制": "语义：烧制指用火烧陶瓷等物品，与口试和口语无关。"}, "sentence_index": 6, "correct_answer": "考核"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "专家考核了这座桥的安全性。", "explanation": "这里应该用〈评估〉。考核评定的是人的成绩或表现，不用于评定桥梁的安全。"}, {"text": "编辑考核了这篇稿子。", "explanation": "这里应该用〈审核〉。考核评定的是人的表现，稿件内容要用审核。"}, {"text": "工程师每天考核机器的温度。", "explanation": "这里应该用〈监测〉。考核评定的是人的成绩或表现，机器的温度要用监测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93719, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理把我们的工作考核。", "corrected_sentence": "经理把我们的工作考核了。", "error_description": "把字句中动词后面要有其他成分，如“了”。错误形式“把我们的工作考核”缺少“了”，应说“考核了”，“了”放在动词后面，句子才完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93719, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校考核了过全班同学的口语。", "corrected_sentence": "学校考核过全班同学的口语。", "error_description": "“了”和“过”不能同时用在同一个动词后面。表示曾经做过，应说“考核过”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
