INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93720, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按一定标准检查、评定人的成绩或表现。", "primary_collocate": null, "pronunciation": "kǎo hé", "ipa": "kʰaʊ˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "学校按标准考核老师的成绩。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司按销售成绩考核每个员工。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂里每月考核工人的表现。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导根据表现考核干部。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司用分数考核员工的工作。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校怎么考核老师的教学成绩？", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个季度，我们都要考核大家的成绩。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司考核员工，主要看工作完成得好不好。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院按规定考核护士的表现。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板根据标准考核新来的经理。", "target_word": "考核", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "考核了", "label": "体标"}, {"form": "考核过", "label": "体标"}, {"form": "考核着", "label": "体标"}], "register": "中性", "sense_fingerprint": "按一定标准检查、评定人的成绩或表现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb8dd41a-3ee5-4ea6-a6a8-3eb267922083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93720, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考核", "is_correct": true, "explanation": "正确：考核指按标准评定人的成绩，与“按标准”“老师的成绩”相符。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：装饰的对象是物品或空间，不能说装饰成绩。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪指做饭菜，与评定成绩无关。"}, {"text": "烧制", "is_correct": false, "explanation": "语义：烧制指用火烧制陶瓷等物品，与成绩无关。"}], "explanations": {"考核": "正确：考核指按标准评定人的成绩，与“按标准”“老师的成绩”相符。", "装饰": "搭配：装饰的对象是物品或空间，不能说装饰成绩。", "烹饪": "语义：烹饪指做饭菜，与评定成绩无关。", "烧制": "语义：烧制指用火烧制陶瓷等物品，与成绩无关。"}, "sentence_index": 0, "correct_answer": "考核"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "代表团去那个国家考核了博物馆的藏品。", "explanation": "这里应该用〈鉴定〉。考核评定人的成绩或表现，评定藏品的真伪要用鉴定。"}, {"text": "科学家在显微镜下考核细胞的变化。", "explanation": "这里应该用〈观察〉。考核评定的是人的成绩或表现，不能用来说观察细胞。"}, {"text": "厨师每天考核这锅汤的咸淡。", "explanation": "这里应该用〈品尝〉。考核评定人的成绩或表现，尝汤的咸淡要用品尝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考核", "is_correct": true, "explanation": "正确：考核指按标准评定大家的成绩，与“每个季度”的语境相符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：打扫的对象是场所，不能说打扫成绩。"}, {"text": "检修", "is_correct": false, "explanation": "语义：检修针对机器设备，与大家的成绩无关。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植指栽种植物，不能用来说成绩。"}], "explanations": {"考核": "正确：考核指按标准评定大家的成绩，与“每个季度”的语境相符。", "打扫": "搭配：打扫的对象是场所，不能说打扫成绩。", "检修": "语义：检修针对机器设备，与大家的成绩无关。", "种植": "语义：种植指栽种植物，不能用来说成绩。"}, "sentence_index": 6, "correct_answer": "考核"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工作人员每天考核空气质量。", "explanation": "这里应该用〈监测〉。考核评定的是人，空气质量要用监测。"}, {"text": "工人考核了房间的面积。", "explanation": "这里应该用〈测量〉。考核是评定人的表现，测量面积要用测量。"}, {"text": "海关考核了旅客的行李。", "explanation": "这里应该用〈检查〉。考核的对象是人的成绩或表现，海关查验旅客行李应说检查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "领导严格的考核干部。", "corrected_sentence": "领导严格地考核干部。", "error_description": "“严格”修饰动词“考核”时应用“地”，错误形式用了“的”。“严格的考核”是名词短语，后面不能直接接宾语“干部”，应说“严格地考核干部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板已经考核着新来的经理。", "corrected_sentence": "老板已经考核过新来的经理。", "error_description": "“已经”表示动作已完成，应与“过”搭配。“着”表示动作正在进行，与“已经”矛盾，应改为“考核过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93721, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "朴素", "is_correct": true, "explanation": "正确答案。“朴素”指不讲排场、外观简单，与“豪华”构成反义。"}, {"text": "明亮", "is_correct": false, "explanation": "与“豪华”无反义关系；“明亮”说光线充足，不说档次与价钱。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“豪华”无反义关系；“陡峭”形容地势或坡度，与东西的档次无关。"}, {"text": "寂静", "is_correct": false, "explanation": "与“豪华”无反义关系；“寂静”形容周围没有声音，与外观和价钱无关。"}], "correct_answer": "朴素", "explanations": {"朴素": "正确答案。“朴素”指不讲排场、外观简单，与“豪华”构成反义。", "明亮": "与“豪华”无反义关系；“明亮”说光线充足，不说档次与价钱。", "陡峭": "与“豪华”无反义关系；“陡峭”形容地势或坡度，与东西的档次无关。", "寂静": "与“豪华”无反义关系；“寂静”形容周围没有声音，与外观和价钱无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93721, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "简陋", "is_correct": true, "explanation": "正确答案。“简陋”指简单粗陋、不讲排场，与“豪华”构成反义。"}, {"text": "清澈", "is_correct": false, "explanation": "与“豪华”无反义关系；“清澈”形容水或眼睛清亮透明。"}, {"text": "沉重", "is_correct": false, "explanation": "与“豪华”无反义关系；“沉重”说重量大或心情压抑，与档次无关。"}, {"text": "湿润", "is_correct": false, "explanation": "与“豪华”无反义关系；“湿润”形容含水分适中，与陈设、价钱无关。"}], "correct_answer": "简陋", "explanations": {"简陋": "正确答案。“简陋”指简单粗陋、不讲排场，与“豪华”构成反义。", "清澈": "与“豪华”无反义关系；“清澈”形容水或眼睛清亮透明。", "沉重": "与“豪华”无反义关系；“沉重”说重量大或心情压抑，与档次无关。", "湿润": "与“豪华”无反义关系；“湿润”形容含水分适中，与陈设、价钱无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93721, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "豪华是特别漂亮，又很贵。", "primary_collocate": null, "pronunciation": "háo huá", "ipa": "xɑʊ˧˥ xwɑ˧˥", "syllable_count": 2, "sentences": [{"text": "他买了一辆豪华汽车。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个酒店又大又豪华。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我住过一家很豪华的酒店。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的新家不太豪华。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐着豪华游轮去旅行。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着一件豪华的晚礼服出席了宴会。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "豪华的房子价钱也很高。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不用住得太豪华。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友送了我一个豪华礼盒。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家餐厅太豪华，我们吃不起。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "豪华车", "label": "复合词"}, {"form": "豪华酒店", "label": "复合词"}], "register": "中性", "sense_fingerprint": "形容东西特别漂亮而且价钱很高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e36a8cdb-5406-47d1-930e-7fc5be5a3f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93721, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "豪华", "is_correct": true, "explanation": "正确答案。豪华（háo huá）：特别漂亮，又很贵。"}, {"text": "好话", "is_correct": false, "explanation": "hǎo huà 与 háo huá 两个音节的声调都不同，意思是好的话语。"}, {"text": "好花", "is_correct": false, "explanation": "hǎo huā 与 háo huá 两个音节的声调都不同，意思是好看的花。"}, {"text": "好滑", "is_correct": false, "explanation": "hǎo huá 与 háo huá 只有第一个音节声调不同，意思是很滑。"}], "explanations": {"豪华": "正确答案。豪华（háo huá）：特别漂亮，又很贵。", "好话": "hǎo huà 与 háo huá 两个音节的声调都不同，意思是好的话语。", "好花": "hǎo huā 与 háo huá 两个音节的声调都不同，意思是好看的花。", "好滑": "hǎo huá 与 háo huá 只有第一个音节声调不同，意思是很滑。"}, "sentence_index": null, "correct_answer": "豪华"}, "level_3": {"options": [{"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”说质地，不能用来修饰汽车。"}, {"text": "免费", "is_correct": false, "explanation": "语义：“免费”与“买”矛盾，免费的东西不需要购买。"}, {"text": "豪华", "is_correct": true, "explanation": "正确答案。“豪华”形容汽车的档次高、特别漂亮又很贵，修饰“汽车”。"}, {"text": "清秀", "is_correct": false, "explanation": "体貌：“清秀”多形容人的容貌，不用来形容汽车。"}], "explanations": {"柔软": "搭配：“柔软”说质地，不能用来修饰汽车。", "免费": "语义：“免费”与“买”矛盾，免费的东西不需要购买。", "豪华": "正确答案。“豪华”形容汽车的档次高、特别漂亮又很贵，修饰“汽车”。", "清秀": "体貌：“清秀”多形容人的容貌，不用来形容汽车。"}, "sentence_index": 0, "correct_answer": "豪华"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块手表的价格很豪华。", "explanation": "这里应该用〈昂贵〉。豪华形容东西特别漂亮、档次高，不用来形容价格；说价格高要用昂贵。"}, {"text": "他花钱很豪华，一个月买了好几件名牌。", "explanation": "这里应该用〈奢侈〉。豪华形容东西的档次与排场，不用来形容花钱的样子；花钱大手大脚要用奢侈。"}, {"text": "这碗汤的味道很豪华。", "explanation": "这里应该用〈鲜美〉。豪华形容东西的档次与排场，不用来形容味道；说味道好要用鲜美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93721, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”与“价钱也很高”相矛盾，便宜的房子价钱不会很高。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”多形容人的笑容或声音，不用来形容房子。"}, {"text": "清瘦", "is_correct": false, "explanation": "体貌：“清瘦”形容人的身材，不用来形容房子。"}, {"text": "豪华", "is_correct": true, "explanation": "正确答案。“豪华”形容东西特别漂亮、价钱很高，修饰“房子”，与“价钱也很高”相合。"}], "explanations": {"便宜": "语义：“便宜”与“价钱也很高”相矛盾，便宜的房子价钱不会很高。", "甜美": "搭配：“甜美”多形容人的笑容或声音，不用来形容房子。", "清瘦": "体貌：“清瘦”形容人的身材，不用来形容房子。", "豪华": "正确答案。“豪华”形容东西特别漂亮、价钱很高，修饰“房子”，与“价钱也很高”相合。"}, "sentence_index": 6, "correct_answer": "豪华"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅油画的色彩很豪华。", "explanation": "这里应该用〈华丽〉。豪华形容东西的档次与排场，不用来形容色彩、花纹；说色彩漂亮要用华丽。"}, {"text": "他的歌声很豪华。", "explanation": "这里应该用〈豪放〉。豪华形容东西的档次与排场，不用来形容歌声；形容歌声气势奔放、不拘一格要用豪放。"}, {"text": "这篇文章的气势很豪华。", "explanation": "这里应该用〈豪迈〉。豪华形容东西的档次与排场，不用来形容文章的气势；形容气概雄壮、充满豪情要用豪迈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93721, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她买了一辆豪华得轿车。", "corrected_sentence": "她买了一辆豪华轿车。", "error_description": "错误：「豪华得轿车」；正确：「豪华轿车」。「得」用于动词或形容词后作补语，不能用来连接定语与名词；此处修饰名词，应说「豪华轿车」（或「豪华的轿车」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93721, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家宾馆太豪华太，我们住不起。", "corrected_sentence": "这家宾馆太豪华，我们住不起。", "error_description": "错误：「太豪华太」；多出的「太」。「太」已修饰形容词「豪华」，不能重复加在其后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93722, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "简陋", "is_correct": true, "explanation": "正确答案。“简陋”指简单粗陋、不讲排场，与“豪华”的富丽堂皇构成反义。"}, {"text": "狭窄", "is_correct": false, "explanation": "与“豪华”无反义关系；“狭窄”说空间小，不说陈设与场面的富丽程度。"}, {"text": "明亮", "is_correct": false, "explanation": "与“豪华”无反义关系；“明亮”说光线充足，不是“豪华”的对立面。"}, {"text": "安静", "is_correct": false, "explanation": "与“豪华”无反义关系；“安静”说声音少，不与陈设、场面的华美相对。"}], "correct_answer": "简陋", "explanations": {"简陋": "正确答案。“简陋”指简单粗陋、不讲排场，与“豪华”的富丽堂皇构成反义。", "狭窄": "与“豪华”无反义关系；“狭窄”说空间小，不说陈设与场面的富丽程度。", "明亮": "与“豪华”无反义关系；“明亮”说光线充足，不是“豪华”的对立面。", "安静": "与“豪华”无反义关系；“安静”说声音少，不与陈设、场面的华美相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93722, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "朴素", "is_correct": true, "explanation": "正确答案。“朴素”指不讲排场、陈设简单，与“豪华”构成反义。"}, {"text": "清澈", "is_correct": false, "explanation": "与“豪华”无反义关系；“清澈”形容水或眼睛等清亮透明。"}, {"text": "沉重", "is_correct": false, "explanation": "与“豪华”无反义关系；“沉重”说重量大或心情压抑，不说陈设与场面。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“豪华”无反义关系；“陡峭”形容地势或坡度，与装饰排场无关。"}], "correct_answer": "朴素", "explanations": {"朴素": "正确答案。“朴素”指不讲排场、陈设简单，与“豪华”构成反义。", "清澈": "与“豪华”无反义关系；“清澈”形容水或眼睛等清亮透明。", "沉重": "与“豪华”无反义关系；“沉重”说重量大或心情压抑，不说陈设与场面。", "陡峭": "与“豪华”无反义关系；“陡峭”形容地势或坡度，与装饰排场无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93722, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（陈设、场面等）富丽堂皇，奢侈华美。", "primary_collocate": null, "pronunciation": "háo huá", "ipa": "xɑʊ˧˥ xwɑ˧˥", "syllable_count": 2, "sentences": [{"text": "这家酒店的大厅非常豪华。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们举行了一场豪华的婚礼。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的陈设很豪华。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会的场面十分豪华。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座别墅装修得特别豪华。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的内部不算豪华。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她住在一栋豪华的大楼里。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宴会厅布置得豪华极了。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都被豪华的舞台吸引住了。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个餐厅看上去很豪华。", "target_word": "豪华", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "豪华车", "label": "复合词"}, {"form": "豪华酒店", "label": "复合词"}], "register": "中性", "sense_fingerprint": "形容陈设、场面等富丽堂皇、奢侈华美", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e36a8cdb-5406-47d1-930e-7fc5be5a3f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93722, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "豪华", "is_correct": true, "explanation": "正确答案。豪华（háo huá）：陈设、场面富丽堂皇，奢侈华美。"}, {"text": "好话", "is_correct": false, "explanation": "hǎo huà 与 háo huá 两个音节的声调都不同（háo 第二声与 hǎo 第三声，huá 第二声与 huà 第四声），意思是好的话语。"}, {"text": "好花", "is_correct": false, "explanation": "hǎo huā 与 háo huá 两个音节的声调都不同（第三声、第一声），意思是好看的花。"}, {"text": "好滑", "is_correct": false, "explanation": "hǎo huá 与 háo huá 只有第一个音节声调不同（háo 第二声与 hǎo 第三声），意思是很滑。"}], "explanations": {"豪华": "正确答案。豪华（háo huá）：陈设、场面富丽堂皇，奢侈华美。", "好话": "hǎo huà 与 háo huá 两个音节的声调都不同（háo 第二声与 hǎo 第三声，huá 第二声与 huà 第四声），意思是好的话语。", "好花": "hǎo huā 与 háo huá 两个音节的声调都不同（第三声、第一声），意思是好看的花。", "好滑": "hǎo huá 与 háo huá 只有第一个音节声调不同（háo 第二声与 hǎo 第三声），意思是很滑。"}, "sentence_index": null, "correct_answer": "豪华"}, "level_3": {"options": [{"text": "清脆", "is_correct": false, "explanation": "搭配：「清脆」形容声音，不用来形容大厅的陈设与场面。"}, {"text": "豪华", "is_correct": true, "explanation": "正确答案。“豪华”形容陈设、场面富丽堂皇，与“非常”搭配，修饰“大厅”的装潢与氛围。"}, {"text": "低廉", "is_correct": false, "explanation": "搭配：“低廉”说价格便宜，不用来形容大厅的装修或陈设。"}, {"text": "纤细", "is_correct": false, "explanation": "体貌：“纤细”形容细长、瘦弱的样子，不用来形容大厅的外观与陈设。"}], "explanations": {"清脆": "搭配：「清脆」形容声音，不用来形容大厅的陈设与场面。", "豪华": "正确答案。“豪华”形容陈设、场面富丽堂皇，与“非常”搭配，修饰“大厅”的装潢与氛围。", "低廉": "搭配：“低廉”说价格便宜，不用来形容大厅的装修或陈设。", "纤细": "体貌：“纤细”形容细长、瘦弱的样子，不用来形容大厅的外观与陈设。"}, "sentence_index": 0, "correct_answer": "豪华"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他花钱很豪华，一个月买了好几件名牌。", "explanation": "这里应该用〈奢侈〉。豪华形容陈设、场面的排场，不用来形容花钱的样子；说花钱大手大脚要用奢侈。"}, {"text": "这幅油画的色彩很豪华。", "explanation": "这里应该用〈华丽〉。豪华侧重陈设、场面的规模与排场，说色彩、花纹等要用华丽。"}, {"text": "她的舞姿很豪华。", "explanation": "这里应该用〈优美〉。豪华侧重陈设、场面的富丽与排场，不用来形容舞姿；形容舞姿美好要用优美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”多形容人或动物的身材，与“大楼”的高大相矛盾。"}, {"text": "香甜", "is_correct": false, "explanation": "搭配：“香甜”说味道，不能用来修饰大楼。"}, {"text": "袖珍", "is_correct": false, "explanation": "语义：“袖珍”指极小的样式，与“大楼”的大相矛盾。"}, {"text": "豪华", "is_correct": true, "explanation": "正确答案。“豪华”形容陈设、场面富丽堂皇，修饰“大楼”，与“住在”的语境相合。"}], "explanations": {"矮小": "体貌：“矮小”多形容人或动物的身材，与“大楼”的高大相矛盾。", "香甜": "搭配：“香甜”说味道，不能用来修饰大楼。", "袖珍": "语义：“袖珍”指极小的样式，与“大楼”的大相矛盾。", "豪华": "正确答案。“豪华”形容陈设、场面富丽堂皇，修饰“大楼”，与“住在”的语境相合。"}, "sentence_index": 6, "correct_answer": "豪华"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的旋律很豪华。", "explanation": "这里应该用〈豪迈〉。豪华指陈设、场面的富丽，不用来形容旋律；形容旋律气势雄壮要用豪迈。"}, {"text": "他性格豪华，很讲义气。", "explanation": "这里应该用〈豪爽〉。豪华形容物品或场面，不用来形容人的性格；性情直爽、不拘小节要用豪爽。"}, {"text": "这首词的风格很豪华。", "explanation": "这里应该用〈豪放〉。豪华不用来形容文学作品的风格；风格气势奔放要用豪放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在酒店举办了一场豪华地晚宴。", "corrected_sentence": "他们在酒店举办了一场豪华的晚宴。", "error_description": "“豪华”修饰名词“晚宴”，应用结构助词“的”：“一场豪华的晚宴”。误用“地”（地用于修饰动词）是的／地混用的常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个客厅布置得很豪华很。", "corrected_sentence": "这个客厅布置得很豪华。", "error_description": "错误：「很豪华很」；多出的「很」。「很」已修饰形容词「豪华」，不能再加在其后重复修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
