INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93723, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "至爱是最爱的，比别的都更爱。", "primary_collocate": null, "pronunciation": "zhì ài", "ipa": "ʈʂɻ̩˥˩ aɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这是我至爱的食物。", "target_word": "至爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他至爱的朋友搬到了外地。", "target_word": "至爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外婆至爱的花开了。", "target_word": "至爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她送给我至爱的玩具。", "target_word": "至爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是妈妈至爱的一首老歌。", "target_word": "至爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想起了至爱的故乡。", "target_word": "至爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶至爱的孙子来看她了。", "target_word": "至爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画是画家至爱的作品。", "target_word": "至爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我至爱的老师今天要退休了。", "target_word": "至爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷至爱的茶叶放在柜子里。", "target_word": "至爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "至愛", "label": "繁体"}], "register": "书面", "sense_fingerprint": "作定语，表示最爱的，比其他都更爱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8eb21289-7e21-4025-8e45-bb69550d4010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93723, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "至爱", "is_correct": true, "explanation": "正确答案：“至爱”修饰“食物”，表示我最爱的食物。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材，不能修饰食物。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：“瘦弱”形容人的身体状态，不能修饰食物。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”形容人不说话，不能修饰食物。"}], "explanations": {"至爱": "正确答案：“至爱”修饰“食物”，表示我最爱的食物。", "高大": "体貌：“高大”形容人或物的身材，不能修饰食物。", "瘦弱": "体貌：“瘦弱”形容人的身体状态，不能修饰食物。", "沉默": "语义：“沉默”形容人不说话，不能修饰食物。"}, "sentence_index": 0, "correct_answer": "至爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把伞很至爱。", "explanation": "这里应该用〈很珍贵〉。“至爱”表示比别的都更爱，不能作谓语受“很”修饰。"}, {"text": "这件外套有点至爱。", "explanation": "这里应该用〈有点珍贵〉。“至爱”表示比别的都更爱，已是最高程度，不能用“有点”来表示程度。"}, {"text": "他至爱地看着窗外。", "explanation": "这里应该用〈深情地〉。“至爱”表示最爱，不能表示“深情地”这种动作方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93723, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "至爱", "is_correct": true, "explanation": "正确答案：“至爱”修饰“孙子”，表示奶奶最疼爱的孙子。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”形容物体能透光，不能修饰人的孙子。"}, {"text": "扁平", "is_correct": false, "explanation": "体貌：“扁平”形容形状或体态，不能修饰孙子。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：“滚烫”形容温度，不能修饰孙子。"}], "explanations": {"至爱": "正确答案：“至爱”修饰“孙子”，表示奶奶最疼爱的孙子。", "透明": "语义：“透明”形容物体能透光，不能修饰人的孙子。", "扁平": "体貌：“扁平”形容形状或体态，不能修饰孙子。", "滚烫": "语义：“滚烫”形容温度，不能修饰孙子。"}, "sentence_index": 6, "correct_answer": "至爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书比那本更至爱。", "explanation": "这里应该用〈更喜欢〉。“至爱”已表示比别的都更爱，不能再用“更”作比较。"}, {"text": "这份礼物太至爱了。", "explanation": "这里应该用〈太珍贵了〉。“至爱”表示最爱，不能受“太……了”修饰。"}, {"text": "他至爱地拿着这块布。", "explanation": "这里应该用〈珍惜地〉。“至爱”表示最爱，不能用“地”表示“珍惜地”这种动作方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93723, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "外婆至爱小院子在村口。", "corrected_sentence": "外婆至爱的小院子在村口。", "error_description": "漏掉“的”：“至爱”修饰名词时应说“至爱的小院子”，漏掉“的”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93723, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷至爱老的茶杯摆在窗台上。", "corrected_sentence": "爷爷至爱的老茶杯摆在窗台上。", "error_description": "“的”位置错误：“至爱”修饰名词时，“的”应紧跟“至爱”，“老”在后，应说“至爱的老茶杯”，不能说“至爱老的茶杯”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
