INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93725, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "西南是在西边和南边中间的那个方向。", "primary_collocate": null, "pronunciation": "xī nán", "ipa": "ɕi˥ nan˧˥", "syllable_count": 2, "sentences": [{"text": "我家在学校的西南，走路十分钟就到。", "target_word": "西南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上，西在左边，南在下边，西南在左下角。", "target_word": "西南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风从西南吹过来，天气会变热。", "target_word": "西南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的西南有一个小湖。", "target_word": "西南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你往西南走，就能看到那座桥。", "target_word": "西南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的西南是新开发的地区。", "target_word": "西南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的教室在楼的西南，下午很晒。", "target_word": "西南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说，车站在西南，不在东北。", "target_word": "西南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，太阳在西南落下。", "target_word": "西南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手里的地图上，箭头指向西南。", "target_word": "西南", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "西南：西边和南边之间的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ab86027-31e9-470c-a719-029cfab81c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93725, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "东西", "is_correct": false, "explanation": "语义：“东西”指物品，“我家在学校的东西”说不通。"}, {"text": "西南", "is_correct": true, "explanation": "西南是学校西边和南边之间的方向，符合“在学校的……”的方位说法。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场是活动场地，“我家”不会设在操场的位置上。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“我家”是住处，不能用“食堂”这类场所作住址的方位。"}], "explanations": {"东西": "语义：“东西”指物品，“我家在学校的东西”说不通。", "西南": "西南是学校西边和南边之间的方向，符合“在学校的……”的方位说法。", "操场": "语义：操场是活动场地，“我家”不会设在操场的位置上。", "食堂": "搭配：“我家”是住处，不能用“食堂”这类场所作住址的方位。"}, "sentence_index": 0, "correct_answer": "西南"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹妹每天中午都吃西南。", "explanation": "这里把“西南”当作食物来吃，是词义误用：方位名词不指可以吃的东西。"}, {"text": "他把西南放进书包里带回家了。", "explanation": "这里把“西南”当作可以拿的物品，方位名词不能作“放进书包”的对象。"}, {"text": "我的数学作业是西南。", "explanation": "这里把“西南”当作作业内容，方位名词不能表示作业，句意不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93725, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "东北", "is_correct": false, "explanation": "语义：东北方向下午不会西晒，与后句“下午很晒”不符。"}, {"text": "楼梯", "is_correct": false, "explanation": "搭配：“楼的”后可接方位，但“楼梯”是建筑部件，教室不设在楼梯的位置。"}, {"text": "西南", "is_correct": true, "explanation": "西南是楼的西南方向，下午阳光照射多，符合“下午很晒”。"}, {"text": "地下室", "is_correct": false, "explanation": "语义：地下室少有阳光，与“下午很晒”矛盾。"}], "explanations": {"东北": "语义：东北方向下午不会西晒，与后句“下午很晒”不符。", "楼梯": "搭配：“楼的”后可接方位，但“楼梯”是建筑部件，教室不设在楼梯的位置。", "西南": "西南是楼的西南方向，下午阳光照射多，符合“下午很晒”。", "地下室": "语义：地下室少有阳光，与“下午很晒”矛盾。"}, "sentence_index": 6, "correct_answer": "西南"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把西南穿在身上去上学。", "explanation": "这里把“西南”当作衣服来穿，是词义误用：方位名词不能作穿戴的对象。"}, {"text": "我妈妈每天早上都喝西南。", "explanation": "这里把“西南”当作饮料来喝，方位名词不指饮品，句意不通。"}, {"text": "他的理想是当一名西南。", "explanation": "这里把“西南”当作职业身份，方位名词不能表示人的身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暖风在西南方向吹过来，天气变热了。", "corrected_sentence": "暖风从西南方向吹过来，天气变热了。", "error_description": "错误：“在西南方向”，应为“从西南方向”。表示风的来处要用“从”，“在”只表示所在位置，不能表示来源。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们西南走了十分钟。", "corrected_sentence": "我们往西南走了十分钟。", "error_description": "错误：缺少介词“往”。表示朝某个方向移动，要说“往西南走”，不能直接说“西南走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
