INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93728, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事先做好准备，不让坏事发生。", "primary_collocate": null, "pronunciation": "fáng", "ipa": "fɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "天气冷了，要提前防感冒。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天蚊子多，晚上得防蚊子。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了防雨水灌进屋，村民在门口堆沙袋。", "target_word": "防", "complexity_tier": "T3", "furigana": "Wèile fáng yǔshuǐ guàn jìn wū, cūnmín zài ménkǒu duī shādài.", "sentence_source": "generated"}, {"text": "老人走路慢，要防摔。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前带上伞，防下雨。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在手机里存了备份，防丢。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子玩水，家长在旁边防着出事。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年雨水多，农民提前防虫。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带了两个充电宝，防手机没电。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天风大，出门要戴帽子防冷。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防着", "label": "体标"}, {"form": "防过", "label": "体标"}, {"form": "防了", "label": "体标"}], "register": "中性", "sense_fingerprint": "提前做准备，避免不好的事发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6b8e2c5-1682-4b33-9c63-d8dce1b8d46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93728, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "防", "is_correct": true, "explanation": "防（fáng）：事先做好准备，避免坏事发生。"}, {"text": "访", "is_correct": false, "explanation": "fǎng（第三声）与 fáng（第二声）声调不同，意思是拜访。"}, {"text": "方", "is_correct": false, "explanation": "fāng（第一声）与 fáng（第二声）声调不同，意思是方向、方形。"}, {"text": "忙", "is_correct": false, "explanation": "máng 与 fáng 声母不同（m 与 f），声调相同，意思是忙碌。"}, {"text": "烦", "is_correct": false, "explanation": "fán 与 fáng 韵母不同（an 与 ang），声调相同，意思是烦恼。"}], "explanations": {"防": "防（fáng）：事先做好准备，避免坏事发生。", "访": "fǎng（第三声）与 fáng（第二声）声调不同，意思是拜访。", "方": "fāng（第一声）与 fáng（第二声）声调不同，意思是方向、方形。", "忙": "máng 与 fáng 声母不同（m 与 f），声调相同，意思是忙碌。", "烦": "fán 与 fáng 韵母不同（an 与 ang），声调相同，意思是烦恼。"}, "sentence_index": null, "correct_answer": "防"}, "level_3": {"options": [{"text": "防", "is_correct": true, "explanation": "正确：“防感冒”表示提前做好准备，避免生病，符合句意。"}, {"text": "治", "is_correct": false, "explanation": "语义：“治”是治疗已经得了的病，与“提前”矛盾。"}, {"text": "退", "is_correct": false, "explanation": "搭配：“退”常与“烧”搭配（退烧），不能说“退感冒”。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”不与“感冒”搭配，“要提前打感冒”不成说法。"}], "explanations": {"防": "正确：“防感冒”表示提前做好准备，避免生病，符合句意。", "治": "语义：“治”是治疗已经得了的病，与“提前”矛盾。", "退": "搭配：“退”常与“烧”搭配（退烧），不能说“退感冒”。", "打": "搭配：“打”不与“感冒”搭配，“要提前打感冒”不成说法。"}, "sentence_index": 0, "correct_answer": "防"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "噪音会防学习。", "explanation": "这里应该用〈妨碍〉。防表示事先避免坏事，不能用于阻碍正在进行的学习。"}, {"text": "士兵们防了一夜，城门终于没有被攻破。", "explanation": "这里的“防”是“防守”，指抵挡敌人进攻，与“事先做好准备、避免坏事”的意思不同。"}, {"text": "学校防了很多人才。", "explanation": "这里应该用〈培养〉。防表示事先避免坏事，不能用来说培育人才。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93728, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "防", "is_correct": true, "explanation": "防（fáng）：事先做好准备，避免坏事发生。"}, {"text": "放", "is_correct": false, "explanation": "fàng（第四声）与 fáng（第二声）声调不同，意思是放置。"}, {"text": "旁", "is_correct": false, "explanation": "páng 与 fáng 声母不同（p 与 f），意思是旁边。"}, {"text": "反", "is_correct": false, "explanation": "fǎn 与 fáng 韵母不同（an 与 ang），声调也不同，意思是相反。"}, {"text": "翻", "is_correct": false, "explanation": "fān（第一声）与 fáng 韵母与声调都不同，意思是翻动、翻转。"}, {"text": "仿", "is_correct": false, "explanation": "fǎng（第三声）与 fáng（第二声）声调不同，意思是模仿。"}], "explanations": {"防": "防（fáng）：事先做好准备，避免坏事发生。", "放": "fàng（第四声）与 fáng（第二声）声调不同，意思是放置。", "旁": "páng 与 fáng 声母不同（p 与 f），意思是旁边。", "反": "fǎn 与 fáng 韵母不同（an 与 ang），声调也不同，意思是相反。", "翻": "fān（第一声）与 fáng 韵母与声调都不同，意思是翻动、翻转。", "仿": "fǎng（第三声）与 fáng（第二声）声调不同，意思是模仿。"}, "sentence_index": null, "correct_answer": "防"}, "level_3": {"options": [{"text": "防", "is_correct": true, "explanation": "正确：“防着出事”表示提前戒备、避免事故，符合句意。"}, {"text": "盼", "is_correct": false, "explanation": "语义：“盼”是希望，“盼着出事”与家长的意图相反。"}, {"text": "图", "is_correct": false, "explanation": "语义：“图”是谋求，“图着出事”与家长的意图相反。"}, {"text": "吓", "is_correct": false, "explanation": "配价：“吓”要带受事（吓着某人），不能只接“出事”这一小句。"}], "explanations": {"防": "正确：“防着出事”表示提前戒备、避免事故，符合句意。", "盼": "语义：“盼”是希望，“盼着出事”与家长的意图相反。", "图": "语义：“图”是谋求，“图着出事”与家长的意图相反。", "吓": "配价：“吓”要带受事（吓着某人），不能只接“出事”这一小句。"}, "sentence_index": 6, "correct_answer": "防"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他防开了迎面而来的车。", "explanation": "这里应该用〈躲开〉。防表示事先做好准备、避免坏事，不能用于躲避已经迎面而来的车。"}, {"text": "门将防住了对方的射门，球队赢了比赛。", "explanation": "这里的“防”是“防守”，指阻挡对方射门，与“事先做好准备、避免坏事”的意思不同。"}, {"text": "农民防了很多鸡。", "explanation": "这里应该用〈饲养〉。防表示避免坏事，不能用于养殖动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年雨季提前，我们要把水灾防。", "corrected_sentence": "今年雨季提前，我们要把水灾防住。", "error_description": "错误：“把水灾防”。正确：“把水灾防住”。用“把”字句时，动词后面要有补语，单独的“防”不能完整表达意思。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去年不防过洪水，结果房子进了水。", "corrected_sentence": "我们去年没防过洪水，结果房子进了水。", "error_description": "错误：“不防过”。正确：“没防过”。表示过去没有过这种经历，要用“没”否定，不能用“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93729, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静", "is_correct": true, "explanation": "正确答案：静与响构成反义，响指发出声音，静指没有声音。"}, {"text": "亮", "is_correct": false, "explanation": "亮与“响”没有反义关系，“亮”指光线充足。"}, {"text": "快", "is_correct": false, "explanation": "快与“响”没有反义关系，“快”指速度高。"}, {"text": "暖", "is_correct": false, "explanation": "暖与“响”没有反义关系，“暖”指温度。"}], "correct_answer": "静", "explanations": {"静": "正确答案：静与响构成反义，响指发出声音，静指没有声音。", "亮": "亮与“响”没有反义关系，“亮”指光线充足。", "快": "快与“响”没有反义关系，“快”指速度高。", "暖": "暖与“响”没有反义关系，“暖”指温度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93729, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93729, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "响是发出声音。", "primary_collocate": null, "pronunciation": "xiǎng", "ipa": "ɕjɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "电话响了，他马上去接。", "target_word": "响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门铃响了，有人来了。", "target_word": "响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里的铃声响了。", "target_word": "响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面的雷声响了一下。", "target_word": "响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机在桌子上响着。", "target_word": "响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜里，闹钟突然响了。", "target_word": "响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手机在会上响过两次。", "target_word": "响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听见楼下的鞭炮响了。", "target_word": "响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课铃一响，学生们都跑出去了。", "target_word": "响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安静的夜里，钟声响了十二下。", "target_word": "响", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "响了", "label": "体标：了"}, {"form": "响着", "label": "体标：着"}, {"form": "响过", "label": "体标：过"}, {"form": "響", "label": "繁体"}], "register": "中性", "sense_fingerprint": "铃、电话、钟等物体发出声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8eb21289-7e21-4025-8e45-bb69550d4010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93729, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "响", "is_correct": true, "explanation": "正确答案：响（xiǎng），指物体发出声音。"}, {"text": "香", "is_correct": false, "explanation": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是香气。"}, {"text": "向", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是方向。"}, {"text": "显", "is_correct": false, "explanation": "xiǎn 与 xiǎng 的韵母不同（-n 与 -ng），意思是明显。"}, {"text": "像", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是像似。"}, {"text": "箱", "is_correct": false, "explanation": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是箱子。"}], "explanations": {"响": "正确答案：响（xiǎng），指物体发出声音。", "香": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是香气。", "向": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是方向。", "显": "xiǎn 与 xiǎng 的韵母不同（-n 与 -ng），意思是明显。", "像": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是像似。", "箱": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是箱子。"}, "sentence_index": null, "correct_answer": "响"}, "level_3": {"options": [{"text": "响", "is_correct": true, "explanation": "正确答案：响，指电话发出声音，与“电话”搭配。"}, {"text": "饿", "is_correct": false, "explanation": "语义：电话不会饿，“电话饿了”不成立。"}, {"text": "累", "is_correct": false, "explanation": "语义：“累”说人或动物的疲劳，不能用于电话。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写，电话不能“写”，“电话写了”不成立。"}], "explanations": {"响": "正确答案：响，指电话发出声音，与“电话”搭配。", "饿": "语义：电话不会饿，“电话饿了”不成立。", "累": "语义：“累”说人或动物的疲劳，不能用于电话。", "写": "语义：“写”指书写，电话不能“写”，“电话写了”不成立。"}, "sentence_index": 0, "correct_answer": "响"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳突然响了一下。", "explanation": "这里应该用〈亮〉。响指发出声音，不能用来说光线的明亮，光线的明亮要用亮。"}, {"text": "屏幕响了一下。", "explanation": "这里应该用〈闪〉。响指发出声音，不能描述屏幕的闪动。"}, {"text": "眼皮响了一下。", "explanation": "这里应该用〈跳〉。响指发出声音，眼皮不会发出声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93729, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "响", "is_correct": true, "explanation": "正确答案：响（xiǎng），指物体发出声音。"}, {"text": "乡", "is_correct": false, "explanation": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是乡村。"}, {"text": "相", "is_correct": false, "explanation": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是互相。"}, {"text": "险", "is_correct": false, "explanation": "xiǎn 与 xiǎng 的韵母不同（-n 与 -ng），意思是危险。"}, {"text": "项", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是项目。"}, {"text": "象", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是大象。"}], "explanations": {"响": "正确答案：响（xiǎng），指物体发出声音。", "乡": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是乡村。", "相": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是互相。", "险": "xiǎn 与 xiǎng 的韵母不同（-n 与 -ng），意思是危险。", "项": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是项目。", "象": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是大象。"}, "sentence_index": null, "correct_answer": "响"}, "level_3": {"options": [{"text": "响", "is_correct": true, "explanation": "正确答案：响，指手机发出声音，与“过两次”搭配。"}, {"text": "讲", "is_correct": false, "explanation": "搭配：“讲”的主语须是人，手机不能“讲”。"}, {"text": "笑", "is_correct": false, "explanation": "语义：手机不会笑，“手机笑过两次”不成立。"}, {"text": "吃", "is_correct": false, "explanation": "语义：手机不会吃东西，“手机在会上吃过两次”不成立。"}], "explanations": {"响": "正确答案：响，指手机发出声音，与“过两次”搭配。", "讲": "搭配：“讲”的主语须是人，手机不能“讲”。", "笑": "语义：手机不会笑，“手机笑过两次”不成立。", "吃": "语义：手机不会吃东西，“手机在会上吃过两次”不成立。"}, "sentence_index": 6, "correct_answer": "响"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小狗突然响了一声。", "explanation": "这里应该用〈叫〉。响用于枪声、铃声等，不能用于小狗的叫声，小狗的叫声要用叫。"}, {"text": "我的头响了一下。", "explanation": "这里应该用〈疼〉。响指发出声音，头不会发出声音。"}, {"text": "这块蛋糕很响。", "explanation": "这里应该用〈甜〉。响指发出声音，蛋糕不会发出声音，不能用“响”说蛋糕的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "闹钟了响三次。", "corrected_sentence": "闹钟响了三次。", "error_description": "错误形式“了响”，正确形式“响了”。“了”须紧跟动词，表示动作已完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
