INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93731, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "风暴是又大又猛的风，常常还带着大雨。", "primary_collocate": null, "pronunciation": "fēng bào", "ipa": "fəŋ˥ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "昨晚海上来了一场大风暴。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风暴来了，渔船都回港了。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风暴过后，路上到处是断树。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为风暴，今天所有航班都取消了。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风暴把我们家的窗户吹坏了。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报说，明天有风暴和大雨。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场风暴带来了很大的雨。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风暴来的时候，我们躲在屋里。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在风暴里走了一整夜。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上的风暴又大又猛，船开不了。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场风暴", "label": "量词"}, {"form": "沙尘风暴", "label": "复合"}, {"form": "風暴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "又大又猛、常带大雨的风", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6890ad06-571d-4ab3-9fbc-f9d69fcc7e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93731, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风暴", "is_correct": true, "explanation": "正确。“一场大风暴”指海上这场又大又猛的风。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不会“来”到海上，与“来了一场大……”这样的天气事件不合。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“场”用于天气、比赛等事件，不用于石头，“一场大石头”不成立。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不是会在海上出现的天气现象，与句中的“海上来了”不合。"}], "explanations": {"风暴": "正确。“一场大风暴”指海上这场又大又猛的风。", "面包": "语义：面包是食物，不会“来”到海上，与“来了一场大……”这样的天气事件不合。", "石头": "搭配：“场”用于天气、比赛等事件，不用于石头，“一场大石头”不成立。", "饺子": "语义：饺子是食物，不是会在海上出现的天气现象，与句中的“海上来了”不合。"}, "sentence_index": 0, "correct_answer": "风暴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几天一直在下风暴。", "explanation": "这里应该用〈暴雨〉。“下”用于雨、雪，风暴是强风，不能说“下风暴”。"}, {"text": "今天风暴很小，适合出海。", "explanation": "这里应该用〈风〉。风暴指又大又猛、常带大雨的风，不能说“很小”；说“风很小”才合理。"}, {"text": "他的风暴很好，大家都喜欢他。", "explanation": "这里应该用〈风度〉。风暴指又大又猛的风，不能用来说人的气质；说“风度很好”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93731, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风暴", "is_correct": true, "explanation": "正确。“这场风暴”指带来大雨的那场大风。"}, {"text": "讲座", "is_correct": false, "explanation": "语义：讲座是活动，不会带来大雨，与“带来了很大的雨”的天气因果不合。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“场”不用于桌子，“这场桌子”不成立，桌子也不会带来降雨。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是身体的病，不会带来大雨，与句中的天气因果不合。"}], "explanations": {"风暴": "正确。“这场风暴”指带来大雨的那场大风。", "讲座": "语义：讲座是活动，不会带来大雨，与“带来了很大的雨”的天气因果不合。", "桌子": "搭配：“场”不用于桌子，“这场桌子”不成立，桌子也不会带来降雨。", "感冒": "语义：感冒是身体的病，不会带来大雨，与句中的天气因果不合。"}, "sentence_index": 6, "correct_answer": "风暴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的写作风暴很独特。", "explanation": "这里应该用〈风格〉。风暴指又大又猛、常带大雨的风，不能用来说写作的特点；应说“写作风格”。"}, {"text": "远处传来了风暴。", "explanation": "这里应该用〈雷声〉。“传来”后面要接听得见的声音，风暴是天气现象，不是一种声音。"}, {"text": "这杯茶的风暴很苦，我不想喝。", "explanation": "这里应该用〈味道〉。风暴是天气现象，不能用来形容茶的味道；说“味道很苦”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93731, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海边刮起了一只风暴，渔船都没出海。", "corrected_sentence": "海边刮起了一场风暴，渔船都没出海。", "error_description": "错误：量词“只”用错。风暴是一场天气事件，应用量词“场”，说“一场风暴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93731, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年冬天，我们遇到着一场风暴。", "corrected_sentence": "去年冬天，我们遇到过一场风暴。", "error_description": "错误：动态助词“着”用错。表示经历过的事要用“过”，应说“遇到过一场风暴”，不能说“遇到着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
