INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93732, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "强烈的大风，常伴有暴雨或大雪。", "primary_collocate": null, "pronunciation": "fēng bào", "ipa": "fəŋ˥ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这场风暴来得很突然，海上的船都回港了。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场风暴伴着大雪，路都封了。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方遇到了一场风暴，下了很大的雪。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气象台发布了风暴预警。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风暴伴着暴雨，一直下到天亮。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长看见远处有风暴，马上改了路线。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风暴中，大树被吹倒了。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个海岛夏天常常有风暴。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说今晚有风暴，别出门了。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风暴停了，天空慢慢变蓝了。", "target_word": "风暴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场风暴", "label": "量词"}, {"form": "沙尘风暴", "label": "复合"}, {"form": "風暴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "伴有暴雨或大雪的强烈大风", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6890ad06-571d-4ab3-9fbc-f9d69fcc7e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93732, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风暴", "is_correct": true, "explanation": "正确。“这场风暴”指来得突然、让船只回港的那场大风。"}, {"text": "讲座", "is_correct": false, "explanation": "语义：讲座是活动，不会让海上的船回港，与句中的天气情境不合。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不是能突然来袭的天气现象，与句中的情境不合。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“来”和“场”搭配的多是天气、事件，“这场桌子来得很突然”不成立。"}], "explanations": {"风暴": "正确。“这场风暴”指来得突然、让船只回港的那场大风。", "讲座": "语义：讲座是活动，不会让海上的船回港，与句中的天气情境不合。", "饺子": "语义：饺子是食物，不是能突然来袭的天气现象，与句中的情境不合。", "桌子": "搭配：“来”和“场”搭配的多是天气、事件，“这场桌子来得很突然”不成立。"}, "sentence_index": 0, "correct_answer": "风暴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "北方下了一场风暴，路上都是雪。", "explanation": "这里应该用〈暴雪〉。风暴是大风，“下”的是雪，不能说“下风暴”。"}, {"text": "夏天的风暴很温暖，像一床被子。", "explanation": "这里应该用〈暖风〉。风暴指强烈的大风，常伴暴雨大雪，不能用“温暖”“像一床被子”来形容。"}, {"text": "今天的风暴很轻，树叶都不动。", "explanation": "这里应该用〈微风〉。风暴指强烈的大风，不能用“很轻”“树叶都不动”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风暴", "is_correct": true, "explanation": "正确。“风暴中”指大风里，符合大树被吹倒的情境。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，“面包中”与“大树被吹倒”的情境毫不相关。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是身体的病，不会吹倒大树，与句中的情境不合。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不会吹倒大树，“歌曲中”与句中的自然现象无关。"}], "explanations": {"风暴": "正确。“风暴中”指大风里，符合大树被吹倒的情境。", "面包": "语义：面包是食物，“面包中”与“大树被吹倒”的情境毫不相关。", "感冒": "语义：感冒是身体的病，不会吹倒大树，与句中的情境不合。", "歌曲": "语义：歌曲不会吹倒大树，“歌曲中”与句中的自然现象无关。"}, "sentence_index": 6, "correct_answer": "风暴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位画家的风暴很独特。", "explanation": "这里应该用〈风格〉。风暴不能用来说画家的作画特点；应说“风格很独特”。"}, {"text": "风暴很凉，吹得人很舒服。", "explanation": "这里应该用〈海风〉。风暴指强烈的大风，常伴暴雨大雪，不能用来形容清凉舒服的风。"}, {"text": "天上下了一场风暴，路上都是水。", "explanation": "这里应该用〈暴雨〉。“下”用于雨，风暴不能说“下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上个月，我们在海边遇到着一场风暴。", "corrected_sentence": "上个月，我们在海边遇到过一场风暴。", "error_description": "错误：动态助词“着”用错。表示经历过的事要用“过”，应说“遇到过一场风暴”，不能说“遇到着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里来了一只风暴，路都封了。", "corrected_sentence": "夜里来了一场风暴，路都封了。", "error_description": "错误：量词“只”用错。风暴是一场天气事件，应用量词“场”，说“一场风暴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
