INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93735, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "function", "definition": "一应是所有的，什么都包括。", "primary_collocate": null, "pronunciation": "yì yīng", "ipa": "i˥˩ iŋ˥", "syllable_count": 2, "sentences": [{"text": "这家酒店的一应设施都很新。", "target_word": "一应", "complexity_tier": "T3", "furigana": "zhè jiā jiǔdiàn de yì yīng shèshī dōu hěn xīn", "sentence_source": "generated"}, {"text": "房间里的一应家具都是新的。", "target_word": "一应", "complexity_tier": "T3", "furigana": "fáng jiān lǐ de yì yīng jiā jù dōu shì xīn de", "sentence_source": "generated"}, {"text": "老人的衣食住行，子女一应安排好了。", "target_word": "一应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行的一应费用，公司都会出。", "target_word": "一应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的一应开支都由父母负担。", "target_word": "一应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的一应器皿，都擦得干干净净。", "target_word": "一应", "complexity_tier": "T3", "furigana": "chú fáng lǐ de yì yīng qì mǐn, dōu cā de gān gān jìng jìng", "sentence_source": "generated"}, {"text": "会议所需的一应材料，已经放在桌上了。", "target_word": "一应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店为客人准备了一应生活用品。", "target_word": "一应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的一应教学用具都由老师统一保管。", "target_word": "一应", "complexity_tier": "T3", "furigana": "xué xiào de yì yīng jiào xué yòng jù dōu yóu lǎo shī tǒng yī bǎo guǎn", "sentence_source": "generated"}, {"text": "出国前，一应证件都要带好，护照尤其重要。", "target_word": "一应", "complexity_tier": "T3", "furigana": "chū guó qián, yì yīng zhèng jiàn dōu yào dài hǎo, hù zhào yóu qí zhòng yào", "sentence_source": "generated"}], "morphological_forms": [{"form": "一应俱全", "label": "复合"}], "register": "书面语", "sense_fingerprint": "一应：所有东西都有，什么都包括（常说一应俱全）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f254cf03-f386-45b9-9358-a04ac5249126') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93735, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一应", "is_correct": true, "explanation": "正确：「这家酒店的一应设施」指全部设施，与「都很新」所说的全体相合。"}, {"text": "某", "is_correct": false, "explanation": "语义：「某」指不确定的某一个，与「都很新」所说的全部设施相矛盾。"}, {"text": "独自", "is_correct": false, "explanation": "搭配：「独自」只修饰人的行为，不能修饰「设施」。"}, {"text": "单独", "is_correct": false, "explanation": "搭配：「单独」多修饰动作，不能直接修饰名词「设施」。"}], "explanations": {"一应": "正确：「这家酒店的一应设施」指全部设施，与「都很新」所说的全体相合。", "某": "语义：「某」指不确定的某一个，与「都很新」所说的全部设施相矛盾。", "独自": "搭配：「独自」只修饰人的行为，不能修饰「设施」。", "单独": "搭配：「单独」多修饰动作，不能直接修饰名词「设施」。"}, "sentence_index": 0, "correct_answer": "一应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们只买了一应商品。", "explanation": "这里应该用〈一些〉。一应指全部，不能用来说只买了一部分商品；表示部分时应用〈一些〉。"}, {"text": "老师只讲了一应内容。", "explanation": "这里应该用〈部分〉。一应指全部，不能用来说只讲了其中一部分内容；表示部分时应用〈部分〉。"}, {"text": "他只带了一应行李。", "explanation": "这里应该用〈几件〉。一应指全部，不能用来说只带了几件行李；表示部分时应用〈几件〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93735, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一应", "is_correct": true, "explanation": "正确：「会议所需的一应材料」指全部所需材料，与「已经放在桌上了」相合。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：「亲自」修饰动作，不能直接修饰「材料」。"}, {"text": "独自", "is_correct": false, "explanation": "搭配：「独自」只修饰人的行为，不能修饰「材料」。"}, {"text": "个个", "is_correct": false, "explanation": "搭配：「个个」多用来指人或逐一，不能修饰「材料」。"}], "explanations": {"一应": "正确：「会议所需的一应材料」指全部所需材料，与「已经放在桌上了」相合。", "亲自": "搭配：「亲自」修饰动作，不能直接修饰「材料」。", "独自": "搭配：「独自」只修饰人的行为，不能修饰「材料」。", "个个": "搭配：「个个」多用来指人或逐一，不能修饰「材料」。"}, "sentence_index": 6, "correct_answer": "一应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们只看了一应电影。", "explanation": "这里应该用〈几部〉。一应指全部，不能用来说只看了几部电影；表示部分时应用〈几部〉。"}, {"text": "我只喝了一应饮料。", "explanation": "这里应该用〈一杯〉。一应指全部，不能用来说只喝了一杯饮料；表示部分时应用〈一杯〉。"}, {"text": "她只读了一应书。", "explanation": "这里应该用〈几本〉。一应指全部，不能用来说只读了几本书；表示部分时应用〈几本〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93735, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "搬家的一应三箱物品都打包好了。", "corrected_sentence": "搬家的一应物品都打包好了。", "error_description": "错在「一应三箱」。「一应」表示全部，后面不能再接具体数量词「三箱」，应删去「三箱」，改为「搬家的一应物品」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93735, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份一应文件都已经交给王经理了。", "corrected_sentence": "一应文件都已经交给王经理了。", "error_description": "错在「这份一应文件」。「一应」指全部，不能与「这份」这类表示单个的指示词连用，应删去「这份」，改为「一应文件」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
