INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93736, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "function", "definition": "全部；一切（多用于书面语）。", "primary_collocate": null, "pronunciation": "yì yīng", "ipa": "i˥˩ iŋ˥", "syllable_count": 2, "sentences": [{"text": "搬家的一应事务，都由公司安排。", "target_word": "一应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一应杂事都交给了助手。", "target_word": "一应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活动的一应安排，请看通知。", "target_word": "一应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，课上的一应问题都可以问。", "target_word": "一应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览所需的一应设备，我们已经准备好了。", "target_word": "一应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼的一应事宜，由他们家负责。", "target_word": "一应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把一应文件交给王经理。", "target_word": "一应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次出差的一应花费，公司全部报销。", "target_word": "一应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的一应要求，我们都会考虑。", "target_word": "一应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一应手续办完以后，他就回国了。", "target_word": "一应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一应俱全", "label": "复合"}], "register": "书面语", "sense_fingerprint": "一应：全部、一切（放在名词前，书面语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f254cf03-f386-45b9-9358-a04ac5249126') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93736, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一应", "is_correct": true, "explanation": "正确：「搬家的一应事务」指全部事务，与「都由公司安排」相合。"}, {"text": "独自", "is_correct": false, "explanation": "搭配：「独自」只修饰人的行为，不能修饰「事务」。"}, {"text": "每", "is_correct": false, "explanation": "搭配：「每」后要接量词，不能直接修饰「事务」。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：「亲自」修饰动作，不能直接修饰名词「事务」。"}], "explanations": {"一应": "正确：「搬家的一应事务」指全部事务，与「都由公司安排」相合。", "独自": "搭配：「独自」只修饰人的行为，不能修饰「事务」。", "每": "搭配：「每」后要接量词，不能直接修饰「事务」。", "亲自": "搭配：「亲自」修饰动作，不能直接修饰名词「事务」。"}, "sentence_index": 0, "correct_answer": "一应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们只借阅了一应书籍。", "explanation": "这里应该用〈一些〉。一应指全部，不能用来说只借阅了一部分书籍；表示部分时应用〈一些〉。"}, {"text": "他只带了一应证件。", "explanation": "这里应该用〈几份〉。一应指全部，不能用来说只带了几份证件；表示部分时应用〈几份〉。"}, {"text": "他们只采纳了一应建议。", "explanation": "这里应该用〈几条〉。一应指全部，不能用来说只采纳了几条建议；表示部分时应用〈几条〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93736, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一应", "is_correct": true, "explanation": "正确：「一应文件」指全部文件，与「请把……交给王经理」要求全部交出的语境相合。"}, {"text": "个个", "is_correct": false, "explanation": "搭配：「个个」多指人或逐一，不能修饰「文件」。"}, {"text": "互相", "is_correct": false, "explanation": "搭配：「互相」是副词，表示彼此对待，修饰动作，不能直接修饰名词「文件」。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：「一直」是时间副词，修饰动作，不能直接修饰名词「文件」。"}], "explanations": {"一应": "正确：「一应文件」指全部文件，与「请把……交给王经理」要求全部交出的语境相合。", "个个": "搭配：「个个」多指人或逐一，不能修饰「文件」。", "互相": "搭配：「互相」是副词，表示彼此对待，修饰动作，不能直接修饰名词「文件」。", "一直": "搭配：「一直」是时间副词，修饰动作，不能直接修饰名词「文件」。"}, "sentence_index": 6, "correct_answer": "一应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他只办了一应手续，就回国了。", "explanation": "这里应该用〈几项〉。一应指全部，不能用来说只办了其中几项手续；表示部分时应用〈几项〉。"}, {"text": "我只装了一应衣服。", "explanation": "这里应该用〈几件〉。一应指全部，不能用来说只装了几件衣服；表示部分时应用〈几件〉。"}, {"text": "同学们只带了一应笔记本。", "explanation": "这里应该用〈几本〉。一应指全部，不能用来说只带了几本笔记本；表示部分时应用〈几本〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "活动的一应三笔费用，都由学校承担。", "corrected_sentence": "活动的一应费用，都由学校承担。", "error_description": "错在「一应三笔费用」。「一应」已表示全部，不能再接具体数量词「三笔」，应删去「三笔」，改为「活动的一应费用」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份一应证件都已经办好了。", "corrected_sentence": "一应证件都已经办好了。", "error_description": "错在「这份一应证件」。「一应」指全部，不能与「这份」这类表示单个的指示词连用，应删去「这份」，改为「一应证件」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
