INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93737, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一总是全部加起来。", "primary_collocate": null, "pronunciation": "yī zǒng", "ipa": "i˥ tsʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这些东西一总多少钱？", "target_word": "一总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天买菜，一总花了五十块。", "target_word": "一总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班一总有三十个学生。", "target_word": "一总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几笔钱一总一千二。", "target_word": "一总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个月的房租，一总要六千块。", "target_word": "一总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一总来了十个人，椅子不够。", "target_word": "一总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我一总看了三遍。", "target_word": "一总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们家一总四口人，住得很挤。", "target_word": "一总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他借给我两次钱，一总两千。", "target_word": "一总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买书、买笔，一总用了八十块。", "target_word": "一总", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一總", "label": "繁体"}], "register": "口语", "sense_fingerprint": "一总：把数量全部加起来，表示总数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ab86027-31e9-470c-a719-029cfab81c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93737, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一总", "is_correct": true, "explanation": "一总：副词，表示全部加起来的总数。"}, {"text": "一种", "is_correct": false, "explanation": "一种（zhǒng）与 zǒng 声母不同（zh 与 z），意思是种类，不表示总数。"}, {"text": "一宗", "is_correct": false, "explanation": "一宗（zōng）与 zǒng 声调不同（第一声与第三声），意思是一笔或一桩，不是合计。"}, {"text": "一纵", "is_correct": false, "explanation": "一纵（zòng）与 zǒng 声调不同（第四声与第三声），意思是一竖，不是合计。"}], "explanations": {"一总": "一总：副词，表示全部加起来的总数。", "一种": "一种（zhǒng）与 zǒng 声母不同（zh 与 z），意思是种类，不表示总数。", "一宗": "一宗（zōng）与 zǒng 声调不同（第一声与第三声），意思是一笔或一桩，不是合计。", "一纵": "一纵（zòng）与 zǒng 声调不同（第四声与第三声），意思是一竖，不是合计。"}, "sentence_index": null, "correct_answer": "一总"}, "level_3": {"options": [{"text": "只", "is_correct": false, "explanation": "语义：“只”表示限于某范围，与问全部东西总价的语境不合。"}, {"text": "一总", "is_correct": true, "explanation": "一总：副词，问全部东西加起来共多少钱。"}, {"text": "刚", "is_correct": false, "explanation": "搭配：“刚”表示时间刚过，不能与“多少钱”的总数问法搭配。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与问全部价格的语境冲突。"}], "explanations": {"只": "语义：“只”表示限于某范围，与问全部东西总价的语境不合。", "一总": "一总：副词，问全部东西加起来共多少钱。", "刚": "搭配：“刚”表示时间刚过，不能与“多少钱”的总数问法搭配。", "偶尔": "语义：“偶尔”表示不常发生，与问全部价格的语境冲突。"}, "sentence_index": 0, "correct_answer": "一总"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们一总去公园玩。", "explanation": "这里应该用〈一起〉。一总表示合计数量，不表示共同行动。"}, {"text": "我一总很喜欢这首歌。", "explanation": "这里应该用〈一直〉。一总表示合计，不表示持续。"}, {"text": "大家一总拍手叫好。", "explanation": "这里应该用〈一齐〉。一总不表示大家同时做某事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一下", "is_correct": false, "explanation": "语义：“一下”表示短时间，与“看了三遍”的多次冲突。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”多与否定词连用，不能修饰“看了三遍”。"}, {"text": "一总", "is_correct": true, "explanation": "一总：副词，表示看的次数合计为三遍。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”指一向如此，与“看了三遍”的具体次数冲突。"}], "explanations": {"一下": "语义：“一下”表示短时间，与“看了三遍”的多次冲突。", "根本": "搭配：“根本”多与否定词连用，不能修饰“看了三遍”。", "一总": "一总：副词，表示看的次数合计为三遍。", "从来": "语义：“从来”指一向如此，与“看了三遍”的具体次数冲突。"}, "sentence_index": 6, "correct_answer": "一总"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一总在图书馆学习。", "explanation": "这里应该用〈常常〉。一总表示合计，不表示经常发生。"}, {"text": "孩子们一总唱歌跳舞。", "explanation": "这里应该用〈都〉。一总不表示全体一起做某事。"}, {"text": "我的朋友一总喜欢运动。", "explanation": "这里应该用〈非常〉。一总表示合计，不能表示程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些书一总了多少钱？", "corrected_sentence": "这些书一总多少钱？", "error_description": "错误：“一总”后多加了“了”。“一总”是副词，后面直接接“多少钱”，不带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月的水费，我们一总的交了两百块。", "corrected_sentence": "这个月的水费，我们一总交了两百块。", "error_description": "错误：“一总”后多加了“的”。副词“一总”后不能直接接“的”，应为“我们一总交了两百块”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
