INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93740, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "就任某项职务，多指就职的时间节点或任职期间。", "primary_collocate": null, "pronunciation": "rèn zhí", "ipa": "ɻən˥˩ ʈʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "他任职期间，学校变化很大。", "target_word": "任职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去年开始任职，负责公司的财务工作。", "target_word": "任职", "complexity_tier": "T3", "furigana": "Tā qùnián kāishǐ rènzhí, fùzé gōngsī de cáiwù gōngzuò.", "sentence_source": "generated"}, {"text": "李先生将在下个月任职。", "target_word": "任职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新校长今天正式任职。", "target_word": "任职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他任职以后，一直很努力。", "target_word": "任职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她任职以后，把销售部门整顿了一遍。", "target_word": "任职", "complexity_tier": "T3", "furigana": "Tā rènzhí yǐhòu, bǎ xiāoshòu bùmén zhěngdùn le yí biàn.", "sentence_source": "generated"}, {"text": "他在任职前先去学习了。", "target_word": "任职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张任职时间不长就调走了。", "target_word": "任职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新市长任职第一天就去了医院。", "target_word": "任职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他任职两年后，就辞去了职务。", "target_word": "任职", "complexity_tier": "T3", "furigana": "Tā rènzhí liǎng nián hòu, jiù cíqù le zhíwù.", "sentence_source": "generated"}], "morphological_forms": [{"form": "任职了", "label": "体标"}, {"form": "任职过", "label": "体标"}], "register": "书面", "sense_fingerprint": "就任职务，常指就职时点或任职期间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6b8e2c5-1682-4b33-9c63-d8dce1b8d46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93740, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "任职", "is_correct": true, "explanation": "任职（rèn zhí）：担任某个职务。"}, {"text": "认知", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，意思是认知、认识。"}, {"text": "人质", "is_correct": false, "explanation": "rén（第二声）与 rèn（第四声）、zhì（第四声）与 zhí（第二声）声调都不同，意思是人质。"}, {"text": "认识", "is_correct": false, "explanation": "shi（轻声）与 zhí 声母不同（sh 与 zh），意思是认识、了解。"}], "explanations": {"任职": "任职（rèn zhí）：担任某个职务。", "认知": "zhī（第一声）与 zhí（第二声）声调不同，意思是认知、认识。", "人质": "rén（第二声）与 rèn（第四声）、zhì（第四声）与 zhí（第二声）声调都不同，意思是人质。", "认识": "shi（轻声）与 zhí 声母不同（sh 与 zh），意思是认识、了解。"}, "sentence_index": null, "correct_answer": "任职"}, "level_3": {"options": [{"text": "任职", "is_correct": true, "explanation": "正确：“任职期间”指担任职务的这段时间，符合句意。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳期间”与“学校变化很大”没有关联，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉期间”与“学校变化很大”没有逻辑联系，句意不通。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：“下雨”的主语是天气，“他下雨期间”不成立。"}], "explanations": {"任职": "正确：“任职期间”指担任职务的这段时间，符合句意。", "游泳": "语义：“游泳期间”与“学校变化很大”没有关联，句意不通。", "睡觉": "语义：“睡觉期间”与“学校变化很大”没有逻辑联系，句意不通。", "下雨": "搭配：“下雨”的主语是天气，“他下雨期间”不成立。"}, "sentence_index": 0, "correct_answer": "任职"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老校长明年任职，大家为他送行。", "explanation": "这里应该用〈卸任〉。任职是就任职务，卸任才是离开职务，与“送行”的语境矛盾。"}, {"text": "张老师今年任职，在家养花。", "explanation": "这里应该用〈退休〉。任职表示就任职务，退休是结束工作，两者不能混用。"}, {"text": "我们五点任职。", "explanation": "这里应该用〈下班〉。任职是担任职务，不表示每天结束工作的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93740, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任职", "is_correct": true, "explanation": "正确：“在任职前先去学习”表示担任职务之前的准备，符合句意。"}, {"text": "去世", "is_correct": false, "explanation": "语义：人去世后不能再去学习，“去世前先去学习”句意矛盾。"}, {"text": "出生", "is_correct": false, "explanation": "语义：人出生之前不可能去学习，“在出生前先去学习了”句意不通。"}, {"text": "咽气", "is_correct": false, "explanation": "搭配：“咽气”指生命结束，不能作为“先去学习”之前的时间状态。"}], "explanations": {"任职": "正确：“在任职前先去学习”表示担任职务之前的准备，符合句意。", "去世": "语义：人去世后不能再去学习，“去世前先去学习”句意矛盾。", "出生": "语义：人出生之前不可能去学习，“在出生前先去学习了”句意不通。", "咽气": "搭配：“咽气”指生命结束，不能作为“先去学习”之前的时间状态。"}, "sentence_index": 6, "correct_answer": "任职"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去年任职，所以不再上班了。", "explanation": "这里应该用〈辞职〉。任职是就任职务，辞职是离开职务，两者意思相反。"}, {"text": "我们去年在欧洲任职，每天都去旅游。", "explanation": "这里应该用〈旅行〉。任职表示担任职务，与“每天去旅游”的语境矛盾，不能用来说外出游览。"}, {"text": "他每天晚上任职。", "explanation": "这里应该用〈洗澡〉。任职表示担任职务，不能用于日常生活动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天被正式任职。", "corrected_sentence": "他今天正式任职。", "error_description": "错误：“被正式任职”。正确：“正式任职”。“任职”是不及物动词，表示就任职务，不能加“被”构成被动；人被任命某职务应说“被任命”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来不任职过，所以经验不足。", "corrected_sentence": "他从来没任职过，所以经验不足。", "error_description": "错误：“不任职过”。正确：“没任职过”。表示过去从未有过这种经历，要用“没”否定，不能用“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
