INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93742, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "什么时候；询问时间的疑问词，多用于书面语。", "primary_collocate": null, "pronunciation": "hé shí", "ipa": "xɤ˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "请问经理何时能回到公司？", "target_word": "何时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告何时可以交给我？", "target_word": "何时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不知他们何时才能见面。", "target_word": "何时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您何时有空，我们谈一谈。", "target_word": "何时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新书何时出版，作者还没说。", "target_word": "何时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议何时开始，请看通知。", "target_word": "何时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你何时离开上海，告诉我一声。", "target_word": "何时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我，火车何时到站？", "target_word": "何时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没人知道这家店何时关门。", "target_word": "何时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想知道，比赛何时结束。", "target_word": "何时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "何時", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "疑问代词，询问时间，书面语，相当于什么时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33f1f67f-f906-4ff1-b27e-6aefc2c445ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93742, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "何时", "is_correct": true, "explanation": "正确：何时（hé shí），疑问代词，询问什么时候。"}, {"text": "何事", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是「什么事」，不是时间。"}, {"text": "合适", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是「合适、恰当」。"}, {"text": "合式", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是「合乎格式、合适」，不是时间。"}], "explanations": {"何时": "正确：何时（hé shí），疑问代词，询问什么时候。", "何事": "shì（第四声）与 shí（第二声）声调不同，意思是「什么事」，不是时间。", "合适": "shì（第四声）与 shí（第二声）声调不同，意思是「合适、恰当」。", "合式": "shì（第四声）与 shí（第二声）声调不同，意思是「合乎格式、合适」，不是时间。"}, "sentence_index": null, "correct_answer": "何时"}, "level_3": {"options": [{"text": "何时", "is_correct": true, "explanation": "正确：「何时」询问时间，放在助动词「能」之前。"}, {"text": "何处", "is_correct": false, "explanation": "语义：「何处」问地点，但句中「回到公司」已给出地点，不能再问地点。"}, {"text": "何人", "is_correct": false, "explanation": "搭配：「经理」已是具体的人，「何人」不能用来修饰「经理」作主语。"}, {"text": "何种", "is_correct": false, "explanation": "搭配：「何种」要修饰名词，不能直接接「能回到公司」这样的动词短语。"}], "explanations": {"何时": "正确：「何时」询问时间，放在助动词「能」之前。", "何处": "语义：「何处」问地点，但句中「回到公司」已给出地点，不能再问地点。", "何人": "搭配：「经理」已是具体的人，「何人」不能用来修饰「经理」作主语。", "何种": "搭配：「何种」要修饰名词，不能直接接「能回到公司」这样的动词短语。"}, "sentence_index": 0, "correct_answer": "何时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他没来上班，原因是何时？", "explanation": "这里应该用〈什么〉，询问原因（原因是什么）。「何时」只问时间点，不能用来问原因。"}, {"text": "他的身高是何时？", "explanation": "这里应该用〈多少〉，询问身高的数值。「何时」只问时间，不能用来问身高。"}, {"text": "他的家乡是何时？", "explanation": "这里应该用〈哪儿〉，询问地点。「何时」只问时间点，不能用来指地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '068d6e78-5434-461a-91c4-d2f1ef1559a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "何时", "is_correct": true, "explanation": "正确：「何时」询问离开的时间，放在主语之后、动词之前。"}, {"text": "何地", "is_correct": false, "explanation": "语义：「上海」已是地点，「何地」再问地点，与句意重复。"}, {"text": "何物", "is_correct": false, "explanation": "语义：「何物」问事物，而句中的主语「你」是人，不能这样问。"}, {"text": "何方", "is_correct": false, "explanation": "搭配：「何方」不能与人称「你」直接组成「何方离开」的结构。"}], "explanations": {"何时": "正确：「何时」询问离开的时间，放在主语之后、动词之前。", "何地": "语义：「上海」已是地点，「何地」再问地点，与句意重复。", "何物": "语义：「何物」问事物，而句中的主语「你」是人，不能这样问。", "何方": "搭配：「何方」不能与人称「你」直接组成「何方离开」的结构。"}, "sentence_index": 6, "correct_answer": "何时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个包的价格是何时？", "explanation": "这里应该用〈多少〉，询问价格的数额。「何时」只问时间，不能用来问价格。"}, {"text": "他的声音何时？", "explanation": "这里应该用〈怎么样〉，询问声音的好坏。「何时」只问时间，不能用来问声音如何。"}, {"text": "这张桌子有何时重？", "explanation": "这里应该用〈多〉（有多重），询问重量。「何时」只问时间，不能用来问轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '068d6e78-5434-461a-91c4-d2f1ef1559a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
