INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93743, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "全身是从头到脚，整个身体。", "primary_collocate": null, "pronunciation": "quán shēn", "ipa": "tɕʰɥɛn˧˥ ʂən˥", "syllable_count": 2, "sentences": [{"text": "他全身都湿了。", "target_word": "全身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑完步，我全身是汗。", "target_word": "全身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给他做了全身检查。", "target_word": "全身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她全身上下都是泥。", "target_word": "全身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪了，他全身都是雪。", "target_word": "全身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我全身没有一点力气。", "target_word": "全身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子全身发热，要去医院。", "target_word": "全身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳以后，全身很舒服。", "target_word": "全身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全身都疼，我想休息。", "target_word": "全身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的全身都包着布，只露出眼睛。", "target_word": "全身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "从头到脚的整个身体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8eb21289-7e21-4025-8e45-bb69550d4010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93743, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "全身", "is_correct": true, "explanation": "正确答案：全身（quán shēn），指从头到脚的整个身体。"}, {"text": "全神", "is_correct": false, "explanation": "shén（第二声）与 shēn（第一声）声调不同，意思是集中精神。"}, {"text": "前身", "is_correct": false, "explanation": "qián 与 quán 的韵母不同（ian 与 uan），意思是以前的身份或组织的前身。"}, {"text": "全真", "is_correct": false, "explanation": "zhēn 与 shēn 声母不同（zh 与 sh），意思是完全真实。"}, {"text": "全胜", "is_correct": false, "explanation": "shèng（第四声）与 shēn（第一声）声调不同，韵母由 -en 变为 -eng，意思是完全胜利。"}, {"text": "全省", "is_correct": false, "explanation": "shěng（第三声）与 shēn（第一声）声调不同，韵母由 -en 变为 -eng，意思是整个省。"}], "explanations": {"全身": "正确答案：全身（quán shēn），指从头到脚的整个身体。", "全神": "shén（第二声）与 shēn（第一声）声调不同，意思是集中精神。", "前身": "qián 与 quán 的韵母不同（ian 与 uan），意思是以前的身份或组织的前身。", "全真": "zhēn 与 shēn 声母不同（zh 与 sh），意思是完全真实。", "全胜": "shèng（第四声）与 shēn（第一声）声调不同，韵母由 -en 变为 -eng，意思是完全胜利。", "全省": "shěng（第三声）与 shēn（第一声）声调不同，韵母由 -en 变为 -eng，意思是整个省。"}, "sentence_index": null, "correct_answer": "全身"}, "level_3": {"options": [{"text": "全身", "is_correct": true, "explanation": "正确答案：全身，指整个身体，与“都湿了”搭配。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是身体的部分，“他天气都湿了”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”说分量，不能说“湿了”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人的岁数，不能说“湿了”。"}], "explanations": {"全身": "正确答案：全身，指整个身体，与“都湿了”搭配。", "天气": "语义：“天气”不是身体的部分，“他天气都湿了”不成立。", "体重": "搭配：“体重”说分量，不能说“湿了”。", "年龄": "语义：“年龄”指人的岁数，不能说“湿了”。"}, "sentence_index": 0, "correct_answer": "全身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市全身都是绿色的。", "explanation": "这里应该用〈整个〉。全身只指人或动物的身体，不能指城市，表示整个城市要用整个。"}, {"text": "这些书全身是新的。", "explanation": "这里应该用〈全部〉。全身只指身体，不能修饰书，表示“所有”要用全部。"}, {"text": "这个方案全身可行。", "explanation": "这里应该用〈整体〉。全身只指身体，不能用来说方案的整体，整个方案是否可行要用整体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93743, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全身", "is_correct": true, "explanation": "正确答案：全身，指整个身体，与“发热”搭配。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“发热”说身体或物体的温度，“心情”不能发热。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”是物件，不是身体，“孩子电脑发热”不成立。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是性格，“孩子脾气发热”不成立。"}], "explanations": {"全身": "正确答案：全身，指整个身体，与“发热”搭配。", "心情": "搭配：“发热”说身体或物体的温度，“心情”不能发热。", "电脑": "语义：“电脑”是物件，不是身体，“孩子电脑发热”不成立。", "脾气": "语义：“脾气”是性格，“孩子脾气发热”不成立。"}, "sentence_index": 6, "correct_answer": "全身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班全身都来了。", "explanation": "这里应该用〈全体〉。全身只指身体，不能指一群人，表示“所有人”要用全体。"}, {"text": "这次旅行全身都很顺利。", "explanation": "这里应该用〈全程〉。全身不能指整个过程，整个旅程要用全程。"}, {"text": "全身的天气都很好。", "explanation": "这里应该用〈全国〉。全身只指身体，不能说天气的范围，指范围广要用全国。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
