INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93745, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "兵是在军队里当战士的人。", "primary_collocate": null, "pronunciation": "bīng", "ipa": "piŋ˥", "syllable_count": 1, "sentences": [{"text": "他在部队里是一个兵。", "target_word": "兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个兵站在门口，一动不动。", "target_word": "兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥是兵，不是官。", "target_word": "兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个兵今年才十九岁。", "target_word": "兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门前有两个兵守着。", "target_word": "兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想做一个兵。", "target_word": "兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个兵每天都要早起跑步。", "target_word": "兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个兵把枪放在桌子上。", "target_word": "兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不当官，只想当一个好兵。", "target_word": "兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路上走来了一个兵。", "target_word": "兵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "士兵", "label": "复合词"}], "register": "中性", "sense_fingerprint": "军队里的普通战士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdffcdca-4576-4326-9e48-c5ba571a4003') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93745, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "兵", "is_correct": true, "explanation": "正确。bīng（第一声）意思是军队里的战士。"}, {"text": "病", "is_correct": false, "explanation": "声调不同：bìng（第四声）与 bīng（第一声）声调不同，意思是病。"}, {"text": "饼", "is_correct": false, "explanation": "声调不同：bǐng（第三声）与 bīng（第一声）声调不同，意思是饼。"}, {"text": "宾", "is_correct": false, "explanation": "韵母不同：bīn 与 bīng 的韵尾 n、ng 不同，意思是宾客。"}], "explanations": {"兵": "正确。bīng（第一声）意思是军队里的战士。", "病": "声调不同：bìng（第四声）与 bīng（第一声）声调不同，意思是病。", "饼": "声调不同：bǐng（第三声）与 bīng（第一声）声调不同，意思是饼。", "宾": "韵母不同：bīn 与 bīng 的韵尾 n、ng 不同，意思是宾客。"}, "sentence_index": null, "correct_answer": "兵"}, "level_3": {"options": [{"text": "兵", "is_correct": true, "explanation": "正确。“兵”指军队里的普通战士，与“部队里”相合。"}, {"text": "农民", "is_correct": false, "explanation": "语义：“农民”指种地的人，“在部队里是一个农民”与语境不符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：“游客”指旅游的人，与部队里的身份不符。"}, {"text": "小学生", "is_correct": false, "explanation": "搭配：“小学生”指在小学读书的学生，不能用来说明在部队里的身份。"}], "explanations": {"兵": "正确。“兵”指军队里的普通战士，与“部队里”相合。", "农民": "语义：“农民”指种地的人，“在部队里是一个农民”与语境不符。", "游客": "语义：“游客”指旅游的人，与部队里的身份不符。", "小学生": "搭配：“小学生”指在小学读书的学生，不能用来说明在部队里的身份。"}, "sentence_index": 0, "correct_answer": "兵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门口站着一只兵。", "explanation": "这里应该用〈个〉。“只”多用于动物，指人的“兵”应用“个”。"}, {"text": "厨房里那只大猫是一名兵。", "explanation": "兵指军队里的战士，不能用来指猫。"}, {"text": "他的电脑是一名兵，每天都要开机。", "explanation": "兵指军队里的战士，不能用来指电脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93745, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "兵", "is_correct": true, "explanation": "正确。bīng（第一声）意思是军队里的战士。"}, {"text": "并", "is_correct": false, "explanation": "声调不同：bìng（第四声）与 bīng（第一声）声调不同，意思是并且、合并。"}, {"text": "柄", "is_correct": false, "explanation": "声调不同：bǐng（第三声）与 bīng（第一声）声调不同，意思是把手、柄。"}, {"text": "滨", "is_correct": false, "explanation": "韵母不同：bīn 与 bīng 的韵尾 n、ng 不同，意思是岸边、海滨。"}], "explanations": {"兵": "正确。bīng（第一声）意思是军队里的战士。", "并": "声调不同：bìng（第四声）与 bīng（第一声）声调不同，意思是并且、合并。", "柄": "声调不同：bǐng（第三声）与 bīng（第一声）声调不同，意思是把手、柄。", "滨": "韵母不同：bīn 与 bīng 的韵尾 n、ng 不同，意思是岸边、海滨。"}, "sentence_index": null, "correct_answer": "兵"}, "level_3": {"options": [{"text": "兵", "is_correct": true, "explanation": "正确。“一个兵每天早起跑步”指的是军人的日常训练，与“兵”相合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是物体，不能跑步，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不会动，不能每天早起跑步。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：“杯子”是物体，不会起床，也不会跑步。"}], "explanations": {"兵": "正确。“一个兵每天早起跑步”指的是军人的日常训练，与“兵”相合。", "桌子": "语义：“桌子”是物体，不能跑步，句意不通。", "石头": "语义：“石头”不会动，不能每天早起跑步。", "杯子": "语义：“杯子”是物体，不会起床，也不会跑步。"}, "sentence_index": 6, "correct_answer": "兵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏台灯是一名兵，每天都很亮。", "explanation": "兵指军队里的战士，不能用来指台灯。"}, {"text": "这把手术刀，原来是一名兵。", "explanation": "兵指军队里的战士，不能用来指手术刀。"}, {"text": "山路上走来了一匹兵。", "explanation": "这里应该用〈个〉。“匹”多用于马、骡等牲畜，指人的“兵”应用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只新来的兵很年轻。", "corrected_sentence": "那个新来的兵很年轻。", "error_description": "量词错误。“兵”指人，量词应用“个”，“只”多用于动物，应改为“那个新来的兵很年轻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那张兵刚刚从前线回来。", "corrected_sentence": "那个兵刚刚从前线回来。", "error_description": "量词错误。“张”多用于有平面的物体，指人的“兵”应用“个”，“那张兵”应改为“那个兵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
