INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93746, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军队中的士兵；也泛指军人。", "primary_collocate": null, "pronunciation": "bīng", "ipa": "piŋ˥", "syllable_count": 1, "sentences": [{"text": "战争年代，很多兵牺牲在前线。", "target_word": "兵", "complexity_tier": "T3", "furigana": "zhàn zhēng nián dài hěn duō bīng xī shēng zài qián xiàn", "sentence_source": "generated"}, {"text": "那支部队里有很多年轻的兵。", "target_word": "兵", "complexity_tier": "T3", "furigana": "nà zhī bù duì lǐ yǒu hěn duō nián qīng de bīng", "sentence_source": "generated"}, {"text": "国家派了很多兵到边境。", "target_word": "兵", "complexity_tier": "T3", "furigana": "guó jiā pài le hěn duō bīng dào biān jìng", "sentence_source": "generated"}, {"text": "那几个兵正在检查装备。", "target_word": "兵", "complexity_tier": "T3", "furigana": "nà jǐ gè bīng zhèng zài jiǎn chá zhuāng bèi", "sentence_source": "generated"}, {"text": "前线的兵每天都很辛苦。", "target_word": "兵", "complexity_tier": "T3", "furigana": "qián xiàn de bīng měi tiān dōu hěn xīn kǔ", "sentence_source": "generated"}, {"text": "训练一个兵需要很长时间。", "target_word": "兵", "complexity_tier": "T3", "furigana": "xùn liàn yí gè bīng xū yào hěn cháng shí jiān", "sentence_source": "generated"}, {"text": "那个兵的父亲以前也是军人。", "target_word": "兵", "complexity_tier": "T3", "furigana": "nà gè bīng de fù qīn yǐ qián yě shì jūn rén", "sentence_source": "generated"}, {"text": "战后许多兵回到了家乡。", "target_word": "兵", "complexity_tier": "T3", "furigana": "zhàn hòu xǔ duō bīng huí dào le jiā xiāng", "sentence_source": "generated"}, {"text": "他手下有三十个兵。", "target_word": "兵", "complexity_tier": "T3", "furigana": "tā shǒu xià yǒu sān shí gè bīng", "sentence_source": "generated"}, {"text": "这次演习参加的兵超过一万人。", "target_word": "兵", "complexity_tier": "T3", "furigana": "zhè cì yǎn xí cān jiā de bīng chāo guò yí wàn rén", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "士兵", "label": "复合词"}], "register": "中性", "sense_fingerprint": "士兵，也泛指从军的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdffcdca-4576-4326-9e48-c5ba571a4003') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93746, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "兵", "is_correct": true, "explanation": "正确。bīng（第一声）意思是军人、士兵。"}, {"text": "病", "is_correct": false, "explanation": "声调不同：bìng（第四声）与 bīng（第一声）声调不同，意思是病。"}, {"text": "饼", "is_correct": false, "explanation": "声调不同：bǐng（第三声）与 bīng（第一声）声调不同，意思是饼。"}, {"text": "宾", "is_correct": false, "explanation": "韵母不同：bīn 与 bīng 的韵尾 n、ng 不同，意思是宾客。"}], "explanations": {"兵": "正确。bīng（第一声）意思是军人、士兵。", "病": "声调不同：bìng（第四声）与 bīng（第一声）声调不同，意思是病。", "饼": "声调不同：bǐng（第三声）与 bīng（第一声）声调不同，意思是饼。", "宾": "韵母不同：bīn 与 bīng 的韵尾 n、ng 不同，意思是宾客。"}, "sentence_index": null, "correct_answer": "兵"}, "level_3": {"options": [{"text": "兵", "is_correct": true, "explanation": "正确。“兵”指参战的军人，与“战争年代”“牺牲在前线”相合。"}, {"text": "游客", "is_correct": false, "explanation": "语义：“游客”指旅游的人，与“战争年代”“牺牲在前线”明显不符。"}, {"text": "商人", "is_correct": false, "explanation": "语义：“商人”指做买卖的人，一般不会在前线牺牲，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是物体，不会牺牲，句意不通。"}], "explanations": {"兵": "正确。“兵”指参战的军人，与“战争年代”“牺牲在前线”相合。", "游客": "语义：“游客”指旅游的人，与“战争年代”“牺牲在前线”明显不符。", "商人": "语义：“商人”指做买卖的人，一般不会在前线牺牲，句意不通。", "桌子": "语义：“桌子”是物体，不会牺牲，句意不通。"}, "sentence_index": 0, "correct_answer": "兵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那几头兵正在检查装备。", "explanation": "这里应该用〈个〉。“头”多用于牛、猪等牲畜，指军人应用“个”。"}, {"text": "食堂里那几棵白菜是几个兵。", "explanation": "兵指军人，不能用来指白菜。"}, {"text": "学校里那几只鸡是几个兵。", "explanation": "兵指军人，不能用来指鸡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93746, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "兵", "is_correct": true, "explanation": "正确。bīng（第一声）意思是军人、士兵。"}, {"text": "并", "is_correct": false, "explanation": "声调不同：bìng（第四声）与 bīng（第一声）声调不同，意思是并且、合并。"}, {"text": "柄", "is_correct": false, "explanation": "声调不同：bǐng（第三声）与 bīng（第一声）声调不同，意思是把手、柄。"}, {"text": "滨", "is_correct": false, "explanation": "韵母不同：bīn 与 bīng 的韵尾 n、ng 不同，意思是岸边、海滨。"}], "explanations": {"兵": "正确。bīng（第一声）意思是军人、士兵。", "并": "声调不同：bìng（第四声）与 bīng（第一声）声调不同，意思是并且、合并。", "柄": "声调不同：bǐng（第三声）与 bīng（第一声）声调不同，意思是把手、柄。", "滨": "韵母不同：bīn 与 bīng 的韵尾 n、ng 不同，意思是岸边、海滨。"}, "sentence_index": null, "correct_answer": "兵"}, "level_3": {"options": [{"text": "兵", "is_correct": true, "explanation": "正确。“那个兵”是句子的主语，“父亲以前也是军人”与军人身份的语境相合。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”是动物，“小猫的父亲以前也是军人”与语境完全不符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是物体，不能有父亲，也不能是军人的后代，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是人，没有父亲，“那个石头的父亲以前也是军人”句意不通。"}], "explanations": {"兵": "正确。“那个兵”是句子的主语，“父亲以前也是军人”与军人身份的语境相合。", "小猫": "语义：“小猫”是动物，“小猫的父亲以前也是军人”与语境完全不符。", "窗户": "语义：“窗户”是物体，不能有父亲，也不能是军人的后代，句意不通。", "石头": "语义：“石头”不是人，没有父亲，“那个石头的父亲以前也是军人”句意不通。"}, "sentence_index": 6, "correct_answer": "兵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场音乐会的舞台上开出了一万个兵。", "explanation": "兵指军人，不能像花一样开出来。"}, {"text": "这所大学的湖里长着三千个兵。", "explanation": "兵指军人，不能像植物一样长在湖里。"}, {"text": "这块面包里有两百个兵。", "explanation": "兵指军人，不能在面包里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那场战斗里，很多兵们受了伤。", "corrected_sentence": "那场战斗里，很多兵受了伤。", "error_description": "错误在于“很多”本身已表示数量多，后面不能再加复数词尾“们”，“兵们”应改为“兵”，即“很多兵受了伤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支部队里有许多条兵。", "corrected_sentence": "这支部队里有许多兵。", "error_description": "量词错误。“条”多用于细长的物体，指人的“兵”不能用“条”，应去掉量词，改为“许多兵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
