INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93748, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "分别时的客套话，表示希望以后再见。", "primary_collocate": null, "pronunciation": "zài jiàn", "ipa": "tsai˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "再见，明天学校见！", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“再见！”她在门口大声说。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好，再见，路上小心。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再见，有空给我打电话。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“今天谢谢你，再见！”", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再见，祝你一路平安。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下午放学，老师对同学们说：“再见！”", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再见了，我的好朋友。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先走了，再见！", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再见，下个星期我们再聊。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "分别时单独说的客套话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e00da9fe-c9f4-4fde-8aa7-2a7d288258f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93748, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "再见", "is_correct": true, "explanation": "正确。再见 zài jiàn 是分别时单独说的客套话，表示希望以后再见。"}, {"text": "在线", "is_correct": false, "explanation": "zài xiàn（第四声）与 zài jiàn（第四声）只有声母不同（x 与 j），意思是通过网络连接。"}, {"text": "再现", "is_correct": false, "explanation": "xiàn 与 jiàn 只有声母不同（x 与 j），意思是再次出现或重新呈现。"}, {"text": "拜见", "is_correct": false, "explanation": "bài（第四声）与 zài 声母不同（b 与 z），意思是郑重地拜访见面，属于书面用语。"}], "explanations": {"再见": "正确。再见 zài jiàn 是分别时单独说的客套话，表示希望以后再见。", "在线": "zài xiàn（第四声）与 zài jiàn（第四声）只有声母不同（x 与 j），意思是通过网络连接。", "再现": "xiàn 与 jiàn 只有声母不同（x 与 j），意思是再次出现或重新呈现。", "拜见": "bài（第四声）与 zài 声母不同（b 与 z），意思是郑重地拜访见面，属于书面用语。"}, "sentence_index": null, "correct_answer": "再见"}, "level_3": {"options": [{"text": "再见", "is_correct": true, "explanation": "正确。作为分别时的客套话，“再见”放在句首与“明天学校见”相配。"}, {"text": "你好", "is_correct": false, "explanation": "语义：你好是见面时的问候，与后面“明天学校见”的分别语境相反。"}, {"text": "好久不见", "is_correct": false, "explanation": "语义：好久不见是见面时的问候，不能接“明天学校见”这样的道别话。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：欢迎用于迎接客人，不能接“明天学校见”这样的道别语。"}], "explanations": {"再见": "正确。作为分别时的客套话，“再见”放在句首与“明天学校见”相配。", "你好": "语义：你好是见面时的问候，与后面“明天学校见”的分别语境相反。", "好久不见": "语义：好久不见是见面时的问候，不能接“明天学校见”这样的道别话。", "欢迎": "搭配：欢迎用于迎接客人，不能接“明天学校见”这样的道别语。"}, "sentence_index": 0, "correct_answer": "再见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "再见！好久不见，最近怎么样？", "explanation": "这里应该用〈你好〉。“好久不见”是见面时的问候，与“再见”的告别意思不合。"}, {"text": "我不小心踩到了你的脚，只说了一句：“再见！”", "explanation": "这里应该用〈对不起〉。不小心伤到别人要先道歉，“再见”是分别时说的，不能代替道歉。"}, {"text": "再见，我给你倒杯水，请坐。", "explanation": "这里应该用〈请进〉。请客人进门时说“请进”，再接倒水、请坐；“再见”是分别时说的，不能用在这里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93748, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "再见", "is_correct": true, "explanation": "正确。再见 zài jiàn 是分别时单独说的客套话，表示希望以后再见。"}, {"text": "再减", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）只有声调不同，意思是再减少一些。"}, {"text": "再战", "is_correct": false, "explanation": "zhàn 与 jiàn 声母不同（zh 与 j），意思是再次比赛或战斗。"}, {"text": "再降", "is_correct": false, "explanation": "jiàng（第四声）与 jiàn 韵母不同（ang 与 an），意思是再次下降。"}], "explanations": {"再见": "正确。再见 zài jiàn 是分别时单独说的客套话，表示希望以后再见。", "再减": "jiǎn（第三声）与 jiàn（第四声）只有声调不同，意思是再减少一些。", "再战": "zhàn 与 jiàn 声母不同（zh 与 j），意思是再次比赛或战斗。", "再降": "jiàng（第四声）与 jiàn 韵母不同（ang 与 an），意思是再次下降。"}, "sentence_index": null, "correct_answer": "再见"}, "level_3": {"options": [{"text": "再见", "is_correct": true, "explanation": "正确。老师在课堂结束时对同学说“再见”，符合语境。"}, {"text": "早安", "is_correct": false, "explanation": "语义：早安是清晨的问候，与下午放学的道别场景不合。"}, {"text": "晚安", "is_correct": false, "explanation": "语义：晚安是睡前说的话，不用于下午放学时的道别。"}, {"text": "好久不见", "is_correct": false, "explanation": "语义：好久不见是重逢时的问候，老师每天见学生，放学时不会这样说。"}], "explanations": {"再见": "正确。老师在课堂结束时对同学说“再见”，符合语境。", "早安": "语义：早安是清晨的问候，与下午放学的道别场景不合。", "晚安": "语义：晚安是睡前说的话，不用于下午放学时的道别。", "好久不见": "语义：好久不见是重逢时的问候，老师每天见学生，放学时不会这样说。"}, "sentence_index": 6, "correct_answer": "再见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "再见，你考上了大学！", "explanation": "这里应该用〈恭喜〉。“你考上了大学”是祝贺的内容，“再见”是分别时说的，不能用来祝贺。"}, {"text": "我刚进门，对爸妈说：“再见！”", "explanation": "这里应该用〈我回来了〉。进门要说“我回来了”，“再见”是离开时说的，不能用在这里。"}, {"text": "再见，这份礼物我很喜欢。", "explanation": "这里应该用〈谢谢〉。夸奖或说明收到礼物时要表示感谢，“再见”不能接在这里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我该走了，跟你声再见。", "corrected_sentence": "我该走了，跟你说声再见。", "error_description": "错误：漏掉了动词“说”。应说“跟你说声再见”，去掉“说”后，量词“声”没有依附的动词，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他挥挥手，说了一件再见。", "corrected_sentence": "他挥挥手，说了声再见。", "error_description": "错误：量词用错。“再见”前的量词应为“声”（说了一声再见），“件”用于事情或衣服，不能用于话语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93749, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
