INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93751, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "分之用在两个数中间，说一份占总数的多少，比如三分之一。", "primary_collocate": null, "pronunciation": "fēn zhī", "ipa": "fən˥ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "三分之一就是把一个东西分成三份，取一份。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把“二分之一”写在本子上。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师写了“五分之三”这个数。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四分之一比二分之一小。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半个苹果是二分之一个苹果。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "六分之五怎么读？", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "七分之二和七分之三，哪个大？", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会写三分之二，也会读它。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学课上，我们学了八分之一。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个数中间加上分之，就是分数。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "三分之一", "label": "复合"}, {"form": "七分之二", "label": "复合"}], "register": "中性", "sense_fingerprint": "用在两个数中间构成分数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65734415-928a-473e-bc99-3005a844ecdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93751, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分之", "is_correct": true, "explanation": "正确答案。分之读 fēn zhī，用在两个数中间，表示一份占总数的多少。"}, {"text": "分子", "is_correct": false, "explanation": "zǐ（第三声）与 zhī（第一声）声母和声调都不同，意思是分数里的“分子”。"}, {"text": "分吃", "is_correct": false, "explanation": "chī（第一声）与 zhī（第一声）声调相同，只有声母不同（ch 与 zh），意思是“分开吃”。"}, {"text": "粉汁", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，意思是粉状食物调成的汁。"}, {"text": "分置", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是分开设置。"}], "explanations": {"分之": "正确答案。分之读 fēn zhī，用在两个数中间，表示一份占总数的多少。", "分子": "zǐ（第三声）与 zhī（第一声）声母和声调都不同，意思是分数里的“分子”。", "分吃": "chī（第一声）与 zhī（第一声）声调相同，只有声母不同（ch 与 zh），意思是“分开吃”。", "粉汁": "fěn（第三声）与 fēn（第一声）声调不同，意思是粉状食物调成的汁。", "分置": "zhì（第四声）与 zhī（第一声）声调不同，意思是分开设置。"}, "sentence_index": null, "correct_answer": "分之"}, "level_3": {"options": [{"text": "分之", "is_correct": true, "explanation": "正确。“三分之一”是分数的固定结构，分之表示一份占总数的多少。"}, {"text": "得", "is_correct": false, "explanation": "搭配：“得”用来引出补语，不能接在两个数字之间，“三得一”不通顺。"}, {"text": "似的", "is_correct": false, "explanation": "语义：“似的”表示相似，与一份占总数的多少无关，“三似的一”说不通。"}, {"text": "而已", "is_correct": false, "explanation": "语义：“而已”表示限定语气，不能用来表示份额。"}], "explanations": {"分之": "正确。“三分之一”是分数的固定结构，分之表示一份占总数的多少。", "得": "搭配：“得”用来引出补语，不能接在两个数字之间，“三得一”不通顺。", "似的": "语义：“似的”表示相似，与一份占总数的多少无关，“三似的一”说不通。", "而已": "语义：“而已”表示限定语气，不能用来表示份额。"}, "sentence_index": 0, "correct_answer": "分之"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把一块饼分成三分之一。", "explanation": "这里应该用〈三份〉。“分成”后面要接份数，不能接表示占比的分数；“三分之一”表示份额，要说“分成三份”。"}, {"text": "我家有三分之一个哥哥。", "explanation": "这里应该用〈一个〉。哥哥是整体的人，不能按份额计算；“三分之一”只用于可以平分的整体，应说“一个哥哥”。"}, {"text": "班里很多分之一的同学都去了公园。", "explanation": "这里应该用〈三〉。“分之一”前缺分子，“很多”不是数字；把“很多”改为“三”，即“三分之一的同学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93751, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分之", "is_correct": true, "explanation": "正确答案。分之读 fēn zhī，用在两个数中间，表示一份占总数的多少。"}, {"text": "分值", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是分数或得分的价值。"}, {"text": "分制", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是学分或分数的制度。"}, {"text": "粉质", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，zhì（第四声）与 zhī（第一声）声调也不同，意思是粉末的性质。"}], "explanations": {"分之": "正确答案。分之读 fēn zhī，用在两个数中间，表示一份占总数的多少。", "分值": "zhí（第二声）与 zhī（第一声）声调不同，意思是分数或得分的价值。", "分制": "zhì（第四声）与 zhī（第一声）声调不同，意思是学分或分数的制度。", "粉质": "fěn（第三声）与 fēn（第一声）声调不同，zhì（第四声）与 zhī（第一声）声调也不同，意思是粉末的性质。"}, "sentence_index": null, "correct_answer": "分之"}, "level_3": {"options": [{"text": "分之", "is_correct": true, "explanation": "正确。“七分之二和七分之三”是比较两个分数，分之是分数的固定结构。"}, {"text": "的", "is_correct": false, "explanation": "搭配：“七的二”不是分数的说法，两个数字之间不能直接用“的”连接。"}, {"text": "地", "is_correct": false, "explanation": "搭配：“地”用于修饰动词或形容词，不能放在两个数字之间。"}, {"text": "所", "is_correct": false, "explanation": "语域：“所”属书面结构，要接动词构成名词性词组，不能用在表示分数的数字之间。"}], "explanations": {"分之": "正确。“七分之二和七分之三”是比较两个分数，分之是分数的固定结构。", "的": "搭配：“七的二”不是分数的说法，两个数字之间不能直接用“的”连接。", "地": "搭配：“地”用于修饰动词或形容词，不能放在两个数字之间。", "所": "语域：“所”属书面结构，要接动词构成名词性词组，不能用在表示分数的数字之间。"}, "sentence_index": 6, "correct_answer": "分之"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个数中间加上分之，就是减号。", "explanation": "这里应该用〈分数〉。分之只用来构成分数，不表示减法。"}, {"text": "两个数中间加上分之，就是两个数相加。", "explanation": "分之不表示相加。两个数相加要用“加号”，分之的意思不是加法。"}, {"text": "两个数中间加上分之，就是乘法算式。", "explanation": "分之不是乘法。两个数相乘要用“乘号”，分之只用于表示分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每人分到四的分之一，剩下的留给明天。", "corrected_sentence": "每人分到四分之一，剩下的留给明天。", "error_description": "错误：“四”与“分之”之间多加了“的”。分数结构要连续说“四分之一”，不能在数字和“分之”之间加“的”，应为“四分之一”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班里有七个分之三的同学带了午饭。", "corrected_sentence": "班里有七分之三的同学带了午饭。", "error_description": "多加了量词。“七个分之三”在数字和“分之”之间加了“个”，分数结构要连续说“七分之三”，量词会打断分数结构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
