INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93756, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表示事物特性的数值或变量；计算和设计中用到的数据。", "primary_collocate": null, "pronunciation": "cān shù", "ipa": "tsʰan˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "请在程序里输入这个参数。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师调整了机器的运行参数。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个函数需要两个参数。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师根据参数计算桥的重量。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改一下参数，结果就不一样了。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件无法启动，要检查一下参数设置。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验前，我们先设定好温度参数。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模型的参数越多，计算越慢。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电脑上修改了设计参数。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个参数的值必须大于零。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "组", "label": "量词"}, {"form": "参数表", "label": "复合"}, {"form": "参數", "label": "繁体"}], "register": "中性", "sense_fingerprint": "计算设计中的变量或数值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6b8e2c5-1682-4b33-9c63-d8dce1b8d46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93756, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "参数", "is_correct": true, "explanation": "正确。cānshù 即“参数”，指计算和设计中的变量或数值。"}, {"text": "残暑", "is_correct": false, "explanation": "cán（第二声）与 cān（第一声）声调不同，shǔ（第三声）与 shù（第四声）声调也不同，意思是夏末的余热。"}, {"text": "残书", "is_correct": false, "explanation": "cán（第二声）与 cān（第一声）声调不同，shū（第一声）与 shù（第四声）声调也不同，意思是破旧、不完整的书。"}, {"text": "餐食", "is_correct": false, "explanation": "shí（第二声）与 shù（第四声）韵母不同，意思是饭菜、食物。"}, {"text": "餐室", "is_correct": false, "explanation": "shì（第四声）与 shù（第四声）韵母不同，意思是餐厅或用餐的房间。"}], "explanations": {"参数": "正确。cānshù 即“参数”，指计算和设计中的变量或数值。", "残暑": "cán（第二声）与 cān（第一声）声调不同，shǔ（第三声）与 shù（第四声）声调也不同，意思是夏末的余热。", "残书": "cán（第二声）与 cān（第一声）声调不同，shū（第一声）与 shù（第四声）声调也不同，意思是破旧、不完整的书。", "餐食": "shí（第二声）与 shù（第四声）韵母不同，意思是饭菜、食物。", "餐室": "shì（第四声）与 shù（第四声）韵母不同，意思是餐厅或用餐的房间。"}, "sentence_index": null, "correct_answer": "参数"}, "level_3": {"options": [{"text": "参数", "is_correct": true, "explanation": "正确。“参数”指程序中要输入的变量或数值，可以“输入”。"}, {"text": "风景", "is_correct": false, "explanation": "语义：风景指自然景象，不能输入程序，与“输入”搭配不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是人的情绪，程序里不能输入心情，与句中的“程序里”冲突。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人或动物的体形，不是程序中可以输入的内容。"}], "explanations": {"参数": "正确。“参数”指程序中要输入的变量或数值，可以“输入”。", "风景": "语义：风景指自然景象，不能输入程序，与“输入”搭配不通。", "心情": "语义：心情是人的情绪，程序里不能输入心情，与句中的“程序里”冲突。", "身材": "体貌：身材指人或动物的体形，不是程序中可以输入的内容。"}, "sentence_index": 0, "correct_answer": "参数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的参数很有趣。", "explanation": "这里应该用〈内容〉。参数指数值或变量，不能用来说书的内容有趣。"}, {"text": "这件衣服的参数是三百元。", "explanation": "这里应该用〈价格〉。参数指数值或变量，不指钱数。"}, {"text": "这家餐厅的参数在市中心。", "explanation": "这里应该用〈地址〉。参数指数值或变量，不指地点；说餐厅的位置要用地址。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参数", "is_correct": true, "explanation": "正确。“参数”指实验中设定的数值，温度参数可以被设定。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是色彩，不能设定为温度，与“温度”搭配不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指金额，不能作为温度的设定值，与“温度”冲突。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重指人或动物的重量，实验中设定的温度不说体重。"}], "explanations": {"参数": "正确。“参数”指实验中设定的数值，温度参数可以被设定。", "颜色": "语义：颜色是色彩，不能设定为温度，与“温度”搭配不通。", "价格": "语义：价格指金额，不能作为温度的设定值，与“温度”冲突。", "体重": "体貌：体重指人或动物的重量，实验中设定的温度不说体重。"}, "sentence_index": 6, "correct_answer": "参数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张图的参数是红色的。", "explanation": "这里应该用〈颜色〉。参数是数值或变量，不指颜色。"}, {"text": "这台电脑的参数是联想。", "explanation": "这里应该用〈品牌〉。参数指数值或设置，不指生产厂家。"}, {"text": "这篇论文的参数是张三。", "explanation": "这里应该用〈作者〉。参数不指写作的人，不能用来说作者是谁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个程序有三台参数需要设置。", "corrected_sentence": "这个程序有三项参数需要设置。", "error_description": "量词错误：“台”用于机器、设备，“参数”应搭配“项”或“个”。正确说法是“这个程序有三项参数需要设置”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个模型有很多块参数。", "corrected_sentence": "这个模型有很多项参数。", "error_description": "量词错误：“块”用于块状的东西，不能用来数“参数”。“参数”应搭配“项”或“个”，正确说法是“这个模型有很多项参数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
