INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93757, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "友谊是朋友之间互相喜欢、互相帮助的好感情。", "primary_collocate": null, "pronunciation": "yǒu yì", "ipa": "jou˨˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "我们的友谊从小学开始。", "target_word": "友谊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们靠互相帮助建立了友谊。", "target_word": "友谊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友要珍惜友谊。", "target_word": "友谊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份友谊让我们都很温暖。", "target_word": "友谊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一起学习让我们的友谊更好。", "target_word": "友谊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "友谊需要互相帮助。", "target_word": "友谊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和邻居之间有真正的友谊。", "target_word": "友谊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望我们的友谊永远不变。", "target_word": "友谊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的友谊陪我走过了最难的日子。", "target_word": "友谊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明和小红通过游戏增进了友谊。", "target_word": "友谊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份友谊", "label": "量词"}], "register": "通用", "sense_fingerprint": "朋友间互相喜欢、互相帮助的感情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e00da9fe-c9f4-4fde-8aa7-2a7d288258f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93757, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "友谊", "is_correct": true, "explanation": "正确。友谊 yǒu yì 指朋友之间互相喜欢、互相帮助的感情。"}, {"text": "优异", "is_correct": false, "explanation": "yōu（第一声）与 yǒu（第三声）声调不同，“优异”意思是特别好、出色。"}, {"text": "游艺", "is_correct": false, "explanation": "yóu（第二声）与 yǒu（第三声）声调不同，“游艺”意思是娱乐活动。"}, {"text": "右翼", "is_correct": false, "explanation": "yòu（第四声）与 yǒu（第三声）声调不同，“右翼”意思是右边的一翼。"}], "explanations": {"友谊": "正确。友谊 yǒu yì 指朋友之间互相喜欢、互相帮助的感情。", "优异": "yōu（第一声）与 yǒu（第三声）声调不同，“优异”意思是特别好、出色。", "游艺": "yóu（第二声）与 yǒu（第三声）声调不同，“游艺”意思是娱乐活动。", "右翼": "yòu（第四声）与 yǒu（第三声）声调不同，“右翼”意思是右边的一翼。"}, "sentence_index": null, "correct_answer": "友谊"}, "level_3": {"options": [{"text": "友谊", "is_correct": true, "explanation": "正确。“我们的友谊从小学开始”指朋友之间的感情，符合句意。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不能说“我们的感冒从小学开始”，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人际关系，“我们的天气从小学开始”句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是感情，“我们的桌子从小学开始”句意不通。"}], "explanations": {"友谊": "正确。“我们的友谊从小学开始”指朋友之间的感情，符合句意。", "感冒": "语义：感冒是疾病，不能说“我们的感冒从小学开始”，句意不通。", "天气": "语义：天气不是人际关系，“我们的天气从小学开始”句意不通。", "桌子": "语义：桌子是家具，不是感情，“我们的桌子从小学开始”句意不通。"}, "sentence_index": 0, "correct_answer": "友谊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对女朋友的友谊很深。", "explanation": "这里应该用〈爱情〉。友谊指朋友之间的感情，恋人之间的感情要用爱情。"}, {"text": "这次比赛的友谊很激烈。", "explanation": "这里应该用〈竞争〉。比赛中的激烈情况是竞争，友谊指朋友间的好感。"}, {"text": "他对这个城市的友谊很深。", "explanation": "这里应该用〈感情〉。友谊只用于人与人之间，对城市的喜爱要用感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93757, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "友谊", "is_correct": true, "explanation": "正确。“他和邻居之间有真正的友谊”，指邻居间的好感，符合句意。"}, {"text": "亲戚", "is_correct": false, "explanation": "语义：亲戚指有血缘关系的人，与邻居之间的关系不符。"}, {"text": "合同", "is_correct": false, "explanation": "搭配：合同是书面协议，“真正的合同”不能用来描述邻居之间的关系。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不是人际关系，“他和邻居之间有真正的作业”句意不通。"}], "explanations": {"友谊": "正确。“他和邻居之间有真正的友谊”，指邻居间的好感，符合句意。", "亲戚": "语义：亲戚指有血缘关系的人，与邻居之间的关系不符。", "合同": "搭配：合同是书面协议，“真正的合同”不能用来描述邻居之间的关系。", "作业": "语义：作业是学习任务，不是人际关系，“他和邻居之间有真正的作业”句意不通。"}, "sentence_index": 6, "correct_answer": "友谊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的友谊考了一百分。", "explanation": "这里应该用〈成绩〉。考试得分要说成绩，友谊不能用来计分。"}, {"text": "他这个月的友谊涨了五百块。", "explanation": "这里应该用〈工资〉。按月涨钱的是工资，友谊不能用钱来计算。"}, {"text": "车站的友谊很拥挤。", "explanation": "这里应该用〈人群〉。拥挤的是人群，友谊不能用来形容地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93757, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们之间有一只珍贵的友谊。", "corrected_sentence": "他们之间有一份珍贵的友谊。", "error_description": "错误：量词用错。“友谊”的量词应为“份”，“只”用于动物等，不能用来修饰友谊。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93757, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们之间有很深友谊。", "corrected_sentence": "我们之间有很深的友谊。", "error_description": "错误：漏掉了修饰语后的“的”。“很深”修饰名词时要说“很深的友谊”，去掉“的”不符合规范。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
