INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93759, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "function", "definition": "另一是还有的那一个，不是前面说的这个。", "primary_collocate": null, "pronunciation": "lìng yī", "ipa": "liŋ˥˩ i˥", "syllable_count": 2, "sentences": [{"text": "这个房间太小，我想换另一个。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一只手拿着书，另一只手拿着水。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个是我的，另一个是你的。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有两个妹妹，一个在上海，另一个在北京。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一条路太远，我们走另一条吧。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子很旧，请给我另一个。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子的一边有书，另一边有花。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人去了，另一个人没有去。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢红色的，不喜欢另一件。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只鞋在这儿，另一只在哪儿？", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "另一个", "label": "量词"}, {"form": "另一边", "label": "复合"}, {"form": "另一半", "label": "复合"}], "register": "中性", "sense_fingerprint": "两者相对时指还有的那一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65734415-928a-473e-bc99-3005a844ecdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93759, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同一", "is_correct": false, "explanation": "语义：同一指相同的那一个，与“另”指还有的另外一个相反。"}, {"text": "这一", "is_correct": false, "explanation": "语义：这一个指眼前的这个房间，与“房间太小，想换”的意思矛盾。"}, {"text": "每一", "is_correct": false, "explanation": "语义：每一指全部中的每一个，与“另”只指相对的那一个不符。"}, {"text": "另一", "is_correct": true, "explanation": "正确：“另一个”指还有的另外一个房间，与“房间太小，想换”的意思相合，符合句意。"}], "explanations": {"同一": "语义：同一指相同的那一个，与“另”指还有的另外一个相反。", "这一": "语义：这一个指眼前的这个房间，与“房间太小，想换”的意思矛盾。", "每一": "语义：每一指全部中的每一个，与“另”只指相对的那一个不符。", "另一": "正确：“另一个”指还有的另外一个房间，与“房间太小，想换”的意思相合，符合句意。"}, "sentence_index": 0, "correct_answer": "另一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我只有一个妹妹，另一个在北京。", "explanation": "这里应该用〈还有一个〉。“另一”要求前文已有相对的一方；这里“只有一个妹妹”，并没有可相对的另一个，两句互相矛盾。"}, {"text": "我有两个妹妹，一个在上海，另一只在北京。", "explanation": "这里应该用〈个〉。妹妹是人，不能用“只”。"}, {"text": "我家只有一台电脑，另一台在哪儿？", "explanation": "这里应该用〈还有一台〉。“另一”要求前文已有相对的一方，这里“只有一台电脑”，并没有可相对的另一台，两句互相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任一", "is_correct": false, "explanation": "语义：任一指任选其一，与“一边有书”的具体描述冲突。"}, {"text": "每一", "is_correct": false, "explanation": "语义：每一指全部中的每一个，与前句“一边有书”矛盾，不能与“一边”相对。"}, {"text": "另一", "is_correct": true, "explanation": "正确：“另一边”指桌子的另外一边，与前句“一边”相对，符合句意。"}, {"text": "前一", "is_correct": false, "explanation": "语义：前一指先前提到的那个，不是与“一边”并列的另一边。"}], "explanations": {"任一": "语义：任一指任选其一，与“一边有书”的具体描述冲突。", "每一": "语义：每一指全部中的每一个，与前句“一边有书”矛盾，不能与“一边”相对。", "另一": "正确：“另一边”指桌子的另外一边，与前句“一边”相对，符合句意。", "前一": "语义：前一指先前提到的那个，不是与“一边”并列的另一边。"}, "sentence_index": 6, "correct_answer": "另一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一只鞋在这儿，另一把在哪儿？", "explanation": "这里应该用〈只〉。“把”用于有柄的物件，鞋要用“只”或“双”。"}, {"text": "一只鞋在这儿，另一支在哪儿？", "explanation": "这里应该用〈只〉。“支”用于笔、枪等细长的东西，鞋不用“支”。"}, {"text": "一只鞋在这儿，另一条在哪儿？", "explanation": "这里应该用〈只〉。“条”用于细长的东西，鞋不用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不喜欢这顶帽子，想试试另一只。", "corrected_sentence": "我不喜欢这顶帽子，想试试另一顶。", "error_description": "错误：量词“只”。帽子的量词应用“顶”，“只”不用于帽子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上有两支笔，另一在书包里。", "corrected_sentence": "桌上有两支笔，另一支在书包里。", "error_description": "错误：“另一”后面漏了量词。笔的量词应用“支”，“另一”不能单独指代，应说“另一支”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
