INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93760, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93760, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "function", "definition": "指已提到的以外的；别的一个。", "primary_collocate": null, "pronunciation": "lìng yī", "ipa": "liŋ˥˩ i˥", "syllable_count": 2, "sentences": [{"text": "她在一家银行工作，也在另一家公司做事。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们换另一个办法试试。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了这件事，还有另一个问题。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个星期很忙，我们约在另一天吧。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友要来，另一个同学也想来，可以吗？", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样说不对，我从另一个方面想想。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河的另一边有一个小公园。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在另一个城市，很少回家。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不喜欢这个，可以选另一种。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们另一个机会。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "另一个", "label": "量词"}, {"form": "另一种", "label": "量词"}, {"form": "另一方面", "label": "复合"}], "register": "中性", "sense_fingerprint": "指已提到的以外的别的一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65734415-928a-473e-bc99-3005a844ecdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同一", "is_correct": false, "explanation": "语义：同一表示相同的那一家，与“另一家”指不同的公司相反。"}, {"text": "另一", "is_correct": true, "explanation": "正确：“另一家”指已提到的银行以外的别的公司，与“也在”相合，符合句意。"}, {"text": "每一", "is_correct": false, "explanation": "语义：每一指全部中的每一个，与“另一家”只指一家不符。"}, {"text": "这一", "is_correct": false, "explanation": "语义：这一家指说话人指定的某一家公司，并非银行以外“另外”的一家，与句意不符。"}], "explanations": {"同一": "语义：同一表示相同的那一家，与“另一家”指不同的公司相反。", "另一": "正确：“另一家”指已提到的银行以外的别的公司，与“也在”相合，符合句意。", "每一": "语义：每一指全部中的每一个，与“另一家”只指一家不符。", "这一": "语义：这一家指说话人指定的某一家公司，并非银行以外“另外”的一家，与句意不符。"}, "sentence_index": 0, "correct_answer": "另一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在一家银行工作，也在另一条公司做事。", "explanation": "这里应该用〈家〉。“条”用于细长的东西，公司要用“家”。"}, {"text": "我们换另一把办法试试。", "explanation": "这里应该用〈种〉。“把”用于有柄的东西，办法要用“种”或“个”。"}, {"text": "我只有一个朋友，另一个朋友很热情。", "explanation": "这里应该用〈还有一个〉。“另一”指已提到之外的别的一个；这里前文说“只有一个朋友”，就没有别的朋友可指，两句互相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任一", "is_correct": false, "explanation": "语义：任一指任选其一，与“河的一边”这种特定位置不符。"}, {"text": "同一", "is_correct": false, "explanation": "语义：同一指同一边，句中并无已提及的一边可供指称，与“河的另一边”（对岸）不符。"}, {"text": "另一", "is_correct": true, "explanation": "正确：“另一边”指河的另外一边，与“有一个小公园”相合，符合句意。"}, {"text": "前一", "is_correct": false, "explanation": "语义：前一指先前提到的那一个，与“河的另一边”的并列位置不符。"}], "explanations": {"任一": "语义：任一指任选其一，与“河的一边”这种特定位置不符。", "同一": "语义：同一指同一边，句中并无已提及的一边可供指称，与“河的另一边”（对岸）不符。", "另一": "正确：“另一边”指河的另外一边，与“有一个小公园”相合，符合句意。", "前一": "语义：前一指先前提到的那一个，与“河的另一边”的并列位置不符。"}, "sentence_index": 6, "correct_answer": "另一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师给了我们另一座机会。", "explanation": "这里应该用〈个〉。“座”用于山、桥、房屋等大型固定的东西，机会要用“个”。"}, {"text": "老师给了我们另一位机会。", "explanation": "这里应该用〈个〉。“位”用于人，“机会”要用“个”。"}, {"text": "公司只有一位老板，另一位老板在上海。", "explanation": "这里应该用〈还有一位〉。“另一”指已提到之外的别的一个，这里前文说“只有一位老板”，就没有别的老板可指，两句互相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方案不行，我们换另一只方案吧。", "corrected_sentence": "这个方案不行，我们换另一个方案吧。", "error_description": "错误：量词“只”。“方案”的量词应用“个”，“只”不用于方案，应写成“另一个方案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他换了另一的公司。", "corrected_sentence": "他换了另一家公司。", "error_description": "错误：“另一”后多加了“的”。“另一”后直接接量词“家”，应写成“另一家公司”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c5e4ac0-581d-48ee-9061-b81f7ec11dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93761, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "多样", "is_correct": true, "explanation": "多样：种类繁多，与“单一”（只有一种）相对。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰指清楚分明，与种类多少无关，不是反义词。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速指速度快，与种类多少无关，不是反义词。"}, {"text": "安静", "is_correct": false, "explanation": "安静指没有声音，与种类多少无关，不是反义词。"}], "correct_answer": "多样", "explanations": {"多样": "多样：种类繁多，与“单一”（只有一种）相对。", "清晰": "清晰指清楚分明，与种类多少无关，不是反义词。", "迅速": "迅速指速度快，与种类多少无关，不是反义词。", "安静": "安静指没有声音，与种类多少无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93761, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "多样", "is_correct": true, "explanation": "多样：种类繁多，与“单一”（只有一种）相对。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮指光线强、颜色鲜亮，与种类多少无关，不是反义词。"}, {"text": "轻松", "is_correct": false, "explanation": "轻松指不紧张、不费力，与种类多少无关，不是反义词。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐指排列有序，与种类多少无关，不是反义词。"}], "correct_answer": "多样", "explanations": {"多样": "多样：种类繁多，与“单一”（只有一种）相对。", "明亮": "明亮指光线强、颜色鲜亮，与种类多少无关，不是反义词。", "轻松": "轻松指不紧张、不费力，与种类多少无关，不是反义词。", "整齐": "整齐指排列有序，与种类多少无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93761, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "单一是只有一种，没有别的。", "primary_collocate": null, "pronunciation": "dān yī", "ipa": "tan˥ i˥", "syllable_count": 2, "sentences": [{"text": "这家店卖的东西太单一了，只有一种面包。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的饮食很单一，每天都只吃米饭。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园里的花很单一，全是红色的。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的颜色太单一，只有白色。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只吃一种菜，饮食太单一，对身体不好。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的课程很单一，只有数学。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的树很单一，到处都是同一种。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "单一的颜色看久了，眼睛会累。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的收入来源很单一，只靠一份工作。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的故事很单一，只讲了一件事。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "单一化", "label": "复合词"}], "register": "中性", "sense_fingerprint": "单一：只有一种，没有别的种类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb8dd41a-3ee5-4ea6-a6a8-3eb267922083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93761, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "单一", "is_correct": true, "explanation": "单一：只有一种，与“只有一种面包”一致，句意成立。"}, {"text": "丰富", "is_correct": false, "explanation": "语义：“丰富”指种类多，与后面“只有一种面包”矛盾。"}, {"text": "多样", "is_correct": false, "explanation": "语义：“多样”指种类多，与“只有一种面包”相反。"}, {"text": "复杂", "is_correct": false, "explanation": "搭配：“复杂”多形容事情、结构，不说“东西太复杂”，且与“只有一种”也不合。"}], "explanations": {"单一": "单一：只有一种，与“只有一种面包”一致，句意成立。", "丰富": "语义：“丰富”指种类多，与后面“只有一种面包”矛盾。", "多样": "语义：“多样”指种类多，与“只有一种面包”相反。", "复杂": "搭配：“复杂”多形容事情、结构，不说“东西太复杂”，且与“只有一种”也不合。"}, "sentence_index": 0, "correct_answer": "单一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个超市的货品很单一，有各种各样的东西。", "explanation": "这里应该用〈丰富〉。“单一”指只有一种，与“有各种各样的东西”矛盾，品种多要用“丰富”。"}, {"text": "这个电影的情节很单一，有很多条线索。", "explanation": "这里应该用〈复杂〉。情节线索多、头绪多要用“复杂”，“单一”指只有一种，与此矛盾。"}, {"text": "她是这个家里单一的孩子。", "explanation": "这里应该用〈唯一〉。表示只有一个人，要用唯一，“单一”不用于数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93761, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "单一", "is_correct": true, "explanation": "单一：只有一种，与“到处都是同一种”一致，句意成立。"}, {"text": "多彩", "is_correct": false, "explanation": "语义：“多彩”指颜色丰富，与“到处都是同一种”矛盾。"}, {"text": "繁多", "is_correct": false, "explanation": "搭配：“繁多”多用于数量、种类，不说“树很繁多”。"}, {"text": "繁复", "is_correct": false, "explanation": "搭配：“繁复”多形容事情、手续，不说“树很繁复”。"}], "explanations": {"单一": "单一：只有一种，与“到处都是同一种”一致，句意成立。", "多彩": "语义：“多彩”指颜色丰富，与“到处都是同一种”矛盾。", "繁多": "搭配：“繁多”多用于数量、种类，不说“树很繁多”。", "繁复": "搭配：“繁复”多形容事情、手续，不说“树很繁复”。"}, "sentence_index": 6, "correct_answer": "单一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个盒子里的糖果很单一，有红的、黄的和绿的。", "explanation": "这里应该用〈多样〉。“单一”指只有一种，与“红的、黄的和绿的”矛盾，种类多要用“多样”。"}, {"text": "这份菜单很单一，有二十多道菜。", "explanation": "这里应该用〈丰富〉。“单一”指只有一种，与“二十多道菜”矛盾，菜品多样要说菜单“丰富”。"}, {"text": "他的兴趣很单一，音乐、绘画、运动样样都喜欢。", "explanation": "这里应该用〈广泛〉。“单一”指只有一种，与“样样都喜欢”矛盾，兴趣范围大要用“广泛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店的东西很的单一。", "corrected_sentence": "这家店的东西很单一。", "error_description": "修饰错误：程度副词“很”后面不能直接加“的”再接形容词，应说“很单一”，不能说“很的单一”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的面包太单一得，只有一种。", "corrected_sentence": "这家店的面包太单一了，只有一种。", "error_description": "补语错误：“太……了”表示程度过高，句末要用“了”，不能用“得”，应说“太单一了”，不说“太单一得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
