INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93762, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "只有一种；不复杂。", "primary_collocate": null, "pronunciation": "dān yī", "ipa": "tan˥ i˥", "syllable_count": 2, "sentences": [{"text": "他的生活很单一，每天上班、回家。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的玩法单一，一会儿就没意思了。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的节奏很单一，听起来没有变化。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的想法很单一，只想着玩。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影的情节单一，一看就懂。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的结构单一，坏了也容易修。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作的内容很单一，每天做同样的事。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲话的方式单一，听久了让人想睡觉。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张画只用黑色，画面很单一。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的日子过得单一，每天散步、看报。", "target_word": "单一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "单一化", "label": "复合词"}], "register": "中性", "sense_fingerprint": "单一：只有一种，不复杂、没有变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb8dd41a-3ee5-4ea6-a6a8-3eb267922083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93762, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "单一", "is_correct": true, "explanation": "单一：不复杂、没有变化，与“每天上班、回家”一致，句意成立。"}, {"text": "精彩", "is_correct": false, "explanation": "语义：“精彩”指生动有趣，与“每天上班、回家”的重复生活矛盾。"}, {"text": "有趣", "is_correct": false, "explanation": "语义：“有趣”指让人愉快，与“每天上班、回家”的单调生活矛盾。"}, {"text": "丰富", "is_correct": false, "explanation": "搭配：“丰富”多指内容、资源，用来形容这种重复的生活不合适。"}], "explanations": {"单一": "单一：不复杂、没有变化，与“每天上班、回家”一致，句意成立。", "精彩": "语义：“精彩”指生动有趣，与“每天上班、回家”的重复生活矛盾。", "有趣": "语义：“有趣”指让人愉快，与“每天上班、回家”的单调生活矛盾。", "丰富": "搭配：“丰富”多指内容、资源，用来形容这种重复的生活不合适。"}, "sentence_index": 0, "correct_answer": "单一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班的同学很单一，有来自各地的人。", "explanation": "这里应该用〈多样〉。“单一”指只有一种、不复杂，与“来自各地的人”矛盾，人员来源多要用“多样”。"}, {"text": "这道题很单一，我花了一个小时才做完。", "explanation": "这里应该用〈复杂〉。题目难、要花很长时间，要用“复杂”，“单一”指不复杂，与句意矛盾。"}, {"text": "这个孩子的心思很单一，想法总是很多。", "explanation": "这里应该用〈丰富〉。想法多、内容多要用“丰富”，“单一”指只有一种、不复杂，与“想法总是很多”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "单一", "is_correct": true, "explanation": "单一：不复杂、没有变化，与“每天做同样的事”一致，句意成立。"}, {"text": "多变", "is_correct": false, "explanation": "语义：“多变”指变化很多，与“每天做同样的事”矛盾。"}, {"text": "有意思", "is_correct": false, "explanation": "语义：“有意思”指有趣味，与“每天做同样的事”的重复工作矛盾。"}, {"text": "新颖", "is_correct": false, "explanation": "搭配：“新颖”多指想法、样式，形容工作内容不合适，且与“同样的事”矛盾。"}], "explanations": {"单一": "单一：不复杂、没有变化，与“每天做同样的事”一致，句意成立。", "多变": "语义：“多变”指变化很多，与“每天做同样的事”矛盾。", "有意思": "语义：“有意思”指有趣味，与“每天做同样的事”的重复工作矛盾。", "新颖": "搭配：“新颖”多指想法、样式，形容工作内容不合适，且与“同样的事”矛盾。"}, "sentence_index": 6, "correct_answer": "单一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店卖的东西很单一，货架上有上百种商品。", "explanation": "这里应该用〈繁多〉。“单一”指只有一种，与“上百种商品”矛盾，商品种类多要用“繁多”。"}, {"text": "这件事很单一，有很多种处理方法。", "explanation": "这里应该用〈复杂〉。“单一”指不复杂，与“有很多种处理方法”矛盾，事情头绪多要用“复杂”。"}, {"text": "老人的心思很单一，每天要操心很多事。", "explanation": "这里应该用〈繁杂〉。心思或事务头绪多要用“繁杂”，“单一”指不复杂，与“每天要操心很多事”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的生活被单一，每天都一样。", "corrected_sentence": "我的生活很单一，每天都一样。", "error_description": "句式错误：形容词“单一”不能用于“被”字句，“被”应改为表示程度的“很”，说“很单一”，不能说“被单一”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个游戏的玩法太单一的，玩久了没意思。", "corrected_sentence": "这个游戏的玩法太单一了，玩久了没意思。", "error_description": "语气助词错用：“太……了”结构中句末要用“了”，应说“太单一了”，不能用“的”说“太单一的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd768154b-ba5f-44c0-af68-86231ddf75eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
