INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93763, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "外界是一个地方的外面。", "primary_collocate": null, "pronunciation": "wài jiè", "ipa": "wai˥˩ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "山里的人很少和外界联系。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间很安静，听不到外界的声音。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小村子离外界很远。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他整天待在家里，从不和外界来往。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户一关，外界的灰尘就进不来了。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨的时候，这个村子和外界断了联系。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人很少出门，对外界的变化不太了解。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的病人需要和外界保持联系。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岛上的孩子通过一条小船和外界相连。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我戴上耳机，不听外界的吵闹。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：一个地方、一个空间之外的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd05d25bf-15fb-4699-a34e-f76e1fe1de8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93763, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外界", "is_correct": true, "explanation": "空格处应填“外界”，与“联系”搭配，表示山里的人与外面的世界少有往来，是本句的原词。"}, {"text": "内部", "is_correct": false, "explanation": "语义：“内部”与“联系”组合后，与“很少和……联系”的语境无法对应，句意不通。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“联系”不能与“厨房”这类场所搭配，句子不自然。"}, {"text": "墙壁", "is_correct": false, "explanation": "搭配：“和墙壁联系”不符合常用搭配，句意荒谬。"}], "explanations": {"外界": "空格处应填“外界”，与“联系”搭配，表示山里的人与外面的世界少有往来，是本句的原词。", "内部": "语义：“内部”与“联系”组合后，与“很少和……联系”的语境无法对应，句意不通。", "厨房": "搭配：“联系”不能与“厨房”这类场所搭配，句子不自然。", "墙壁": "搭配：“和墙壁联系”不符合常用搭配，句意荒谬。"}, "sentence_index": 0, "correct_answer": "外界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个鸡蛋的外界很硬。", "explanation": "这里应该用“外壳”。外界指周围的环境，不能用来指东西的外层。"}, {"text": "他从窗口看见了一座外界。", "explanation": "这里“外界”被误当成了“建筑、山、桥”之类的具体事物，所以误用了量词“座”。外界是抽象的环境，不能用“座”计量。"}, {"text": "他的外界很严重，需要包扎。", "explanation": "这里应该用“外伤”。外界指周围的环境，不能用来指身体上的伤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93763, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外界", "is_correct": true, "explanation": "空格处应填“外界”，表示老人对外面环境的变化不了解，是本句的原词。"}, {"text": "脚", "is_correct": false, "explanation": "搭配：“脚的变化”与“对……的变化不太了解”的常用搭配不符，句意别扭。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房与“很少出门”的语境无关，句意不通。"}, {"text": "天花板", "is_correct": false, "explanation": "语义：天花板不是可以“了解变化”的对象，与句意冲突。"}], "explanations": {"外界": "空格处应填“外界”，表示老人对外面环境的变化不了解，是本句的原词。", "脚": "搭配：“脚的变化”与“对……的变化不太了解”的常用搭配不符，句意别扭。", "厨房": "语义：厨房与“很少出门”的语境无关，句意不通。", "天花板": "语义：天花板不是可以“了解变化”的对象，与句意冲突。"}, "sentence_index": 6, "correct_answer": "外界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的外界很美。", "explanation": "这里应该用“外貌”。外界指环境，不能用来形容人的相貌。"}, {"text": "他很小就去外界留学了。", "explanation": "这里应该用“外国”。外界指环境，不能指国家。"}, {"text": "我回到外界休息了。", "explanation": "这里应该用“家”。外界不能作为人回去休息的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93763, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很快适应了外界地生活。", "corrected_sentence": "他很快适应了外界的生活。", "error_description": "错误：“外界”后修饰名词应用“的”，这里误用了“地”。“地”用于修饰动词，正确说法是“外界的生活”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93763, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想了解那座外界的一切。", "corrected_sentence": "他想了解外界的一切。", "error_description": "错误：在“外界”前加了量词“那座”。外界是抽象概念，不能用量词修饰，应直接说“外界的一切”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
