INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93764, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某个范围以外的地方或环境；外部。", "primary_collocate": null, "pronunciation": "wài jiè", "ipa": "wai˥˩ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "外界的温度会影响植物的生长。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外界对这件事有很多看法。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司不愿意向外界公开消息。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物会对外界的变化做出反应。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要太在意外界的评价。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们通过网络了解外界。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，身体要适应外界的冷空气。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的新计划还没有对外界说明。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外界都在猜他会不会参加比赛。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验要避免外界的光线进入。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：某个范围、群体或系统之外的环境与人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd05d25bf-15fb-4699-a34e-f76e1fe1de8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93764, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外界", "is_correct": true, "explanation": "空格处应填“外界”，表示某个范围之外的环境影响温度，是本句的原词。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔与植物的生长没有关系，“钢笔的温度会影响植物的生长”句意不通。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“名字的温度”不是常用搭配，句子不自然。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不具有温度属性，与“影响植物的生长”的语境不符。"}], "explanations": {"外界": "空格处应填“外界”，表示某个范围之外的环境影响温度，是本句的原词。", "钢笔": "语义：钢笔与植物的生长没有关系，“钢笔的温度会影响植物的生长”句意不通。", "名字": "搭配：“名字的温度”不是常用搭配，句子不自然。", "声音": "语义：声音不具有温度属性，与“影响植物的生长”的语境不符。"}, "sentence_index": 0, "correct_answer": "外界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的外界很英俊。", "explanation": "这里应该用“外表”。外界指周围的环境，不能用来形容人的外在形象。"}, {"text": "外界一边吃饭，一边看书。", "explanation": "这里“外界”被误当成了“人、别人”的意思。外界是环境，不能做吃饭、看书的动作，应该用“他”“我”这样的人作主语。"}, {"text": "这里有一条外界。", "explanation": "这里“外界”被误当成了“河流、道路”之类的具体事物，所以误用了量词“条”。外界是抽象的环境，不能用“条”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外界", "is_correct": true, "explanation": "空格处应填“外界”，表示冬天身体要适应外面的冷空气，是本句的原词。"}, {"text": "工作", "is_correct": false, "explanation": "语义：“工作的冷空气”没有意义，与句意冲突。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不能产生冷空气，与“冬天身体要适应”的语境不符。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“适应书包的冷空气”不是常用搭配，句子不自然。"}], "explanations": {"外界": "空格处应填“外界”，表示冬天身体要适应外面的冷空气，是本句的原词。", "工作": "语义：“工作的冷空气”没有意义，与句意冲突。", "课本": "语义：课本不能产生冷空气，与“冬天身体要适应”的语境不符。", "书包": "搭配：“适应书包的冷空气”不是常用搭配，句子不自然。"}, "sentence_index": 6, "correct_answer": "外界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在外界做饭，我在旁边帮忙。", "explanation": "这里应该用“厨房”。外界指某个范围以外的环境，不能用来指做饭的具体房间。"}, {"text": "这个小组的外界很团结。", "explanation": "这里应该用“成员”。外界指环境，不能指组成小组的人。"}, {"text": "这本书的外界很漂亮。", "explanation": "这里应该用“封面”。外界指周围的环境，不能用来指书的外层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座小城很少受到一个外界的影响。", "corrected_sentence": "这座小城很少受到外界的影响。", "error_description": "错误：在“外界”前加了数量短语“一个”。外界是抽象概念，不能被数量词修饰，应直接说“外界的影响”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "外界地消息传得很快。", "corrected_sentence": "外界的消息传得很快。", "error_description": "错误：外界与中心语“消息”之间的定语标记“的”写成了“地”。“地”用于状语后，修饰名词应用“的”，应说“外界的消息”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93765, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小声", "is_correct": true, "explanation": "正确答案。“大声”与“小声”是一对反义词，都描述声音的大小。"}, {"text": "慢慢", "is_correct": false, "explanation": "“慢慢”描述速度，与声音大小无关，不是反义词。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”描述态度，与声音大小无关，不是反义词。"}, {"text": "赶紧", "is_correct": false, "explanation": "“赶紧”描述速度或催促，与声音大小无关，不是反义词。"}], "correct_answer": "小声", "explanations": {"小声": "正确答案。“大声”与“小声”是一对反义词，都描述声音的大小。", "慢慢": "“慢慢”描述速度，与声音大小无关，不是反义词。", "认真": "“认真”描述态度，与声音大小无关，不是反义词。", "赶紧": "“赶紧”描述速度或催促，与声音大小无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93765, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小声", "is_correct": true, "explanation": "正确答案。“大声”与“小声”是一对反义词，都描述声音的大小。"}, {"text": "偷偷", "is_correct": false, "explanation": "“偷偷”指不让人察觉，与声音大小无关，不是反义词。"}, {"text": "仔细", "is_correct": false, "explanation": "“仔细”描述态度，与声音大小无关，不是反义词。"}, {"text": "连忙", "is_correct": false, "explanation": "“连忙”描述速度，与声音大小无关，不是反义词。"}], "correct_answer": "小声", "explanations": {"小声": "正确答案。“大声”与“小声”是一对反义词，都描述声音的大小。", "偷偷": "“偷偷”指不让人察觉，与声音大小无关，不是反义词。", "仔细": "“仔细”描述态度，与声音大小无关，不是反义词。", "连忙": "“连忙”描述速度，与声音大小无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93765, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "大声是声音很响，离得远也能听到。", "primary_collocate": null, "pronunciation": "dà shēng", "ipa": "ta˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "他站在山上大声喊我的名字。", "target_word": "大声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你大声一点儿，后面听不到。", "target_word": "大声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们大声读课文。", "target_word": "大声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她大声叫着，想让远处的人听见。", "target_word": "大声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室很大，请大声回答问题。", "target_word": "大声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在河对岸大声说话，我听得很清楚。", "target_word": "大声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明大声喊：“我在这儿！”", "target_word": "大声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球场上太吵了，你要大声说。", "target_word": "大声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在楼下大声叫妈妈。", "target_word": "大声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他大声地对远处的朋友打招呼。", "target_word": "大声", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大声地", "label": "状语形式"}], "register": "口语", "sense_fingerprint": "声音大到远处的人也能听见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c42c51fa-068b-42d8-870b-2b763e4e5f46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93765, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大声", "is_correct": true, "explanation": "正确答案。“大声”指声音很响，远处也能听到。"}, {"text": "大胜", "is_correct": false, "explanation": "声调不同：shèng（第四声）与 shēng（第一声），意思是取得很大的胜利。"}, {"text": "大省", "is_correct": false, "explanation": "声调不同：shěng（第三声）与 shēng（第一声），意思是面积大的省份。"}, {"text": "大绳", "is_correct": false, "explanation": "声调不同：shéng（第二声）与 shēng（第一声），意思是粗绳子。"}], "explanations": {"大声": "正确答案。“大声”指声音很响，远处也能听到。", "大胜": "声调不同：shèng（第四声）与 shēng（第一声），意思是取得很大的胜利。", "大省": "声调不同：shěng（第三声）与 shēng（第一声），意思是面积大的省份。", "大绳": "声调不同：shéng（第二声）与 shēng（第一声），意思是粗绳子。"}, "sentence_index": null, "correct_answer": "大声"}, "level_3": {"options": [{"text": "大声", "is_correct": true, "explanation": "“大声”修饰“喊”，说明声音很响，远处也能听到。"}, {"text": "齐声", "is_correct": false, "explanation": "搭配：“齐声”需要多人一起发声，句中只有“他”一个人。"}, {"text": "默默", "is_correct": false, "explanation": "语义：“默默”指不出声，与“喊”矛盾。"}, {"text": "无声", "is_correct": false, "explanation": "语义：“无声”指没有声音，与“喊”矛盾。"}], "explanations": {"大声": "“大声”修饰“喊”，说明声音很响，远处也能听到。", "齐声": "搭配：“齐声”需要多人一起发声，句中只有“他”一个人。", "默默": "语义：“默默”指不出声，与“喊”矛盾。", "无声": "语义：“无声”指没有声音，与“喊”矛盾。"}, "sentence_index": 0, "correct_answer": "大声"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她大声地想着心事。", "explanation": "这里应该用〈默默〉。“大声”说的是发出很大的声音，“想”不发声，不能用“大声”修饰。"}, {"text": "他大声地坐在角落里。", "explanation": "这里应该用〈安静〉。“大声”修饰发出声音的动作，“坐”不发声，这里不能用“大声”。"}, {"text": "这个小孩大声地长高了。", "explanation": "“大声”只修饰发出声音的动作，“长高”不发声，这里用“大声”是错误的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大声", "is_correct": true, "explanation": "“大声”修饰“喊”，表示声音响亮，与“我在这儿！”的呼喊相符。"}, {"text": "暗暗", "is_correct": false, "explanation": "语义：“暗暗”指不声张、不被人察觉，与公开的呼喊矛盾。"}, {"text": "默读", "is_correct": false, "explanation": "搭配：“默读”指不出声地看，不能用来修饰“喊”。"}, {"text": "跳跃", "is_correct": false, "explanation": "语义：“跳跃”是身体动作，不能修饰“喊”，与句意不合。"}], "explanations": {"大声": "“大声”修饰“喊”，表示声音响亮，与“我在这儿！”的呼喊相符。", "暗暗": "语义：“暗暗”指不声张、不被人察觉，与公开的呼喊矛盾。", "默读": "搭配：“默读”指不出声地看，不能用来修饰“喊”。", "跳跃": "语义：“跳跃”是身体动作，不能修饰“喊”，与句意不合。"}, "sentence_index": 6, "correct_answer": "大声"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子大声地睡着了。", "explanation": "这里应该用〈悄悄〉。“大声”修饰发出声音的动作，“睡着”不发声，这里不能用“大声”。"}, {"text": "她大声地看着窗外。", "explanation": "这里应该用〈呆呆〉。“大声”需要发出声音的动作，“看”不发声，这里不能用“大声”。"}, {"text": "这盆花大声地开了。", "explanation": "“大声”只修饰发出声音的动作，花开不发声，这里用“大声”是错误的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在操场上大声了喊我的名字。", "corrected_sentence": "他在操场上大声喊我的名字。", "error_description": "“了”不能放在状语“大声”和动词“喊”之间。“大声”修饰动作，应说“大声喊”，去掉“了”，说“他在操场上大声喊我的名字。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈叫很大声，全楼都听见了。", "corrected_sentence": "妈妈叫得很大声，全楼都听见了。", "error_description": "“叫”后面要用“得”引出程度补语，应说“叫得很大声”；漏掉“得”，说“叫很大声”，是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93766, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小声", "is_correct": true, "explanation": "正确答案。“大声”与“小声”是一对反义词，都描述声音的大小。"}, {"text": "慢慢", "is_correct": false, "explanation": "“慢慢”描述速度，与声音大小无关，不是反义词。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”描述态度，与声音大小无关，不是反义词。"}, {"text": "赶紧", "is_correct": false, "explanation": "“赶紧”描述速度或催促，与声音大小无关，不是反义词。"}], "correct_answer": "小声", "explanations": {"小声": "正确答案。“大声”与“小声”是一对反义词，都描述声音的大小。", "慢慢": "“慢慢”描述速度，与声音大小无关，不是反义词。", "认真": "“认真”描述态度，与声音大小无关，不是反义词。", "赶紧": "“赶紧”描述速度或催促，与声音大小无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93766, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小声", "is_correct": true, "explanation": "正确答案。“大声”与“小声”是一对反义词，都描述声音的大小。"}, {"text": "偷偷", "is_correct": false, "explanation": "“偷偷”指不让人察觉，与声音大小无关，不是反义词。"}, {"text": "仔细", "is_correct": false, "explanation": "“仔细”描述态度，与声音大小无关，不是反义词。"}, {"text": "连忙", "is_correct": false, "explanation": "“连忙”描述速度，与声音大小无关，不是反义词。"}], "correct_answer": "小声", "explanations": {"小声": "正确答案。“大声”与“小声”是一对反义词，都描述声音的大小。", "偷偷": "“偷偷”指不让人察觉，与声音大小无关，不是反义词。", "仔细": "“仔细”描述态度，与声音大小无关，不是反义词。", "连忙": "“连忙”描述速度，与声音大小无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93766, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "声音响亮。", "primary_collocate": null, "pronunciation": "dà shēng", "ipa": "ta˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "孩子们大声唱起了歌。", "target_word": "大声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他大声笑了起来。", "target_word": "大声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李大声读着今天的新闻。", "target_word": "大声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师大声说：“请坐好。”", "target_word": "大声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她大声地念出了自己的名字。", "target_word": "大声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们大声回答：“好！”", "target_word": "大声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他高兴得大声叫了起来。", "target_word": "大声", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "婴儿在房间里大声哭，妈妈赶紧去抱她。", "target_word": "大声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时大家大声给运动员加油。", "target_word": "大声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们大声说出自己的想法。", "target_word": "大声", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大声地", "label": "状语形式"}], "register": "口语", "sense_fingerprint": "发出的声音响亮，不压低声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c42c51fa-068b-42d8-870b-2b763e4e5f46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93766, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大声", "is_correct": true, "explanation": "正确答案。“大声”指声音响亮，不压低声音。"}, {"text": "大胜", "is_correct": false, "explanation": "声调不同：shèng（第四声）与 shēng（第一声），意思是取得很大的胜利。"}, {"text": "大省", "is_correct": false, "explanation": "声调不同：shěng（第三声）与 shēng（第一声），意思是面积大的省份。"}, {"text": "大绳", "is_correct": false, "explanation": "声调不同：shéng（第二声）与 shēng（第一声），意思是粗绳子。"}], "explanations": {"大声": "正确答案。“大声”指声音响亮，不压低声音。", "大胜": "声调不同：shèng（第四声）与 shēng（第一声），意思是取得很大的胜利。", "大省": "声调不同：shěng（第三声）与 shēng（第一声），意思是面积大的省份。", "大绳": "声调不同：shéng（第二声）与 shēng（第一声），意思是粗绳子。"}, "sentence_index": null, "correct_answer": "大声"}, "level_3": {"options": [{"text": "大声", "is_correct": true, "explanation": "“大声”修饰“唱”，表示声音响亮，与“唱起了歌”相符。"}, {"text": "默默", "is_correct": false, "explanation": "语义：“默默”指不出声，与“唱歌”要发出声音矛盾。"}, {"text": "静默", "is_correct": false, "explanation": "语义：“静默”指不作声，与“唱歌”矛盾。"}, {"text": "无声", "is_correct": false, "explanation": "搭配：“唱歌”必须发出声音，与“无声”搭配不当。"}], "explanations": {"大声": "“大声”修饰“唱”，表示声音响亮，与“唱起了歌”相符。", "默默": "语义：“默默”指不出声，与“唱歌”要发出声音矛盾。", "静默": "语义：“静默”指不作声，与“唱歌”矛盾。", "无声": "搭配：“唱歌”必须发出声音，与“无声”搭配不当。"}, "sentence_index": 0, "correct_answer": "大声"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子大声地摇着头。", "explanation": "这里应该用〈默默〉。“大声”修饰发出声音的动作，摇头不发声，这里不能用“大声”。"}, {"text": "她大声地点着头。", "explanation": "这里应该用〈轻轻〉。“大声”指声音响亮，点头不发声，这里不能用“大声”。"}, {"text": "他大声地思念远方的家人。", "explanation": "“思念”是心里的感情，不发声，这里不能用“大声”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大声", "is_correct": true, "explanation": "“大声”修饰“叫”，表示声音响亮，与“高兴得叫了起来”相符。"}, {"text": "悄悄", "is_correct": false, "explanation": "语义：“悄悄”指不让人察觉，与“叫”的声音响亮矛盾。"}, {"text": "暗暗", "is_correct": false, "explanation": "语义：“暗暗”指暗中、不声张，与“高兴得叫起来”矛盾。"}, {"text": "齐声", "is_correct": false, "explanation": "搭配：“齐声”需要多人一起发声，句中只有“他”一个人。"}], "explanations": {"大声": "“大声”修饰“叫”，表示声音响亮，与“高兴得叫了起来”相符。", "悄悄": "语义：“悄悄”指不让人察觉，与“叫”的声音响亮矛盾。", "暗暗": "语义：“暗暗”指暗中、不声张，与“高兴得叫起来”矛盾。", "齐声": "搭配：“齐声”需要多人一起发声，句中只有“他”一个人。"}, "sentence_index": 6, "correct_answer": "大声"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们大声地思考问题。", "explanation": "这里应该用〈认真〉。“思考”不发声，“大声”修饰的动作必须发出声音，这里用“大声”是错误的。"}, {"text": "这朵花大声地开了。", "explanation": "这里应该用〈慢慢〉。“大声”指声音响亮，花开不发声，这里不能用“大声”。"}, {"text": "她大声地看着我。", "explanation": "“看”不发声，“大声”只能修饰发出声音的动作，这里用“大声”是错误的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她哭很大声，邻居都听见了。", "corrected_sentence": "她哭得很大声，邻居都听见了。", "error_description": "“哭”后面要用“得”引出程度补语，应说“哭得很大声”；漏掉“得”，说“哭很大声”，是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们大声了争论着这个问题。", "corrected_sentence": "同学们大声争论着这个问题。", "error_description": "“了”不能放在状语“大声”和动词“争论”之间。“大声”修饰动作，应说“大声争论”，去掉“了”，说“同学们大声争论着这个问题。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
