INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93767, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "客人是来家里玩的人，不是家里的人。", "primary_collocate": null, "pronunciation": "kè rén", "ipa": "kʰɤ˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "家里来客人了，妈妈在做饭。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人走了以后，我帮妈妈洗碗。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶给客人倒了一杯茶。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家有客人，今晚不能出去玩。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是家人，是我们家的客人。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人来的时候，我们都会拿出水果。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末有客人来家里吃饭。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗看见客人，高兴地跳了起来。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请客人坐沙发上，我去拿饮料。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人在我家住了两天。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位客人", "label": "量词"}, {"form": "一批客人", "label": "量词"}], "register": "中性", "sense_fingerprint": "客人：来家里做客的人，不是家人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f254cf03-f386-45b9-9358-a04ac5249126') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93767, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客人", "is_correct": true, "explanation": "正确：「家里来客人了」指来家里做客的人，与「来」的外来语境相合。"}, {"text": "家人", "is_correct": false, "explanation": "语义：「家人」指自家人，与「家里来……了」所说的外来人的语境矛盾。"}, {"text": "主人", "is_correct": false, "explanation": "语义：家里的主人不会是「来」到家里的人，与语境矛盾。"}, {"text": "主意", "is_correct": false, "explanation": "语义：「主意」是想法，不是人，不能说「家里来主意了」。"}], "explanations": {"客人": "正确：「家里来客人了」指来家里做客的人，与「来」的外来语境相合。", "家人": "语义：「家人」指自家人，与「家里来……了」所说的外来人的语境矛盾。", "主人": "语义：家里的主人不会是「来」到家里的人，与语境矛盾。", "主意": "语义：「主意」是想法，不是人，不能说「家里来主意了」。"}, "sentence_index": 0, "correct_answer": "客人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家的客人是爸爸。", "explanation": "这里应该用〈家人〉。「家人」指自家人，爸爸是自家人，不能称为客人。"}, {"text": "我们家养的小猫是我们家的客人。", "explanation": "这里应该用〈宠物〉。「客人」指来家里做客的人，自家养的小猫是宠物，不是客人。"}, {"text": "我们家的客人是我的奶奶。", "explanation": "这里应该用〈家人〉。「家人」指自家人，奶奶是自家人，不能称为客人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93767, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客人", "is_correct": true, "explanation": "正确：「周末有客人来家里吃饭」指受邀来访的人，与语境相合。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：「陌生人」不是受邀来吃饭的人，与「来家里吃饭」的邀约语境不符。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：「小偷」来家里不是为了吃饭，与「周末有……来家里吃饭」的语境矛盾。"}, {"text": "推销员", "is_correct": false, "explanation": "语义：「推销员」是来推销商品的，不是受邀来家里吃饭的客人。"}], "explanations": {"客人": "正确：「周末有客人来家里吃饭」指受邀来访的人，与语境相合。", "陌生人": "语义：「陌生人」不是受邀来吃饭的人，与「来家里吃饭」的邀约语境不符。", "小偷": "语义：「小偷」来家里不是为了吃饭，与「周末有……来家里吃饭」的语境矛盾。", "推销员": "语义：「推销员」是来推销商品的，不是受邀来家里吃饭的客人。"}, "sentence_index": 6, "correct_answer": "客人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子是我们家的客人。", "explanation": "这里应该用〈家具〉。「客人」指人，不能指家具；桌子不能称为客人。"}, {"text": "我家的客人是一台冰箱。", "explanation": "这里应该用〈家电〉。「客人」指人，不能指冰箱这类家电。"}, {"text": "客人在学校门口卖早饭。", "explanation": "这里应该用〈小贩〉。「小贩」在路边做生意，「客人」是来访的人，不能指卖早饭的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93767, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家来了一只客人。", "corrected_sentence": "我们家来了一位客人。", "error_description": "错在「一只客人」。「客人」指人，量词应用「位」，「只」多用于动物，应改为「一位客人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93767, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末有两客人来吃饭。", "corrected_sentence": "周末有两位客人来吃饭。", "error_description": "错在「两客人」。「客人」指人，数词后要加量词，应补为「两位客人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
