INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93768, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "受邀请或来访的人。", "primary_collocate": null, "pronunciation": "kè rén", "ipa": "kʰɤ˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "婚礼上，客人们都送了红包。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他邀请了二十位客人来参加生日会。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来参观的客人已经到门口了。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理在会议室里接待外地来的客人。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今天有重要的客人来访。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人们到齐了，宴会马上开始。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位客人是从北京来的。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主人请客人坐在最好的位置。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要热情地招待来访的客人。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上，客人们唱了歌，也跳了舞。", "target_word": "客人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位客人", "label": "量词"}, {"form": "一批客人", "label": "量词"}], "register": "中性", "sense_fingerprint": "客人：受邀请参加活动或来访的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f254cf03-f386-45b9-9358-a04ac5249126') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93768, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客人", "is_correct": true, "explanation": "正确：婚礼上送红包的是受邀前来的宾客，「客人」指受邀来参加活动的人。"}, {"text": "主人", "is_correct": false, "explanation": "语义：婚礼的主人是接受祝福的一方，不是送红包的人，与「都送了红包」的语境矛盾。"}, {"text": "服务员", "is_correct": false, "explanation": "语义：服务员在婚礼上不送红包，与「都送了红包」的语境不符。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：「乘客」多指乘坐交通工具的人，不能用于婚礼场合。"}], "explanations": {"客人": "正确：婚礼上送红包的是受邀前来的宾客，「客人」指受邀来参加活动的人。", "主人": "语义：婚礼的主人是接受祝福的一方，不是送红包的人，与「都送了红包」的语境矛盾。", "服务员": "语义：服务员在婚礼上不送红包，与「都送了红包」的语境不符。", "乘客": "搭配：「乘客」多指乘坐交通工具的人，不能用于婚礼场合。"}, "sentence_index": 0, "correct_answer": "客人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医院里的客人都在给病人看病。", "explanation": "这里应该用〈医生〉。「客人」指来访的人，给病人看病的是医生，不能称为客人。"}, {"text": "草地上的客人在吃草。", "explanation": "这里应该用〈羊〉。「客人」指人，不能指吃草的动物；应换成〈羊〉。"}, {"text": "婚礼上的客人就是新郎和新娘。", "explanation": "这里应该用〈主人〉。新郎新娘是婚礼的主人，不是受邀来参加的客人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客人", "is_correct": true, "explanation": "正确：「这位客人」指受邀或来访的人，与「是从北京来的」相合。"}, {"text": "本地人", "is_correct": false, "explanation": "搭配：「本地人」指本地居民，与「是从北京来的」的来源不能同时成立。"}, {"text": "村民", "is_correct": false, "explanation": "语义：「村民」指本村居民，与「是从北京来的」所指的外地来源矛盾。"}, {"text": "土著", "is_correct": false, "explanation": "语义：「土著」指世代居住在当地的原住民，与「是从北京来的」矛盾。"}], "explanations": {"客人": "正确：「这位客人」指受邀或来访的人，与「是从北京来的」相合。", "本地人": "搭配：「本地人」指本地居民，与「是从北京来的」的来源不能同时成立。", "村民": "语义：「村民」指本村居民，与「是从北京来的」所指的外地来源矛盾。", "土著": "语义：「土著」指世代居住在当地的原住民，与「是从北京来的」矛盾。"}, "sentence_index": 6, "correct_answer": "客人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饭店后厨的客人正在切菜。", "explanation": "这里应该用〈厨师〉。「厨师」在后厨工作，「客人」是来访的人，不能指后厨切菜的人。"}, {"text": "客人们在训练场上训练。", "explanation": "这里应该用〈战士〉。「战士」指军人，在训练场训练的人不能称客人。"}, {"text": "公司的客人都很努力。", "explanation": "这里应该用〈员工〉。「员工」指在公司工作的人，公司里努力工作的人不能称客人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只客人喝了一杯茶。", "corrected_sentence": "这位客人喝了一杯茶。", "error_description": "错在「这只客人」。「客人」指人，量词应用「位」，「只」多用于动物，应改为「这位客人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他请了三客人来吃饭。", "corrected_sentence": "他请了三位客人来吃饭。", "error_description": "错在「三客人」。「客人」指人，数词后要加量词，应补为「三位客人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
