INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93769, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "巴士是很多人一起坐的大汽车。", "primary_collocate": null, "pronunciation": "bā shì", "ipa": "pa˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "我们坐巴士去机场。", "target_word": "巴士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巴士上有很多人，我没有座位。", "target_word": "巴士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆巴士会开到火车站。", "target_word": "巴士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们一起坐巴士去春游。", "target_word": "巴士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巴士开得很慢，我们迟到了。", "target_word": "巴士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在车站等了二十分钟巴士。", "target_word": "巴士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游巴士停在酒店门口。", "target_word": "巴士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在巴士上唱着歌。", "target_word": "巴士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了巴士，我们走路去公园。", "target_word": "巴士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最后一班巴士已经开走了。", "target_word": "巴士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "旅游巴士", "label": "复合"}, {"form": "机场巴士", "label": "复合"}], "register": "中性", "sense_fingerprint": "很多人一起乘坐的大汽车，常用于旅游、接送", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01308c1-157a-474f-8335-9b2ec1714ab6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93769, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "巴士", "is_correct": true, "explanation": "正确。巴士是很多人一起坐的大汽车，读作 bā shì。"}, {"text": "怕事", "is_correct": false, "explanation": "pà shì（第四声）与 bā shì（第一声）第一音节声调不同，意思是胆小、怕惹麻烦，与巴士不同。"}, {"text": "八十", "is_correct": false, "explanation": "bā shí（第二声）与 bā shì 第二音节声调不同（第二声与第四声），意思是数字八十。"}, {"text": "罢市", "is_correct": false, "explanation": "bà shì（第四声）与 bā shì 第一音节声调不同，意思是商店集体停业，与巴士不同。"}], "explanations": {"巴士": "正确。巴士是很多人一起坐的大汽车，读作 bā shì。", "怕事": "pà shì（第四声）与 bā shì（第一声）第一音节声调不同，意思是胆小、怕惹麻烦，与巴士不同。", "八十": "bā shí（第二声）与 bā shì 第二音节声调不同（第二声与第四声），意思是数字八十。", "罢市": "bà shì（第四声）与 bā shì 第一音节声调不同，意思是商店集体停业，与巴士不同。"}, "sentence_index": null, "correct_answer": "巴士"}, "level_3": {"options": [{"text": "巴士", "is_correct": true, "explanation": "正确。巴士是很多人一起坐的大汽车，可以坐去机场。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是可以乘坐的东西，与“坐”的意思不合。"}, {"text": "书包", "is_correct": false, "explanation": "配价：“坐”的宾语要是交通工具或座位，书包不能被坐。"}, {"text": "火车站", "is_correct": false, "explanation": "语义：火车站是地点，不是可以乘坐的交通工具，“坐火车站”不成立。"}], "explanations": {"巴士": "正确。巴士是很多人一起坐的大汽车，可以坐去机场。", "窗户": "语义：窗户不是可以乘坐的东西，与“坐”的意思不合。", "书包": "配价：“坐”的宾语要是交通工具或座位，书包不能被坐。", "火车站": "语义：火车站是地点，不是可以乘坐的交通工具，“坐火车站”不成立。"}, "sentence_index": 0, "correct_answer": "巴士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "巴士在天上飞了两个小时，乘客们很开心。", "explanation": "这里应该用〈飞机〉。巴士是在道路上行驶的车，不会在天上飞，在天上飞的是飞机。"}, {"text": "巴士在河上慢慢航行，乘客们在甲板上看风景。", "explanation": "这里应该用〈轮船〉。巴士只在陆地的道路上行驶，不能在河上航行，在河上航行、有甲板的是轮船。"}, {"text": "巴士在楼里上下运行，很快就到了楼上。", "explanation": "这里应该用〈电梯〉。巴士在道路上行驶，不能在楼里上下运行，在楼里上下运行的是电梯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93769, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "巴士", "is_correct": true, "explanation": "正确。巴士是很多人一起坐的大汽车，读作 bā shì。"}, {"text": "白事", "is_correct": false, "explanation": "bái shì（第二声）与 bā shì 第一音节声调不同，意思是丧事，属于口语，与巴士不同。"}, {"text": "罢市", "is_correct": false, "explanation": "bà shì（第四声）与 bā shì 第一音节声调不同，意思是商店集体停业，与巴士不同。"}, {"text": "把式", "is_correct": false, "explanation": "bǎ shi 第一音节声调不同，第二音节读轻声，意思是本领、手艺，与巴士不同。"}], "explanations": {"巴士": "正确。巴士是很多人一起坐的大汽车，读作 bā shì。", "白事": "bái shì（第二声）与 bā shì 第一音节声调不同，意思是丧事，属于口语，与巴士不同。", "罢市": "bà shì（第四声）与 bā shì 第一音节声调不同，意思是商店集体停业，与巴士不同。", "把式": "bǎ shi 第一音节声调不同，第二音节读轻声，意思是本领、手艺，与巴士不同。"}, "sentence_index": null, "correct_answer": "巴士"}, "level_3": {"options": [{"text": "巴士", "is_correct": true, "explanation": "正确。旅游巴士是专门用于出游的大型车，停在酒店门口很合理。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能停在门口，与“旅游”的语境不符。"}, {"text": "书架", "is_correct": false, "explanation": "搭配：“旅游”修饰的是车、船等交通工具，不说“旅游书架”。"}, {"text": "鼠标", "is_correct": false, "explanation": "语义：鼠标是电脑配件，不能停在酒店门口。"}], "explanations": {"巴士": "正确。旅游巴士是专门用于出游的大型车，停在酒店门口很合理。", "冰箱": "语义：冰箱是家用电器，不能停在门口，与“旅游”的语境不符。", "书架": "搭配：“旅游”修饰的是车、船等交通工具，不说“旅游书架”。", "鼠标": "语义：鼠标是电脑配件，不能停在酒店门口。"}, "sentence_index": 6, "correct_answer": "巴士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "巴士在铁轨上飞快地前进，我们很快就到了。", "explanation": "这里应该用〈火车〉。巴士是在道路上行驶的车，不会在铁轨上跑，在铁轨上跑的是火车。"}, {"text": "巴士在大海上航行了一整天，乘客们都晕船了。", "explanation": "这里应该用〈轮船〉。巴士只能在陆地的道路上行驶，不能在海上航行，在海上航行的是轮船。"}, {"text": "巴士在大楼里上上下下，我们一会儿就到了八楼。", "explanation": "这里应该用〈电梯〉。巴士在道路上行驶，不能在楼里上下运行，在楼里上下运行的是电梯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们坐了一只巴士去春游。", "corrected_sentence": "我们坐了一辆巴士去春游。", "error_description": "量词错误：“巴士”是车，量词应该用“辆”，不能用“只”（“只”多用于动物或成对的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个旅游巴士刚停在酒店门口。", "corrected_sentence": "一辆旅游巴士刚停在酒店门口。", "error_description": "量词错误：“巴士”是车，应该用“辆”；“个”是通用量词，不能用来数车辆。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
