INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93773, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "后期是一件事情快要结束的那一段时间。", "primary_collocate": null, "pronunciation": "hòu qī", "ipa": "xoʊ˥˩ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "学期后期，同学们都在复习。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏到了后期，大家越玩越累。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目后期，我们每天都加班。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风的后期，风雨渐渐小了。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的后期，场上特别紧张。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了装修后期，家里还很乱。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作后期，大家又检查了一遍。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议后期，经理说了几句话。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减肥的后期最难坚持。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视剧的后期，故事越来越快。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "後期", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一件事情快要结束的那段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33f1f67f-f906-4ff1-b27e-6aefc2c445ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93773, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "后期", "is_correct": true, "explanation": "正确答案。后期指一件事快要结束的那段时间，读作 hòu qī。"}, {"text": "后事", "is_correct": false, "explanation": "后事（shì）与后期（qī）声母不同（sh 与 q），意思是身后的事务。"}, {"text": "后市", "is_correct": false, "explanation": "后市（shì）与后期（qī）声母不同（sh 与 q），常指股市的走势。"}, {"text": "后区", "is_correct": false, "explanation": "后区（qū）与后期（qī）韵母不同（-ü 与 -i），指彩票中的后区号码。"}, {"text": "后起", "is_correct": false, "explanation": "后起（qǐ，第三声）与后期（qī，第一声）声调不同，意思是较晚出现的。"}], "explanations": {"后期": "正确答案。后期指一件事快要结束的那段时间，读作 hòu qī。", "后事": "后事（shì）与后期（qī）声母不同（sh 与 q），意思是身后的事务。", "后市": "后市（shì）与后期（qī）声母不同（sh 与 q），常指股市的走势。", "后区": "后区（qū）与后期（qī）韵母不同（-ü 与 -i），指彩票中的后区号码。", "后起": "后起（qǐ，第三声）与后期（qī，第一声）声调不同，意思是较晚出现的。"}, "sentence_index": null, "correct_answer": "后期"}, "level_3": {"options": [{"text": "后期", "is_correct": true, "explanation": "后期指事情快要结束的那段时间，「学期后期」指学期快结束的时段，符合「同学们都在复习」。"}, {"text": "凌晨", "is_correct": false, "explanation": "语义：凌晨是一天中的时段，不能指学期的阶段。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：午夜是一个时间点，不能说「学期午夜」。"}, {"text": "年头", "is_correct": false, "explanation": "搭配：「年头」指一年的开始，不能与「学期」组成表示阶段的说法。"}], "explanations": {"后期": "后期指事情快要结束的那段时间，「学期后期」指学期快结束的时段，符合「同学们都在复习」。", "凌晨": "语义：凌晨是一天中的时段，不能指学期的阶段。", "午夜": "语义：午夜是一个时间点，不能说「学期午夜」。", "年头": "搭配：「年头」指一年的开始，不能与「学期」组成表示阶段的说法。"}, "sentence_index": 0, "correct_answer": "后期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的后期很暗。", "explanation": "这里的「后期」只指时间阶段，不指房间的部位；屋子靠后的部分应说〈后部〉。"}, {"text": "这盘菜的后期很咸。", "explanation": "这里的「后期」不能指菜的某一部分；应说〈后半〉或〈后面〉。"}, {"text": "这碗面的后期很香。", "explanation": "这里的「后期」指时间阶段，不指面的部分；应说〈后半〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '068d6e78-5434-461a-91c4-d2f1ef1559a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93773, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "后期", "is_correct": true, "explanation": "正确答案。后期指一件事快要结束的那段时间，读作 hòu qī。"}, {"text": "后记", "is_correct": false, "explanation": "后记（jì）与后期（qī）第二音节声母不同（j 与 q），意思是书籍末尾的附记。"}, {"text": "后起", "is_correct": false, "explanation": "后起（qǐ，第三声）与后期（qī，第一声）声调不同，意思是较晚出现的。"}, {"text": "后世", "is_correct": false, "explanation": "后世（shì）与后期（qī）声母不同（sh 与 q），意思是子孙后代。"}, {"text": "后继", "is_correct": false, "explanation": "后继（jì）与后期（qī）第二音节声母不同（j 与 q），意思是接续的人。"}], "explanations": {"后期": "正确答案。后期指一件事快要结束的那段时间，读作 hòu qī。", "后记": "后记（jì）与后期（qī）第二音节声母不同（j 与 q），意思是书籍末尾的附记。", "后起": "后起（qǐ，第三声）与后期（qī，第一声）声调不同，意思是较晚出现的。", "后世": "后世（shì）与后期（qī）声母不同（sh 与 q），意思是子孙后代。", "后继": "后继（jì）与后期（qī）第二音节声母不同（j 与 q），意思是接续的人。"}, "sentence_index": null, "correct_answer": "后期"}, "level_3": {"options": [{"text": "后期", "is_correct": true, "explanation": "后期指事情快要结束的那段时间，「工作后期」符合「大家又检查了一遍」的语境。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭是一顿饭，不是工作的阶段。"}, {"text": "夜宵", "is_correct": false, "explanation": "语义：夜宵是一餐，与工作的阶段无关。"}, {"text": "年假", "is_correct": false, "explanation": "搭配：「年假」是一种假期，不能与「工作」组成表示阶段的说法。"}], "explanations": {"后期": "后期指事情快要结束的那段时间，「工作后期」符合「大家又检查了一遍」的语境。", "午饭": "语义：午饭是一顿饭，不是工作的阶段。", "夜宵": "语义：夜宵是一餐，与工作的阶段无关。", "年假": "搭配：「年假」是一种假期，不能与「工作」组成表示阶段的说法。"}, "sentence_index": 6, "correct_answer": "后期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我站在队伍的后期。", "explanation": "这里应该用〈后面〉。后期指时间阶段，表示位置要说后面或后头。"}, {"text": "这张床的后期很硬。", "explanation": "这里的「后期」指时间阶段，不指床的部位；床尾应说〈后部〉。"}, {"text": "这道菜做了后期，味道更好了。", "explanation": "这里的「后期」是影视、摄影的后期制作义项，菜肴不说做后期；本题要的是某一时期的后一阶段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '068d6e78-5434-461a-91c4-d2f1ef1559a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动到了一只后期，参加的人越来越少了。", "corrected_sentence": "这次活动到了后期，参加的人越来越少了。", "error_description": "量词错误：「后期」是时间阶段名词，前面不加量词，「一只」更不对（「只」用于动物等）。应去掉「一只」，说「到了后期」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '068d6e78-5434-461a-91c4-d2f1ef1559a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场演出到了很后期，观众渐渐散场了。", "corrected_sentence": "这场演出到了后期，观众渐渐散场了。", "error_description": "程度词错误：「后期」是时间阶段名词，不能用「很」修饰，应去掉「很」，说「到了后期」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '068d6e78-5434-461a-91c4-d2f1ef1559a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93774, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前期", "is_correct": true, "explanation": "前期指同一时期的前一阶段，与「后期」互为反义。"}, {"text": "春季", "is_correct": false, "explanation": "与后期没有反义关系，只是同为时间名词。"}, {"text": "夜晚", "is_correct": false, "explanation": "与后期没有反义关系，只是同为时间名词。"}, {"text": "年代", "is_correct": false, "explanation": "与后期没有反义关系，只是同为时间名词。"}], "correct_answer": "前期", "explanations": {"前期": "前期指同一时期的前一阶段，与「后期」互为反义。", "春季": "与后期没有反义关系，只是同为时间名词。", "夜晚": "与后期没有反义关系，只是同为时间名词。", "年代": "与后期没有反义关系，只是同为时间名词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '068d6e78-5434-461a-91c4-d2f1ef1559a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
