INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93774, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "后期", "is_correct": true, "explanation": "正确答案。后期指某一时期的后一阶段，读作 hòu qī。"}, {"text": "后记", "is_correct": false, "explanation": "后记（jì）与后期（qī）第二音节声母不同（j 与 q），意思是书籍末尾的附记。"}, {"text": "后勤", "is_correct": false, "explanation": "后勤（qín）与后期（qī）韵母不同（-in 与 -i），意思是后方的保障工作。"}, {"text": "后起", "is_correct": false, "explanation": "后起（qǐ，第三声）与后期（qī，第一声）声调不同，意思是较晚出现的。"}, {"text": "后世", "is_correct": false, "explanation": "后世（shì）与后期（qī）声母不同（sh 与 q），意思是子孙后代。"}, {"text": "后区", "is_correct": false, "explanation": "后区（qū）与后期（qī）韵母不同（-ü 与 -i），指彩票中的后区号码。"}], "explanations": {"后期": "正确答案。后期指某一时期的后一阶段，读作 hòu qī。", "后记": "后记（jì）与后期（qī）第二音节声母不同（j 与 q），意思是书籍末尾的附记。", "后勤": "后勤（qín）与后期（qī）韵母不同（-in 与 -i），意思是后方的保障工作。", "后起": "后起（qǐ，第三声）与后期（qī，第一声）声调不同，意思是较晚出现的。", "后世": "后世（shì）与后期（qī）声母不同（sh 与 q），意思是子孙后代。", "后区": "后区（qū）与后期（qī）韵母不同（-ü 与 -i），指彩票中的后区号码。"}, "sentence_index": null, "correct_answer": "后期"}, "level_3": {"options": [{"text": "后期", "is_correct": true, "explanation": "后期指某一时期的后一阶段，「暑假后期」指暑假快结束的时段，符合「每天都在写作业」。"}, {"text": "深夜", "is_correct": false, "explanation": "语义：深夜是一天中的时段，不能说「暑假深夜」表示暑假的阶段。"}, {"text": "年末", "is_correct": false, "explanation": "搭配：「年末」只指一年的末尾，不说「暑假年末」。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是一顿饭，不能指暑假的阶段。"}], "explanations": {"后期": "后期指某一时期的后一阶段，「暑假后期」指暑假快结束的时段，符合「每天都在写作业」。", "深夜": "语义：深夜是一天中的时段，不能说「暑假深夜」表示暑假的阶段。", "年末": "搭配：「年末」只指一年的末尾，不说「暑假年末」。", "早餐": "语义：早餐是一顿饭，不能指暑假的阶段。"}, "sentence_index": 0, "correct_answer": "后期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的座位在教室的后期。", "explanation": "这里应该用〈后面〉。后期指时间上靠后的阶段，表示空间位置要用后面。"}, {"text": "这辆车的后期坏了。", "explanation": "这里的「后期」指时间阶段，不指车的部位。车尾应说〈后部〉或〈后面〉，不能用后期。"}, {"text": "我吃了蛋糕的后期。", "explanation": "这里应该用〈后半块〉。后期只指时间阶段，不能指食物的一部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '068d6e78-5434-461a-91c4-d2f1ef1559a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93774, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "后期", "is_correct": true, "explanation": "正确答案。后期指某一时期的后一阶段，读作 hòu qī。"}, {"text": "后继", "is_correct": false, "explanation": "后继（jì）与后期（qī）第二音节声母不同（j 与 q），意思是接续的人。"}, {"text": "后区", "is_correct": false, "explanation": "后区（qū）与后期（qī）韵母不同（-ü 与 -i），指彩票中的后区号码。"}, {"text": "后视", "is_correct": false, "explanation": "后视（shì）与后期（qī）声母不同（sh 与 q），意思是向后看。"}, {"text": "后事", "is_correct": false, "explanation": "后事（shì）与后期（qī）声母不同（sh 与 q），意思是身后的事务。"}], "explanations": {"后期": "正确答案。后期指某一时期的后一阶段，读作 hòu qī。", "后继": "后继（jì）与后期（qī）第二音节声母不同（j 与 q），意思是接续的人。", "后区": "后区（qū）与后期（qī）韵母不同（-ü 与 -i），指彩票中的后区号码。", "后视": "后视（shì）与后期（qī）声母不同（sh 与 q），意思是向后看。", "后事": "后事（shì）与后期（qī）声母不同（sh 与 q），意思是身后的事务。"}, "sentence_index": null, "correct_answer": "后期"}, "level_3": {"options": [{"text": "后期", "is_correct": true, "explanation": "后期指某一时期的后一阶段，「到了后期」符合语境，学习变难。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是一顿饭的时段，不能指学习的阶段。"}, {"text": "晚餐", "is_correct": false, "explanation": "语义：晚餐同样是一顿饭，与学习的阶段无关。"}, {"text": "难度", "is_correct": false, "explanation": "搭配：「到了」后面接时段或阶段，「难度」不能用「到了」引出时间。"}], "explanations": {"后期": "后期指某一时期的后一阶段，「到了后期」符合语境，学习变难。", "早餐": "语义：早餐是一顿饭的时段，不能指学习的阶段。", "晚餐": "语义：晚餐同样是一顿饭，与学习的阶段无关。", "难度": "搭配：「到了」后面接时段或阶段，「难度」不能用「到了」引出时间。"}, "sentence_index": 6, "correct_answer": "后期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜做了后期，味道更好了。", "explanation": "这里的「后期」是影视、摄影的后期制作义项，菜肴不说做后期；本题要的是某一时期的后一阶段。"}, {"text": "这个路口的后期经常堵车。", "explanation": "这里的「后期」指时间阶段，不指路口的某一段；路口靠后的部分应说〈后面〉或〈尽头〉。"}, {"text": "他是我们公司的后期。", "explanation": "这里应该用〈后来的人〉。后期只指时间阶段，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '068d6e78-5434-461a-91c4-d2f1ef1559a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部小说进入了一条后期，节奏明显变快了。", "corrected_sentence": "这部小说进入了后期，节奏明显变快了。", "error_description": "量词错误：「后期」是时间阶段名词，前面不加量词，「一条」（用于细长的东西）更不对。应去掉「一条」，说「进入了后期」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '068d6e78-5434-461a-91c4-d2f1ef1559a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场比赛进入了很后期，大家都很紧张。", "corrected_sentence": "这场比赛进入了后期，大家都很紧张。", "error_description": "程度词错误：「后期」是时间阶段名词，不能用「很」修饰，应去掉「很」，说「进入了后期」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '068d6e78-5434-461a-91c4-d2f1ef1559a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93775, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "痛苦", "is_correct": true, "explanation": "痛苦：与“愉快”相对，指心里难受，构成反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙：形容质地不光滑，与“愉快”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：指明白、分明，与“愉快”没有反义关系。"}, {"text": "遥远", "is_correct": false, "explanation": "遥远：指距离很远，与“愉快”没有反义关系。"}], "correct_answer": "痛苦", "explanations": {"痛苦": "痛苦：与“愉快”相对，指心里难受，构成反义关系。", "粗糙": "粗糙：形容质地不光滑，与“愉快”没有反义关系。", "清楚": "清楚：指明白、分明，与“愉快”没有反义关系。", "遥远": "遥远：指距离很远，与“愉快”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93775, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "痛苦", "is_correct": true, "explanation": "痛苦：与“愉快”相对，指心里难受，构成反义关系。"}, {"text": "繁忙", "is_correct": false, "explanation": "繁忙：指事情多、很忙碌，与“愉快”没有反义关系。"}, {"text": "狭窄", "is_correct": false, "explanation": "狭窄：指面积小、空间不宽，与“愉快”没有反义关系。"}, {"text": "平坦", "is_correct": false, "explanation": "平坦：指地面没有起伏，与“愉快”没有反义关系。"}], "correct_answer": "痛苦", "explanations": {"痛苦": "痛苦：与“愉快”相对，指心里难受，构成反义关系。", "繁忙": "繁忙：指事情多、很忙碌，与“愉快”没有反义关系。", "狭窄": "狭窄：指面积小、空间不宽，与“愉快”没有反义关系。", "平坦": "平坦：指地面没有起伏，与“愉快”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93775, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "愉快是心里很高兴，很舒服。", "primary_collocate": null, "pronunciation": "yú kuài", "ipa": "y˧˥ kʰuaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "祝大家周末愉快！", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们合作得很愉快。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听着音乐，我的心里特别愉快。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在饭桌上聊得很愉快。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在公园里度过了愉快的一天。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一段愉快的旅行，我永远忘不了。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到朋友的信，她愉快地笑了。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的会议开得很愉快，大家都满意。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝您新年愉快，工作顺利！", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在新学校，他每天都过得很愉快。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "愉愉快快", "label": "重叠"}], "register": "中性", "sense_fingerprint": "愉快：心里高兴，感觉舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ab86027-31e9-470c-a719-029cfab81c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93775, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "愉快", "is_correct": true, "explanation": "愉快：心里高兴，符合对周末的祝愿。"}, {"text": "烦闷", "is_correct": false, "explanation": "语义：“烦闷”表示心里不痛快，与“祝大家周末”的祝愿相反。"}, {"text": "完整", "is_correct": false, "explanation": "搭配：“完整”说事物齐全，不修饰“周末”。"}, {"text": "尖锐", "is_correct": false, "explanation": "搭配：“尖锐”形容锋利或言辞激烈，不修饰“周末”。"}], "explanations": {"愉快": "愉快：心里高兴，符合对周末的祝愿。", "烦闷": "语义：“烦闷”表示心里不痛快，与“祝大家周末”的祝愿相反。", "完整": "搭配：“完整”说事物齐全，不修饰“周末”。", "尖锐": "搭配：“尖锐”形容锋利或言辞激烈，不修饰“周末”。"}, "sentence_index": 0, "correct_answer": "愉快"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "泡完热水澡，我身上觉得很愉快。", "explanation": "这里应该用〈舒服〉。身体的舒适感要用〈舒服〉，愉快说的是心里的高兴，不能用来形容身上的感觉。"}, {"text": "他跑完一千米，浑身都觉得很愉快。", "explanation": "这里应该用〈痛快〉。跑完步后浑身畅快的身体感觉要用〈痛快〉，愉快说的是心情，不用来形容“浑身”的感觉。"}, {"text": "对这个分数，他很愉快。", "explanation": "这里应该用〈满意〉。对分数、结果的态度要用〈满意〉，愉快不用来评价结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93775, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "愉快", "is_correct": true, "explanation": "愉快：形容看到信后心里高兴，符合语境。"}, {"text": "粗暴", "is_correct": false, "explanation": "语义：“粗暴”与“看到朋友的信”的友好语境相反。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”形容质地，不用来修饰笑的方式。"}, {"text": "迟钝", "is_correct": false, "explanation": "搭配：“迟钝”说反应慢，不用来修饰“笑”。"}], "explanations": {"愉快": "愉快：形容看到信后心里高兴，符合语境。", "粗暴": "语义：“粗暴”与“看到朋友的信”的友好语境相反。", "坚硬": "搭配：“坚硬”形容质地，不用来修饰笑的方式。", "迟钝": "搭配：“迟钝”说反应慢，不用来修饰“笑”。"}, "sentence_index": 6, "correct_answer": "愉快"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "长途坐车后，他的身体觉得很愉快。", "explanation": "这里应该用〈疲惫〉。长途乘车后身体是劳累的，愉快的舒适感不符合这种状态，应说〈疲惫〉。"}, {"text": "这件衣服的价格很愉快。", "explanation": "这里应该用〈便宜〉。价格的高低要用〈便宜〉或〈贵〉，愉快的主语应是人的感受，不能用来说价钱。"}, {"text": "这杯水的温度很愉快。", "explanation": "这里应该用〈合适〉。水温的高低要用〈合适〉或〈烫〉，愉快的主语应是人的感受，不能用来说水温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93775, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祝大家新年愉快了！", "corrected_sentence": "祝大家新年愉快！", "error_description": "错误形式：“愉快了”；正确形式：“愉快”。祝福语中的形容词“愉快”后不加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93775, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们玩很愉快。", "corrected_sentence": "孩子们玩得很愉快。", "error_description": "错误形式：“玩很愉快”；正确形式：“玩得很愉快”。动词与程度补语“很愉快”之间要用“得”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93776, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "痛苦", "is_correct": true, "explanation": "痛苦：与“愉快”相对，指心里难受，构成反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙：形容质地不光滑，与“愉快”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：指明白、分明，与“愉快”没有反义关系。"}, {"text": "遥远", "is_correct": false, "explanation": "遥远：指距离很远，与“愉快”没有反义关系。"}], "correct_answer": "痛苦", "explanations": {"痛苦": "痛苦：与“愉快”相对，指心里难受，构成反义关系。", "粗糙": "粗糙：形容质地不光滑，与“愉快”没有反义关系。", "清楚": "清楚：指明白、分明，与“愉快”没有反义关系。", "遥远": "遥远：指距离很远，与“愉快”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93776, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "痛苦", "is_correct": true, "explanation": "痛苦：与“愉快”相对，指心里难受，构成反义关系。"}, {"text": "繁忙", "is_correct": false, "explanation": "繁忙：指事情多、很忙碌，与“愉快”没有反义关系。"}, {"text": "狭窄", "is_correct": false, "explanation": "狭窄：指面积小、空间不宽，与“愉快”没有反义关系。"}, {"text": "平坦", "is_correct": false, "explanation": "平坦：指地面没有起伏，与“愉快”没有反义关系。"}], "correct_answer": "痛苦", "explanations": {"痛苦": "痛苦：与“愉快”相对，指心里难受，构成反义关系。", "繁忙": "繁忙：指事情多、很忙碌，与“愉快”没有反义关系。", "狭窄": "狭窄：指面积小、空间不宽，与“愉快”没有反义关系。", "平坦": "平坦：指地面没有起伏，与“愉快”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93776, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心情舒畅，快乐。", "primary_collocate": null, "pronunciation": "yú kuài", "ipa": "y˧˥ kʰuaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "祝你们旅途愉快！", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和你合作，我觉得非常愉快。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天天气好，大家的心情都很愉快。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在一起度过了愉快的周末。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次见面很愉快，我们聊了很久。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想起愉快的往事，脸上露出了笑容。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和学生的谈话十分愉快。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总是笑着说话，同事都觉得很愉快。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝你生日愉快，身体健康。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了一个愉快的暑假，他又回到学校。", "target_word": "愉快", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "愉愉快快", "label": "重叠"}], "register": "中性", "sense_fingerprint": "愉快：心情舒畅，快乐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ab86027-31e9-470c-a719-029cfab81c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "愉快", "is_correct": true, "explanation": "愉快：心情舒畅，符合对旅途的祝福。"}, {"text": "烦闷", "is_correct": false, "explanation": "语义：“烦闷”表示心里闷闷不乐，与“祝你们旅途”的祝愿相反。"}, {"text": "饱满", "is_correct": false, "explanation": "搭配：“饱满”说充实或丰满，不修饰“旅途”。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌或事物好看，不说“旅途漂亮”。"}], "explanations": {"愉快": "愉快：心情舒畅，符合对旅途的祝福。", "烦闷": "语义：“烦闷”表示心里闷闷不乐，与“祝你们旅途”的祝愿相反。", "饱满": "搭配：“饱满”说充实或丰满，不修饰“旅途”。", "漂亮": "搭配：“漂亮”形容外貌或事物好看，不说“旅途漂亮”。"}, "sentence_index": 0, "correct_answer": "愉快"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喝了一杯冰水，身上觉得很愉快。", "explanation": "这里应该用〈舒服〉。愉快说的是心情，身体的舒适感要用〈舒服〉。"}, {"text": "他挑着担子走了十里路，肩膀酸痛，觉得很愉快。", "explanation": "这里应该用〈难受〉。肩膀酸痛是身体的不适，愉快说的是心情，不能用来形容身体的疼痛。"}, {"text": "对这次考试的成绩，他很愉快。", "explanation": "这里应该用〈满意〉。对成绩、结果的态度要用〈满意〉，愉快不用来评价结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "愉快", "is_correct": true, "explanation": "愉快：形容谈话时心情舒畅，符合语境。"}, {"text": "疲惫", "is_correct": false, "explanation": "语义：“疲惫”描述人的身体状态，不用来形容谈话的情况。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”形容质地，不修饰“谈话”。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容嗓音，不说“谈话沙哑”。"}], "explanations": {"愉快": "愉快：形容谈话时心情舒畅，符合语境。", "疲惫": "语义：“疲惫”描述人的身体状态，不用来形容谈话的情况。", "坚硬": "搭配：“坚硬”形容质地，不修饰“谈话”。", "沙哑": "搭配：“沙哑”形容嗓音，不说“谈话沙哑”。"}, "sentence_index": 6, "correct_answer": "愉快"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "泡在温泉里，他觉得身上很愉快。", "explanation": "这里应该用〈惬意〉。愉快侧重心里的快乐，泡温泉这种舒适自在的身体感受要用〈惬意〉。"}, {"text": "坐了一整天的车，他的身体很愉快。", "explanation": "这里应该用〈疲惫〉。坐了一整天车，身体是劳累的，愉快说的是心情，不能用来形容身体的疲劳状态。"}, {"text": "干完活，他浑身很愉快。", "explanation": "这里应该用〈轻松〉。干完活后身体放松的感觉要用〈轻松〉，愉快不表示身体感觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们愉快的聊了一个下午。", "corrected_sentence": "他们愉快地聊了一个下午。", "error_description": "错误形式：“愉快的聊”；正确形式：“愉快地聊”。愉快在句中修饰动词时，要用“地”而不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们玩很愉快。", "corrected_sentence": "他们玩得很愉快。", "error_description": "错误形式：“玩很愉快”；正确形式：“玩得很愉快”。动词与程度补语“很愉快”之间要用“得”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
