INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93777, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "手法是做一件事的办法和样子。", "primary_collocate": null, "pronunciation": "shǒu fǎ", "ipa": "ʂou˨˩ fa˨˩", "syllable_count": 2, "sentences": [{"text": "他处理问题的手法很老练。", "target_word": "手法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不喜欢他做事的手法。", "target_word": "手法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家公司的宣传手法很聪明。", "target_word": "手法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板用温和的手法解决了矛盾。", "target_word": "手法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者的报道手法让大家有些不满。", "target_word": "手法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手法太老了，观众早就看腻了。", "target_word": "手法", "complexity_tier": "T3", "furigana": "zhè zhǒng shǒu fǎ tài lǎo le, guān zhòng zǎo jiù kàn nì le", "sentence_source": "generated"}, {"text": "他对孩子的教育手法很严格。", "target_word": "手法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个人的做事手法完全不一样。", "target_word": "手法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察用了一些特别的手法抓住他。", "target_word": "手法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以换个手法，再试一次。", "target_word": "手法", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "做事手法", "label": "复合"}], "register": "中性", "sense_fingerprint": "处理事情、做事的方式和作风", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ab86027-31e9-470c-a719-029cfab81c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93777, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手法", "is_correct": true, "explanation": "正确。手法 shǒufǎ，指做事的办法和作风。"}, {"text": "首发", "is_correct": false, "explanation": "声调：首发 shǒufā（第一声）与手法 shǒufǎ（第三声）只有末字声调不同，意思是首次发表或发行。"}, {"text": "收发", "is_correct": false, "explanation": "声调：收发 shōufā 的两个音节声调都与手法不同，意思是收信和发信。"}, {"text": "首府", "is_correct": false, "explanation": "韵母：首府 shǒufǔ 只有末字韵母不同（u 与 a），声调相同，意思是省或自治区的首府。"}, {"text": "走法", "is_correct": false, "explanation": "声母：走法 zǒufǎ 首字声母为 z，手法为 sh，其余相同，意思是走的方式，如棋的走法。"}], "explanations": {"手法": "正确。手法 shǒufǎ，指做事的办法和作风。", "首发": "声调：首发 shǒufā（第一声）与手法 shǒufǎ（第三声）只有末字声调不同，意思是首次发表或发行。", "收发": "声调：收发 shōufā 的两个音节声调都与手法不同，意思是收信和发信。", "首府": "韵母：首府 shǒufǔ 只有末字韵母不同（u 与 a），声调相同，意思是省或自治区的首府。", "走法": "声母：走法 zǒufǎ 首字声母为 z，手法为 sh，其余相同，意思是走的方式，如棋的走法。"}, "sentence_index": null, "correct_answer": "手法"}, "level_3": {"options": [{"text": "手法", "is_correct": true, "explanation": "正确。处理问题的办法可以说“很老练”，符合句意。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气指性情，不是处理问题的办法，“很老练”也不用来形容脾气。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高属于外貌特征，不能用“老练”形容处理问题的方式。"}, {"text": "嗓音", "is_correct": false, "explanation": "搭配：“老练”形容处事或技艺，不搭配“嗓音”。"}], "explanations": {"手法": "正确。处理问题的办法可以说“很老练”，符合句意。", "脾气": "语义：脾气指性情，不是处理问题的办法，“很老练”也不用来形容脾气。", "身高": "体貌：身高属于外貌特征，不能用“老练”形容处理问题的方式。", "嗓音": "搭配：“老练”形容处事或技艺，不搭配“嗓音”。"}, "sentence_index": 0, "correct_answer": "手法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去银行开户时走完了所有手法。", "explanation": "这里应该用〈手续〉。手续指办事要经过的程序，手法指做事的办法和样子，不能说走完手法。"}, {"text": "他花钱的手法很大，一次买了十套衣服。", "explanation": "这里应该用〈手笔〉。手笔指花钱、办事的气派，说出手阔绰要用〈手笔〉；手法指做事的办法和样子，不能用来形容花钱的阔气。"}, {"text": "他的手法受伤了，我们送他去医院。", "explanation": "这里把〈手法〉当成了身体部位。手法指做事的办法，不能指人身上受伤的部位，这里应说〈手指〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93777, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手法", "is_correct": true, "explanation": "正确。对孩子的教育方式可以说“很严格”，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是色彩，不是教育的方式，“教育颜色很严格”说不通。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资指报酬，与教育孩子的方式无关，句子不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重描述身材，不能用来形容教育方式。"}], "explanations": {"手法": "正确。对孩子的教育方式可以说“很严格”，符合句意。", "颜色": "语义：颜色是色彩，不是教育的方式，“教育颜色很严格”说不通。", "工资": "语义：工资指报酬，与教育孩子的方式无关，句子不通。", "体重": "体貌：体重描述身材，不能用来形容教育方式。"}, "sentence_index": 6, "correct_answer": "手法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他脸上露出了温和的手法。", "explanation": "这里应该用〈表情〉。手法指做事的办法，不能用来指脸上的神情。"}, {"text": "她的手法很苗条，穿什么都好看。", "explanation": "这里应该用〈身材〉。身材指人体的高矮胖瘦，手法指做事的办法和样子，不能用来说人的体型。"}, {"text": "我的手法冻僵了，写不了字。", "explanation": "这里把〈手法〉当成了身体部位。手法指做事的办法，不能指人身上冻僵的部位，这里应说〈手指〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93777, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用一条温和的手法解决了争端。", "corrected_sentence": "他用一种温和的手法解决了争端。", "error_description": "量词错误。“手法”是抽象名词，量词应用“种”，不用“条”；“条”多用于细长或成条的事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93777, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用一本独特的手法处理问题。", "corrected_sentence": "他用一种独特的手法处理问题。", "error_description": "量词错误。“手法”是抽象名词，应用量词“种”，不用“本”；“本”用于书籍、册子等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
