lid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93778, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手法", "is_correct": true, "explanation": "正确。手法 shǒufǎ，指做事或表现的技巧、方法。"}, {"text": "首发", "is_correct": false, "explanation": "声调：首发 shǒufā（第一声）与手法 shǒufǎ（第三声）只有末字声调不同，意思是首次发表或发行。"}, {"text": "收发", "is_correct": false, "explanation": "声调：收发 shōufā 的两个音节声调都与手法不同，意思是收信和发信。"}, {"text": "首府", "is_correct": false, "explanation": "韵母：首府 shǒufǔ 只有末字韵母不同（u 与 a），声调相同，意思是省或自治区的首府。"}, {"text": "走法", "is_correct": false, "explanation": "声母：走法 zǒufǎ 首字声母为 z，手法为 sh，其余相同，意思是走的方式，如棋的走法。"}], "explanations": {"手法": "正确。手法 shǒufǎ，指做事或表现的技巧、方法。", "首发": "声调：首发 shǒufā（第一声）与手法 shǒufǎ（第三声）只有末字声调不同，意思是首次发表或发行。", "收发": "声调：收发 shōufā 的两个音节声调都与手法不同，意思是收信和发信。", "首府": "韵母：首府 shǒufǔ 只有末字韵母不同（u 与 a），声调相同，意思是省或自治区的首府。", "走法": "声母：走法 zǒufǎ 首字声母为 z，手法为 sh，其余相同，意思是走的方式，如棋的走法。"}, "sentence_index": null, "correct_answer": "手法"}, "level_3": {"options": [{"text": "手法", "is_correct": true, "explanation": "正确。画家的绘画技巧可以说“很特别”，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重描写身材，句中谈的是画家的技巧，不能说画家的体重很特别。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资指报酬，与画家的特点无关，句子不通。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：面积说大小或多大，不能用“很特别”来形容画家。"}], "explanations": {"手法": "正确。画家的绘画技巧可以说“很特别”，符合句意。", "体重": "体貌：体重描写身材，句中谈的是画家的技巧，不能说画家的体重很特别。", "工资": "语义：工资指报酬，与画家的特点无关，句子不通。", "面积": "搭配：面积说大小或多大，不能用“很特别”来形容画家。"}, "sentence_index": 0, "correct_answer": "手法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的手法很先进。", "explanation": "这里应该用〈技术〉。手法指人手上的操作技巧，说机器的先进程度要用〈技术〉。"}, {"text": "他去医院看病，先在窗口办理了手法。", "explanation": "这里应该用〈手续〉。办理的是办事要经过的程序，要说办理手续；手法指做事的办法和样子，不能说办理手法。"}, {"text": "他的手法很大，一下子花了好几万块。", "explanation": "这里应该用〈手笔〉。手笔指花钱、办事的气派，说出手阔绰要用〈手笔〉；手法指做事的技巧，不能用来形容花钱的阔气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手法", "is_correct": true, "explanation": "正确。诗人用比喻这种写法来写风景，符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是写作的方式，诗人不能用比喻的声音写风景。"}, {"text": "节奏", "is_correct": false, "explanation": "搭配：“比喻的”修饰的应是写法，不宜与“节奏”搭配，句子不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是身材特征，不能用来写风景。"}], "explanations": {"手法": "正确。诗人用比喻这种写法来写风景，符合句意。", "声音": "语义：声音不是写作的方式，诗人不能用比喻的声音写风景。", "节奏": "搭配：“比喻的”修饰的应是写法，不宜与“节奏”搭配，句子不通。", "身高": "体貌：身高是身材特征，不能用来写风景。"}, "sentence_index": 6, "correct_answer": "手法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他摆出了一个奇怪的手法。", "explanation": "这里应该用〈姿势〉。摆出的是身体的样子，手法指做事的技巧，不能摆出。"}, {"text": "他的手法受伤了，需要去医院。", "explanation": "这里把〈手法〉当成了身体部位。手法指做事的技巧，不能指人身上受伤的部位，这里应说〈手指〉。"}, {"text": "他的手法很足，一拳就打碎了木板。", "explanation": "这里应该用〈力气〉。力气指身体的劲儿，手法指做事的技巧，不能用来说劲儿足。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨师用一张快速的手法切菜。", "corrected_sentence": "厨师用一种快速的手法切菜。", "error_description": "量词错误。“手法”是抽象名词，量词应用“种”，不用“张”；“张”多用于纸张、桌子等扁平的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用一条巧妙的手法修好了钟表。", "corrected_sentence": "他用一种巧妙的手法修好了钟表。", "error_description": "量词错误。手法是抽象名词，应用量词“种”，不用“条”；“条”多用于细长或成条的事物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
