INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93780, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "旧时夜间巡行报时，敲梆子或锣以通报时辰。", "primary_collocate": null, "pronunciation": "dǎ gēng", "ipa": "ta˨˩ kɤŋ˥", "syllable_count": 2, "sentences": [{"text": "旧时更夫夜里敲锣打更，通报时辰。", "target_word": "打更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三更时分，街上传来了打更声。", "target_word": "打更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在古镇住了一晚，听到了打更的锣声。", "target_word": "打更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代城里每晚都有人打更报时。", "target_word": "打更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的更夫，提着灯笼在街上打更。", "target_word": "打更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打更到三更天，一路敲着梆子。", "target_word": "打更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清朝的时候，这条街上每晚都有人打更。", "target_word": "打更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜深了，远处响起了打更的梆子声。", "target_word": "打更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古装剧里常有人夜里打更的画面。", "target_word": "打更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候城门关了以后，有人在街上打更。", "target_word": "打更", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打过更", "label": "体标"}, {"form": "打更人", "label": "复合"}], "register": "书面语", "sense_fingerprint": "打更：旧时夜间巡行，敲梆子或锣通报时辰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f254cf03-f386-45b9-9358-a04ac5249126') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93780, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打更", "is_correct": true, "explanation": "正确。“敲锣打更”指夜里敲锣巡行报时，与“通报时辰”相符。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭不能用来通报时辰，与句中的目的不符。"}, {"text": "扫地", "is_correct": false, "explanation": "语义：扫地不是通报时辰的动作，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“敲锣”是边走边做的动作，不能和“睡觉”并列在这里。"}], "explanations": {"打更": "正确。“敲锣打更”指夜里敲锣巡行报时，与“通报时辰”相符。", "吃饭": "语义：吃饭不能用来通报时辰，与句中的目的不符。", "扫地": "语义：扫地不是通报时辰的动作，句意不通。", "睡觉": "搭配：“敲锣”是边走边做的动作，不能和“睡觉”并列在这里。"}, "sentence_index": 0, "correct_answer": "打更"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "城门口的士兵每晚打更。", "explanation": "这里应该用〈守夜〉。守夜是在一处值守，打更是边走边敲梆子报时。"}, {"text": "警察每晚在街上打更。", "explanation": "这里应该用〈巡逻〉。巡逻是四处查看，打更是敲梆子报时，不能互换。"}, {"text": "卖花的人在街上打更。", "explanation": "这里应该用〈吆喝〉。吆喝是大声叫卖，打更是夜里敲梆子报时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打更", "is_correct": true, "explanation": "正确。清朝时夜里有人打更报时，符合句中的时代背景。"}, {"text": "上网", "is_correct": false, "explanation": "语义：清朝没有网络，“上网”与时代不符。"}, {"text": "开车", "is_correct": false, "explanation": "语义：清朝没有汽车，“开车”与时代不符。"}, {"text": "看电视", "is_correct": false, "explanation": "搭配：清朝没有电视，“看电视”与“清朝的时候”不搭配。"}], "explanations": {"打更": "正确。清朝时夜里有人打更报时，符合句中的时代背景。", "上网": "语义：清朝没有网络，“上网”与时代不符。", "开车": "语义：清朝没有汽车，“开车”与时代不符。", "看电视": "搭配：清朝没有电视，“看电视”与“清朝的时候”不搭配。"}, "sentence_index": 6, "correct_answer": "打更"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在大门口打更。", "explanation": "这里应该用〈站岗〉。站岗是守在一处，打更是边走边敲梆子报时。"}, {"text": "老师在教室里给学生打更。", "explanation": "这里应该用〈上课〉。打更是旧时夜间敲梆子报时，不是老师教学生。"}, {"text": "卖冰的人在街上打更。", "explanation": "这里应该用〈叫卖〉。叫卖是大声做生意，打更是夜里敲梆子报时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时在城里打更过。", "corrected_sentence": "他年轻时在城里打过更。", "error_description": "错误：“打更过”。正确：“打过更”。“打更”是动宾结构，“过”应紧跟动词“打”，说“打过更”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每晚都在城墙下打更过。", "corrected_sentence": "他每晚都在城墙下打更。", "error_description": "错误：“每晚都……打更过”。正确：“每晚都……打更”。“每晚都”表示经常性的习惯，不能再用表示经历的“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93781, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "表扬", "is_correct": true, "explanation": "正确。表扬与指责意思相对，一个说别人的好，一个说别人的错。"}, {"text": "打扫", "is_correct": false, "explanation": "与“指责”无反义关系，打扫指清除垃圾和污物。"}, {"text": "烹饪", "is_correct": false, "explanation": "与“指责”无反义关系，烹饪指做饭菜。"}, {"text": "散步", "is_correct": false, "explanation": "与“指责”无反义关系，散步指悠闲地走路。"}], "correct_answer": "表扬", "explanations": {"表扬": "正确。表扬与指责意思相对，一个说别人的好，一个说别人的错。", "打扫": "与“指责”无反义关系，打扫指清除垃圾和污物。", "烹饪": "与“指责”无反义关系，烹饪指做饭菜。", "散步": "与“指责”无反义关系，散步指悠闲地走路。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93781, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "表扬", "is_correct": true, "explanation": "正确。表扬与指责意思相对，一个说别人的好，一个说别人的错。"}, {"text": "搬运", "is_correct": false, "explanation": "与“指责”无反义关系，搬运指搬动物体。"}, {"text": "游泳", "is_correct": false, "explanation": "与“指责”无反义关系，游泳是身体活动。"}, {"text": "旅行", "is_correct": false, "explanation": "与“指责”无反义关系，旅行指到外地去游览。"}], "correct_answer": "表扬", "explanations": {"表扬": "正确。表扬与指责意思相对，一个说别人的好，一个说别人的错。", "搬运": "与“指责”无反义关系，搬运指搬动物体。", "游泳": "与“指责”无反义关系，游泳是身体活动。", "旅行": "与“指责”无反义关系，旅行指到外地去游览。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93781, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指责是说别人做得不对，很不高兴。", "primary_collocate": null, "pronunciation": "zhǐ zé", "ipa": "ʈʂɨ˨˩˦ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "妈妈生气地指责哥哥不爱干净。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一回家就指责我没做饭。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么总是指责别人？", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很不高兴，指责我说话不算话。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟打破了杯子，爸爸指责了他。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都指责他不守规矩。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人指责你的时候，先听听原因。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人指责服务员太慢，很不满意。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他指责过我好几次，我都没生气。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板指责大家做事不认真。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指责了", "label": "体标"}, {"form": "指责过", "label": "体标"}, {"form": "指責", "label": "繁体"}], "register": "中性", "sense_fingerprint": "带着不满说别人做得不对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6890ad06-571d-4ab3-9fbc-f9d69fcc7e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93781, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指责", "is_correct": true, "explanation": "正确。“妈妈生气地指责哥哥不爱干净”表示说哥哥做得不对、很不高兴。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：夸奖是称赞别人，与“生气地”和“不爱干净”的负面情绪矛盾。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是物体，不能接“哥哥不爱干净”这样的句子。"}, {"text": "旅行", "is_correct": false, "explanation": "配价：“旅行”是不及物动词，不能带“哥哥”作宾语。"}], "explanations": {"指责": "正确。“妈妈生气地指责哥哥不爱干净”表示说哥哥做得不对、很不高兴。", "夸奖": "语义：夸奖是称赞别人，与“生气地”和“不爱干净”的负面情绪矛盾。", "搬运": "搭配：“搬运”的对象是物体，不能接“哥哥不爱干净”这样的句子。", "旅行": "配价：“旅行”是不及物动词，不能带“哥哥”作宾语。"}, "sentence_index": 0, "correct_answer": "指责"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我指责朋友的帮助，他一直陪着我。", "explanation": "这里应该用〈感谢〉。指责用于说别人做得不对，不能用于感激别人的帮助。"}, {"text": "老板指责了大家的努力，大家都很高兴。", "explanation": "这里应该用〈表扬〉。指责用于批评过错，不能用于值得肯定的努力。"}, {"text": "老师指责我的进步，还给我发了奖状。", "explanation": "这里应该用〈夸奖〉。指责用于批评过错，不能用于值得肯定的进步，应说“夸奖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93781, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指责", "is_correct": true, "explanation": "正确。“别人指责你的时候”指别人说你做错了，应先听原因。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”的宾语应是车辆等，不能接“你”这样的人作宾语。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不是可以对人做出的行为，与句中的情境不合。"}, {"text": "讲座", "is_correct": false, "explanation": "语义：讲座是活动，不是对人的言语行为，“讲座你的时候”不合语境。"}], "explanations": {"指责": "正确。“别人指责你的时候”指别人说你做错了，应先听原因。", "驾驶": "配价：“驾驶”的宾语应是车辆等，不能接“你”这样的人作宾语。", "面包": "语义：面包是食物，不是可以对人做出的行为，与句中的情境不合。", "讲座": "语义：讲座是活动，不是对人的言语行为，“讲座你的时候”不合语境。"}, "sentence_index": 6, "correct_answer": "指责"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班长指责大家认真做事，大家都很开心。", "explanation": "这里应该用〈鼓励〉。指责用于说别人做错，不能用于鼓励认真做事。"}, {"text": "同学们指责老师的耐心，大家都很感动。", "explanation": "这里应该用〈赞美〉。指责不能用于耐心这样的优点，赞美优点要用“赞美”。"}, {"text": "同学们指责他的勇气，大家都佩服他。", "explanation": "这里应该用〈称赞〉。指责不能用于勇气这样的优点，称赞优点要用“称赞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93781, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一开口就把指责了我一顿，我很委屈。", "corrected_sentence": "她一开口就指责了我一顿，我很委屈。", "error_description": "错误：“把”字句用错。“指责了我一顿”不需要“把”，不能说“把指责了我”。正确：“她一开口就指责了我一顿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93781, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板当众指责了过小李，小李很尴尬。", "corrected_sentence": "老板当众指责了小李，小李很尴尬。", "error_description": "错误：动态助词“过”多加了一个。“了”已表示完成，不能再加“过”，应说“指责了小李”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
