INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93782, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指出错误并加以责备。", "primary_collocate": null, "pronunciation": "zhǐ zé", "ipa": "ʈʂɨ˨˩˦ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "老师指责他抄别人的作业。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都指责这家公司骗人。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者指责市长没有说真话。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他指责我迟到，可我没有。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理当面指责了小王的错误。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不能只指责别人，也要看看自己。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸指责这家工厂污染河水。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友指责过她很多次。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他指责对方没有遵守规定。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈没有指责我，只是说下次小心。", "target_word": "指责", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指责了", "label": "体标"}, {"form": "指责过", "label": "体标"}, {"form": "指責", "label": "繁体"}], "register": "中性", "sense_fingerprint": "指出别人的错误并责备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6890ad06-571d-4ab3-9fbc-f9d69fcc7e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指责", "is_correct": true, "explanation": "正确。“指责他抄别人的作业”指出错误并加以责备。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：表扬是肯定别人的好表现，与“抄别人的作业”这一错误行为矛盾。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是物体，不能带“他抄别人的作业”这样的动作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求可以吃的东西作宾语，不能接人或动作。"}], "explanations": {"指责": "正确。“指责他抄别人的作业”指出错误并加以责备。", "表扬": "语义：表扬是肯定别人的好表现，与“抄别人的作业”这一错误行为矛盾。", "搬运": "搭配：“搬运”的对象是物体，不能带“他抄别人的作业”这样的动作宾语。", "吃": "配价：“吃”要求可以吃的东西作宾语，不能接人或动作。"}, "sentence_index": 0, "correct_answer": "指责"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师指责了他的努力，大家都为他鼓掌。", "explanation": "这里应该用〈表扬〉。指责用于错误或过失，不用于值得肯定的努力。"}, {"text": "他指责我的帮助，我很感激。", "explanation": "这里应该用〈感谢〉。指责是批评过失，不能用来针对帮助；感激别人的帮助应说“感谢”。"}, {"text": "爸爸指责我的好成绩，还给我买了礼物。", "explanation": "这里应该用〈夸奖〉。指责不能用于好成绩，赞扬好成绩要用“夸奖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指责", "is_correct": true, "explanation": "正确。“报纸指责这家工厂污染河水”表示批评和责备。"}, {"text": "鼓励", "is_correct": false, "explanation": "语义：鼓励是支持别人，与“污染河水”这一过错矛盾。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”的宾语应是车辆等，不能接“这家工厂污染河水”这样的句子。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：欢迎是热情对待，与“污染河水”的负面行为不合。"}], "explanations": {"指责": "正确。“报纸指责这家工厂污染河水”表示批评和责备。", "鼓励": "语义：鼓励是支持别人，与“污染河水”这一过错矛盾。", "驾驶": "配价：“驾驶”的宾语应是车辆等，不能接“这家工厂污染河水”这样的句子。", "欢迎": "语义：欢迎是热情对待，与“污染河水”的负面行为不合。"}, "sentence_index": 6, "correct_answer": "指责"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师指责他认真学习，成绩进步很快。", "explanation": "这里应该用〈鼓励〉。指责针对过错，不能用于值得鼓励的认真学习。"}, {"text": "妈妈指责我的懂事，还给我买了新书。", "explanation": "这里应该用〈夸奖〉。指责用于批评过错，不能用于值得夸赞的懂事，应说“夸奖”。"}, {"text": "大家都指责他的诚实，很佩服他。", "explanation": "这里应该用〈赞美〉。指责不能用于诚实这样的优点，称赞优点要用“赞美”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把指责了他一顿，因为他迟到了。", "corrected_sentence": "老师指责了他一顿，因为他迟到了。", "error_description": "错误：“把”字句用错。“指责了他一顿”不需要“把”，不能说“把指责了他”。正确：“老师指责了他一顿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师没有指责了他，只是提醒他下次注意。", "corrected_sentence": "老师没有指责他，只是提醒他下次注意。", "error_description": "错误：“没有”否定过去的动作时，动词后不能再加“了”。正确：“没有指责他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
