INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93784, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "欧洲联盟许多国家使用的统一货币。", "primary_collocate": null, "pronunciation": "ōu yuán", "ipa": "ou˥ ɥæn˧˥", "syllable_count": 2, "sentences": [{"text": "欧盟很多国家都用欧元。", "target_word": "欧元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欧元是欧洲联盟的统一货币。", "target_word": "欧元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在欧洲旅行时，我带了很多欧元。", "target_word": "欧元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些国家用同一种钱，就是欧元。", "target_word": "欧元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欧元比人民币贵很多。", "target_word": "欧元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "德国和法国用同一种货币，叫欧元。", "target_word": "欧元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在银行换了两百欧元。", "target_word": "欧元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欧元的纸币有很多颜色。", "target_word": "欧元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用欧元付房租。", "target_word": "欧元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年欧元对人民币的汇率一直在变。", "target_word": "欧元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "歐元", "label": "繁体"}, {"form": "欧元区", "label": "复合"}], "register": "中性", "sense_fingerprint": "欧盟许多国家的统一货币", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f254cf03-f386-45b9-9358-a04ac5249126') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欧元", "is_correct": true, "explanation": "正确。欧盟许多国家使用的统一货币就是欧元。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是货币，国家不能“用月亮”交易。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“用”后面接的应是货币，“面包”不能作为货币使用。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是货币，句中说的是欧盟国家通用的钱。"}], "explanations": {"欧元": "正确。欧盟许多国家使用的统一货币就是欧元。", "月亮": "语义：月亮不是货币，国家不能“用月亮”交易。", "面包": "搭配：“用”后面接的应是货币，“面包”不能作为货币使用。", "石头": "语义：石头不是货币，句中说的是欧盟国家通用的钱。"}, "sentence_index": 0, "correct_answer": "欧元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了两本欧元。", "explanation": "这里不该用量词“本”。“本”用于书籍，货币不用“本”来数。"}, {"text": "欧元是一种水果，味道很甜。", "explanation": "欧元指一种货币，不指水果，这里词义用错了。"}, {"text": "欧元每年召开一次会议。", "explanation": "这里应该用〈欧盟〉。召开会议的是组织，欧元是货币，不能召开会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欧元", "is_correct": true, "explanation": "正确。在银行可以兑换欧元，“两百欧元”是金额。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：银行兑换的是货币，不是苹果。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：在银行“换”指兑换钱，蔬菜不能这样兑换。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“换了两百”后接的应是货币，“花”不能这样搭配。"}], "explanations": {"欧元": "正确。在银行可以兑换欧元，“两百欧元”是金额。", "苹果": "语义：银行兑换的是货币，不是苹果。", "蔬菜": "语义：在银行“换”指兑换钱，蔬菜不能这样兑换。", "花": "搭配：“换了两百”后接的应是货币，“花”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "欧元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一辆欧元。", "explanation": "这里不该用量词“辆”。“辆”用于车辆，货币不用“辆”来数。"}, {"text": "欧元是一种花，颜色很漂亮。", "explanation": "欧元只指货币，不指花，这里把它当成了植物，词义用错了。"}, {"text": "我今年要去欧元学习。", "explanation": "这里应该用〈欧洲〉。欧元是货币，表示去学习的地方要用欧洲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用两百条欧元买了一双鞋。", "corrected_sentence": "他用两百欧元买了一双鞋。", "error_description": "错误：“两百条欧元”。正确：“两百欧元”。货币前不用量词“条”，直接说“两百欧元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在柏林换了五百条欧元。", "corrected_sentence": "我在柏林换了五百欧元。", "error_description": "错误：“五百条欧元”。正确：“五百欧元”。“条”用于细长的东西，货币前不用量词，直接说“五百欧元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
