INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93785, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "正好是刚刚好，不多也不少。", "primary_collocate": null, "pronunciation": "zhèng hǎo", "ipa": "ʈʂɤŋ˥˩ xɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这些钱正好够买一本书。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋不大不小，正好合适。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们正好十个人。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶水正好一升。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一共三十块，正好不多不少。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间正好能放下一张床。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的价钱正好是一百元。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子长短正好。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米饭正好够我们四个人吃。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗汤的咸淡正好。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量、大小、程度刚刚合适，不多不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8eb21289-7e21-4025-8e45-bb69550d4010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93785, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正好", "is_correct": true, "explanation": "正好：zhèng hǎo（第四声、第三声），表示刚刚好，不多也不少。"}, {"text": "正在", "is_correct": false, "explanation": "zhèngzài 与 zhènghǎo 韵母不同（ài 与 ǎo），意思是“正在”，表示动作进行中。"}, {"text": "真好", "is_correct": false, "explanation": "zhēnhǎo 与 zhènghǎo 韵母不同（n 与 ng），意思是“真好”，表示很好。"}, {"text": "正要", "is_correct": false, "explanation": "zhèngyào 与 zhènghǎo 声母不同（y 与 h），意思是“正要”，表示将要。"}], "explanations": {"正好": "正好：zhèng hǎo（第四声、第三声），表示刚刚好，不多也不少。", "正在": "zhèngzài 与 zhènghǎo 韵母不同（ài 与 ǎo），意思是“正在”，表示动作进行中。", "真好": "zhēnhǎo 与 zhènghǎo 韵母不同（n 与 ng），意思是“真好”，表示很好。", "正要": "zhèngyào 与 zhènghǎo 声母不同（y 与 h），意思是“正要”，表示将要。"}, "sentence_index": null, "correct_answer": "正好"}, "level_3": {"options": [{"text": "正好", "is_correct": true, "explanation": "“正好”表示数量刚好够用，与“够买一本书”搭配。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，不能描述钱的数量刚好够用这一状态。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示间或发生，与“这些钱”这一具体数额不合。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”通常修饰形容词，不修饰能愿动词“够买”。"}], "explanations": {"正好": "“正好”表示数量刚好够用，与“够买一本书”搭配。", "忽然": "语义：“忽然”表示突然发生，不能描述钱的数量刚好够用这一状态。", "偶尔": "语义：“偶尔”表示间或发生，与“这些钱”这一具体数额不合。", "十分": "搭配：“十分”通常修饰形容词，不修饰能愿动词“够买”。"}, "sentence_index": 0, "correct_answer": "正好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些钱正好够买一本书，还多出来三块。", "explanation": "这里“正好”表示不多不少，与“还多出来三块”矛盾；只想说大致够用，应改用〈差不多〉。"}, {"text": "这块布正好三米，还差半米才到三米。", "explanation": "这里“正好”表示不多不少，与“还差半米才到三米”矛盾；布不够三米时应说〈不到〉三米。"}, {"text": "这双鞋正好合适，就是大了两号。", "explanation": "这里“正好”表示不大不小，与“大了两号”矛盾；鞋大了应说〈不合适〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93785, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正好", "is_correct": true, "explanation": "“正好”表示刚刚好，与“价钱……是一百元”的确定数额相合。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，价钱不能“立刻”成为某个确定的数额。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便”表示任意，与价钱固定为一百元的说法不合。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词或心理动词，不能用于“是一百元”这种数量判断句。"}], "explanations": {"正好": "“正好”表示刚刚好，与“价钱……是一百元”的确定数额相合。", "立刻": "语义：“立刻”表示马上，价钱不能“立刻”成为某个确定的数额。", "随便": "语义：“随便”表示任意，与价钱固定为一百元的说法不合。", "很": "搭配：“很”修饰形容词或心理动词，不能用于“是一百元”这种数量判断句。"}, "sentence_index": 6, "correct_answer": "正好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果正好有二十个多。", "explanation": "这里应该用〈大约〉。“正好”表示不多不少，不能与表示略超出的说法并用；只想说估计数量，应改用〈大约〉。"}, {"text": "这些书正好有三百页左右。", "explanation": "这里应该用〈差不多〉。“正好”表示确定不差，不能与表示估计的说法并用；只说大致数量，应改用〈差不多〉。"}, {"text": "我们正好大约需要两天。", "explanation": "这里“正好”表示不多不少，与估计时长的说法冲突；只想说大概需要的时长，应去掉“正好”，改用〈差不多〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93785, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这箱饮料正好了够我们四个人喝。", "corrected_sentence": "这箱饮料正好够我们四个人喝。", "error_description": "位置错误：“了”不能插在副词“正好”与动词“够”之间，应说“正好够”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93785, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔钱正好了是两百元。", "corrected_sentence": "这笔钱正好是两百元。", "error_description": "位置错误：“了”不能直接放在“正好”后面，应说“正好是两百元”，“了”不能附着在副词“正好”上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
