INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93786, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "恰好；恰巧合适。", "primary_collocate": null, "pronunciation": "zhèng hǎo", "ipa": "ʈʂɤŋ˥˩ xɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我去找他，他正好在家。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚出门，正好碰到了他。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买书，朋友正好有一本。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你来得正好，我们正要吃饭。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正好路过我家，就进来坐了。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正好带了伞，没被淋到。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我正好遇见了老同学。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们正好坐在同一辆车上。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走的时候，我正好不在。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话打来时，我正好在洗澡。", "target_word": "正好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "时机、情况碰巧遇上，恰巧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8eb21289-7e21-4025-8e45-bb69550d4010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93786, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正好", "is_correct": true, "explanation": "正好：zhèng hǎo（第四声、第三声），表示恰巧遇上。"}, {"text": "正在", "is_correct": false, "explanation": "zhèngzài 与 zhènghǎo 韵母不同（ài 与 ǎo），意思是“正在”，表示动作进行中。"}, {"text": "真好", "is_correct": false, "explanation": "zhēnhǎo 与 zhènghǎo 韵母不同（n 与 ng），意思是“真好”，表示很好。"}, {"text": "正要", "is_correct": false, "explanation": "zhèngyào 与 zhènghǎo 声母不同（y 与 h），意思是“正要”，表示将要。"}], "explanations": {"正好": "正好：zhèng hǎo（第四声、第三声），表示恰巧遇上。", "正在": "zhèngzài 与 zhènghǎo 韵母不同（ài 与 ǎo），意思是“正在”，表示动作进行中。", "真好": "zhēnhǎo 与 zhènghǎo 韵母不同（n 与 ng），意思是“真好”，表示很好。", "正要": "zhèngyào 与 zhènghǎo 声母不同（y 与 h），意思是“正要”，表示将要。"}, "sentence_index": null, "correct_answer": "正好"}, "level_3": {"options": [{"text": "正好", "is_correct": true, "explanation": "“正好”表示碰巧，与“我去找他，他……在家”的偶遇语境相合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”指突然出现的情况，与“他在家”这一已存在的状态不合。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰程度，不能修饰“在家”这样的动词短语，“他非常在家”不通。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”通常与否定词连用，不能单独修饰“在家”。"}], "explanations": {"正好": "“正好”表示碰巧，与“我去找他，他……在家”的偶遇语境相合。", "忽然": "语义：“忽然”指突然出现的情况，与“他在家”这一已存在的状态不合。", "非常": "搭配：“非常”修饰程度，不能修饰“在家”这样的动词短语，“他非常在家”不通。", "根本": "搭配：“根本”通常与否定词连用，不能单独修饰“在家”。"}, "sentence_index": 0, "correct_answer": "正好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他故意把杯子正好打破了。", "explanation": "“正好”表示偶然凑巧，与“故意”矛盾，应去掉“正好”。"}, {"text": "他每天都正好去上班。", "explanation": "“正好”表示偶然凑巧，不能修饰每天例行的事，应去掉“正好”。"}, {"text": "这是我特意为你正好准备的礼物。", "explanation": "“正好”表示偶然凑巧，与“特意”的有意安排矛盾，应去掉“正好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正好", "is_correct": true, "explanation": "“正好”表示碰巧，与“昨天……遇见了老同学”的一次性相遇相合。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不断，与“昨天”的一次相遇不合。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示经常发生，与“昨天”这一次相遇不合。"}, {"text": "将", "is_correct": false, "explanation": "体貌：“将”标示将来，不能与“昨天”这一已发生的时间搭配。"}], "explanations": {"正好": "“正好”表示碰巧，与“昨天……遇见了老同学”的一次性相遇相合。", "一直": "语义：“一直”表示持续不断，与“昨天”的一次相遇不合。", "总是": "语义：“总是”表示经常发生，与“昨天”这一次相遇不合。", "将": "体貌：“将”标示将来，不能与“昨天”这一已发生的时间搭配。"}, "sentence_index": 6, "correct_answer": "正好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每次都正好迟到，大家都习惯了。", "explanation": "“正好”表示一次偶然的巧合，不能用于“每次都”的习惯性情况，应去掉“正好”。"}, {"text": "他每天都提前到，正好每次都迟到。", "explanation": "这里“正好”表示偶然凑巧，不能与“每天都提前”的习惯性说法搭配；表示相反的结果应说〈却〉。"}, {"text": "他故意不接电话，正好没接。", "explanation": "这里应去掉“正好”。“正好”表示偶然凑巧，不能用于有意的行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我到家的时候，他正好了在看电视。", "corrected_sentence": "我到家的时候，他正好在看电视。", "error_description": "位置错误：“了”不能附着在副词“正好”之后，应说“他正好在看电视”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我到车站的时候，正好的赶上了末班车。", "corrected_sentence": "我到车站的时候，正好赶上了末班车。", "error_description": "多余成分：“正好”是副词，后面不能加“的”，应说“正好赶上”，不能说“正好的赶上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93787, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "仁慈", "is_correct": true, "explanation": "仁慈：对人宽厚、有同情心，与“残酷”构成反义。"}, {"text": "复杂", "is_correct": false, "explanation": "与“残酷”无反义关系：复杂说事情或结构繁多，与对人的态度无关。"}, {"text": "愉快", "is_correct": false, "explanation": "与“残酷”无反义关系：愉快说心情好，不是“残酷”的对立面。"}, {"text": "精致", "is_correct": false, "explanation": "与“残酷”无反义关系：精致形容做工或东西细巧。"}], "correct_answer": "仁慈", "explanations": {"仁慈": "仁慈：对人宽厚、有同情心，与“残酷”构成反义。", "复杂": "与“残酷”无反义关系：复杂说事情或结构繁多，与对人的态度无关。", "愉快": "与“残酷”无反义关系：愉快说心情好，不是“残酷”的对立面。", "精致": "与“残酷”无反义关系：精致形容做工或东西细巧。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93787, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "仁慈", "is_correct": true, "explanation": "仁慈：对人宽厚、有同情心，与“残酷”构成反义。"}, {"text": "清晰", "is_correct": false, "explanation": "与“残酷”无反义关系：清晰说的是看得分明，与对人的态度无关。"}, {"text": "香甜", "is_correct": false, "explanation": "与“残酷”无反义关系：香甜说味道甜美。"}, {"text": "透明", "is_correct": false, "explanation": "与“残酷”无反义关系：透明说的是能看透，与对人的态度无关。"}], "correct_answer": "仁慈", "explanations": {"仁慈": "仁慈：对人宽厚、有同情心，与“残酷”构成反义。", "清晰": "与“残酷”无反义关系：清晰说的是看得分明，与对人的态度无关。", "香甜": "与“残酷”无反义关系：香甜说味道甜美。", "透明": "与“残酷”无反义关系：透明说的是能看透，与对人的态度无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93787, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "残酷是对别人很狠，一点也不可怜别人。", "primary_collocate": null, "pronunciation": "cán kù", "ipa": "tsʰan³⁵ kʰu⁵¹", "syllable_count": 2, "sentences": [{"text": "他对小动物很残酷，我不喜欢他。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老板对工人太残酷了，从不让他们休息。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们笑着打小猫，这样做太残酷了。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的话很残酷，朋友听了哭了。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个残酷的人，从来不帮别人。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要对自己的孩子这么残酷。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位国王对敌人非常残酷。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么能这样残酷地对待老人？", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他残酷地打了那只狗，邻居都很生气。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对没有钱的人这么残酷，真让人难过。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "残酷地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "形容人对别人很狠、毫不怜悯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ac5386f-a5c3-4a5f-b7d7-6ad2731789e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93787, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温柔", "is_correct": false, "explanation": "语义：温柔与后句“我不喜欢他”的态度相反，前后意思不通。"}, {"text": "残酷", "is_correct": true, "explanation": "残酷：对别人很狠、毫不怜悯，与“我不喜欢他”相合。"}, {"text": "活泼", "is_correct": false, "explanation": "配价：活泼形容性格或样子，不能带“对小动物”这样的对象。"}, {"text": "慈祥", "is_correct": false, "explanation": "搭配：慈祥多形容长辈的面容和神态，不说对小动物很慈祥。"}], "explanations": {"温柔": "语义：温柔与后句“我不喜欢他”的态度相反，前后意思不通。", "残酷": "残酷：对别人很狠、毫不怜悯，与“我不喜欢他”相合。", "活泼": "配价：活泼形容性格或样子，不能带“对小动物”这样的对象。", "慈祥": "搭配：慈祥多形容长辈的面容和神态，不说对小动物很慈祥。"}, "sentence_index": 0, "correct_answer": "残酷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈对我很残酷，每天晚上都给我讲故事、盖被子。", "explanation": "这里应该用〈温柔〉。残酷指对别人很狠、毫不怜悯，讲故事、盖被子是温柔体贴的表现，与“残酷”相矛盾。"}, {"text": "老师对学生很残酷，每次都热心地帮大家讲解课文。", "explanation": "这里应该用〈热心〉。残酷指对别人狠毒、毫不怜悯，老师热心讲解只能说热心。"}, {"text": "这位护士对病人很残酷，总是轻声细语地照顾他们。", "explanation": "这里应该用〈温柔〉。残酷指毫不怜悯地对待别人，轻声细语地照顾病人是温柔，与“残酷”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "懒惰", "is_correct": false, "explanation": "语义：懒惰说的是做事不勤快，与国王对敌人的态度无关。"}, {"text": "残酷", "is_correct": true, "explanation": "残酷：对敌人毫不怜悯、很狠，正好与句意相合。"}, {"text": "谦虚", "is_correct": false, "explanation": "搭配：谦虚多用来说对自己或对人的态度，不说对敌人谦虚。"}, {"text": "勤奋", "is_correct": false, "explanation": "语义：勤奋指努力做事，与对敌人的态度不相干。"}], "explanations": {"懒惰": "语义：懒惰说的是做事不勤快，与国王对敌人的态度无关。", "残酷": "残酷：对敌人毫不怜悯、很狠，正好与句意相合。", "谦虚": "搭配：谦虚多用来说对自己或对人的态度，不说对敌人谦虚。", "勤奋": "语义：勤奋指努力做事，与对敌人的态度不相干。"}, "sentence_index": 6, "correct_answer": "残酷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他残酷地把钱分给了那些穷人，大家都很感动。", "explanation": "这里应该用〈慷慨〉。残酷指对别人狠毒、不怜悯，把钱分给穷人是慷慨，不能说“残酷地分钱”。"}, {"text": "这家饭店的菜很残酷，我们都吃得很满意。", "explanation": "这里应该用〈好吃〉。残酷形容对人狠毒、不怜悯，不能形容菜的味道，夸味道好要用好吃。"}, {"text": "老师残酷地表扬了每个学生，大家都很高兴。", "explanation": "这里应该用〈热情〉。残酷形容狠毒、不怜悯，不能修饰善意的表扬；热情地夸奖要用热情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个商人给穷人很残酷，从不给他们留余地。", "corrected_sentence": "那个商人对穷人很残酷，从不给他们留余地。", "error_description": "说对某人很狠，要用介词“对”引出对象，说“对穷人很残酷”；不能用“给”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个男人残酷的抽打他的马，路人都看不下去。", "corrected_sentence": "那个男人残酷地抽打他的马，路人都看不下去。", "error_description": "“残酷”在这里修饰动词“抽打”，作状语要加“地”，说“残酷地抽打”；用“的”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
