INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93788, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "冷酷无情；严酷。", "primary_collocate": null, "pronunciation": "cán kù", "ipa": "tsʰan³⁵ kʰu⁵¹", "syllable_count": 2, "sentences": [{"text": "现实很残酷，不是每个人都能成功。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛太残酷了，只有第一名能留下。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争带来了残酷的结果。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠的自然环境非常残酷，很少有动物能活下来。", "target_word": "残酷", "complexity_tier": "T3", "furigana": "shā mò de zì rán huán jìng fēi cháng cán kù, hěn shǎo yǒu dòng wù néng huó xià lái.", "sentence_source": "generated"}, {"text": "这是一个残酷的故事，我看哭了。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作中的竞争非常残酷。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次知道生活有多残酷。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "残酷的事实摆在我们面前。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的竞争很残酷，三个人只能录取一个。", "target_word": "残酷", "complexity_tier": "T3", "furigana": "zhè cì kǎo shì de jìng zhēng hěn cán kù, sān gè rén zhǐ néng lù qǔ yí gè.", "sentence_source": "generated"}, {"text": "经过残酷的训练，他成了好兵。", "target_word": "残酷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "残酷地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "形容现实、竞争、环境等严酷无情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ac5386f-a5c3-4a5f-b7d7-6ad2731789e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美好", "is_correct": false, "explanation": "语义：说现实美好，与后句“不是每个人都能成功”相矛盾。"}, {"text": "残酷", "is_correct": true, "explanation": "残酷：严酷无情，指现实对人不留情面，与后句意思相合。"}, {"text": "慈祥", "is_correct": false, "explanation": "搭配：慈祥多用于形容人，不用来形容现实。"}, {"text": "简单", "is_correct": false, "explanation": "语义：说现实简单，与后句“不是每个人都能成功”不相合。"}], "explanations": {"美好": "语义：说现实美好，与后句“不是每个人都能成功”相矛盾。", "残酷": "残酷：严酷无情，指现实对人不留情面，与后句意思相合。", "慈祥": "搭配：慈祥多用于形容人，不用来形容现实。", "简单": "语义：说现实简单，与后句“不是每个人都能成功”不相合。"}, "sentence_index": 0, "correct_answer": "残酷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的服务很残酷，客人们都很满意。", "explanation": "这里应该用〈周到〉。残酷形容严酷无情，不能用来形容服务的态度；服务细致周到要用周到。"}, {"text": "春天的花园很残酷，花朵开得很美。", "explanation": "这里应该用〈美丽〉。残酷形容严酷无情的环境或现实，形容景色好看要用美丽。"}, {"text": "今天的天气很残酷，阳光温暖，微风轻轻吹。", "explanation": "这里应该用〈舒服〉。残酷形容环境严酷无情，阳光温暖、微风轻吹的天气是舒服宜人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高大", "is_correct": false, "explanation": "体貌：高大描述人或物的体形，不能用来形容生活。"}, {"text": "残酷", "is_correct": true, "explanation": "残酷：严酷无情，指生活中的艰难与不留情面，与“第一次知道”的意思相合。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：响亮多用于声音，不说生活有多响亮。"}, {"text": "天真", "is_correct": false, "explanation": "语义：天真形容人单纯，不能用来形容生活。"}], "explanations": {"高大": "体貌：高大描述人或物的体形，不能用来形容生活。", "残酷": "残酷：严酷无情，指生活中的艰难与不留情面，与“第一次知道”的意思相合。", "响亮": "搭配：响亮多用于声音，不说生活有多响亮。", "天真": "语义：天真形容人单纯，不能用来形容生活。"}, "sentence_index": 6, "correct_answer": "残酷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天残酷地哄我们睡觉，讲故事给我们听。", "explanation": "这里应该用〈温柔〉。残酷形容冷酷无情，不能形容哄孩子睡觉的态度；温柔地哄孩子要用温柔。"}, {"text": "这首歌的旋律很残酷，大家都很喜欢它。", "explanation": "这里应该用〈悦耳〉。残酷形容冷酷无情或严酷，不能形容旋律；形容旋律好听要用悦耳。"}, {"text": "这次聚会的气氛很残酷，大家都笑得很开心。", "explanation": "这里应该用〈热闹〉。残酷形容严酷无情，不能形容欢乐的气氛；欢乐热烈的场面要用热闹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一行的竞争很残酷地，不少新人坚持不了一年。", "corrected_sentence": "这一行的竞争很残酷，不少新人坚持不了一年。", "error_description": "“残酷”在这里作谓语，说“竞争很残酷”；“地”只用在修饰动词的状语后面，这里不能加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛中，他们残酷的淘汰了很多弱者。", "corrected_sentence": "比赛中，他们残酷地淘汰了很多弱者。", "error_description": "“残酷”在这里修饰动词“淘汰”，作状语要加“地”，说“残酷地淘汰”；用“的”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93789, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93789, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93789, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "渐渐是一点一点地，慢慢地变。", "primary_collocate": null, "pronunciation": "jiàn jiàn", "ipa": "tɕjɛn˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "天渐渐黑了，街上的人越来越少。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，天气渐渐热起来。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨渐渐小了，我们走出了店。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了她的话，我渐渐明白了。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳渐渐落到山后面去了。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声音渐渐低下去了。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了几个月，我渐渐习惯了这里的生活。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子渐渐长大，不再跟着妈妈了。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上的云渐渐散开了。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水渐渐变清了。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "渐渐地", "label": "副词+地"}, {"form": "漸漸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "状态一点一点自然地变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1ebf27a-bc60-422b-bfea-fa9b711a051c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93789, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "渐渐", "is_correct": true, "explanation": "“渐渐”读 jiàn jiàn，意思是一点一点地、慢慢地变。"}, {"text": "渐变", "is_correct": false, "explanation": "biàn（b）与 jiàn（j）声母不同，“渐变”意思是逐渐改变。"}, {"text": "尖尖", "is_correct": false, "explanation": "jiān jiān 两个音节都是第一声，与“渐渐”（第四声）声调不同，意思是尖尖的。"}, {"text": "渐现", "is_correct": false, "explanation": "xiàn（x）与 jiàn（j）声母不同，“渐现”意思是逐渐显现。"}, {"text": "渐减", "is_correct": false, "explanation": "第二个音节 jiǎn（第三声）与 jiàn（第四声）声调不同，“渐减”意思是逐渐减少。"}], "explanations": {"渐渐": "“渐渐”读 jiàn jiàn，意思是一点一点地、慢慢地变。", "渐变": "biàn（b）与 jiàn（j）声母不同，“渐变”意思是逐渐改变。", "尖尖": "jiān jiān 两个音节都是第一声，与“渐渐”（第四声）声调不同，意思是尖尖的。", "渐现": "xiàn（x）与 jiàn（j）声母不同，“渐现”意思是逐渐显现。", "渐减": "第二个音节 jiǎn（第三声）与 jiàn（第四声）声调不同，“渐减”意思是逐渐减少。"}, "sentence_index": null, "correct_answer": "渐渐"}, "level_3": {"options": [{"text": "渐渐", "is_correct": true, "explanation": "“渐渐”表示一点一点地变化，与“天渐渐黑了”相符。"}, {"text": "经常", "is_correct": false, "explanation": "语义：“经常”表示多次发生，不能修饰“黑了”这种一次性的逐步变化。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行，与“黑了”这样的完成态不搭配。"}, {"text": "当场", "is_correct": false, "explanation": "语义：“当场”指在现场当时，与“天渐渐黑了”的逐步变化不符。"}], "explanations": {"渐渐": "“渐渐”表示一点一点地变化，与“天渐渐黑了”相符。", "经常": "语义：“经常”表示多次发生，不能修饰“黑了”这种一次性的逐步变化。", "正在": "搭配：“正在”表示动作进行，与“黑了”这样的完成态不搭配。", "当场": "语义：“当场”指在现场当时，与“天渐渐黑了”的逐步变化不符。"}, "sentence_index": 0, "correct_answer": "渐渐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他渐渐就来。", "explanation": "这里应该用〈马上〉。渐渐表示逐步变化，不表示立即发生；表示立刻就来要用“马上”。"}, {"text": "他渐渐摔倒了。", "explanation": "这里应该用〈突然〉。摔倒是瞬间发生的事，不能用表示逐步进行的“渐渐”；这里应该用“突然”。"}, {"text": "他渐渐打了一个喷嚏。", "explanation": "这里应该用〈突然〉。打喷嚏是瞬间发生的事，不能用表示逐步进行的“渐渐”；这里应该用“突然”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渐渐", "is_correct": true, "explanation": "“渐渐”表示逐步变化，与“过了几个月”的时间过程相符。"}, {"text": "霎时", "is_correct": false, "explanation": "语域：“霎时”是书面色彩很重的词，与这句口语叙述不协调；且它指一瞬间，与“过了几个月”冲突。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立即，与“过了几个月”的时间跨度冲突。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时候，不能描述“习惯了这里的生活”这种持续的变化结果。"}], "explanations": {"渐渐": "“渐渐”表示逐步变化，与“过了几个月”的时间过程相符。", "霎时": "语域：“霎时”是书面色彩很重的词，与这句口语叙述不协调；且它指一瞬间，与“过了几个月”冲突。", "马上": "语义：“马上”表示立即，与“过了几个月”的时间跨度冲突。", "偶尔": "语义：“偶尔”表示有时候，不能描述“习惯了这里的生活”这种持续的变化结果。"}, "sentence_index": 6, "correct_answer": "渐渐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我渐渐考上了大学。", "explanation": "这里应该用〈终于〉。考上大学是一次性的结果，不能用表示逐步变化的“渐渐”；这里应该用“终于”。"}, {"text": "他渐渐接了电话。", "explanation": "这里应该用〈立刻〉。接电话是瞬间完成的动作，不能用“渐渐”；这里应该用“立刻”。"}, {"text": "我们渐渐在车站遇见了。", "explanation": "这里应该用〈恰好〉。遇见是偶然发生的一次性事件，不能用“渐渐”表示逐步变化；这里应该用“恰好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气渐渐冷起去了，我们多穿点衣服。", "corrected_sentence": "天气渐渐冷起来了，我们多穿点衣服。", "error_description": "补语错误：表示“逐渐开始并持续”的趋向补语应为“起来”，“起去”不能这样用。正确说法：“天气渐渐冷起来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的病渐渐好起了来。", "corrected_sentence": "他的病渐渐好起来了。", "error_description": "补语错误：趋向补语“起来”不能拆开，“了”应放在“起来”之后，应说“好起来了”，不能说“好起了来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
