INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93790, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "慢慢地；逐步地。", "primary_collocate": null, "pronunciation": "jiàn jiàn", "ipa": "tɕjɛn˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "学了半年，他的汉语渐渐好起来了。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药，她的病渐渐好了。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们渐渐熟悉了，常常一起吃饭。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的生意渐渐好了起来。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "练习多了，我写字渐渐快了。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天跑步，身体渐渐变好了。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚来时我很紧张，现在渐渐放松了。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的路渐渐多了，出门方便了。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她渐渐地爱上了这座小城。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家渐渐接受了这个新办法。", "target_word": "渐渐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "渐渐地", "label": "副词+地"}, {"form": "漸漸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "随时间逐步推进、慢慢发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1ebf27a-bc60-422b-bfea-fa9b711a051c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93790, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "渐渐", "is_correct": true, "explanation": "“渐渐”读 jiàn jiàn，意思是慢慢地、逐步地。"}, {"text": "渐变", "is_correct": false, "explanation": "biàn（b）与 jiàn（j）声母不同，“渐变”意思是逐渐改变。"}, {"text": "尖尖", "is_correct": false, "explanation": "jiān jiān 两个音节都是第一声，与“渐渐”（第四声）声调不同，意思是尖尖的。"}, {"text": "渐现", "is_correct": false, "explanation": "xiàn（x）与 jiàn（j）声母不同，“渐现”意思是逐渐显现。"}, {"text": "渐减", "is_correct": false, "explanation": "第二个音节 jiǎn（第三声）与 jiàn（第四声）声调不同，“渐减”意思是逐渐减少。"}], "explanations": {"渐渐": "“渐渐”读 jiàn jiàn，意思是慢慢地、逐步地。", "渐变": "biàn（b）与 jiàn（j）声母不同，“渐变”意思是逐渐改变。", "尖尖": "jiān jiān 两个音节都是第一声，与“渐渐”（第四声）声调不同，意思是尖尖的。", "渐现": "xiàn（x）与 jiàn（j）声母不同，“渐现”意思是逐渐显现。", "渐减": "第二个音节 jiǎn（第三声）与 jiàn（第四声）声调不同，“渐减”意思是逐渐减少。"}, "sentence_index": null, "correct_answer": "渐渐"}, "level_3": {"options": [{"text": "渐渐", "is_correct": true, "explanation": "“渐渐”表示慢慢地、逐步地变化，与“学了半年”的时间过程相符。"}, {"text": "猛地", "is_correct": false, "explanation": "搭配：“猛地”多修饰突发的动作，不能修饰“好起来”这种逐步的变化。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示马上，与“学了半年”的时间过程冲突。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时候，与“汉语好起来了”这种持续的变化不符。"}], "explanations": {"渐渐": "“渐渐”表示慢慢地、逐步地变化，与“学了半年”的时间过程相符。", "猛地": "搭配：“猛地”多修饰突发的动作，不能修饰“好起来”这种逐步的变化。", "立即": "语义：“立即”表示马上，与“学了半年”的时间过程冲突。", "偶尔": "语义：“偶尔”表示有时候，与“汉语好起来了”这种持续的变化不符。"}, "sentence_index": 0, "correct_answer": "渐渐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她渐渐打碎了杯子。", "explanation": "这里应该用〈突然〉。打碎杯子是瞬间发生的事，不能用表示逐步进行的“渐渐”；这里应该用“突然”。"}, {"text": "他渐渐拿到了冠军。", "explanation": "这里应该用〈终于〉。拿到冠军是一次性的结果，不能用“渐渐”；这里应该用“终于”。"}, {"text": "他渐渐接了电话。", "explanation": "这里应该用〈立刻〉。接电话是瞬间完成的动作，不能用“渐渐”；这里应该用“立刻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渐渐", "is_correct": true, "explanation": "“渐渐”表示逐步变化，与“刚来时……现在”的变化过程相符。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一直不曾，与“现在……放松了”的变化冲突。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续不变，不能与表示变化完成的“放松了”搭配。"}, {"text": "当场", "is_correct": false, "explanation": "语义：“当场”指在现场当时，与“刚来时……现在”的逐步过程不符。"}], "explanations": {"渐渐": "“渐渐”表示逐步变化，与“刚来时……现在”的变化过程相符。", "从来": "语义：“从来”表示一直不曾，与“现在……放松了”的变化冲突。", "一直": "搭配：“一直”表示持续不变，不能与表示变化完成的“放松了”搭配。", "当场": "语义：“当场”指在现场当时，与“刚来时……现在”的逐步过程不符。"}, "sentence_index": 6, "correct_answer": "渐渐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我渐渐就到。", "explanation": "这里应该用〈马上〉。渐渐表示逐步变化，不表示立即发生；表示立刻就到要用“马上”。"}, {"text": "我们渐渐在路上碰到了老同学。", "explanation": "这里应该用〈恰好〉。碰到老同学是偶然发生的一次性事件，不能用“渐渐”；这里应该用“恰好”。"}, {"text": "她渐渐咳了一声。", "explanation": "这里应该用〈突然〉。咳一声是瞬间完成的动作，不能用表示逐步进行的“渐渐”；这里应该用“突然”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的身体渐渐很强壮起来了。", "corrected_sentence": "我的身体渐渐强壮起来了。", "error_description": "程度副词“很”一般不直接修饰与“起来”连用的形容词，“很强壮起来”不自然；应删去“很”，说“我的身体渐渐强壮起来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们渐渐得理解了她的想法。", "corrected_sentence": "我们渐渐地理解了她的想法。", "error_description": "助词错误：“渐渐”作状语修饰动词“理解”，状语后应用助词“地”，不能用“得”（“得”用于动词或形容词后引出补语）。正确说法：“渐渐地理解了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93791, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "讨厌", "is_correct": true, "explanation": "讨厌：表示很不喜欢，与“热爱”相反，“热爱做饭”的反面是“讨厌做饭”。"}, {"text": "观察", "is_correct": false, "explanation": "观察：同为动词，但与“热爱”的任一义项都没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "修理：同为动词，但与“热爱”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：同为动词，但与“热爱”没有反义关系。"}], "correct_answer": "讨厌", "explanations": {"讨厌": "讨厌：表示很不喜欢，与“热爱”相反，“热爱做饭”的反面是“讨厌做饭”。", "观察": "观察：同为动词，但与“热爱”的任一义项都没有反义关系。", "修理": "修理：同为动词，但与“热爱”没有反义关系。", "旅行": "旅行：同为动词，但与“热爱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
