INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93791, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "热爱是特别特别爱，心里很喜欢。", "primary_collocate": null, "pronunciation": "rè ài", "ipa": "ʐɤ˥˩ ai˥˩", "syllable_count": 2, "sentences": [{"text": "我弟弟热爱足球，天天都去踢。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她热爱唱歌，每天都要唱一会儿。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李热爱画画，房间里都是他的画。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸热爱做饭，周末总是做很多菜。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这么热爱游泳，为什么不去比赛？", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就热爱读书，一有空就看书。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同学热爱跑步，下雨也不停。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她热爱小动物，家里养了三只猫。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子热爱玩游戏，一玩就是一下午。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶热爱种花，院子里开满了红花。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "热爱着", "label": "体标"}, {"form": "热爱过", "label": "体标"}, {"form": "熱愛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "热爱：对运动、唱歌、读书等爱好特别喜欢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd05d25bf-15fb-4699-a34e-f76e1fe1de8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93791, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热爱", "is_correct": true, "explanation": "热爱：特别喜欢，与“天天都去踢”的投入相符。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示反感，与“天天都去踢”相矛盾。"}, {"text": "反对", "is_correct": false, "explanation": "搭配：“反对”针对做法或决定，不说反对足球。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”表示不再坚持，与“天天都去踢”相矛盾。"}], "explanations": {"热爱": "热爱：特别喜欢，与“天天都去踢”的投入相符。", "讨厌": "语义：“讨厌”表示反感，与“天天都去踢”相矛盾。", "反对": "搭配：“反对”针对做法或决定，不说反对足球。", "放弃": "语义：“放弃”表示不再坚持，与“天天都去踢”相矛盾。"}, "sentence_index": 0, "correct_answer": "热爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈热爱这件红毛衣，穿起来很暖和。", "explanation": "这里应该用〈喜欢〉。热爱表示深厚强烈的感情，多用于爱好、事业、人，不用于一件毛衣这样的小物件。"}, {"text": "公司很热爱员工的意见。", "explanation": "这里应该用〈重视〉。重视用于看重意见、成绩等事项，热爱的对象是人、爱好或事业。"}, {"text": "我很热爱这次宝贵的机会。", "explanation": "这里应该用〈珍惜〉。珍惜指爱护、不浪费机会，热爱用于对爱好、人、事业的深厚感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93791, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热爱", "is_correct": true, "explanation": "热爱：特别喜欢，与“下雨也不停”的坚持相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，与“下雨也不停”的坚持相矛盾。"}, {"text": "躲避", "is_correct": false, "explanation": "语义：“躲避”表示避开，与“下雨也不停”的坚持相矛盾。"}, {"text": "尊敬", "is_correct": false, "explanation": "搭配：“尊敬”的对象一般是人，不说尊敬跑步。"}], "explanations": {"热爱": "热爱：特别喜欢，与“下雨也不停”的坚持相符。", "拒绝": "语义：“拒绝”表示不接受，与“下雨也不停”的坚持相矛盾。", "躲避": "语义：“躲避”表示避开，与“下雨也不停”的坚持相矛盾。", "尊敬": "搭配：“尊敬”的对象一般是人，不说尊敬跑步。"}, "sentence_index": 6, "correct_answer": "热爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我热爱明天的数学考试。", "explanation": "这里应该用〈害怕〉。热爱是深深喜爱，面对考试应表示紧张或害怕，热爱只用于人、爱好或事业。"}, {"text": "我热爱桌上那份发霉的面包。", "explanation": "这里应该用〈讨厌〉。热爱是深深喜爱，发霉的食物令人厌恶，不能用热爱。"}, {"text": "我热爱这台摔碎的手机。", "explanation": "这里应该用〈心疼〉。热爱是深深喜爱，摔碎的手机令人心疼，不能用热爱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93791, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐把热爱跳舞，每周都去练习。", "corrected_sentence": "我姐姐热爱跳舞，每周都去练习。", "error_description": "多加了“把”：“热爱”是表示感情的动词，不用于把字句，应说“我姐姐热爱跳舞”，不说“把热爱跳舞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93791, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹从小热爱了画画，每天都要画一会儿。", "corrected_sentence": "妹妹从小热爱画画，每天都要画一会儿。", "error_description": "错误：“热爱了”，多加了“了”。正确：“热爱”。“热爱”表示持续的感情，不能加“了”表示完成；想说明过去曾有过这种感情，可用“热爱过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
