INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93793, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "男生是男孩子，常常是指学校里的男同学。", "primary_collocate": null, "pronunciation": "nán shēng", "ipa": "nan˧˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "我们班有二十个男生。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男生们在操场上踢足球。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请男生去搬桌子。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校的男生宿舍很旧。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女生跳舞，男生唱歌。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，几个男生留在教室里打扫。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们班最高的男生。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体育课上，男生跑一千米，女生跑八百米。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里的男生都喜欢打篮球。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的男生坐在我旁边。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "男生们", "label": "复数"}], "register": "口语", "sense_fingerprint": "学校里的男同学", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1ebf27a-bc60-422b-bfea-fa9b711a051c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93793, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男人", "is_correct": false, "explanation": "语义：“男人”指成年男性，班级里不会这样称呼学生。"}, {"text": "男生", "is_correct": true, "explanation": "正确：“男生”指学校里的男同学，与“我们班有二十个”搭配。"}, {"text": "男士", "is_correct": false, "explanation": "语域：“男士”偏正式、礼貌，课堂叙述中不用它来数学生。"}, {"text": "老人", "is_correct": false, "explanation": "语义：“老人”指年长的人，与班里的学生身份不符。"}], "explanations": {"男人": "语义：“男人”指成年男性，班级里不会这样称呼学生。", "男生": "正确：“男生”指学校里的男同学，与“我们班有二十个”搭配。", "男士": "语域：“男士”偏正式、礼貌，课堂叙述中不用它来数学生。", "老人": "语义：“老人”指年长的人，与班里的学生身份不符。"}, "sentence_index": 0, "correct_answer": "男生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她是我们班的男生。", "explanation": "这里应该用〈女生〉。“男生”指男同学，她是女性，不能用“男生”来指称。"}, {"text": "这位男生是我的叔叔。", "explanation": "这里应该用〈男士〉。“男生”指学校里的男同学，不能用来指成年的叔叔。"}, {"text": "那只小狗是男生。", "explanation": "这里应该用〈公〉。“男生”只指人，指动物的雄性要用“公”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93793, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女生", "is_correct": false, "explanation": "语义：“女生”指女同学，与“他”的性别矛盾。"}, {"text": "女士", "is_correct": false, "explanation": "语域：“女士”是礼貌称呼，且与“他”的性别矛盾，课堂叙述中不用。"}, {"text": "男生", "is_correct": true, "explanation": "正确：“男生”指班里的男同学，与“他是我们班最高的”搭配。"}, {"text": "大人", "is_correct": false, "explanation": "搭配：“大人”指成年人，不能说“我们班最高的大人”。"}], "explanations": {"女生": "语义：“女生”指女同学，与“他”的性别矛盾。", "女士": "语域：“女士”是礼貌称呼，且与“他”的性别矛盾，课堂叙述中不用。", "男生": "正确：“男生”指班里的男同学，与“他是我们班最高的”搭配。", "大人": "搭配：“大人”指成年人，不能说“我们班最高的大人”。"}, "sentence_index": 6, "correct_answer": "男生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "问卷上的“性别”一栏写着：男生。", "explanation": "这里应该用〈男性〉。“男生”指学生，表示性别时应说“男性”。"}, {"text": "这位男生已经退休二十年了。", "explanation": "这里应该用〈老先生〉。“男生”指学校里的男同学，已经退休多年的老人不能用“男生”指称。"}, {"text": "这位男生是我们的数学老师。", "explanation": "这里应该用〈教师〉。“男生”指学生，讲课的人不能用“男生”指称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93793, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教室里有三十只男生在打扫卫生。", "corrected_sentence": "教室里有三十个男生在打扫卫生。", "error_description": "“男生”指人，量词应用“个”；“只”用于动物，这里误用。正确说法：“三十个男生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93793, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "操场上站着三个男生们。", "corrected_sentence": "操场上站着三个男生。", "error_description": "“们”表示复数，不能与数词“三个”同时使用。正确说法：“三个男生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
