INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93794, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "泛指年轻的男性（不限于学生）。", "primary_collocate": null, "pronunciation": "nán shēng", "ipa": "nan˧˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "那个男生在街上等朋友。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司新来了一个年轻的男生。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡店里的男生笑着问我喝什么。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个二十岁的男生帮我拿行李。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个男生看起来很有礼貌。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁上有个男生给老人让座。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隔壁住着一个爱唱歌的男生。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个男生背着吉他走进了商店。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说她喜欢笑起来很好看的男生。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上，男生们都穿着西装。", "target_word": "男生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "男生们", "label": "复数"}], "register": "口语", "sense_fingerprint": "泛指年轻的男性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1ebf27a-bc60-422b-bfea-fa9b711a051c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大楼", "is_correct": false, "explanation": "配价：“等”需要有生命的主语，“大楼”是建筑，不能在街上等朋友。"}, {"text": "男生", "is_correct": true, "explanation": "正确：“男生”指年轻的男性，可以在街上等朋友。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”是交通工具，不会在街上等朋友。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“桌子”没有生命，不能主动等人。"}], "explanations": {"大楼": "配价：“等”需要有生命的主语，“大楼”是建筑，不能在街上等朋友。", "男生": "正确：“男生”指年轻的男性，可以在街上等朋友。", "汽车": "语义：“汽车”是交通工具，不会在街上等朋友。", "桌子": "配价：“桌子”没有生命，不能主动等人。"}, "sentence_index": 0, "correct_answer": "男生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位男生已经当了爷爷，有三个孙子。", "explanation": "这里应该用〈老人〉。“男生”指年轻的男性，已经当了爷爷的人不能用“男生”指称。"}, {"text": "一位八十岁的男生在公园里下棋。", "explanation": "这里应该用〈老大爷〉。“男生”指年轻的男性，八十岁的老人不能用它。"}, {"text": "一个二十岁的男生是我的女朋友。", "explanation": "这里应该用〈女生〉。“男生”指年轻的男性，“我的女朋友”是女性，不能用“男生”来指称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房子", "is_correct": false, "explanation": "语义：“房子”是建筑，不会唱歌，与“爱唱歌的”矛盾。"}, {"text": "电脑", "is_correct": false, "explanation": "配价：“住着”需要有生命的主语，“电脑”不能住。"}, {"text": "男生", "is_correct": true, "explanation": "正确：“男生”指年轻的男性，可以住在隔壁、爱唱歌。"}, {"text": "足球", "is_correct": false, "explanation": "搭配：“爱唱歌的”一般修饰人，不能修饰“足球”。"}], "explanations": {"房子": "语义：“房子”是建筑，不会唱歌，与“爱唱歌的”矛盾。", "电脑": "配价：“住着”需要有生命的主语，“电脑”不能住。", "男生": "正确：“男生”指年轻的男性，可以住在隔壁、爱唱歌。", "足球": "搭配：“爱唱歌的”一般修饰人，不能修饰“足球”。"}, "sentence_index": 6, "correct_answer": "男生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "问卷上的“性别”一栏请填：男生。", "explanation": "这里应该用〈男性〉。“男生”指年轻的男性，表示性别时应说“男性”。"}, {"text": "这位男生是我的妈妈。", "explanation": "这里应该用〈女性〉。“男生”指年轻的男性，指女性长辈不能用“男生”。"}, {"text": "那只小猫是我们家的男生。", "explanation": "这里应该用〈公〉。“男生”指年轻的男性，猫不能用“男生”指称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街角站着一只年轻的男生，他在等朋友。", "corrected_sentence": "街角站着一个年轻的男生，他在等朋友。", "error_description": "“男生”指人，量词应用“个”（或“位”）；“只”用于动物，这里误用。正确说法：“一个年轻的男生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站旁边有几个年轻的男生们在聊天。", "corrected_sentence": "车站旁边有几个年轻的男生在聊天。", "error_description": "“们”表示复数，不能与“几个”同时使用。正确说法：“几个年轻的男生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
