INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93795, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "疫情是很多人生了同一种病，病传得很快的情况。", "primary_collocate": null, "pronunciation": "yì qíng", "ipa": "i˥˩ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个城市的疫情很严重。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情让很多人不能出门。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为疫情，学校关门了。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生每天都在关注疫情。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情过去以后，我想去旅行。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情期间，我们在家上网课。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家乡又有了新的疫情。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情发生后，大家都戴口罩。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次疫情影响了很多行业。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府每天公布疫情的消息。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}], "register": "中性", "sense_fingerprint": "很多人得同一种病、病传得很快的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8eb21289-7e21-4025-8e45-bb69550d4010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93795, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疫情", "is_correct": true, "explanation": "“疫情”指很多人患同一种病、病传得很快的情况，可以说“很严重”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“严重”不能用来形容“天气”，不说“天气很严重”。"}, {"text": "会议", "is_correct": false, "explanation": "语义：会议不是可以“严重”的情况，与城市层面的状况不合。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气属于个人性格，不能作为整座城市的“严重”状况。"}], "explanations": {"疫情": "“疫情”指很多人患同一种病、病传得很快的情况，可以说“很严重”。", "天气": "搭配：“严重”不能用来形容“天气”，不说“天气很严重”。", "会议": "语义：会议不是可以“严重”的情况，与城市层面的状况不合。", "脾气": "语义：脾气属于个人性格，不能作为整座城市的“严重”状况。"}, "sentence_index": 0, "correct_answer": "疫情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生每天都在关注病人的疫情。", "explanation": "这里应该用〈病情〉。“疫情”指很多人患同一种病的流行情况，指某个病人的病况应说“病情”。"}, {"text": "我昨天得了疫情，在家休息了一天。", "explanation": "“疫情”指流行的情况，不是一种病，不能说“得了疫情”，应说得了某种病。"}, {"text": "这家餐厅的疫情很好吃。", "explanation": "这里“疫情”指传染病的流行情况，不是食物，不能用来评价味道；评价饭菜的味道应说〈菜〉的口感。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93795, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疫情", "is_correct": true, "explanation": "“疫情”指流行病的情况，与“家乡又有了新的……”的语境相合。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“数学”是学科，不是家乡可以“又有了新的”出现的情况。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“有了新的体重”不成立，体重不说“有了新的”某种状况。"}, {"text": "语文", "is_correct": false, "explanation": "语义：语文是学科，不能说家乡“又有了新的语文”。"}], "explanations": {"疫情": "“疫情”指流行病的情况，与“家乡又有了新的……”的语境相合。", "数学": "语义：“数学”是学科，不是家乡可以“又有了新的”出现的情况。", "体重": "搭配：“有了新的体重”不成立，体重不说“有了新的”某种状况。", "语文": "语义：语文是学科，不能说家乡“又有了新的语文”。"}, "sentence_index": 6, "correct_answer": "疫情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府要开放疫情，让学生回学校。", "explanation": "这里应该用〈城市〉。“开放”用于城市、地区，不能用于疫情；疫情应说“控制”或“解除”。"}, {"text": "他最近的疫情很好，每天都很开心。", "explanation": "这里应该用〈心情〉。“疫情”指传染病的流行情况，表示情绪状态应说〈心情〉。"}, {"text": "我们要吃掉疫情，才能安心出门。", "explanation": "“吃掉”的对象应是食物，疫情不能被“吃掉”，应说“控制”或“消除”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93795, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市刚经历了一个疫情。", "corrected_sentence": "这座城市刚经历了一场疫情。", "error_description": "量词错误：“疫情”应配量词“场”，说“一场疫情”，不能说“一个疫情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93795, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的城市又出现了新的疫情的。", "corrected_sentence": "他的城市又出现了新的疫情。", "error_description": "多余成分：“疫情”后面不能加“的”，应说“新的疫情”，句末不能再接“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
