INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93796, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93796, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "传染病流行的情况。", "primary_collocate": null, "pronunciation": "yì qíng", "ipa": "i˥˩ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "医院每天报告疫情的变化。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情得到了控制。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的疫情没有去年严重。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要防止疫情扩散，勤洗手。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情严重的地方，要少出门。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说疫情还没有结束。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里说疫情正在好转。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情传到了别的国家。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了防止疫情扩大，学校停课了。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天疫情结束了，公园又开了。", "target_word": "疫情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}], "register": "中性", "sense_fingerprint": "传染病流行、发展、控制的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8eb21289-7e21-4025-8e45-bb69550d4010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疫情", "is_correct": true, "explanation": "“疫情”指传染病流行的情况，与“报告……的变化”相合。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：医院报告的是传染病流行的情况，不是个人脾气的变化。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是医院报告的对象，与传染病的语境不合。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“报告脚步的变化”搭配不当，脚步不能作为报告的对象。"}], "explanations": {"疫情": "“疫情”指传染病流行的情况，与“报告……的变化”相合。", "脾气": "语义：医院报告的是传染病流行的情况，不是个人脾气的变化。", "作业": "语义：作业不是医院报告的对象，与传染病的语境不合。", "脚步": "搭配：“报告脚步的变化”搭配不当，脚步不能作为报告的对象。"}, "sentence_index": 0, "correct_answer": "疫情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位病人的疫情已经好转，可以出院了。", "explanation": "这里应该用〈病情〉。“疫情”指传染病的流行情况，指某个病人的病况应说“病情”。"}, {"text": "这次展览的疫情很有意思。", "explanation": "这里“疫情”指传染病的流行情况，不能用来评价展览；说展览有意思应用〈内容〉。"}, {"text": "我们要开放疫情，让游客进来参观。", "explanation": "这里应该用〈公园〉。“开放”用于公园、地区等场所，不能用于疫情；疫情应说“控制”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疫情", "is_correct": true, "explanation": "“疫情”指传染病流行的情况，新闻中可以说它“正在好转”。"}, {"text": "家务", "is_correct": false, "explanation": "语义：新闻报道不会说“家务正在好转”，与语境不合。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：体重不说“好转”，“好转”不能用于体重。"}, {"text": "门口", "is_correct": false, "explanation": "语义：“门口”不是新闻会报道“正在好转”的对象。"}], "explanations": {"疫情": "“疫情”指传染病流行的情况，新闻中可以说它“正在好转”。", "家务": "语义：新闻报道不会说“家务正在好转”，与语境不合。", "体重": "搭配：体重不说“好转”，“好转”不能用于体重。", "门口": "语义：“门口”不是新闻会报道“正在好转”的对象。"}, "sentence_index": 6, "correct_answer": "疫情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天得了疫情，在床上躺了一天。", "explanation": "“疫情”指传染病流行的情况，不是一种病，不能说“得了疫情”；这里应该用〈感冒〉。"}, {"text": "今天的疫情很晴朗，我们去郊游吧。", "explanation": "这里“疫情”指传染病的流行情况，不能用“晴朗”形容；说天气应用〈天气〉。"}, {"text": "这家店的疫情很便宜，大家可以放心买。", "explanation": "这里“疫情”指传染病的流行情况，不是商品，不能说“便宜”；这里应该用〈东西〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家去年经历了一个疫情。", "corrected_sentence": "这个国家去年经历了一场疫情。", "error_description": "量词错误：“疫情”应配量词“场”，说“一场疫情”，不能说“一个疫情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市的疫情的很快得到了控制。", "corrected_sentence": "这座城市的疫情很快得到了控制。", "error_description": "多余成分：“疫情”后面不能加“的”再接副词“很快”，应说“疫情很快得到了控制”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
