INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93800, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "靠头顶旋转的旋翼产生升力，能垂直起降的飞行器。", "primary_collocate": null, "pronunciation": "zhí shēng jī", "ipa": "tʂʅ³⁵ ʂɤŋ⁵⁵ tɕi⁵⁵", "syllable_count": 3, "sentences": [{"text": "直升机靠头顶的旋翼产生升力。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "直升机可以在空中停住不动。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生坐直升机赶到了山里。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "直升机能在很小的地方起飞和降落。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消防队用直升机把水运到山上灭火。", "target_word": "直升机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直升机不需要长长的跑道。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水太大，救援队开着直升机去救人。", "target_word": "直升机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直升机的旋翼转得很快，声音很大。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这架直升机最多能坐六个人。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里没有路，只能用直升机运东西。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "架", "label": "量词"}, {"form": "武装直升机", "label": "复合"}], "register": "中性", "sense_fingerprint": "靠旋翼产生升力、能垂直起降和空中悬停的飞行器（技术说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f5f24a-08cb-4f02-a962-6cffc7a480b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93800, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直升机", "is_correct": true, "explanation": "正确：直升机靠头顶的旋翼产生升力，与句中描述相合。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：飞机靠机翼产生升力，不靠旋翼，“飞机靠头顶的旋翼”不符合事实。"}, {"text": "气球", "is_correct": false, "explanation": "语义：气球靠浮力升空，不靠旋翼产生升力。"}, {"text": "滑翔机", "is_correct": false, "explanation": "搭配：“旋翼”是直升机的部件，滑翔机搭配的是机翼，不说“靠旋翼”。"}], "explanations": {"直升机": "正确：直升机靠头顶的旋翼产生升力，与句中描述相合。", "飞机": "语义：飞机靠机翼产生升力，不靠旋翼，“飞机靠头顶的旋翼”不符合事实。", "气球": "语义：气球靠浮力升空，不靠旋翼产生升力。", "滑翔机": "搭配：“旋翼”是直升机的部件，滑翔机搭配的是机翼，不说“靠旋翼”。"}, "sentence_index": 0, "correct_answer": "直升机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "直升机的机翼很长，能借助气流飞得很远。", "explanation": "这里应该用〈飞机〉。直升机靠头顶的旋翼产生升力，不说“机翼”。"}, {"text": "直升机靠加热的空气产生浮力，慢慢升起。", "explanation": "这里应该用〈热气球〉。直升机靠旋翼产生升力，不靠浮力。"}, {"text": "救援队开着直升机驶进港口，准备出海救人。", "explanation": "这里应该用〈轮船〉。“驶进港口”是船只的行动，直升机在空中飞，不说“驶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直升机", "is_correct": true, "explanation": "正确：救援队开着直升机去救人，与“河水太大”的情境相合。"}, {"text": "大桥", "is_correct": false, "explanation": "语义：大桥是建筑，不是交通工具，不能“开着”去救人。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“书包”不能作交通工具，“开着书包”不搭配。"}, {"text": "稻田", "is_correct": false, "explanation": "语义：稻田是农田，不是交通工具，不能“开着”去救人。"}], "explanations": {"直升机": "正确：救援队开着直升机去救人，与“河水太大”的情境相合。", "大桥": "语义：大桥是建筑，不是交通工具，不能“开着”去救人。", "书包": "搭配：“书包”不能作交通工具，“开着书包”不搭配。", "稻田": "语义：稻田是农田，不是交通工具，不能“开着”去救人。"}, "sentence_index": 6, "correct_answer": "直升机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "直升机在坑坑洼洼的山路上颠簸前进。", "explanation": "这里应该用〈卡车〉。“颠簸”和“山路”是地面车辆的情境，直升机是在空中飞。"}, {"text": "直升机在湖面上慢慢划着，船夫唱着歌。", "explanation": "这里应该用〈小船〉。“划”是用桨推动船只前进，直升机不用桨划行。"}, {"text": "直升机在铁轨上飞快地跑，汽笛响个不停。", "explanation": "这里应该用〈火车〉。直升机在空中飞，不在铁轨上跑，“汽笛”是火车的声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士骑直升机去了海岛。", "corrected_sentence": "护士坐直升机去了海岛。", "error_description": "错误形式：“骑直升机”。正确形式：“坐直升机”。“骑”用于自行车、马等跨坐的东西，乘直升机要说“坐”或“乘”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次救援用了一辆直升机，很快找到了人。", "corrected_sentence": "这次救援用了一架直升机，很快找到了人。", "error_description": "错误形式：“一辆直升机”。正确形式：“一架直升机”。直升机的量词是“架”，“辆”只用于有轮子的车。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93801, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "祸", "is_correct": true, "explanation": "祸：灾祸，与“福”构成反义。"}, {"text": "草地", "is_correct": false, "explanation": "与“福”无反义关系：草地指长满草的土地。"}, {"text": "钟表", "is_correct": false, "explanation": "与“福”无反义关系：钟表指显示时间的器具。"}, {"text": "课本", "is_correct": false, "explanation": "与“福”无反义关系：课本指学校里用来学习的书。"}], "correct_answer": "祸", "explanations": {"祸": "祸：灾祸，与“福”构成反义。", "草地": "与“福”无反义关系：草地指长满草的土地。", "钟表": "与“福”无反义关系：钟表指显示时间的器具。", "课本": "与“福”无反义关系：课本指学校里用来学习的书。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93801, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "祸", "is_correct": true, "explanation": "祸：灾祸，与“福”构成反义。"}, {"text": "玻璃", "is_correct": false, "explanation": "与“福”无反义关系：玻璃指透明的硬质材料。"}, {"text": "地毯", "is_correct": false, "explanation": "与“福”无反义关系：地毯指铺在地上的织物。"}, {"text": "钢笔", "is_correct": false, "explanation": "与“福”无反义关系：钢笔指用墨水写字的笔。"}], "correct_answer": "祸", "explanations": {"祸": "祸：灾祸，与“福”构成反义。", "玻璃": "与“福”无反义关系：玻璃指透明的硬质材料。", "地毯": "与“福”无反义关系：地毯指铺在地上的织物。", "钢笔": "与“福”无反义关系：钢笔指用墨水写字的笔。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93801, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "福是很好的运气和平安快乐。", "primary_collocate": null, "pronunciation": "fú", "ipa": "fu³⁵", "syllable_count": 1, "sentences": [{"text": "一家人平平安安，就是福。", "target_word": "福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们说，健康是最大的福。", "target_word": "福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工程给全村人带来好日子，真是大家的福。", "target_word": "福", "complexity_tier": "T3", "furigana": "zhè ge gōng chéng gěi quán cūn rén dài lái hǎo rì zi, zhēn shì dà jiā de fú.", "sentence_source": "generated"}, {"text": "人在福中不知福。", "target_word": "福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人常说，吃得下，睡得好，就是福。", "target_word": "福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对我来说，孩子们快乐就是福。", "target_word": "福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "福和祸有时候只差一步。", "target_word": "福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说能活着回家就是福。", "target_word": "福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的好日子，是大家的福。", "target_word": "福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要只想自己的福，也要想想别人。", "target_word": "福", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幸福", "label": "复合词"}, {"form": "福气", "label": "复合词"}], "register": "中性", "sense_fingerprint": "指平安快乐的好生活，常说平安是福、造福、福和祸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ac5386f-a5c3-4a5f-b7d7-6ad2731789e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93801, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "富", "is_correct": false, "explanation": "fù（第四声）与 fú（第二声）声调不同，意思是富裕。"}, {"text": "福", "is_correct": true, "explanation": "福 fú：平安快乐的好生活。"}, {"text": "府", "is_correct": false, "explanation": "fǔ（第三声）与 fú（第二声）声调不同，意思是政府或府邸。"}, {"text": "腐", "is_correct": false, "explanation": "fǔ（第三声）与 fú（第二声）声调不同，意思是腐烂。"}, {"text": "父", "is_correct": false, "explanation": "fù（第四声）与 fú（第二声）声调不同，意思是父亲。"}, {"text": "夫", "is_correct": false, "explanation": "fū（第一声）与 fú（第二声）声调不同，意思是丈夫。"}], "explanations": {"富": "fù（第四声）与 fú（第二声）声调不同，意思是富裕。", "福": "福 fú：平安快乐的好生活。", "府": "fǔ（第三声）与 fú（第二声）声调不同，意思是政府或府邸。", "腐": "fǔ（第三声）与 fú（第二声）声调不同，意思是腐烂。", "父": "fù（第四声）与 fú（第二声）声调不同，意思是父亲。", "夫": "fū（第一声）与 fú（第二声）声调不同，意思是丈夫。"}, "sentence_index": null, "correct_answer": "福"}, "level_3": {"options": [{"text": "灾", "is_correct": false, "explanation": "语义：灾指灾难，与“平平安安”相反，句意不通。"}, {"text": "福", "is_correct": true, "explanation": "福：平安快乐的好生活，与“平平安安”相合。"}, {"text": "锅", "is_correct": false, "explanation": "搭配：“就是锅”不能表示平平安安的好日子，不是常见搭配。"}, {"text": "病", "is_correct": false, "explanation": "语义：病指身体不好，与“平平安安”相矛盾。"}], "explanations": {"灾": "语义：灾指灾难，与“平平安安”相反，句意不通。", "福": "福：平安快乐的好生活，与“平平安安”相合。", "锅": "搭配：“就是锅”不能表示平平安安的好日子，不是常见搭配。", "病": "语义：病指身体不好，与“平平安安”相矛盾。"}, "sentence_index": 0, "correct_answer": "福"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司每年都给员工很多福，大家都很满意。", "explanation": "这里应该用〈福利〉。福指平安快乐的生活，不指公司为员工提供的待遇。"}, {"text": "这份工作的福很高，大家都想去。", "explanation": "这里应该用〈报酬〉。福指很好的运气和平安快乐，不指工作的薪水；说报酬高要用报酬。"}, {"text": "这家店的福很便宜，大家都来买。", "explanation": "这里应该用〈商品〉。福指平安快乐的好生活，不指店里卖的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93801, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "父", "is_correct": false, "explanation": "fù（第四声）与 fú（第二声）声调不同，意思是父亲。"}, {"text": "福", "is_correct": true, "explanation": "福 fú：平安快乐的好生活。"}, {"text": "湖", "is_correct": false, "explanation": "hú 与 fú 声母不同（h 与 f），意思是湖。"}, {"text": "斧", "is_correct": false, "explanation": "fǔ（第三声）与 fú（第二声）声调不同，意思是斧头。"}, {"text": "夫", "is_correct": false, "explanation": "fū（第一声）与 fú（第二声）声调不同，意思是丈夫。"}], "explanations": {"父": "fù（第四声）与 fú（第二声）声调不同，意思是父亲。", "福": "福 fú：平安快乐的好生活。", "湖": "hú 与 fú 声母不同（h 与 f），意思是湖。", "斧": "fǔ（第三声）与 fú（第二声）声调不同，意思是斧头。", "夫": "fū（第一声）与 fú（第二声）声调不同，意思是丈夫。"}, "sentence_index": null, "correct_answer": "福"}, "level_3": {"options": [{"text": "桌", "is_correct": false, "explanation": "语义：桌是家具，与句中“福和祸”的意思不相合。"}, {"text": "福", "is_correct": true, "explanation": "福：平安快乐的好生活，与“祸”相对，句意通顺。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是遮雨用的东西，与“福和祸”的意思不相合。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“饭”不能与“祸”组成这样表示吉凶对举的说法。"}], "explanations": {"桌": "语义：桌是家具，与句中“福和祸”的意思不相合。", "福": "福：平安快乐的好生活，与“祸”相对，句意通顺。", "雨伞": "语义：雨伞是遮雨用的东西，与“福和祸”的意思不相合。", "饭": "搭配：“饭”不能与“祸”组成这样表示吉凶对举的说法。"}, "sentence_index": 6, "correct_answer": "福"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每天走路对身体很有福，大家都应该坚持。", "explanation": "这里应该用〈好处〉。福指平安快乐的生活，不说“对身体有福”，讲益处要用好处。"}, {"text": "这次投资的福很高，每个人都赚了钱。", "explanation": "这里应该用〈收益〉。福指平安快乐的好生活，不指投资赚来的钱，讲赚来的钱要用收益。"}, {"text": "这台旧冰箱的福很好，陪我们过了十年。", "explanation": "这里应该用〈质量〉。福指平安快乐的好生活，不指冰箱的好坏；讲东西的好坏要用质量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "只要家人都身体健康，对我来说就是最大福。", "corrected_sentence": "只要家人都身体健康，对我来说就是最大的福。", "error_description": "“最大”后面要加“的”，说“最大的福”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个人能健健康康地过日子，就很福。", "corrected_sentence": "一个人能健健康康地过日子，就是福。", "error_description": "“福”是名词，不能直接受程度副词“很”修饰，应说“就是福”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93802, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "祸", "is_correct": true, "explanation": "祸：灾祸，与“福”构成反义。"}, {"text": "信件", "is_correct": false, "explanation": "与“福”无反义关系：信件指写给别人的书信。"}, {"text": "河流", "is_correct": false, "explanation": "与“福”无反义关系：河流指流动的水体。"}, {"text": "窗户", "is_correct": false, "explanation": "与“福”无反义关系：窗户指墙上透光通气的开口。"}], "correct_answer": "祸", "explanations": {"祸": "祸：灾祸，与“福”构成反义。", "信件": "与“福”无反义关系：信件指写给别人的书信。", "河流": "与“福”无反义关系：河流指流动的水体。", "窗户": "与“福”无反义关系：窗户指墙上透光通气的开口。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93802, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "祸", "is_correct": true, "explanation": "祸：灾祸，与“福”构成反义。"}, {"text": "桌子", "is_correct": false, "explanation": "与“福”无反义关系：桌子指放东西的家具。"}, {"text": "海洋", "is_correct": false, "explanation": "与“福”无反义关系：海洋指大片的咸水区域。"}, {"text": "手套", "is_correct": false, "explanation": "与“福”无反义关系：手套指戴在手上的御寒或防护用品。"}], "correct_answer": "祸", "explanations": {"祸": "祸：灾祸，与“福”构成反义。", "桌子": "与“福”无反义关系：桌子指放东西的家具。", "海洋": "与“福”无反义关系：海洋指大片的咸水区域。", "手套": "与“福”无反义关系：手套指戴在手上的御寒或防护用品。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93802, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "幸福；好运气。也指福气。", "primary_collocate": null, "pronunciation": "fú", "ipa": "fu³⁵", "syllable_count": 1, "sentences": [{"text": "这么好的老公，是你这辈子的福。", "target_word": "福", "complexity_tier": "T3", "furigana": "zhè me hǎo de lǎo gōng, shì nǐ zhè bèi zi de fú.", "sentence_source": "generated"}, {"text": "奶奶年轻时吃了很多苦，如今终于能享受晚年的福。", "target_word": "福", "complexity_tier": "T3", "furigana": "nǎi nai nián qīng shí chī le hěn duō kǔ, rú jīn zhōng yú néng xiǎng shòu wǎn nián de fú.", "sentence_source": "generated"}, {"text": "孩子这么听话，真是你的福。", "target_word": "福", "complexity_tier": "T3", "furigana": "hái zi zhè me tīng huà, zhēn shì nǐ de fú.", "sentence_source": "generated"}, {"text": "她命不好，没福看到孙子长大。", "target_word": "福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，生在好时代，是我们年轻人的福。", "target_word": "福", "complexity_tier": "T3", "furigana": "lǎo rén shuō, shēng zài hǎo shí dài, shì wǒ men nián qīng rén de fú.", "sentence_source": "generated"}, {"text": "爸爸退休后在家过清闲日子，这是他晚年的福。", "target_word": "福", "complexity_tier": "T3", "furigana": "bà ba tuì xiū hòu zài jiā guò qīng xián rì zi, zhè shì tā wǎn nián de fú.", "sentence_source": "generated"}, {"text": "你们能一起长大，是你们的福。", "target_word": "福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我能遇到这么好的老师，真是我的福。", "target_word": "福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他娶了这么好的妻子，这是他一生的福。", "target_word": "福", "complexity_tier": "T3", "furigana": "tā qǔ le zhè me hǎo de qī zi, zhè shì tā yì shēng de fú.", "sentence_source": "generated"}, {"text": "年轻时吃过苦，老了能安享晚年，这是最大的福。", "target_word": "福", "complexity_tier": "T3", "furigana": "nián qīng shí chī guò kǔ, lǎo le néng ān xiǎng wǎn nián, zhè shì zuì dà de fú.", "sentence_source": "generated"}], "morphological_forms": [{"form": "福气", "label": "复合词"}, {"form": "享福", "label": "复合词"}], "register": "中性", "sense_fingerprint": "指人命好、有福气，常说有福、享福、没福", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ac5386f-a5c3-4a5f-b7d7-6ad2731789e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93802, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "富", "is_correct": false, "explanation": "fù（第四声）与 fú（第二声）声调不同，意思是富裕。"}, {"text": "福", "is_correct": true, "explanation": "福 fú：福分、福气，指一个人命好、有福。"}, {"text": "府", "is_correct": false, "explanation": "fǔ（第三声）与 fú（第二声）声调不同，意思是政府或府邸。"}, {"text": "夫", "is_correct": false, "explanation": "fū（第一声）与 fú（第二声）声调不同，意思是丈夫。"}, {"text": "湖", "is_correct": false, "explanation": "hú 与 fú 声母不同（h 与 f），意思是湖。"}, {"text": "腐", "is_correct": false, "explanation": "fǔ（第三声）与 fú（第二声）声调不同，意思是腐烂。"}], "explanations": {"富": "fù（第四声）与 fú（第二声）声调不同，意思是富裕。", "福": "福 fú：福分、福气，指一个人命好、有福。", "府": "fǔ（第三声）与 fú（第二声）声调不同，意思是政府或府邸。", "夫": "fū（第一声）与 fú（第二声）声调不同，意思是丈夫。", "湖": "hú 与 fú 声母不同（h 与 f），意思是湖。", "腐": "fǔ（第三声）与 fú（第二声）声调不同，意思是腐烂。"}, "sentence_index": null, "correct_answer": "福"}, "level_3": {"options": [{"text": "苦", "is_correct": false, "explanation": "语义：苦指辛苦、痛苦，与“这么好的老公”的好处相反，句意不通。"}, {"text": "福", "is_correct": true, "explanation": "福：福分、福气，指命好、有福的好处，与句中的“好老公”相合。"}, {"text": "祸", "is_correct": false, "explanation": "语义：祸指灾祸，与“这么好的老公”相矛盾，句意不通。"}, {"text": "锅", "is_correct": false, "explanation": "搭配：“这辈子的锅”不是常见搭配，不能表示好处。"}], "explanations": {"苦": "语义：苦指辛苦、痛苦，与“这么好的老公”的好处相反，句意不通。", "福": "福：福分、福气，指命好、有福的好处，与句中的“好老公”相合。", "祸": "语义：祸指灾祸，与“这么好的老公”相矛盾，句意不通。", "锅": "搭配：“这辈子的锅”不是常见搭配，不能表示好处。"}, "sentence_index": 0, "correct_answer": "福"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司每年给员工提供很好的福，大家都很满意。", "explanation": "这里应该用〈福利〉。福指个人的福分、命好，不指公司为员工提供的待遇。"}, {"text": "他的福特别好，从不发火。", "explanation": "这里应该用〈脾气〉。福指福分、好运，不指性格；说脾气好要用脾气。"}, {"text": "这些旧书的福很大，我们每天都在读。", "explanation": "这里应该用〈有用〉。福指福分、命好，不指书的用处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93802, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "父", "is_correct": false, "explanation": "fù（第四声）与 fú（第二声）声调不同，意思是父亲。"}, {"text": "福", "is_correct": true, "explanation": "福 fú：福分、福气。"}, {"text": "夫", "is_correct": false, "explanation": "fū（第一声）与 fú（第二声）声调不同，意思是丈夫。"}, {"text": "斧", "is_correct": false, "explanation": "fǔ（第三声）与 fú（第二声）声调不同，意思是斧头。"}, {"text": "壶", "is_correct": false, "explanation": "hú 与 fú 声母不同（h 与 f），意思是水壶。"}], "explanations": {"父": "fù（第四声）与 fú（第二声）声调不同，意思是父亲。", "福": "福 fú：福分、福气。", "夫": "fū（第一声）与 fú（第二声）声调不同，意思是丈夫。", "斧": "fǔ（第三声）与 fú（第二声）声调不同，意思是斧头。", "壶": "hú 与 fú 声母不同（h 与 f），意思是水壶。"}, "sentence_index": null, "correct_answer": "福"}, "level_3": {"options": [{"text": "灾", "is_correct": false, "explanation": "语义：灾指灾难，与“能一起长大”的好事相反，句意不通。"}, {"text": "福", "is_correct": true, "explanation": "福：福分、好运，与句中“能一起长大”的好处相合。"}, {"text": "罪", "is_correct": false, "explanation": "语义：罪指过错或罪过，与“能一起长大”相矛盾。"}, {"text": "脸", "is_correct": false, "explanation": "搭配：“脸”是身体部位，不能用来指“一起长大”这样的福分。"}], "explanations": {"灾": "语义：灾指灾难，与“能一起长大”的好事相反，句意不通。", "福": "福：福分、好运，与句中“能一起长大”的好处相合。", "罪": "语义：罪指过错或罪过，与“能一起长大”相矛盾。", "脸": "搭配：“脸”是身体部位，不能用来指“一起长大”这样的福分。"}, "sentence_index": 6, "correct_answer": "福"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "多喝水对身体很有福，大家都应该坚持。", "explanation": "这里应该用〈好处〉。福指命好、有福分，不说“对身体有福”，讲益处要用好处。"}, {"text": "他每个月的福很高，生活很宽裕。", "explanation": "这里应该用〈收入〉。福指好运和幸福，不指每月挣到的钱，说收入高要用收入。"}, {"text": "这张旧沙发的福很好，陪我们一起搬了三次家。", "explanation": "这里应该用〈质量〉。福指福分、命好，不指沙发的好坏；讲东西的好坏要用质量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一辈子平安顺利，是个福的人。", "corrected_sentence": "她一辈子平安顺利，是个有福的人。", "error_description": "“有福”是动宾结构，表示命好。只说“福”加“的”不自然，漏掉“有”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人在儿女身边，很受福。", "corrected_sentence": "老人在儿女身边，很享福。", "error_description": "表示过幸福的生活，固定说“享福”，不说“受福”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
