INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93803, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "称说是用话把一件事叫出来、说出来。", "primary_collocate": null, "pronunciation": "chēng shuō", "ipa": "ʈʂʰɤŋ˥ ʂwo˥", "syllable_count": 2, "sentences": [{"text": "这种感觉，我很难称说。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里的苦，不容易向人称说。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份心情，实在无法称说。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从不向别人称说自己的功劳。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事太复杂，一时难以称说。", "target_word": "称说", "complexity_tier": "T3", "furigana": "zhè jiàn shì tài fù zá, yī shí nán yǐ chēng shuō", "sentence_source": "generated"}, {"text": "那种美，难以用话称说。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有许多心事，从来不称说。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿向朋友称说家里的事。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的好处，他很少对人称说。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的难处，说不出口，也不便称说。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "称说：用话把事情或感受说出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d5d4e3-cb6a-4e49-9798-364dbe498c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93803, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "称说", "is_correct": true, "explanation": "称说：用话把这种感觉说出来，与“很难”的语境相合。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指摩擦、抹去，不能用来说出感觉，句子说不通。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚碰击，句中无法表示“说出感觉”。"}, {"text": "搬", "is_correct": false, "explanation": "配价：“搬”的宾语应是有形的物体，不能以“感觉”作宾语。"}], "explanations": {"称说": "称说：用话把这种感觉说出来，与“很难”的语境相合。", "擦": "语义：“擦”指摩擦、抹去，不能用来说出感觉，句子说不通。", "踢": "语义：“踢”指用脚碰击，句中无法表示“说出感觉”。", "搬": "配价：“搬”的宾语应是有形的物体，不能以“感觉”作宾语。"}, "sentence_index": 0, "correct_answer": "称说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把桌子称说了一遍。", "explanation": "这里应该用〈擦〉，表示用布抹去灰尘；称说只用于用话说出事情或感受。"}, {"text": "他把椅子称说好了。", "explanation": "这里应该用〈修〉，表示使损坏的东西恢复原样；称说只用于用话说出事情或感受。"}, {"text": "他狠狠称说了孩子一把。", "explanation": "这里应该用〈推〉，表示用手用力使人或物移动；称说只表示用话说出一件事，不能表示用手推。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93803, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "称说", "is_correct": true, "explanation": "称说：用话把心事说出来，与“从来不”的语境相合。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指用水去除污物，与“心事”不相容，不能用来说出心事。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”指用脚压，不能用于说出心事，句子说不通。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”通常指缝补衣物，不与“心事”搭配。"}], "explanations": {"称说": "称说：用话把心事说出来，与“从来不”的语境相合。", "洗": "语义：“洗”指用水去除污物，与“心事”不相容，不能用来说出心事。", "踩": "语义：“踩”指用脚压，不能用于说出心事，句子说不通。", "缝": "搭配：“缝”通常指缝补衣物，不与“心事”搭配。"}, "sentence_index": 6, "correct_answer": "称说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把衣服称说干净了。", "explanation": "这里应该用〈洗〉，表示用水去除污垢；称说只用于用话说出事情或感受。"}, {"text": "她把院子称说了一遍。", "explanation": "这里应该用〈扫〉，表示用扫帚清除灰尘；称说只用于用话说出事情或感受。"}, {"text": "他把苹果称说了。", "explanation": "这里应该用〈切〉，表示用刀分开；称说只用于用话说出事情或感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93803, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她不愿同事称说自己的难处。", "corrected_sentence": "她不愿向同事称说自己的难处。", "error_description": "错误形式：“不愿同事称说”，缺少介词“向”。“称说”的对象是人时要用“向”引出，正确形式为“不愿向同事称说”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93803, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没向人称说了心事。", "corrected_sentence": "他从来没向人称说过心事。", "error_description": "错误形式：“从来没……了”。“没”否定有过的经历时应与“过”搭配，“没……了”不成立。正确形式为“从来没向人称说过心事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
